export interface SignalCollector {
  collectSignals(
    context: ConnectorExecutionContext
  ): Promise<ConnectorSignalInput[]>;
}

export interface ControlObserver {
  observeControl?(
    context: ConnectorExecutionContext
  ): Promise<Record<string, unknown>>;
}

export interface WorkflowDestination {
  sendWorkflowEvent?(
    context: ConnectorExecutionContext
  ): Promise<Record<string, unknown>>;
  readWorkflowState?(
    context: ConnectorExecutionContext
  ): Promise<Record<string, unknown>>;
}

export interface EvidenceSink {
  writeEvidence?(
    context: ConnectorExecutionContext
  ): Promise<Record<string, unknown>>;
}

// Squad Zeta (Unified Data Fabric & Ecosystem Interoperability) baseline:
// Fabric ingest for unified ingest of external siloed data (vuln scans, inventories,
// EDR, CSPM) into evidence graph as seeds for pillar validation.
// "Validate from external finding" flows + noise reduction via correlation.
// Deep native adapters use manifest + safe validation (no mutation).
export interface FabricIngestAdapter {
  ingestExternalFinding?(
    context: ConnectorExecutionContext,
    externalFinding: Record<string, unknown>
  ): Promise<SignalEnvelope[]>;
}

export interface Connector
  extends
    SignalCollector,
    ControlObserver,
    WorkflowDestination,
    EvidenceSink,
    FabricIngestAdapter {
  healthCheck(context: ConnectorExecutionContext): Promise<ConnectorHealth>;
  manifest: ConnectorManifest;
  sync(context: ConnectorExecutionContext): Promise<ConnectorSyncResult>;
}

function createMockHealth(
  manifest: ConnectorManifest,
  context: ConnectorExecutionContext
): ConnectorHealth {
  return ConnectorHealthSchema.parse({
    authorizationVerified: context.mockMode,
    checkedAt: new Date().toISOString(),
    detail: context.mockMode
      ? `${manifest.vendor} mock connector is ready.`
      : `${manifest.vendor} ${manifest.product} live runtime is unavailable for this connector; use mock mode or a production-supported connector runtime.`,
    latencyMs: 5,
    status: context.mockMode ? "Healthy" : "Unknown"
  });
}

export function createTimestampedSignal(
  manifest: ConnectorManifest,
  context: ConnectorExecutionContext,
  input: ConnectorSignalInput
): SignalEnvelope {
  const parsedInput = ConnectorSignalInputSchema.parse(input);
  const timestampIngested = new Date().toISOString();

  return SignalEnvelopeSchema.parse({
    confidence: parsedInput.confidence ?? null,
    createdAt: timestampIngested,
    evidenceIds: [],
    freshness: parsedInput.freshness ?? null,
    rawPayloadPointer: parsedInput.rawPayloadPointer ?? null,
    redactionStatus: parsedInput.redactionStatus,
    relatedAssetIds: parsedInput.relatedAssetIds,
    relatedControlIds: parsedInput.relatedControlIds,
    relatedEvidenceIds: parsedInput.relatedEvidenceIds,
    relatedIdentityIds: parsedInput.relatedIdentityIds,
    relatedAssetHints: parsedInput.relatedAssetHints,
    relatedPathIds: parsedInput.relatedPathIds,
    sensitivityLevel: parsedInput.sensitivityLevel,
    signalCategory: parsedInput.signalCategory,
    signalId: randomUUID(),
    signalSubcategory: parsedInput.signalSubcategory ?? null,
    sourceIntegrationId: context.integrationId,
    sourceType: parsedInput.sourceType,
    sourceVendor: manifest.vendor,
    techniqueIds: parsedInput.techniqueIds ?? [],
    tenantId: context.tenantId,
    timestampIngested,
    timestampObserved: parsedInput.timestampObserved,
    updatedAt: timestampIngested
  });
}

export function createMockSignal(
  category: ConnectorSignalInput["signalCategory"],
  subcategory: string,
  sensitivity: ConnectorSignalInput["sensitivityLevel"],
  techniqueIds: string[] = []
): ConnectorSignalInput {
  return {
    confidence: 0.82,
    freshness: "Fresh",
    rawPayloadPointer: null,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: sensitivity,
    signalCategory: category,
    signalSubcategory: subcategory,
    sourceType: "connector.sync",
    // Only stamp a technique when the validation context actually names one —
    // never fabricate a specific detection on an otherwise-placeholder signal.
    ...(techniqueIds.length > 0 ? { techniqueIds } : {}),
    timestampObserved: new Date().toISOString()
  };
}

/**
 * SIEM/EDR connectors whose mock has no real detection payload (Elastic,
 * Datadog SIEM, Chronicle, Sumo, InsightIDR, QRadar, Sentinel) must not look
 * like live "Alerted" telemetry. This helper stamps an explicit placeholder
 * subcategory + low confidence so coverage/executive aggregates can exclude
 * mock technique-only observations (P06-6 SIEM honesty).
 */
export function createMockPlaceholderControlObservation(
  techniqueIds: string[] = []
): ConnectorSignalInput {
  return {
    confidence: 0.35,
    freshness: "Fresh",
    rawPayloadPointer: "mock:placeholder-control-observation",
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Moderate",
    signalCategory: "ControlObservation",
    signalSubcategory: "MockTechniquePlaceholder",
    sourceType: "connector.mock.placeholder",
    // Only stamp a technique when the validation context actually names one —
    // never fabricate a specific detection on an otherwise-placeholder signal.
    ...(techniqueIds.length > 0 ? { techniqueIds } : {}),
    timestampObserved: new Date().toISOString()
  };
}

// Extract MITRE ATT&CK technique ids (T####[.###]) that the validation context
// supplies via config.techniqueId, so a mock ControlObservation signal reflects
// exactly the technique being validated (and stays empty otherwise). SIEM/EDR
// connectors whose mock has no detection payload use this so their telemetry can
// drive control-rule coverage for the scenario under test.
export function contextTechniqueIds(
  context: ConnectorExecutionContext
): string[] {
  const value = context.config.techniqueId;
  if (typeof value !== "string") {
    return [];
  }
  const matches = value.match(/T\d{4}(?:\.\d{3})?/giu) ?? [];
  return [...new Set(matches.map((entry) => entry.toUpperCase()))];
}

function normalizeSplunkOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "Routed":
    case "NeedsTuning":
      return value;
    case "Missed":
      return "NoEvidence";
    default:
      return "Logged";
  }
}

function normalizeElasticSecurityOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      // Neutral default: an unconfigured/unrecognized mock outcome must not
      // over-claim a detection. The live observer only returns "Alerted" when
      // alert hits actually exist, so the mock default falls back to "Logged"
      // (matching every other SIEM connector here), never "Alerted".
      return "Logged";
  }
}

function normalizeDatadogSiemOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      // Neutral default — see normalizeElasticSecurityOutcome: never over-claim
      // a detection ("Alerted") for an unconfigured/unrecognized mock outcome.
      return "Logged";
  }
}

function normalizeGoogleChronicleOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      return "Logged";
  }
}

function normalizeSumoLogicOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      return "Logged";
  }
}

function normalizeRapid7InsightIdrOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      return "Logged";
  }
}

function normalizeIbmQradarOutcome(value: unknown) {
  switch (value) {
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      return "Logged";
  }
}

function normalizeMicrosoftDefenderXdrOutcome(value: unknown) {
  switch (value) {
    case "Blocked":
    case "Detected":
    case "Alerted":
    case "Logged":
    case "NoEvidence":
    case "NeedsTuning":
    case "Missed":
      return value;
    default:
      // Neutral default — an unconfigured/unrecognized mock outcome must not
      // over-claim a successful detection. The live observer only returns the
      // positive "Alerted" verdict when Advanced Hunting evidence actually
      // exists (otherwise "NoEvidence"), so the mock default falls back to the
      // neutral "Logged" (telemetry recorded, no alert claimed) — matching the
      // shared SIEM convention this XDR's Alerted/Logged vocabulary belongs to —
      // never "Alerted".
      return "Logged";
  }
}

