function splunkApiUrl(config: SplunkApiTokenConfig, pathName: string) {
  return new URL(pathName, config.baseUrl).toString();
}

function splunkErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Splunk API error.";
}

function buildSplunkSearch(
  config: SplunkApiTokenConfig,
  context: ConnectorExecutionContext
) {
  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? context.config.techniqueId
      : null;
  const index = config.index ? `index=${config.index}` : "index=*";
  const correlationToken =
    typeof context.config.correlationToken === "string" &&
    context.config.correlationToken.length > 0
      ? context.config.correlationToken.replace(/["'\\;]/gu, "")
      : null;
  if (config.searchQuery && !correlationToken) {
    return config.searchQuery;
  }
  const terms = correlationToken
    ? [`"${correlationToken}"`]
    : [
        "periscan",
        techniqueId ? `"${techniqueId.replace(/"/gu, "")}"` : null
      ].filter((item): item is string => Boolean(item));

  return `search ${index} (${terms.join(" OR ")}) | head 1`;
}

async function observeSplunkControl(context: ConnectorExecutionContext) {
  const config = SplunkApiTokenConfigSchema.parse(context.config);
  const body = new URLSearchParams({
    earliest_time: config.earliestTime ?? "-24h",
    latest_time: config.latestTime ?? "now",
    output_mode: "json",
    search: buildSplunkSearch(config, context)
  });
  const startedAt = Date.now();
  let response: Response;

  try {
    response = await connectorFetch(
      splunkApiUrl(config, "/services/search/jobs/export"),
      {
        body,
        headers: {
          authorization: `Bearer ${config.token}`,
          "content-type": "application/x-www-form-urlencoded"
        },
        method: "POST"
      }
    );
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Splunk search failed: ${splunkErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "splunk.search.observer"
    };
  }

  if (!response.ok) {
    return {
      confidence: 0.4,
      detail: `Splunk search returned status ${response.status}.`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "splunk.search.observer"
    };
  }

  const text = await response.text();
  const hasResult =
    text.trim().length > 0 &&
    (text.includes('"result"') || text.includes('"_raw"'));

  const exactCorrelationRequested =
    typeof context.config.correlationToken === "string" &&
    context.config.correlationToken.length > 0;

  return {
    confidence: hasResult ? 0.82 : 0.62,
    correlationMatched: exactCorrelationRequested && hasResult,
    detail: hasResult
      ? "Splunk search returned log evidence for the validation context."
      : "Splunk search completed but returned no matching log evidence.",
    latencyMs: Date.now() - startedAt,
    outcome: hasResult ? "Logged" : "NoEvidence",
    sourceType: "splunk.search.observer"
  };
}

// The Splunk search-export endpoint streams newline-delimited JSON rows, each an
// envelope { preview, result: {...fields} }. Parse out the result records,
// skipping preview/blank/unparseable lines.
function parseSplunkExportResults(
  text: string
): Array<Record<string, unknown>> {
  const results: Array<Record<string, unknown>> = [];

  for (const line of text.split(/\r?\n/u)) {
    const trimmed = line.trim();
    if (trimmed.length === 0) {
      continue;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      continue;
    }

    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      continue;
    }

    const envelope = parsed as Record<string, unknown>;
    if (envelope.preview === true) {
      continue;
    }

    const result = envelope.result;
    if (result && typeof result === "object" && !Array.isArray(result)) {
      results.push(result as Record<string, unknown>);
    }
  }

  return results;
}

// Run the configured read-only search for continuous telemetry ingest
// (collectSignals / sync), reusing the same export endpoint and bounded search
// the observer uses. Returns the parsed result records for normalization.
async function fetchSplunkResults(
  config: SplunkApiTokenConfig,
  context: ConnectorExecutionContext
): Promise<Array<Record<string, unknown>>> {
  const body = new URLSearchParams({
    earliest_time: config.earliestTime ?? "-24h",
    latest_time: config.latestTime ?? "now",
    output_mode: "json",
    search: buildSplunkSearch(config, context)
  });

  const response = await connectorFetch(
    splunkApiUrl(config, "/services/search/jobs/export"),
    {
      body,
      headers: {
        authorization: `Bearer ${config.token}`,
        "content-type": "application/x-www-form-urlencoded"
      },
      method: "POST"
    }
  );
  if (!response.ok) {
    throw new Error(`Splunk search returned status ${response.status}.`);
  }

  return parseSplunkExportResults(await response.text());
}

// Extract MITRE ATT&CK technique ids (T####[.###]) from a Splunk notable's
// mitre/technique/annotation fields (or the raw event) so the resulting
// ControlObservation signal drives control-rule coverage — mirrors the EDR
// extractors. _time is excluded to avoid matching ISO timestamps.
function splunkResultTechniqueIds(result: Record<string, unknown>): string[] {
  const named: unknown[] = [];
  for (const [key, value] of Object.entries(result)) {
    if (/mitre|technique|annotation|signature|_raw/iu.test(key)) {
      named.push(value);
    }
  }
  const haystack = JSON.stringify(named.length > 0 ? named : result);
  const matches = haystack.match(/T\d{4}(?:\.\d{3})?/gu) ?? [];
  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

// Host/IP hints from a Splunk notable's CIM fields, resolved to tenant asset ids
// during sync so the SIEM telemetry is attributed to the right asset.
function splunkResultAssetHints(result: Record<string, unknown>): string[] {
  const hints = [
    result.host,
    result.dvc,
    result.src,
    result.src_ip,
    result.src_host,
    result.dest,
    result.dest_ip,
    result.dest_host
  ].filter(
    (value): value is string => typeof value === "string" && value.length > 0
  );
  return [...new Set(hints)];
}

// Splunk _time arrives with a numeric offset (e.g. ...+00:00); the signal schema
// requires a strict ISO-Z timestamp. Coerce it, falling back to the sweep time
// when _time is absent or unparseable.
function splunkResultTimestamp(value: unknown, fallback: string): string {
  if (typeof value !== "string") {
    return fallback;
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return fallback;
  }
  return parsed.toISOString();
}

function createSplunkSignals(input: {
  results: Array<Record<string, unknown>>;
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: "splunk://search/results",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "DetectionLogObservation",
      sourceType: "splunk.search.metadata",
      timestampObserved
    })
  ];

  for (const [index, result] of input.results.entries()) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.8,
        freshness: "Fresh",
        rawPayloadPointer: `splunk://search/results/${index + 1}`,
        redactionStatus: "Redacted",
        relatedAssetHints: splunkResultAssetHints(result),
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: "DetectionLogged",
        sourceType: "splunk.detection",
        techniqueIds: splunkResultTechniqueIds(result),
        timestampObserved: splunkResultTimestamp(
          result._time,
          timestampObserved
        )
      })
    );
  }

  if (input.results.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "splunk://search/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoDetectionLogEvidence",
        sourceType: "splunk.search.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadSplunkFixtureResults(
  config: Record<string, unknown>
): Array<Record<string, unknown>> {
  const outcome = normalizeSplunkOutcome(config.fixtureOutcome);

  if (outcome === "NoEvidence") {
    return [];
  }

  return [
    {
      _raw: "2026-06-01 periscan validation detection technique=T1059 host=fixture-siem-host-01",
      _time: "2026-06-01T00:00:00.000+00:00",
      host: "fixture-siem-host-01",
      "annotations.mitre_attack": ["T1059"],
      signature: "Periscan validation detection",
      src_ip: "10.0.0.20"
    }
  ];
}

function normalizeCrowdStrikeOutcome(value: unknown) {
  switch (value) {
    case "Blocked":
    case "Detected":
    case "Missed":
    case "NeedsTuning":
      return value;
    default:
      // Neutral default — an unconfigured/unrecognized mock outcome must not
      // over-claim a successful detection. The live Falcon observer only returns
      // "Detected"/"Blocked" when detection evidence actually exists; with no
      // matching evidence it returns "Missed" (Falcon's vocabulary has no
      // "NoEvidence" verdict), so the mock default falls back to "Missed",
      // never the positive "Detected".
      return "Missed";
  }
}

function normalizeSentinelOneOutcome(value: unknown) {
  switch (value) {
    case "Blocked":
    case "Detected":
    case "Missed":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      // Neutral default — an unconfigured/unrecognized mock outcome must not
      // over-claim a successful detection. The live observer only returns
      // "Detected"/"Blocked" when detection evidence actually exists; when the
      // query succeeds but finds nothing it returns "NoEvidence", so the mock
      // default falls back to the neutral "NoEvidence", never "Detected". The
      // fixture loaders emit no detection for this verdict, matching the
      // observer. Every EDR/WAF connector below shares this convention.
      return "NoEvidence";
  }
}

function normalizeCarbonBlackOutcome(value: unknown) {
  switch (value) {
    case "Blocked":
    case "Detected":
    case "Missed":
    case "NoEvidence":
    case "NeedsTuning":
      return value;
    default:
      // Neutral default — see normalizeSentinelOneOutcome: never over-claim a
      // detection ("Detected") for an unconfigured/unrecognized mock outcome.
      return "NoEvidence";
  }
}

