function crowdStrikeApiUrl(config: CrowdStrikeOAuthConfig, pathName: string) {
  return new URL(pathName, config.baseUrl).toString();
}

function crowdStrikeErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Falcon API error.";
}

async function readCrowdStrikeJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function getCrowdStrikeAccessToken(config: CrowdStrikeOAuthConfig) {
  const response = await connectorFetch(
    crowdStrikeApiUrl(config, "/oauth2/token"),
    {
      body: new URLSearchParams({
        client_id: config.clientId,
        client_secret: config.clientSecret
      }),
      headers: {
        "content-type": "application/x-www-form-urlencoded"
      },
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(`Falcon OAuth returned status ${response.status}.`);
  }

  const json = await readCrowdStrikeJson(response);
  const parsed = z
    .object({
      access_token: z.string().min(1)
    })
    .passthrough()
    .parse(json);

  return parsed.access_token;
}

function buildCrowdStrikeDetectionFilter(
  config: CrowdStrikeOAuthConfig,
  context: ConnectorExecutionContext
) {
  if (config.detectionFilter) {
    return config.detectionFilter;
  }

  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? context.config.techniqueId.replace(/'/gu, "")
      : null;

  return techniqueId ? `behaviors.technique_id:'${techniqueId}'` : null;
}

function crowdStrikeHasBlockedDisposition(value: string) {
  return /\b(blocked|contained|containment|prevented|prevention|quarantined)\b/iu.test(
    value
  );
}

async function summarizeCrowdStrikeDetections(
  config: CrowdStrikeOAuthConfig,
  accessToken: string,
  detectionIds: string[]
) {
  if (detectionIds.length === 0) {
    return { blocked: false, detail: "" };
  }

  const response = await connectorFetch(
    crowdStrikeApiUrl(config, "/detects/entities/summaries/GET/v1"),
    {
      body: JSON.stringify({
        ids: detectionIds.slice(0, 10)
      }),
      headers: {
        authorization: `Bearer ${accessToken}`,
        "content-type": "application/json"
      },
      method: "POST"
    }
  );

  if (!response.ok) {
    return {
      blocked: false,
      detail: `Falcon summary lookup returned status ${response.status}.`
    };
  }

  const text = await response.text();

  return {
    blocked: crowdStrikeHasBlockedDisposition(text),
    detail: text.length > 0 ? "Falcon detection summary returned." : ""
  };
}

async function observeCrowdStrikeControl(context: ConnectorExecutionContext) {
  const config = CrowdStrikeOAuthConfigSchema.parse(context.config);
  const startedAt = Date.now();
  let accessToken: string;

  try {
    accessToken = await getCrowdStrikeAccessToken(config);
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Falcon observer authorization failed: ${crowdStrikeErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      outcome: "Missed",
      sourceType: "crowdstrike.falcon.observer"
    };
  }

  const detectionUrl = new URL(
    crowdStrikeApiUrl(config, "/detects/queries/detects/v1")
  );
  detectionUrl.searchParams.set("limit", String(config.limit));
  const filter = buildCrowdStrikeDetectionFilter(config, context);

  if (filter) {
    detectionUrl.searchParams.set("filter", filter);
  }

  let queryResponse: Response;

  try {
    queryResponse = await connectorFetch(detectionUrl.toString(), {
      headers: {
        authorization: `Bearer ${accessToken}`
      }
    });
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Falcon detection query failed: ${crowdStrikeErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      outcome: "Missed",
      sourceType: "crowdstrike.falcon.observer"
    };
  }

  if (!queryResponse.ok) {
    return {
      confidence: 0.42,
      detail: `Falcon detection query returned status ${queryResponse.status}.`,
      latencyMs: Date.now() - startedAt,
      outcome: "Missed",
      sourceType: "crowdstrike.falcon.observer"
    };
  }

  const queryJson = await readCrowdStrikeJson(queryResponse);
  const resources = Array.isArray(queryJson.resources)
    ? queryJson.resources.filter(
        (item): item is string => typeof item === "string"
      )
    : [];
  const total =
    typeof (queryJson.meta as { pagination?: { total?: unknown } } | undefined)
      ?.pagination?.total === "number"
      ? (queryJson.meta as { pagination: { total: number } }).pagination.total
      : resources.length;

  if (resources.length === 0 && total === 0) {
    return {
      confidence: 0.62,
      detail:
        "Falcon detection query completed but returned no matching evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: "Missed",
      sourceType: "crowdstrike.falcon.observer"
    };
  }

  const summary = await summarizeCrowdStrikeDetections(
    config,
    accessToken,
    resources
  );

  return {
    confidence: summary.blocked ? 0.86 : 0.8,
    detail: summary.blocked
      ? "Falcon returned prevention or containment evidence for the validation context."
      : summary.detail ||
        "Falcon returned detection evidence for the validation context.",
    latencyMs: Date.now() - startedAt,
    outcome: summary.blocked ? "Blocked" : "Detected",
    sourceType: "crowdstrike.falcon.observer"
  };
}

const CrowdStrikeDetectionsResponseSchema = z
  .object({
    resources: z.array(z.record(z.string(), z.unknown())).default([])
  })
  .passthrough();

// Pull recent Falcon detections for continuous telemetry ingest (collectSignals
// / sync), reusing the same OAuth + query + summary endpoints the observer uses.
// Returns the structured detection-summary resources so each can be normalized
// into a ControlObservation signal.
async function fetchCrowdStrikeDetections(
  config: CrowdStrikeOAuthConfig,
  context: ConnectorExecutionContext
): Promise<Array<Record<string, unknown>>> {
  const accessToken = await getCrowdStrikeAccessToken(config);

  const detectionUrl = new URL(
    crowdStrikeApiUrl(config, "/detects/queries/detects/v1")
  );
  detectionUrl.searchParams.set("limit", String(config.limit));
  const filter = buildCrowdStrikeDetectionFilter(config, context);
  if (filter) {
    detectionUrl.searchParams.set("filter", filter);
  }

  const queryResponse = await connectorFetch(detectionUrl.toString(), {
    headers: {
      authorization: `Bearer ${accessToken}`
    }
  });
  if (!queryResponse.ok) {
    throw new Error(
      `Falcon detection query returned status ${queryResponse.status}.`
    );
  }

  const queryJson = await readCrowdStrikeJson(queryResponse);
  const detectionIds = Array.isArray(queryJson.resources)
    ? queryJson.resources.filter(
        (item): item is string => typeof item === "string"
      )
    : [];
  if (detectionIds.length === 0) {
    return [];
  }

  const summaryResponse = await connectorFetch(
    crowdStrikeApiUrl(config, "/detects/entities/summaries/GET/v1"),
    {
      body: JSON.stringify({ ids: detectionIds.slice(0, config.limit) }),
      headers: {
        authorization: `Bearer ${accessToken}`,
        "content-type": "application/json"
      },
      method: "POST"
    }
  );
  if (!summaryResponse.ok) {
    throw new Error(
      `Falcon summary lookup returned status ${summaryResponse.status}.`
    );
  }

  return CrowdStrikeDetectionsResponseSchema.parse(
    await readCrowdStrikeJson(summaryResponse)
  ).resources;
}

function crowdStrikeDetectionIndicatesBlocked(
  detection: Record<string, unknown>
): boolean {
  const fields = [
    detection.status,
    detection.disposition_human_readable,
    detection.max_severity_displayname
  ]
    .filter((value): value is string => typeof value === "string")
    .join(" ");

  return crowdStrikeHasBlockedDisposition(
    `${fields} ${JSON.stringify(detection).toLowerCase()}`
  );
}

// Extract MITRE ATT&CK technique ids (T####[.###]) from a Falcon detection's
// behaviors/tactic fields so the resulting ControlObservation signal drives
// control-rule coverage instead of being inert — mirrors the Cortex XDR and
// SentinelOne extractors.
function crowdStrikeDetectionTechniqueIds(
  detection: Record<string, unknown>
): string[] {
  const haystack = JSON.stringify([
    detection.behaviors,
    detection.technique,
    detection.tactic
  ]);
  const matches = haystack.match(/T\d{4}(?:\.\d{3})?/gu) ?? [];
  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

// Host/IP hints from a Falcon detection's device block, resolved to tenant asset
// ids during sync so the endpoint telemetry is attributed to the right asset.
function crowdStrikeDetectionAssetHints(
  detection: Record<string, unknown>
): string[] {
  const device =
    detection.device && typeof detection.device === "object"
      ? (detection.device as Record<string, unknown>)
      : {};
  const hints = [device.hostname, device.local_ip, device.external_ip].filter(
    (value): value is string => typeof value === "string" && value.length > 0
  );
  return [...new Set(hints)];
}

function createCrowdStrikeSignals(input: {
  detections: Array<Record<string, unknown>>;
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.84,
      freshness: "Fresh",
      rawPayloadPointer: "crowdstrike://detections",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "EndpointDetectionObservation",
      sourceType: "crowdstrike.detections.metadata",
      timestampObserved
    })
  ];

  for (const [index, detection] of input.detections.entries()) {
    const createdTimestamp = detection.created_timestamp;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `crowdstrike://detections/${index + 1}`,
        redactionStatus: "Redacted",
        relatedAssetHints: crowdStrikeDetectionAssetHints(detection),
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: crowdStrikeDetectionIndicatesBlocked(detection)
          ? "EndpointThreatBlocked"
          : "EndpointThreatDetected",
        sourceType: "crowdstrike.detection",
        techniqueIds: crowdStrikeDetectionTechniqueIds(detection),
        timestampObserved:
          typeof createdTimestamp === "string"
            ? createdTimestamp
            : timestampObserved
      })
    );
  }

  if (input.detections.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "crowdstrike://detections/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoEndpointDetectionEvidence",
        sourceType: "crowdstrike.detections.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadCrowdStrikeFixtureDetections(
  config: Record<string, unknown>
): Array<Record<string, unknown>> {
  const outcome = normalizeCrowdStrikeOutcome(config.fixtureOutcome);

  if (outcome === "Missed") {
    return [];
  }

  return [
    {
      behaviors: [
        {
          tactic: "Execution",
          technique: "Command and Scripting Interpreter",
          technique_id: "T1059.001"
        }
      ],
      created_timestamp: "2026-06-01T00:00:00Z",
      detection_id: "ldt:fixture:1",
      device: {
        hostname: "fixture-endpoint-01",
        local_ip: "10.0.0.10"
      },
      max_severity_displayname: "Critical",
      status:
        outcome === "Blocked"
          ? "Prevention triggered: process quarantined."
          : "new"
    }
  ];
}

