function carbonBlackApiUrl(config: CarbonBlackApiKeyConfig, pathName: string) {
  return new URL(pathName, config.baseUrl.replace(/\/+$/u, "")).toString();
}

function carbonBlackHeaders(config: CarbonBlackApiKeyConfig) {
  return {
    accept: "application/json",
    "content-type": "application/json",
    "X-AUTH-TOKEN": `${config.apiSecretKey}/${config.apiId}`
  };
}

function carbonBlackErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Carbon Black Cloud API error.";
}

async function readCarbonBlackJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function carbonBlackSafeQueryTerm(value: string) {
  return value.replace(/[^\w./: -]/gu, "").slice(0, 128);
}

function buildCarbonBlackAlertQuery(
  config: CarbonBlackApiKeyConfig,
  context?: ConnectorExecutionContext
) {
  const techniqueId =
    context &&
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? carbonBlackSafeQueryTerm(context.config.techniqueId)
      : null;

  if (techniqueId) {
    return `periscan ${techniqueId}`;
  }

  return config.query ? carbonBlackSafeQueryTerm(config.query) : "periscan";
}

function carbonBlackSearchBody(
  config: CarbonBlackApiKeyConfig,
  context?: ConnectorExecutionContext
) {
  const criteria: Record<string, unknown> = {};

  if (config.minimumSeverity) {
    criteria.minimum_severity = config.minimumSeverity;
  }

  if (config.timeRange) {
    criteria.backend_timestamp = {
      range: config.timeRange
    };
  }

  return {
    criteria,
    query: buildCarbonBlackAlertQuery(config, context),
    rows: config.limit,
    sort: [
      {
        field: "backend_timestamp",
        order: "DESC"
      }
    ],
    start: 0
  };
}

async function fetchCarbonBlackAlerts(
  config: CarbonBlackApiKeyConfig,
  context?: ConnectorExecutionContext
) {
  const response = await connectorFetch(
    carbonBlackApiUrl(
      config,
      `/api/alerts/v7/orgs/${encodeURIComponent(config.orgKey)}/alerts/_search`
    ),
    {
      body: JSON.stringify(carbonBlackSearchBody(config, context)),
      headers: carbonBlackHeaders(config),
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Carbon Black Alerts v7 search returned status ${response.status}.`
    );
  }

  return CarbonBlackAlertsResponseSchema.parse(
    await readCarbonBlackJson(response)
  );
}

function carbonBlackValueAtPath(value: unknown, path: string[]) {
  let current: unknown = value;

  for (const segment of path) {
    if (!current || typeof current !== "object" || Array.isArray(current)) {
      return null;
    }

    current = (current as Record<string, unknown>)[segment];
  }

  return current;
}

function carbonBlackAlertText(alert: Record<string, unknown>) {
  return JSON.stringify(alert).toLowerCase();
}

function carbonBlackAlertIndicatesBlocked(alert: Record<string, unknown>) {
  const values = [
    alert.determination,
    alert.reason,
    alert.policy_action,
    alert.run_state,
    carbonBlackValueAtPath(alert, ["workflow", "state"]),
    carbonBlackValueAtPath(alert, ["device", "policy_action"])
  ]
    .filter((value): value is string => typeof value === "string")
    .join(" ");

  return /\b(blocked|denied|deny|prevented|terminated|killed|quarantined|policy_applied)\b/iu.test(
    `${values} ${carbonBlackAlertText(alert)}`
  );
}

function createCarbonBlackAssets(): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "Service",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "vmware-carbon-black"
      },
      internetExposed: false,
      name: "Carbon Black Cloud",
      owner: "endpoint-security",
      status: "Active",
      tags: ["edr", "xdr", "carbon-black", "vmware"]
    })
  ];
}

// Extract MITRE ATT&CK technique ids from a Carbon Black alert's threat
// indicators / TTPs (CB encodes them like "MITRE_T1059_..."), so the ingested
// ControlObservation signal drives control-rule coverage.
function carbonBlackAlertTechniqueIds(
  alert: Record<string, unknown>
): string[] {
  const haystack = JSON.stringify([
    alert.threat_indicators,
    alert.ttps,
    alert.mitre_attack_techniques
  ]);
  const matches = haystack.match(/T\d{4}(?:\.\d{3})?/gu) ?? [];
  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

// Host/IP hints from a Carbon Black alert's device fields, resolved to tenant
// asset ids during sync so endpoint telemetry is attributed to the right asset.
function carbonBlackAlertAssetHints(alert: Record<string, unknown>): string[] {
  const hints = [
    alert.device_name,
    alert.device_internal_ip,
    alert.device_external_ip
  ].filter(
    (value): value is string => typeof value === "string" && value.length > 0
  );
  return [...new Set(hints)];
}

function createCarbonBlackSignals(input: {
  alerts: CarbonBlackAlertsResponse;
}) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.84,
      freshness: "Fresh",
      rawPayloadPointer: "carbon-black://alerts",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "EndpointAlertObservation",
      sourceType: "carbon_black.alerts.metadata",
      timestampObserved
    })
  ];

  for (const [index, alert] of input.alerts.results.entries()) {
    const createdAt =
      typeof alert.backend_timestamp === "string"
        ? alert.backend_timestamp
        : typeof alert.create_time === "string"
          ? alert.create_time
          : null;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `carbon-black://alerts/${index + 1}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        relatedAssetHints: carbonBlackAlertAssetHints(alert),
        signalSubcategory: carbonBlackAlertIndicatesBlocked(alert)
          ? "EndpointAlertBlocked"
          : "EndpointAlertDetected",
        sourceType: "carbon_black.alert",
        techniqueIds: carbonBlackAlertTechniqueIds(alert),
        timestampObserved: createdAt ?? timestampObserved
      })
    );
  }

  if (input.alerts.results.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "carbon-black://alerts/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoEndpointAlertEvidence",
        sourceType: "carbon_black.alerts.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadCarbonBlackFixtureAlerts(
  config: Record<string, unknown>
): CarbonBlackAlertsResponse {
  const outcome = normalizeCarbonBlackOutcome(config.fixtureOutcome);

  if (outcome === "Missed" || outcome === "NoEvidence") {
    return {
      num_found: 0,
      results: []
    };
  }

  return {
    num_found: 1,
    results: [
      {
        backend_timestamp: "2026-06-01T15:00:00.000Z",
        determination: outcome === "Blocked" ? "KNOWN_MALWARE" : "SUSPICIOUS",
        device_internal_ip: "10.20.30.40",
        device_name: "edr-host-01",
        id: "carbon-black-alert-1",
        policy_action: outcome === "Blocked" ? "DENY" : "ALLOW",
        reason: `Periscan validation event ${outcome.toLowerCase()}`,
        threat_indicators: [
          {
            ttps: ["MITRE_T1059_COMMAND_AND_SCRIPTING_INTERPRETER"]
          }
        ]
      }
    ]
  };
}

async function getCarbonBlackHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CARBON_BLACK_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = CarbonBlackApiKeyConfigSchema.parse(context.config);
  const alerts = await fetchCarbonBlackAlerts({
    ...config,
    limit: 1
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Carbon Black Alerts v7 read access verified; ${alerts.results.length} sample alert record(s) accessible.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observeCarbonBlackControl(context: ConnectorExecutionContext) {
  const startedAt = Date.now();

  if (context.mockMode) {
    const outcome = normalizeCarbonBlackOutcome(context.config.fixtureOutcome);

    return {
      confidence:
        outcome === "Missed" || outcome === "NoEvidence" ? 0.58 : 0.82,
      detail:
        outcome === "Missed" || outcome === "NoEvidence"
          ? "Carbon Black fixture contains no alert evidence for the validation context."
          : "Carbon Black fixture contains alert evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome,
      sourceType: "carbon_black.alerts.observer"
    };
  }

  try {
    const config = CarbonBlackApiKeyConfigSchema.parse(context.config);
    const alerts = await fetchCarbonBlackAlerts(config, context);

    if (alerts.results.length === 0 && (alerts.num_found ?? 0) === 0) {
      return {
        confidence: 0.62,
        detail:
          "Carbon Black Alerts v7 search completed but returned no matching endpoint evidence.",
        latencyMs: Date.now() - startedAt,
        outcome: "Missed",
        sourceType: "carbon_black.alerts.observer"
      };
    }

    const blocked = alerts.results.some((alert) =>
      carbonBlackAlertIndicatesBlocked(alert)
    );

    return {
      confidence: blocked ? 0.86 : 0.8,
      detail: blocked
        ? "Carbon Black returned prevention or policy-action evidence for the validation context."
        : "Carbon Black returned endpoint alert evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome: blocked ? "Blocked" : "Detected",
      sourceType: "carbon_black.alerts.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Carbon Black Alerts v7 lookup failed: ${carbonBlackErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "carbon_black.alerts.observer"
    };
  }
}

