function sophosErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Sophos Central API error.";
}

async function readSophosJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function getSophosAccessToken(config: SophosCentralOAuthConfig) {
  const response = await connectorFetch(config.tokenUrl, {
    body: new URLSearchParams({
      client_id: config.clientId,
      client_secret: config.clientSecret,
      grant_type: "client_credentials",
      scope: "token"
    }),
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(`Sophos OAuth returned status ${response.status}.`);
  }

  const json = await readSophosJson(response);
  const parsed = z
    .object({
      access_token: z.string().min(1)
    })
    .passthrough()
    .parse(json);

  return parsed.access_token;
}

function sophosApiBaseUrlFromRegion(value: string | undefined) {
  if (!value) {
    return null;
  }

  if (value.startsWith("https://")) {
    return value.replace(/\/+$/u, "");
  }

  return `https://api-${value.replace(/^api-/u, "")}.central.sophos.com`;
}

async function resolveSophosTenantContext(
  config: SophosCentralOAuthConfig,
  accessToken: string
): Promise<SophosTenantContext> {
  if (config.apiBaseUrl && config.tenantId) {
    return {
      apiBaseUrl: config.apiBaseUrl.replace(/\/+$/u, ""),
      tenantId: config.tenantId
    };
  }

  const response = await connectorFetch(config.whoamiUrl, {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${accessToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`Sophos whoami returned status ${response.status}.`);
  }

  const whoami = SophosWhoamiSchema.parse(await readSophosJson(response));
  const tenantId = config.tenantId ?? whoami.id ?? whoami.tenantId;
  const apiBaseUrl =
    config.apiBaseUrl ?? sophosApiBaseUrlFromRegion(whoami.dataRegion);

  if (!tenantId || !apiBaseUrl) {
    throw new Error(
      "Sophos whoami response did not include tenant ID and data-region API host."
    );
  }

  return {
    apiBaseUrl: apiBaseUrl.replace(/\/+$/u, ""),
    tenantId
  };
}

function sophosApiUrl(tenantContext: SophosTenantContext, pathName: string) {
  return new URL(pathName, tenantContext.apiBaseUrl).toString();
}

function sophosHeaders(
  accessToken: string,
  tenantContext: SophosTenantContext
) {
  return {
    accept: "application/json",
    authorization: `Bearer ${accessToken}`,
    "content-type": "application/json",
    "X-Tenant-ID": tenantContext.tenantId
  };
}

function sophosAlertSearchBody(config: SophosCentralOAuthConfig) {
  const body: Record<string, unknown> = {
    fields: [
      "id",
      "allowedActions",
      "category",
      "description",
      "managedAgent",
      "product",
      "raisedAt",
      "severity",
      "type"
    ],
    pageSize: config.limit,
    product: config.products,
    sort: ["raisedAt:desc"]
  };

  if (config.categories && config.categories.length > 0) {
    body.category = config.categories;
  }

  if (config.severities && config.severities.length > 0) {
    body.severity = config.severities;
  }

  if (config.from) {
    body.from = config.from;
  }

  if (config.to) {
    body.to = config.to;
  }

  return body;
}

function sophosAlertRows(value: unknown): SophosAlertRecord[] {
  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};

  for (const key of ["items", "alerts", "data", "results"]) {
    const rows = record[key];

    if (Array.isArray(rows)) {
      return rows.filter(
        (item): item is SophosAlertRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      );
    }
  }

  return [];
}

async function fetchSophosAlerts(
  config: SophosCentralOAuthConfig,
  accessToken: string,
  tenantContext: SophosTenantContext
) {
  const response = await connectorFetch(
    sophosApiUrl(tenantContext, "/common/v1/alerts/search"),
    {
      body: JSON.stringify(sophosAlertSearchBody(config)),
      headers: sophosHeaders(accessToken, tenantContext),
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(`Sophos alert search returned status ${response.status}.`);
  }

  return sophosAlertRows(await readSophosJson(response));
}

function sophosAlertIndicatesBlocked(alert: SophosAlertRecord) {
  return /\b(blocked|prevented|cleaned|cleanedup|remediated|resolved|stopped|deleted|quarantined|contained)\b/iu.test(
    JSON.stringify(alert)
  );
}

