function trendMicroErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Trend Vision One API error.";
}

async function readTrendMicroJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function trendMicroApiUrl(
  config: TrendMicroVisionOneApiTokenConfig,
  pathName: string
) {
  return new URL(pathName, config.baseUrl.replace(/\/+$/u, "")).toString();
}

function buildTrendMicroWorkbenchAlertsUrl(
  config: TrendMicroVisionOneApiTokenConfig
) {
  const url = new URL(trendMicroApiUrl(config, "/v3.0/workbench/alerts"));

  url.searchParams.set("dateTimeTarget", config.dateTimeTarget);
  url.searchParams.set("orderBy", config.orderBy);
  url.searchParams.set("top", String(config.limit));

  if (config.startDateTime) {
    url.searchParams.set("startDateTime", config.startDateTime);
  }

  if (config.endDateTime) {
    url.searchParams.set("endDateTime", config.endDateTime);
  }

  return url.toString();
}

function trendMicroHeaders(config: TrendMicroVisionOneApiTokenConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.apiToken}`,
    ...(config.filter
      ? {
          "TMV1-Filter": config.filter
        }
      : {})
  };
}

function trendMicroAlertRows(value: unknown): TrendMicroWorkbenchAlertRecord[] {
  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};

  for (const key of ["items", "alerts", "data", "results"]) {
    const rows = record[key];

    if (Array.isArray(rows)) {
      return rows.filter(
        (item): item is TrendMicroWorkbenchAlertRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      );
    }
  }

  return [];
}

async function fetchTrendMicroWorkbenchAlerts(
  config: TrendMicroVisionOneApiTokenConfig
) {
  const response = await connectorFetch(
    buildTrendMicroWorkbenchAlertsUrl(config),
    {
      headers: trendMicroHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Trend Vision One Workbench alert query returned status ${response.status}.`
    );
  }

  return trendMicroAlertRows(await readTrendMicroJson(response));
}

function trendMicroAlertIndicatesBlocked(
  alert: TrendMicroWorkbenchAlertRecord
) {
  return /\b(blocked|prevented|remediated|contained|isolated|terminated|stopped|quarantined|response successful|mitigated)\b/iu.test(
    JSON.stringify(alert)
  );
}

