function paloAltoCortexXdrErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Cortex XDR API error.";
}

async function readPaloAltoCortexXdrJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function paloAltoCortexXdrApiUrl(
  config: PaloAltoCortexXdrApiKeyConfig,
  pathName: string
) {
  return new URL(pathName, config.baseUrl.replace(/\/+$/u, "")).toString();
}

function buildPaloAltoCortexXdrIncidentRequest(
  config: PaloAltoCortexXdrApiKeyConfig
) {
  const filters: Array<Record<string, unknown>> = [];

  if (config.creationTimeGte !== undefined) {
    filters.push({
      field: "creation_time",
      operator: "gte",
      value: config.creationTimeGte
    });
  }

  if (config.modificationTimeGte !== undefined) {
    filters.push({
      field: "modification_time",
      operator: "gte",
      value: config.modificationTimeGte
    });
  }

  if (config.incidentStatuses?.length) {
    filters.push({
      field: "status",
      operator: "in",
      value: config.incidentStatuses
    });
  }

  if (config.alertSources?.length) {
    filters.push({
      field: "alert_sources",
      operator: "in",
      value: config.alertSources
    });
  }

  return {
    request_data: {
      filters,
      search_from: config.searchFrom,
      search_to: config.searchFrom + config.limit,
      sort: {
        field: config.sortField,
        keyword: config.sortKeyword
      }
    }
  };
}

function paloAltoCortexXdrHeaders(config: PaloAltoCortexXdrApiKeyConfig) {
  return {
    authorization: config.apiKey,
    "content-type": "application/json",
    "x-xdr-auth-id": config.xdrAuthId
  };
}

function paloAltoCortexXdrIncidentRows(
  value: unknown
): PaloAltoCortexXdrIncidentRecord[] {
  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
  const reply =
    record.reply &&
    typeof record.reply === "object" &&
    !Array.isArray(record.reply)
      ? (record.reply as Record<string, unknown>)
      : {};

  for (const rows of [
    reply.incidents,
    reply.results,
    record.incidents,
    record.data,
    record.results
  ]) {
    if (Array.isArray(rows)) {
      return rows.filter(
        (item): item is PaloAltoCortexXdrIncidentRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      );
    }
  }

  return [];
}

async function fetchPaloAltoCortexXdrIncidents(
  config: PaloAltoCortexXdrApiKeyConfig,
  productLabel = "Cortex XDR"
) {
  const response = await connectorFetch(
    paloAltoCortexXdrApiUrl(config, "/public_api/v1/incidents/get_incidents"),
    {
      body: JSON.stringify(buildPaloAltoCortexXdrIncidentRequest(config)),
      headers: paloAltoCortexXdrHeaders(config),
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(
      `${productLabel} incident query returned status ${response.status}.`
    );
  }

  return paloAltoCortexXdrIncidentRows(
    await readPaloAltoCortexXdrJson(response)
  );
}

function paloAltoCortexXdrIncidentTimestamp(
  incident: PaloAltoCortexXdrIncidentRecord,
  fallback: string
) {
  for (const key of ["creation_time", "modification_time", "detection_time"]) {
    const value = incident[key];

    if (typeof value === "number" && Number.isFinite(value)) {
      return new Date(value).toISOString();
    }

    if (typeof value === "string" && /^\d+$/u.test(value)) {
      return new Date(Number(value)).toISOString();
    }
  }

  return fallback;
}

function paloAltoCortexXdrIncidentIndicatesBlocked(
  incident: PaloAltoCortexXdrIncidentRecord
) {
  const normalized = JSON.stringify(incident).replace(/[_-]+/gu, " ");

  return /\b(blocked|prevented|remediated|contained|isolated|quarantined|resolved|response successful|mitigated)\b/iu.test(
    normalized
  );
}

