async function getPaloAltoCortexXdrHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(PALO_ALTO_CORTEX_XDR_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = PaloAltoCortexXdrApiKeyConfigSchema.parse(context.config);
  const incidents = await fetchPaloAltoCortexXdrIncidents({
    ...config,
    limit: 1
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Cortex XDR incident read access verified; ${incidents.length} sample incident record(s) accessible.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observePaloAltoCortexXdrControl(
  context: ConnectorExecutionContext
) {
  const startedAt = Date.now();

  if (context.mockMode) {
    const outcome = normalizePaloAltoCortexXdrOutcome(
      context.config.fixtureOutcome
    );

    return {
      confidence:
        outcome === "Missed" || outcome === "NoEvidence" ? 0.58 : 0.82,
      detail:
        outcome === "Missed" || outcome === "NoEvidence"
          ? "Cortex XDR fixture contains no incident evidence for the validation context."
          : "Cortex XDR fixture contains incident evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome,
      sourceType: "palo_alto_cortex_xdr.incidents.observer"
    };
  }

  try {
    const config = PaloAltoCortexXdrApiKeyConfigSchema.parse(context.config);
    const incidents = await fetchPaloAltoCortexXdrIncidents(config);

    if (incidents.length === 0) {
      return {
        confidence: 0.62,
        detail:
          "Cortex XDR incident query completed but returned no matching endpoint evidence.",
        latencyMs: Date.now() - startedAt,
        outcome: "Missed",
        sourceType: "palo_alto_cortex_xdr.incidents.observer"
      };
    }

    const blocked = incidents.some((incident) =>
      paloAltoCortexXdrIncidentIndicatesBlocked(incident)
    );

    return {
      confidence: blocked ? 0.86 : 0.8,
      detail: blocked
        ? "Cortex XDR returned resolved, prevented, or containment incident evidence for the validation context."
        : "Cortex XDR returned incident evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome: blocked ? "Blocked" : "Detected",
      sourceType: "palo_alto_cortex_xdr.incidents.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Cortex XDR incident lookup failed: ${paloAltoCortexXdrErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "palo_alto_cortex_xdr.incidents.observer"
    };
  }
}

