function fastlyNextGenWafErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Fastly Next-Gen WAF API error.";
}

async function readFastlyNextGenWafJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function fastlyNextGenWafApiUrl(
  config: FastlyNextGenWafApiTokenConfig,
  pathName: string
) {
  const baseUrl = config.baseUrl.replace(/\/+$/u, "");
  const normalizedPath = pathName.startsWith("/") ? pathName : `/${pathName}`;

  return `${baseUrl}${normalizedPath}`;
}

function buildFastlyNextGenWafEventsUrl(
  config: FastlyNextGenWafApiTokenConfig
) {
  const url = new URL(
    fastlyNextGenWafApiUrl(
      config,
      `/corps/${encodeURIComponent(config.corpName)}/sites/${encodeURIComponent(
        config.siteName
      )}/events`
    )
  );

  url.searchParams.set("limit", String(config.limit));

  if (config.from !== undefined) {
    url.searchParams.set("from", String(config.from));
  }

  if (config.until !== undefined) {
    url.searchParams.set("until", String(config.until));
  }

  return url.toString();
}

function fastlyNextGenWafHeaders(config: FastlyNextGenWafApiTokenConfig) {
  return {
    "content-type": "application/json",
    "x-api-token": config.apiToken,
    "x-api-user": config.email
  };
}

function fastlyNextGenWafEventRows(
  value: unknown
): FastlyNextGenWafEventRecord[] {
  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};

  for (const key of ["data", "events", "results", "items"]) {
    const rows = record[key];

    if (Array.isArray(rows)) {
      return rows.filter(
        (item): item is FastlyNextGenWafEventRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      );
    }
  }

  return [];
}

async function fetchFastlyNextGenWafEvents(
  config: FastlyNextGenWafApiTokenConfig
) {
  const response = await connectorFetch(
    buildFastlyNextGenWafEventsUrl(config),
    {
      headers: fastlyNextGenWafHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Fastly Next-Gen WAF event query returned status ${response.status}.`
    );
  }

  return fastlyNextGenWafEventRows(await readFastlyNextGenWafJson(response));
}

function fastlyNextGenWafEventTimestamp(
  event: FastlyNextGenWafEventRecord,
  fallback: string
) {
  for (const key of ["timestamp", "created", "createdAt", "time"]) {
    const value = event[key];

    if (typeof value === "string" && value.length > 0) {
      const parsed = new Date(value);

      if (!Number.isNaN(parsed.getTime())) {
        return parsed.toISOString();
      }
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return new Date(
        value * (value < 10_000_000_000 ? 1000 : 1)
      ).toISOString();
    }
  }

  return fallback;
}

function fastlyNextGenWafEventIndicatesBlocked(
  event: FastlyNextGenWafEventRecord
) {
  const normalized = JSON.stringify(event).replace(/[_-]+/gu, " ");

  return /\b(block|blocked|flagged|rate limit|rate limited|deny|denied|mitigated|attack)\b/iu.test(
    normalized
  );
}

