function normalizeAkamaiHost(host: string) {
  return host.replace(/^https?:\/\//iu, "").replace(/\/+$/u, "");
}

function buildAkamaiSiemEventsUrl(config: AkamaiSiemEdgeGridConfig) {
  const host = normalizeAkamaiHost(config.host);
  const url = new URL(
    `https://${host}/siem/v1/configs/${encodeURIComponent(config.configId)}`
  );

  url.searchParams.set("limit", String(config.limit));

  if (config.offset) {
    url.searchParams.set("offset", config.offset);
  } else {
    if (config.from !== undefined) {
      url.searchParams.set("from", String(config.from));
    }

    if (config.to !== undefined) {
      url.searchParams.set("to", String(config.to));
    }
  }

  return url;
}

function formatAkamaiTimestamp(date = new Date()) {
  const padded = (value: number) => String(value).padStart(2, "0");

  return `${date.getUTCFullYear()}${padded(
    date.getUTCMonth() + 1
  )}${padded(date.getUTCDate())}T${padded(date.getUTCHours())}:${padded(
    date.getUTCMinutes()
  )}:${padded(date.getUTCSeconds())}+0000`;
}

function createAkamaiEdgeGridAuthorization(input: {
  config: AkamaiSiemEdgeGridConfig;
  method: "GET";
  nonce?: string;
  timestamp?: string;
  url: URL;
}) {
  const timestamp = input.timestamp ?? formatAkamaiTimestamp();
  const nonce = input.nonce ?? randomUUID();
  const authData = `EG1-HMAC-SHA256 client_token=${input.config.clientToken};access_token=${input.config.accessToken};timestamp=${timestamp};nonce=${nonce};`;
  const dataToSign = [
    input.method,
    input.url.protocol.replace(/:$/u, ""),
    input.url.host,
    `${input.url.pathname}${input.url.search}`,
    authData
  ].join("\t");
  const signingKey = createHmac("sha256", input.config.clientSecret)
    .update(timestamp)
    .digest("base64");
  const signature = createHmac("sha256", signingKey)
    .update(dataToSign)
    .digest("base64");

  return `${authData}signature=${signature}`;
}

function akamaiSiemHeaders(config: AkamaiSiemEdgeGridConfig, url: URL) {
  return {
    accept: "application/json",
    authorization: createAkamaiEdgeGridAuthorization({
      config,
      method: "GET",
      url
    })
  };
}

function akamaiRecordLooksLikeMetadata(record: AkamaiSiemEventRecord) {
  return (
    "ResponseContext" in record ||
    "offset" in record ||
    "responseContext" in record
  );
}

function akamaiSiemEventRowsFromUnknown(
  value: unknown
): AkamaiSiemEventRecord[] {
  if (Array.isArray(value)) {
    return value.filter(
      (item): item is AkamaiSiemEventRecord =>
        Boolean(item) &&
        typeof item === "object" &&
        !Array.isArray(item) &&
        !akamaiRecordLooksLikeMetadata(item as AkamaiSiemEventRecord)
    );
  }

  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};

  for (const key of ["events", "data", "results", "items"]) {
    const rows = record[key];

    if (Array.isArray(rows)) {
      return akamaiSiemEventRowsFromUnknown(rows);
    }
  }

  return akamaiRecordLooksLikeMetadata(record) ||
    Object.keys(record).length === 0
    ? []
    : [record];
}

function parseAkamaiSiemEvents(text: string): AkamaiSiemEventRecord[] {
  const trimmed = text.trim();

  if (!trimmed) {
    return [];
  }

  try {
    return akamaiSiemEventRowsFromUnknown(JSON.parse(trimmed));
  } catch {
    return trimmed
      .split(/\r?\n/u)
      .map((line) => line.trim())
      .filter(Boolean)
      .flatMap((line) => {
        try {
          return akamaiSiemEventRowsFromUnknown(JSON.parse(line));
        } catch {
          return [];
        }
      });
  }
}

async function fetchAkamaiSiemEvents(config: AkamaiSiemEdgeGridConfig) {
  const url = buildAkamaiSiemEventsUrl(config);
  const response = await connectorFetch(url.toString(), {
    headers: akamaiSiemHeaders(config, url),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(
      `Akamai SIEM security event query returned status ${response.status}.`
    );
  }

  return parseAkamaiSiemEvents(await response.text());
}

function akamaiSiemEventTimestamp(
  event: AkamaiSiemEventRecord,
  fallback: string
) {
  for (const key of ["eventTime", "eventTimestamp", "timestamp", "time"]) {
    const value = event[key];

    if (typeof value === "string" && value.length > 0) {
      const parsed = new Date(value);

      if (!Number.isNaN(parsed.getTime())) {
        return parsed.toISOString();
      }

      if (/^\d+$/u.test(value)) {
        return new Date(Number(value)).toISOString();
      }
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return new Date(
        value * (value < 10_000_000_000 ? 1000 : 1)
      ).toISOString();
    }
  }

  return fallback;
}

function akamaiSiemEventIndicatesBlocked(event: AkamaiSiemEventRecord) {
  const normalized = JSON.stringify(event).replace(/[_-]+/gu, " ");

  return /\b(block|blocked|deny|denied|mitigated|alert|attack|drop|dropped)\b/iu.test(
    normalized
  );
}

