function createAkamaiWafSignals(input: { events: AkamaiSiemEventRecord[] }) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: "akamai-kona://siem/events",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "WafSecurityEventObservation",
      sourceType: "akamai_kona.siem_events.metadata",
      timestampObserved
    })
  ];

  for (const [index, event] of input.events.entries()) {
    const eventId =
      typeof event.requestId === "string" ||
      typeof event.eventId === "string" ||
      typeof event.uuid === "string"
        ? String(event.requestId ?? event.eventId ?? event.uuid)
        : String(index + 1);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.8,
        freshness: "Fresh",
        rawPayloadPointer: `akamai-kona://siem/events/${eventId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: akamaiSiemEventIndicatesBlocked(event)
          ? "WafSecurityEventBlocked"
          : "WafSecurityEventDetected",
        sourceType: "akamai_kona.siem_event",
        timestampObserved: akamaiSiemEventTimestamp(event, timestampObserved)
      })
    );
  }

  if (input.events.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "akamai-kona://siem/events/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoWafSecurityEventEvidence",
        sourceType: "akamai_kona.siem_events.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadAkamaiWafFixtureEvents(config: Record<string, unknown>) {
  const outcome = normalizeAkamaiWafOutcome(config.fixtureOutcome);

  if (outcome === "Missed" || outcome === "NoEvidence") {
    return [];
  }

  return [
    {
      action: outcome === "Blocked" ? "deny" : "alert",
      attackData: {
        ruleId: "981176",
        ruleMessage: "SQL Injection Attack"
      },
      eventTime: "2026-06-01T18:30:00Z",
      requestId: "akamai-event-1",
      securityConfigId: "12345"
    }
  ];
}

async function getAkamaiWafHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AKAMAI_KONA_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = AkamaiSiemEdgeGridConfigSchema.parse(context.config);
  const events = await fetchAkamaiSiemEvents({
    ...config,
    limit: 1
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Akamai SIEM read access verified; ${events.length} sample security event record(s) accessible.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observeAkamaiWafControl(context: ConnectorExecutionContext) {
  const startedAt = Date.now();

  if (context.mockMode) {
    const outcome = normalizeAkamaiWafOutcome(context.config.fixtureOutcome);

    return {
      confidence: outcome === "Missed" || outcome === "NoEvidence" ? 0.58 : 0.8,
      detail:
        outcome === "Missed" || outcome === "NoEvidence"
          ? "Akamai WAF fixture contains no SIEM security-event evidence for the validation context."
          : "Akamai WAF fixture contains SIEM security-event evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome,
      sourceType: "akamai_kona.siem_events.observer"
    };
  }

  try {
    const config = AkamaiSiemEdgeGridConfigSchema.parse(context.config);
    const events = await fetchAkamaiSiemEvents(config);

    if (events.length === 0) {
      return {
        confidence: 0.62,
        detail:
          "Akamai SIEM security-event query completed but returned no matching WAF evidence.",
        latencyMs: Date.now() - startedAt,
        outcome: "Missed",
        sourceType: "akamai_kona.siem_events.observer"
      };
    }

    const blocked = events.some((event) =>
      akamaiSiemEventIndicatesBlocked(event)
    );

    return {
      confidence: blocked ? 0.84 : 0.78,
      detail: blocked
        ? "Akamai SIEM returned blocked, denied, or attack security-event evidence for the validation context."
        : "Akamai SIEM returned security-event evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome: blocked ? "Blocked" : "Detected",
      sourceType: "akamai_kona.siem_events.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Akamai SIEM security-event lookup failed: ${akamaiWafErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "akamai_kona.siem_events.observer"
    };
  }
}

