function impervaErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Imperva Cloud WAF API error.";
}

function buildImpervaSitesListUrl(config: ImpervaCloudWafApiKeyConfig) {
  const baseUrl = config.baseUrl.replace(/\/+$/u, "");

  return `${baseUrl}/api/prov/v1/sites/list`;
}

function impervaSitesListBody(config: ImpervaCloudWafApiKeyConfig) {
  const body = new URLSearchParams();

  body.set("api_id", config.accessId);
  body.set("api_key", config.apiKey);
  body.set("page_num", String(config.pageNum));
  body.set("page_size", String(config.pageSize));

  return body;
}

async function readImpervaJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function impervaSiteRows(value: unknown): ImpervaCloudWafSiteRecord[] {
  const record =
    value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};

  for (const key of ["sites", "data", "items", "results"]) {
    const rows = record[key];

    if (Array.isArray(rows)) {
      return rows.filter(
        (item): item is ImpervaCloudWafSiteRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      );
    }
  }

  return [];
}

async function fetchImpervaCloudWafSites(config: ImpervaCloudWafApiKeyConfig) {
  const response = await connectorFetch(buildImpervaSitesListUrl(config), {
    body: impervaSitesListBody(config),
    headers: {
      accept: "application/json",
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(
      `Imperva Cloud WAF sites list returned status ${response.status}.`
    );
  }

  const json = await readImpervaJson(response);
  const resultCode = json.res;

  if (
    resultCode !== undefined &&
    resultCode !== 0 &&
    resultCode !== "0" &&
    resultCode !== "OK"
  ) {
    throw new Error(
      `Imperva Cloud WAF sites list returned API result ${String(resultCode)}.`
    );
  }

  return impervaSiteRows(json);
}

function impervaSiteId(site: ImpervaCloudWafSiteRecord, fallback: string) {
  const value = site.site_id ?? site.id;

  return typeof value === "string" || typeof value === "number"
    ? String(value)
    : fallback;
}

function impervaSiteName(site: ImpervaCloudWafSiteRecord) {
  for (const key of ["display_name", "domain", "name"]) {
    const value = site[key];

    if (typeof value === "string" && value.length > 0) {
      return value;
    }
  }

  return "Imperva Cloud WAF site";
}

function impervaSiteTimestamp(
  site: ImpervaCloudWafSiteRecord,
  fallback: string
) {
  const value = site.site_creation_date ?? site.created_at;

  if (typeof value === "number" && Number.isFinite(value)) {
    return new Date(value).toISOString();
  }

  if (typeof value === "string" && /^\d+$/u.test(value)) {
    return new Date(Number(value)).toISOString();
  }

  if (typeof value === "string") {
    const parsed = new Date(value);

    if (!Number.isNaN(parsed.getTime())) {
      return parsed.toISOString();
    }
  }

  return fallback;
}

function impervaSiteWafRules(site: ImpervaCloudWafSiteRecord) {
  const security =
    site.security &&
    typeof site.security === "object" &&
    !Array.isArray(site.security)
      ? (site.security as Record<string, unknown>)
      : {};
  const waf =
    security.waf &&
    typeof security.waf === "object" &&
    !Array.isArray(security.waf)
      ? (security.waf as Record<string, unknown>)
      : {};
  const rules = waf.rules;

  return Array.isArray(rules)
    ? rules.filter(
        (rule): rule is Record<string, unknown> =>
          Boolean(rule) && typeof rule === "object" && !Array.isArray(rule)
      )
    : [];
}

function impervaWafRuleIndicatesBlocked(rule: Record<string, unknown>) {
  const normalized = JSON.stringify(rule).replace(/[_-]+/gu, " ");

  return /\b(block|quarantine|deny|captcha|challenge|block ip)\b/iu.test(
    normalized
  );
}

function impervaWafRuleIndicatesDetected(rule: Record<string, unknown>) {
  const normalized = JSON.stringify(rule).replace(/[_-]+/gu, " ");

  return /\b(alert|count|log|monitor|enabled)\b/iu.test(normalized);
}

function impervaSitesIndicateBlocked(sites: ImpervaCloudWafSiteRecord[]) {
  return sites.some((site) =>
    impervaSiteWafRules(site).some((rule) =>
      impervaWafRuleIndicatesBlocked(rule)
    )
  );
}

function impervaSitesIndicateDetected(sites: ImpervaCloudWafSiteRecord[]) {
  return sites.some((site) =>
    impervaSiteWafRules(site).some(
      (rule) =>
        impervaWafRuleIndicatesDetected(rule) ||
        impervaWafRuleIndicatesBlocked(rule)
    )
  );
}

function createImpervaAssets(sites: ImpervaCloudWafSiteRecord[]) {
  return sites.map((site, index) =>
    createMockAsset({
      assetType: "Domain",
      businessCriticality: impervaSitesIndicateBlocked([site])
        ? "High"
        : "Moderate",
      environment: "edge",
      identifiers: {
        accountId: site.account_id ?? null,
        domain: site.domain ?? null,
        provider: "imperva",
        siteId: impervaSiteId(site, String(index + 1))
      },
      internetExposed: true,
      name: `imperva/${impervaSiteName(site)}`,
      owner: "edge-security",
      status: site.active === "bypass" ? "Inactive" : "Active",
      tags: ["waf", "firewall", "imperva", "cloud-waf"]
    })
  );
}

function createImpervaSignals(input: { sites: ImpervaCloudWafSiteRecord[] }) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const [index, site] of input.sites.entries()) {
    const siteId = impervaSiteId(site, String(index + 1));
    const rules = impervaSiteWafRules(site);
    const sitePointer = `imperva://sites/${siteId}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: sitePointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "WafProtectedSite",
        sourceType: "imperva.cloud_waf.site",
        timestampObserved: impervaSiteTimestamp(site, timestampObserved)
      })
    );

    if (site.active === "bypass") {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `${sitePointer}/status`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Exposure",
          signalSubcategory: "WafBypassMode",
          sourceType: "imperva.cloud_waf.site_status",
          timestampObserved
        })
      );
    }

    for (const [ruleIndex, rule] of rules.entries()) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `${sitePointer}/waf-rules/${String(
            rule.id ?? ruleIndex + 1
          )}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: impervaWafRuleIndicatesBlocked(rule)
            ? "High"
            : "Moderate",
          signalCategory: "ControlObservation",
          signalSubcategory: impervaWafRuleIndicatesBlocked(rule)
            ? "WafRuleBlocking"
            : "WafRuleAlertOnly",
          sourceType: "imperva.cloud_waf.rule_posture",
          timestampObserved
        })
      );
    }
  }

  if (input.sites.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "imperva://sites/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoWafSiteEvidence",
        sourceType: "imperva.cloud_waf.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

