async function getImpervaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(IMPERVA_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = ImpervaCloudWafApiKeyConfigSchema.parse(context.config);
  const sites = await fetchImpervaCloudWafSites({
    ...config,
    pageSize: Math.min(config.pageSize, 1)
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Imperva Cloud WAF read access verified; ${sites.length} sample site record(s) accessible.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observeImpervaControl(context: ConnectorExecutionContext) {
  const startedAt = Date.now();

  if (context.mockMode) {
    const outcome = normalizeImpervaWafOutcome(context.config.fixtureOutcome);

    return {
      confidence: outcome === "Missed" || outcome === "NoEvidence" ? 0.58 : 0.8,
      detail:
        outcome === "Missed" || outcome === "NoEvidence"
          ? "Imperva Cloud WAF fixture contains no protected-site or WAF-rule evidence."
          : "Imperva Cloud WAF fixture contains protected-site and WAF-rule evidence.",
      latencyMs: Date.now() - startedAt,
      outcome,
      sourceType: "imperva.cloud_waf.observer"
    };
  }

  try {
    const config = ImpervaCloudWafApiKeyConfigSchema.parse(context.config);
    const sites = await fetchImpervaCloudWafSites(config);

    if (sites.length === 0) {
      return {
        confidence: 0.62,
        detail:
          "Imperva Cloud WAF site query completed but returned no protected-site evidence.",
        latencyMs: Date.now() - startedAt,
        outcome: "Missed",
        sourceType: "imperva.cloud_waf.observer"
      };
    }

    if (impervaSitesIndicateBlocked(sites)) {
      return {
        confidence: 0.82,
        detail:
          "Imperva Cloud WAF returned protected-site posture with blocking WAF rules configured.",
        latencyMs: Date.now() - startedAt,
        outcome: "Blocked",
        sourceType: "imperva.cloud_waf.observer"
      };
    }

    return {
      confidence: impervaSitesIndicateDetected(sites) ? 0.76 : 0.66,
      detail: impervaSitesIndicateDetected(sites)
        ? "Imperva Cloud WAF returned protected-site posture with alerting WAF rules configured."
        : "Imperva Cloud WAF returned protected-site posture but no explicit blocking or alerting WAF rules.",
      latencyMs: Date.now() - startedAt,
      outcome: impervaSitesIndicateDetected(sites) ? "Detected" : "NoEvidence",
      sourceType: "imperva.cloud_waf.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Imperva Cloud WAF lookup failed: ${impervaErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "imperva.cloud_waf.observer"
    };
  }
}

