function ziaErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown ZIA API error.";
}

async function fetchZiaAccessToken(config: ZscalerZiaOAuthConfig) {
  const body = new URLSearchParams();

  body.set("grant_type", "client_credentials");
  body.set("client_id", config.clientId);
  body.set("client_secret", config.clientSecret);

  if (config.scope) {
    body.set("scope", config.scope);
  }

  const response = await connectorFetch(config.tokenUrl, {
    body,
    headers: {
      accept: "application/json",
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(
      `ZIA OAuth token request returned status ${response.status}.`
    );
  }

  const json = await response.json();

  if (
    typeof json !== "object" ||
    json === null ||
    typeof (json as ZscalerZiaRecord).access_token !== "string"
  ) {
    throw new Error("ZIA OAuth token response did not include access_token.");
  }

  return (json as { access_token: string }).access_token;
}

function ziaApiUrl(config: ZscalerZiaOAuthConfig, path: string) {
  const baseUrl = config.apiBaseUrl.replace(/\/+$/u, "");

  return new URL(path.replace(/^\/+/u, ""), `${baseUrl}/`);
}

async function fetchZiaJson(
  config: ZscalerZiaOAuthConfig,
  accessToken: string,
  path: string,
  query?: Record<string, string | number | undefined>
) {
  const url = ziaApiUrl(config, path);

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== undefined) {
      url.searchParams.set(key, String(value));
    }
  }

  const response = await connectorFetch(url, {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${accessToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`ZIA API request returned status ${response.status}.`);
  }

  return response.json();
}

function ziaRecordsFromResults(value: unknown): ZscalerZiaRecord[] {
  if (Array.isArray(value)) {
    return value.filter(
      (item): item is ZscalerZiaRecord =>
        typeof item === "object" && item !== null && !Array.isArray(item)
    );
  }

  if (typeof value === "object" && value !== null && !Array.isArray(value)) {
    return [value as ZscalerZiaRecord];
  }

  return [];
}

function ziaRulesFromJson(json: unknown) {
  if (typeof json === "object" && json !== null && "results" in json) {
    return ziaRecordsFromResults((json as ZscalerZiaRecord).results);
  }

  return ziaRecordsFromResults(json);
}

async function fetchZiaFirewallRuleCount(config: ZscalerZiaOAuthConfig) {
  const token = await fetchZiaAccessToken(config);
  const json = await fetchZiaJson(
    config,
    token,
    "/firewallFilteringRules/count"
  );

  if (typeof json === "number") {
    return json;
  }

  if (typeof json === "object" && json !== null) {
    for (const key of ["count", "total", "totalPages", "totalCount"]) {
      const value = (json as ZscalerZiaRecord)[key];

      if (typeof value === "number") {
        return value;
      }

      if (typeof value === "string" && value.length > 0) {
        const parsed = Number(value);

        if (!Number.isNaN(parsed)) {
          return parsed;
        }
      }
    }
  }

  return 0;
}

async function fetchZiaFirewallRules(config: ZscalerZiaOAuthConfig) {
  const token = await fetchZiaAccessToken(config);
  const json = await fetchZiaJson(config, token, "/firewallFilteringRules", {
    page: config.page,
    pageSize: config.pageSize
  });

  return ziaRulesFromJson(json);
}

function ziaRuleId(rule: ZscalerZiaRecord, fallback: string) {
  for (const key of ["id", "ruleId", "name", "order", "rank"]) {
    const value = rule[key];

    if (typeof value === "string" && value.length > 0) {
      return value;
    }

    if (typeof value === "number") {
      return String(value);
    }
  }

  return fallback;
}

function ziaRuleIndicatesBlocked(rule: ZscalerZiaRecord) {
  const action = String(rule.action ?? rule.ruleAction ?? "").toLowerCase();

  if (/\b(block|blocked|deny|denied|drop|reset)\b/iu.test(action)) {
    return true;
  }

  return /\b(block|blocked|deny|denied|drop|reset)\b/iu.test(
    JSON.stringify(rule).replace(/[_-]+/gu, " ")
  );
}

