function createZiaSignals(input: {
  ruleCount?: number;
  rules: ZscalerZiaRecord[];
}) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: "zscaler-zia://firewallFilteringRules/count",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "FirewallFilteringRuleCount",
      sourceType: "zscaler_zia.firewall_filtering_rules.count",
      timestampObserved
    })
  ];

  for (const [index, rule] of input.rules.entries()) {
    const ruleId = ziaRuleId(rule, String(index + 1));

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.8,
        freshness: "Fresh",
        rawPayloadPointer: `zscaler-zia://firewallFilteringRules/${ruleId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: ziaRuleIndicatesBlocked(rule)
          ? "FirewallFilteringRuleBlocking"
          : "FirewallFilteringRuleDetected",
        sourceType: "zscaler_zia.firewall_filtering_rule",
        timestampObserved
      })
    );
  }

  if (input.rules.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.58,
        freshness: "Fresh",
        rawPayloadPointer: "zscaler-zia://firewallFilteringRules/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoFirewallFilteringRuleEvidence",
        sourceType: "zscaler_zia.firewall_filtering_rules.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadZiaFixtureRules(config: Record<string, unknown>) {
  const outcome = normalizeZscalerZiaOutcome(config.fixtureOutcome);

  if (outcome === "Missed" || outcome === "NoEvidence") {
    return [];
  }

  return [
    {
      action: outcome === "Blocked" ? "BLOCK_DROP" : "ALLOW",
      id: 1000,
      name: "Periscan validation firewall filtering rule",
      order: 1,
      rank: 1
    }
  ];
}

