function sentinelOneApiUrl(
  config: SentinelOneApiTokenConfig,
  pathName: string
) {
  return new URL(pathName, config.baseUrl.replace(/\/+$/u, "")).toString();
}

function sentinelOneHeaders(config: SentinelOneApiTokenConfig) {
  return {
    accept: "application/json",
    authorization: `ApiToken ${config.apiToken}`
  };
}

function sentinelOneErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown SentinelOne API error.";
}

async function readSentinelOneJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function sentinelOneSafeQueryTerm(value: string) {
  return value.replace(/[^\w./: -]/gu, "").slice(0, 128);
}

function buildSentinelOneThreatsUrl(
  config: SentinelOneApiTokenConfig,
  context?: ConnectorExecutionContext
) {
  const url = new URL(sentinelOneApiUrl(config, "/web/api/v2.1/threats"));

  url.searchParams.set("limit", String(config.limit));
  url.searchParams.set("sortBy", "createdAt");
  url.searchParams.set("sortOrder", "desc");

  const techniqueId =
    context &&
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? sentinelOneSafeQueryTerm(context.config.techniqueId)
      : null;
  const query = config.query ?? (techniqueId ? `periscan ${techniqueId}` : "");

  if (query.length > 0) {
    url.searchParams.set("query", query);
  }

  if (config.createdAtGte) {
    url.searchParams.set("createdAt__gte", config.createdAtGte);
  }

  for (const [key, values] of [
    ["accountIds", config.accountIds],
    ["siteIds", config.siteIds],
    ["groupIds", config.groupIds]
  ] as const) {
    if (values && values.length > 0) {
      url.searchParams.set(key, values.join(","));
    }
  }

  return url.toString();
}

async function fetchSentinelOneThreats(
  config: SentinelOneApiTokenConfig,
  context?: ConnectorExecutionContext
) {
  const response = await connectorFetch(
    buildSentinelOneThreatsUrl(config, context),
    {
      headers: sentinelOneHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(
      `SentinelOne threats query returned status ${response.status}.`
    );
  }

  return SentinelOneThreatsResponseSchema.parse(
    await readSentinelOneJson(response)
  );
}

function sentinelOneValueAtPath(value: unknown, path: string[]) {
  let current: unknown = value;

  for (const segment of path) {
    if (!current || typeof current !== "object" || Array.isArray(current)) {
      return null;
    }

    current = (current as Record<string, unknown>)[segment];
  }

  return current;
}

function sentinelOneThreatText(threat: Record<string, unknown>) {
  return JSON.stringify(threat).toLowerCase();
}

function sentinelOneThreatIndicatesBlocked(threat: Record<string, unknown>) {
  const values = [
    sentinelOneValueAtPath(threat, ["threatInfo", "mitigationStatus"]),
    sentinelOneValueAtPath(threat, ["threatInfo", "incidentStatus"]),
    sentinelOneValueAtPath(threat, ["threatInfo", "analystVerdict"]),
    threat.mitigationStatus,
    threat.incidentStatus,
    threat.status
  ]
    .filter((value): value is string => typeof value === "string")
    .join(" ");

  return /\b(blocked|mitigated|remediated|quarantined|killed|prevented|rollback)\b/iu.test(
    `${values} ${sentinelOneThreatText(threat)}`
  );
}

// Extract MITRE ATT&CK technique ids (T####[.###]) from a SentinelOne threat's
// indicators/tactics (or an explicit mitreTechniqueIds field) so the resulting
// ControlObservation signal drives control-rule coverage instead of being inert
// — mirrors the Cortex XDR extractor.
function sentinelOneThreatTechniqueIds(
  threat: Record<string, unknown>
): string[] {
  const haystack = JSON.stringify([
    threat.indicators,
    sentinelOneValueAtPath(threat, ["threatInfo", "mitreTechniqueIds"]),
    threat.mitre
  ]);
  const matches = haystack.match(/T\d{4}(?:\.\d{3})?/gu) ?? [];
  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

// Host/IP hints from a SentinelOne threat's agent info, resolved to tenant asset
// ids during sync so the endpoint telemetry is attributed to the right asset.
function sentinelOneThreatAssetHints(
  threat: Record<string, unknown>
): string[] {
  const hints = [
    sentinelOneValueAtPath(threat, ["agentRealtimeInfo", "agentComputerName"]),
    sentinelOneValueAtPath(threat, ["agentDetectionInfo", "agentIpV4"]),
    sentinelOneValueAtPath(threat, ["agentRealtimeInfo", "agentIpV4"])
  ].filter(
    (value): value is string => typeof value === "string" && value.length > 0
  );
  return [...new Set(hints)];
}

