async function listGitHubRepositories(config: GitHubPatConfig) {
  if (config.repositoryFullNames && config.repositoryFullNames.length > 0) {
    const repositories = await Promise.all(
      config.repositoryFullNames.map((fullName) =>
        fetchGitHubJson<unknown>(config, `/repos/${fullName}`)
      )
    );

    return repositories.map((repository) =>
      GitHubRepositorySchema.parse(repository)
    );
  }

  const pathName = config.organization
    ? `/orgs/${config.organization}/repos?per_page=100&type=all`
    : "/user/repos?per_page=100&type=all";

  return fetchGitHubArray(config, pathName, GitHubRepositorySchema);
}

async function getGitHubBranchProtection(
  config: GitHubPatConfig,
  repository: GitHubRepository
) {
  const defaultBranch = repository.default_branch;

  if (!defaultBranch) {
    return null;
  }

  try {
    await fetchGitHubJson<unknown>(
      config,
      `/repos/${repository.full_name}/branches/${defaultBranch}/protection`
    );

    return true;
  } catch (error) {
    if (error instanceof GitHubHttpError && error.status === 404) {
      return false;
    }

    return null;
  }
}

function createGitHubAssets(
  repositories: GitHubRepository[]
): ConnectorAssetInput[] {
  return repositories.map((repository) =>
    createMockAsset({
      assetType: "Repository",
      businessCriticality: repository.private ? "High" : "Moderate",
      environment: "production",
      identifiers: {
        archived: repository.archived,
        defaultBranch: repository.default_branch ?? null,
        fullName: repository.full_name,
        visibility:
          repository.visibility ?? (repository.private ? "private" : "public")
      },
      internetExposed: !repository.private,
      name: repository.full_name,
      owner: repository.owner?.login ?? "unknown",
      status: repository.archived ? "Inactive" : "Active",
      tags: [
        "code",
        "github",
        `permission:${getGitHubPermissionLabel(repository).toLowerCase()}`,
        repository.visibility ?? (repository.private ? "private" : "public")
      ]
    })
  );
}

async function createGitHubSignals(
  config: GitHubPatConfig,
  repositories: GitHubRepository[]
): Promise<ConnectorSignalInput[]> {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const repository of repositories) {
    const repoBase = `github://repo/${repository.full_name}`;
    const branchProtection = await getGitHubBranchProtection(
      config,
      repository
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.91,
        freshness: "Fresh",
        rawPayloadPointer: repoBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: repository.private ? "Moderate" : "Low",
        signalCategory: "Repository",
        signalSubcategory: "Repository",
        sourceType: "github.repository.metadata",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: branchProtection === null ? 0.55 : 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `${repoBase}/branch-protection`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory:
          branchProtection === true
            ? "BranchProtection"
            : "BranchProtectionMissing",
        sourceType: "github.repository.branch_protection",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `${repoBase}/permissions`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory: "RepoPermission",
        sourceType: "github.repository.permission",
        timestampObserved
      })
    );
  }

  return signals;
}

async function getGitHubHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GITHUB_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = GitHubPatConfigSchema.parse(context.config);
  const viewer = GitHubViewerSchema.parse(
    await fetchGitHubJson(config, "/user")
  );

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `GitHub PAT verified for ${viewer.login}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createGitHubConnector(): Connector {
  return {
    manifest: GITHUB_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createGitHubFixtureSignals();
      }

      const config = GitHubPatConfigSchema.parse(parsedContext.config);
      const repositories = await listGitHubRepositories(config);

      return createGitHubSignals(config, repositories);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGitHubHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return ConnectorSyncResultSchema.parse({
          assets: createGitHubFixtureAssets(),
          health: await getGitHubHealth(parsedContext),
          signals: createGitHubFixtureSignals().map((signal) =>
            createTimestampedSignal(
              GITHUB_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
          )
        });
      }

      const config = GitHubPatConfigSchema.parse(parsedContext.config);
      const repositories = await listGitHubRepositories(config);

      return ConnectorSyncResultSchema.parse({
        assets: createGitHubAssets(repositories),
        health: await getGitHubHealth(parsedContext),
        signals: (await createGitHubSignals(config, repositories)).map(
          (signal) =>
            createTimestampedSignal(
              GITHUB_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
        )
      });
    }
  };
}

