async function getGitLabHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GITLAB_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = GitLabPatConfigSchema.parse(context.config);
  const user = GitLabUserSchema.parse(await fetchGitLabJson(config, "/user"));

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `GitLab PAT verified for ${user.username}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createGitLabConnector(): Connector {
  return {
    manifest: GITLAB_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createGitLabFixtureSignals();
      }

      const config = GitLabPatConfigSchema.parse(parsedContext.config);
      const projects = await listGitLabProjects(config);

      return createGitLabSignals(config, projects);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGitLabHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return ConnectorSyncResultSchema.parse({
          assets: createGitLabAssets(GITLAB_FIXTURE_PROJECTS),
          health: await getGitLabHealth(parsedContext),
          signals: createGitLabFixtureSignals().map((signal) =>
            createTimestampedSignal(
              GITLAB_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
          )
        });
      }

      const config = GitLabPatConfigSchema.parse(parsedContext.config);
      const projects = await listGitLabProjects(config);

      return ConnectorSyncResultSchema.parse({
        assets: createGitLabAssets(projects),
        health: await getGitLabHealth(parsedContext),
        signals: (await createGitLabSignals(config, projects)).map((signal) =>
          createTimestampedSignal(
            GITLAB_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

