class BitbucketHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeBitbucketApiBaseUrl(config: BitbucketAppPasswordConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function bitbucketAuthorizationHeader(config: BitbucketAppPasswordConfig) {
  return `Basic ${Buffer.from(
    `${config.username}:${config.appPassword}`
  ).toString("base64")}`;
}

function bitbucketUrl(config: BitbucketAppPasswordConfig, pathName: string) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeBitbucketApiBaseUrl(config)}${pathName}`;
}

async function fetchBitbucketJson<T>(
  config: BitbucketAppPasswordConfig,
  pathName: string
) {
  const response = await connectorFetch(bitbucketUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: bitbucketAuthorizationHeader(config)
    }
  });

  if (!response.ok) {
    throw new BitbucketHttpError(
      response.status,
      `Bitbucket API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function fetchBitbucketCollection<T>(
  config: BitbucketAppPasswordConfig,
  pathName: string,
  schema: z.ZodType<T>
) {
  const rows: T[] = [];
  let nextPath: string | null = pathName;
  let pageCount = 0;

  while (nextPath && pageCount < 10) {
    const collection = BitbucketPaginatedCollectionSchema.parse(
      await fetchBitbucketJson(config, nextPath)
    );

    rows.push(...collection.values.map((row) => schema.parse(row)));
    nextPath = collection.next ?? null;
    pageCount += 1;
  }

  return rows;
}

function bitbucketRepositorySlug(repository: BitbucketRepository) {
  return (
    repository.slug ?? repository.full_name.split("/").at(-1) ?? repository.name
  );
}

async function listBitbucketRepositories(config: BitbucketAppPasswordConfig) {
  if (config.repositorySlugs && config.repositorySlugs.length > 0) {
    const repositories = await Promise.all(
      config.repositorySlugs.map((repoSlug) =>
        fetchBitbucketJson<unknown>(
          config,
          `/repositories/${encodeURIComponent(
            config.workspace
          )}/${encodeURIComponent(repoSlug)}`
        )
      )
    );

    return repositories.map((repository) =>
      BitbucketRepositorySchema.parse(repository)
    );
  }

  return fetchBitbucketCollection(
    config,
    `/repositories/${encodeURIComponent(config.workspace)}?pagelen=100`,
    BitbucketRepositorySchema
  );
}

async function getBitbucketBranchProtection(
  config: BitbucketAppPasswordConfig,
  repository: BitbucketRepository
) {
  try {
    const restrictions = await fetchBitbucketCollection(
      config,
      `/repositories/${encodeURIComponent(
        config.workspace
      )}/${encodeURIComponent(
        bitbucketRepositorySlug(repository)
      )}/branch-restrictions?pagelen=100`,
      BitbucketBranchRestrictionSchema
    );

    return restrictions.length > 0;
  } catch (error) {
    if (error instanceof BitbucketHttpError && error.status === 404) {
      return false;
    }

    return null;
  }
}

function createBitbucketAssets(
  repositories: BitbucketRepository[]
): ConnectorAssetInput[] {
  return repositories.map((repository) =>
    createMockAsset({
      assetType: "Repository",
      businessCriticality: repository.is_private ? "High" : "Moderate",
      environment: "production",
      identifiers: {
        defaultBranch: repository.mainbranch?.name ?? null,
        fullName: repository.full_name,
        projectKey: repository.project?.key ?? null,
        repoUuid: repository.uuid,
        scm: repository.scm ?? "git",
        slug: bitbucketRepositorySlug(repository),
        visibility: repository.is_private ? "private" : "public"
      },
      internetExposed: !repository.is_private,
      name: repository.full_name,
      owner:
        repository.owner?.nickname ??
        repository.owner?.display_name ??
        "unknown",
      status: "Active",
      tags: [
        "code",
        "bitbucket",
        repository.is_private ? "private" : "public",
        `project:${repository.project?.key ?? "unknown"}`
      ]
    })
  );
}

