async function getBitbucketHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(BITBUCKET_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = BitbucketAppPasswordConfigSchema.parse(context.config);
  const user = BitbucketUserSchema.parse(
    await fetchBitbucketJson(config, "/user")
  );
  const displayName = user.display_name ?? user.nickname ?? user.username;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Bitbucket read-only access verified for ${displayName}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createBitbucketConnector(): Connector {
  return {
    manifest: BITBUCKET_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createBitbucketFixtureSignals();
      }

      const config = BitbucketAppPasswordConfigSchema.parse(
        parsedContext.config
      );
      const repositories = await listBitbucketRepositories(config);

      return createBitbucketSignals(config, repositories);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getBitbucketHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return ConnectorSyncResultSchema.parse({
          assets: createBitbucketAssets(BITBUCKET_FIXTURE_REPOSITORIES),
          health: await getBitbucketHealth(parsedContext),
          signals: createBitbucketFixtureSignals().map((signal) =>
            createTimestampedSignal(
              BITBUCKET_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
          )
        });
      }

      const config = BitbucketAppPasswordConfigSchema.parse(
        parsedContext.config
      );
      const repositories = await listBitbucketRepositories(config);

      return ConnectorSyncResultSchema.parse({
        assets: createBitbucketAssets(repositories),
        health: await getBitbucketHealth(parsedContext),
        signals: (await createBitbucketSignals(config, repositories)).map(
          (signal) =>
            createTimestampedSignal(
              BITBUCKET_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
        )
      });
    }
  };
}

