class AzureDevOpsHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeAzureDevOpsBaseUrl(config: AzureDevOpsPatConfig) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}/${encodeURIComponent(
    config.organization
  )}`;
}

function azureDevOpsAuthorizationHeader(config: AzureDevOpsPatConfig) {
  return `Basic ${Buffer.from(`:${config.pat}`).toString("base64")}`;
}

function azureDevOpsUrl(config: AzureDevOpsPatConfig, pathName: string) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeAzureDevOpsBaseUrl(config)}${pathName}`;
}

async function fetchAzureDevOpsJson<T>(
  config: AzureDevOpsPatConfig,
  pathName: string
) {
  const response = await connectorFetch(azureDevOpsUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: azureDevOpsAuthorizationHeader(config)
    }
  });

  if (!response.ok) {
    throw new AzureDevOpsHttpError(
      response.status,
      `Azure DevOps API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function fetchAzureDevOpsCollection<T>(
  config: AzureDevOpsPatConfig,
  pathName: string,
  schema: z.ZodType<T>
) {
  const collection = AzureDevOpsCollectionSchema.parse(
    await fetchAzureDevOpsJson(config, pathName)
  );

  return collection.value.map((row) => schema.parse(row));
}

function azureDevOpsProjectPath(project: AzureDevOpsProject) {
  return encodeURIComponent(project.name);
}

async function listAzureDevOpsProjects(config: AzureDevOpsPatConfig) {
  if (config.projects && config.projects.length > 0) {
    return config.projects.map((projectName) =>
      AzureDevOpsProjectSchema.parse({
        id: projectName,
        name: projectName,
        state: "configured"
      })
    );
  }

  return fetchAzureDevOpsCollection(
    config,
    "/_apis/projects?$top=100&api-version=7.1",
    AzureDevOpsProjectSchema
  );
}

async function listAzureDevOpsRepositories(
  config: AzureDevOpsPatConfig,
  projects: AzureDevOpsProject[]
) {
  const repositoryGroups = await Promise.all(
    projects.map((project) =>
      fetchAzureDevOpsCollection(
        config,
        `/${azureDevOpsProjectPath(
          project
        )}/_apis/git/repositories?api-version=7.1`,
        AzureDevOpsRepositorySchema
      )
    )
  );

  return repositoryGroups.flat();
}

async function getAzureDevOpsBranchPolicy(
  config: AzureDevOpsPatConfig,
  repository: AzureDevOpsRepository
) {
  try {
    const policies = await fetchAzureDevOpsCollection(
      config,
      `/${azureDevOpsProjectPath(
        repository.project
      )}/_apis/git/policy/configurations?repositoryId=${encodeURIComponent(
        repository.id
      )}&api-version=7.1`,
      AzureDevOpsPolicyConfigurationSchema
    );

    return policies.some((policy) => policy.isEnabled !== false);
  } catch (error) {
    if (error instanceof AzureDevOpsHttpError && error.status === 404) {
      return false;
    }

    return null;
  }
}

function azureDevOpsRepositoryFullName(repository: AzureDevOpsRepository) {
  return `${repository.project.name}/${repository.name}`;
}

function createAzureDevOpsAssets(
  repositories: AzureDevOpsRepository[]
): ConnectorAssetInput[] {
  return repositories.map((repository) =>
    createMockAsset({
      assetType: "Repository",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        defaultBranch: repository.defaultBranch ?? null,
        fullName: azureDevOpsRepositoryFullName(repository),
        isFork: repository.isFork ?? false,
        projectId: repository.project.id,
        projectName: repository.project.name,
        repoId: repository.id,
        webUrl: repository.webUrl ?? null
      },
      internetExposed: false,
      name: azureDevOpsRepositoryFullName(repository),
      owner: repository.project.name,
      status: repository.isDisabled ? "Inactive" : "Active",
      tags: ["code", "azure-devops", `project:${repository.project.name}`]
    })
  );
}

async function createAzureDevOpsSignals(
  config: AzureDevOpsPatConfig,
  repositories: AzureDevOpsRepository[]
): Promise<ConnectorSignalInput[]> {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const repository of repositories) {
    const repoBase = `azure-devops://repo/${azureDevOpsRepositoryFullName(
      repository
    )}`;
    const branchPolicy = await getAzureDevOpsBranchPolicy(config, repository);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: repoBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory: "Repository",
        sourceType: "azure_devops.repository.metadata",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: branchPolicy === null ? 0.55 : 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `${repoBase}/branch-policies`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory:
          branchPolicy === true
            ? "BranchProtection"
            : "BranchProtectionMissing",
        sourceType: "azure_devops.repository.branch_policy",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.78,
        freshness: "Fresh",
        rawPayloadPointer: `${repoBase}/permissions`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory: "RepoPermission",
        sourceType: "azure_devops.repository.permission",
        timestampObserved
      })
    );
  }

  return signals;
}

function createAzureDevOpsFixtureSignals(): ConnectorSignalInput[] {
  return AZURE_DEVOPS_FIXTURE_REPOSITORIES.flatMap((repository) => [
    {
      ...createMockSignal("Repository", "Repository", "Moderate"),
      confidence: 0.9,
      rawPayloadPointer: `azure-devops://repo/${azureDevOpsRepositoryFullName(
        repository
      )}`,
      sourceType: "azure_devops.repository.metadata"
    },
    {
      ...createMockSignal("Repository", "BranchProtection", "Moderate"),
      confidence: 0.88,
      rawPayloadPointer: `azure-devops://repo/${azureDevOpsRepositoryFullName(
        repository
      )}/branch-policies`,
      sourceType: "azure_devops.repository.branch_policy"
    },
    {
      ...createMockSignal("Repository", "RepoPermission", "Moderate"),
      confidence: 0.78,
      rawPayloadPointer: `azure-devops://repo/${azureDevOpsRepositoryFullName(
        repository
      )}/permissions`,
      sourceType: "azure_devops.repository.permission"
    }
  ]);
}

async function getAzureDevOpsHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AZURE_DEVOPS_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = AzureDevOpsPatConfigSchema.parse(context.config);
  const projects = await fetchAzureDevOpsCollection(
    config,
    "/_apis/projects?$top=1&api-version=7.1",
    AzureDevOpsProjectSchema
  );
  const projectName = projects[0]?.name ?? config.organization;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Azure DevOps read-only access verified for ${projectName}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createAzureDevOpsConnector(): Connector {
  return {
    manifest: AZURE_DEVOPS_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createAzureDevOpsFixtureSignals();
      }

      const config = AzureDevOpsPatConfigSchema.parse(parsedContext.config);
      const repositories = await listAzureDevOpsRepositories(
        config,
        await listAzureDevOpsProjects(config)
      );

      return createAzureDevOpsSignals(config, repositories);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAzureDevOpsHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return ConnectorSyncResultSchema.parse({
          assets: createAzureDevOpsAssets(AZURE_DEVOPS_FIXTURE_REPOSITORIES),
          health: await getAzureDevOpsHealth(parsedContext),
          signals: createAzureDevOpsFixtureSignals().map((signal) =>
            createTimestampedSignal(
              AZURE_DEVOPS_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
          )
        });
      }

      const config = AzureDevOpsPatConfigSchema.parse(parsedContext.config);
      const repositories = await listAzureDevOpsRepositories(
        config,
        await listAzureDevOpsProjects(config)
      );

      return ConnectorSyncResultSchema.parse({
        assets: createAzureDevOpsAssets(repositories),
        health: await getAzureDevOpsHealth(parsedContext),
        signals: (await createAzureDevOpsSignals(config, repositories)).map(
          (signal) =>
            createTimestampedSignal(
              AZURE_DEVOPS_CONNECTOR_MANIFEST,
              parsedContext,
              signal
            )
        )
      });
    }
  };
}

