function normalizeBuildkiteApiBaseUrl(config: BuildkiteApiTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function buildkiteUrl(config: BuildkiteApiTokenConfig, pathName: string) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeBuildkiteApiBaseUrl(config)}${pathName}`;
}

async function fetchBuildkiteJson<T>(
  config: BuildkiteApiTokenConfig,
  pathName: string
) {
  const response = await connectorFetch(buildkiteUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${config.token}`
    }
  });

  if (!response.ok) {
    throw new Error(
      `Buildkite API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function listBuildkitePipelines(config: BuildkiteApiTokenConfig) {
  if (config.pipelineSlugs && config.pipelineSlugs.length > 0) {
    const pipelines = await Promise.all(
      config.pipelineSlugs.map((pipelineSlug) =>
        fetchBuildkiteJson<unknown>(
          config,
          `/organizations/${encodeURIComponent(
            config.organization
          )}/pipelines/${encodeURIComponent(pipelineSlug)}`
        )
      )
    );

    return pipelines.map((pipeline) => BuildkitePipelineSchema.parse(pipeline));
  }

  const pipelines = await fetchBuildkiteJson<unknown[]>(
    config,
    `/organizations/${encodeURIComponent(
      config.organization
    )}/pipelines?per_page=100`
  );

  return pipelines.map((pipeline) => BuildkitePipelineSchema.parse(pipeline));
}

