async function getBuildkiteHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(BUILDKITE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = BuildkiteApiTokenConfigSchema.parse(context.config);
  const user = BuildkiteUserSchema.parse(
    await fetchBuildkiteJson(config, "/user")
  );
  const displayName = user.name ?? user.email ?? user.uuid ?? "Buildkite user";

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Buildkite API token verified for ${displayName}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createBuildkiteConnector(): Connector {
  return {
    manifest: BUILDKITE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const pipelines = parsedContext.mockMode
        ? BUILDKITE_FIXTURE_PIPELINES
        : await listBuildkitePipelines(
            BuildkiteApiTokenConfigSchema.parse(parsedContext.config)
          );

      return createBuildkiteSignals(pipelines);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getBuildkiteHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const pipelines = parsedContext.mockMode
        ? BUILDKITE_FIXTURE_PIPELINES
        : await listBuildkitePipelines(
            BuildkiteApiTokenConfigSchema.parse(parsedContext.config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createBuildkiteAssets(pipelines),
        health: await getBuildkiteHealth(parsedContext),
        signals: createBuildkiteSignals(pipelines).map((signal) =>
          createTimestampedSignal(
            BUILDKITE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

