class JenkinsHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeJenkinsApiBaseUrl(config: JenkinsApiTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function jenkinsAuthorizationHeader(config: JenkinsApiTokenConfig) {
  return `Basic ${Buffer.from(`${config.username}:${config.apiToken}`).toString(
    "base64"
  )}`;
}

function jenkinsUrl(config: JenkinsApiTokenConfig, pathName: string) {
  return `${normalizeJenkinsApiBaseUrl(config)}${pathName}`;
}

function jenkinsJobPath(jobName: string) {
  return jobName
    .split("/")
    .filter((segment) => segment.length > 0)
    .map((segment) => `/job/${encodeURIComponent(segment)}`)
    .join("");
}

function jenkinsJobApiPath(jobName: string) {
  return `${jenkinsJobPath(
    jobName
  )}/api/json?tree=name,fullName,url,color,buildable,disabled,inQueue,lastBuild[number,url]`;
}

function jenkinsLastBuildApiPath(jobName: string) {
  return `${jenkinsJobPath(
    jobName
  )}/lastBuild/api/json?tree=number,id,result,building,duration,estimatedDuration,timestamp,fullDisplayName,url`;
}

async function fetchJenkinsJson<T>(
  config: JenkinsApiTokenConfig,
  pathName: string
) {
  const response = await connectorFetch(jenkinsUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: jenkinsAuthorizationHeader(config)
    }
  });

  if (!response.ok) {
    throw new JenkinsHttpError(
      response.status,
      `Jenkins API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function listJenkinsJobs(config: JenkinsApiTokenConfig) {
  if (config.jobNames.length > 0) {
    const jobs = await Promise.all(
      config.jobNames.map((jobName) =>
        fetchJenkinsJson<unknown>(config, jenkinsJobApiPath(jobName))
      )
    );

    return jobs.map((job, index) => ({
      job: JenkinsJobSchema.parse(job),
      jobPath: config.jobNames[index]!
    }));
  }

  const collection = JenkinsJobCollectionSchema.parse(
    await fetchJenkinsJson<unknown>(
      config,
      "/api/json?tree=jobs[name,fullName,url,color,buildable,disabled,inQueue,lastBuild[number,url]]"
    )
  );

  return collection.jobs
    .slice(0, config.maxJobs)
    .map((job) => JenkinsJobSchema.parse(job))
    .map((job) => ({
      job,
      jobPath: job.fullName ?? job.name
    }));
}

async function getJenkinsLastBuild(
  config: JenkinsApiTokenConfig,
  jobPath: string
) {
  if (!config.includeLastBuild) {
    return null;
  }

  try {
    return JenkinsBuildSchema.parse(
      await fetchJenkinsJson<unknown>(config, jenkinsLastBuildApiPath(jobPath))
    );
  } catch (error) {
    if (error instanceof JenkinsHttpError && error.status === 404) {
      return null;
    }

    throw error;
  }
}

async function listJenkinsInventory(config: JenkinsApiTokenConfig) {
  const jobs = await listJenkinsJobs(config);
  const builds = await Promise.all(
    jobs.map(({ jobPath }) => getJenkinsLastBuild(config, jobPath))
  );

  return jobs.map(({ job, jobPath }, index) => ({
    build: builds[index] ?? null,
    job,
    jobPath
  }));
}

function createJenkinsAssets(
  inventory: JenkinsInventoryItem[]
): ConnectorAssetInput[] {
  return inventory.map(({ build, job, jobPath }) =>
    createMockAsset({
      assetType: "Application",
      businessCriticality: "Moderate",
      environment: "ci-cd",
      identifiers: {
        buildable: job.buildable ?? null,
        color: job.color ?? null,
        disabled: job.disabled ?? null,
        inQueue: job.inQueue ?? null,
        jobName: job.name,
        jobPath,
        lastBuildBuilding: build?.building ?? null,
        lastBuildNumber: build?.number ?? job.lastBuild?.number ?? null,
        lastBuildResult: build?.result ?? null
      },
      internetExposed: false,
      name: `jenkins/${jobPath}`,
      owner: "platform-engineering",
      status:
        job.disabled === true || job.buildable === false
          ? "Inactive"
          : "Active",
      tags: ["ci-cd", "jenkins", build?.result?.toLowerCase() ?? "unknown"]
    })
  );
}

function createJenkinsSignals(
  inventory: JenkinsInventoryItem[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return inventory.flatMap(({ build, job, jobPath }) => {
    const pipelineBase = `jenkins://job/${encodeURIComponent(jobPath)}`;
    const observedAt = build?.timestamp
      ? new Date(build.timestamp).toISOString()
      : timestampObserved;

    return [
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: pipelineBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "CICDPipeline",
        sourceType: "jenkins.job.metadata",
        timestampObserved: observedAt
      }),
      ConnectorSignalInputSchema.parse({
        confidence: job.url ? 0.5 : 0.35,
        freshness: "Fresh",
        rawPayloadPointer: `${pipelineBase}/repository`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Repository",
        signalSubcategory: "PipelineRepositoryMissing",
        sourceType: "jenkins.job.repository_context",
        timestampObserved: observedAt
      }),
      ConnectorSignalInputSchema.parse({
        confidence: build ? 0.76 : 0.58,
        freshness: "Fresh",
        rawPayloadPointer: `${pipelineBase}/last-build`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory:
          build?.result === "SUCCESS"
            ? "PipelineLastBuildSucceeded"
            : build?.result
              ? "PipelineLastBuildNotSuccessful"
              : "PipelineLastBuildUnknown",
        sourceType: "jenkins.job.last_build_status",
        timestampObserved: observedAt
      }),
      ConnectorSignalInputSchema.parse({
        confidence: 0.72,
        freshness: "Fresh",
        rawPayloadPointer: `${pipelineBase}/control-context`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "PipelineControlContext",
        sourceType: "jenkins.job.control_context",
        timestampObserved: observedAt
      })
    ];
  });
}

async function getJenkinsHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(JENKINS_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = JenkinsApiTokenConfigSchema.parse(context.config);
  const user = JenkinsUserSchema.parse(
    await fetchJenkinsJson(config, "/me/api/json?tree=id,fullName,absoluteUrl")
  );
  const displayName = user.fullName ?? user.id ?? config.username;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Jenkins API token verified for ${displayName}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createJenkinsConnector(): Connector {
  return {
    manifest: JENKINS_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? JENKINS_FIXTURE_INVENTORY
        : await listJenkinsInventory(
            JenkinsApiTokenConfigSchema.parse(parsedContext.config)
          );

      return createJenkinsSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getJenkinsHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? JENKINS_FIXTURE_INVENTORY
        : await listJenkinsInventory(
            JenkinsApiTokenConfigSchema.parse(parsedContext.config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createJenkinsAssets(inventory),
        health: await getJenkinsHealth(parsedContext),
        signals: createJenkinsSignals(inventory).map((signal) =>
          createTimestampedSignal(
            JENKINS_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

