function normalizeDockerHubApiBaseUrl(config: DockerHubAccessTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function dockerHubUrl(config: DockerHubAccessTokenConfig, pathName: string) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeDockerHubApiBaseUrl(config)}${pathName}`;
}

async function fetchDockerHubJson<T>(
  config: DockerHubAccessTokenConfig,
  pathName: string
) {
  const headers: Record<string, string> = {
    accept: "application/json"
  };

  if (config.token) {
    headers.authorization = `Bearer ${config.token}`;
  }

  const response = await connectorFetch(dockerHubUrl(config, pathName), {
    headers
  });

  if (!response.ok) {
    throw new Error(
      `Docker Hub API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function fetchDockerHubCollection<T>(
  config: DockerHubAccessTokenConfig,
  pathName: string,
  schema: z.ZodType<T>
) {
  const collection = DockerHubCollectionSchema.parse(
    await fetchDockerHubJson(config, pathName)
  );

  return collection.results.map((item) => schema.parse(item));
}

async function listDockerHubRepositories(config: DockerHubAccessTokenConfig) {
  if (config.repositories.length > 0) {
    const repositories = await Promise.all(
      config.repositories.map((repository) =>
        fetchDockerHubJson<unknown>(
          config,
          `/repositories/${encodeURIComponent(
            config.namespace
          )}/${encodeURIComponent(repository)}/`
        )
      )
    );

    return repositories.map((repository) =>
      DockerHubRepositorySchema.parse(repository)
    );
  }

  return fetchDockerHubCollection(
    config,
    `/repositories/${encodeURIComponent(config.namespace)}/?page_size=100`,
    DockerHubRepositorySchema
  );
}

async function listDockerHubTags(
  config: DockerHubAccessTokenConfig,
  repository: DockerHubRepository
) {
  return fetchDockerHubCollection(
    config,
    `/repositories/${encodeURIComponent(
      repository.namespace ?? config.namespace
    )}/${encodeURIComponent(repository.name)}/tags?page_size=25`,
    DockerHubTagSchema
  );
}

function loadDockerHubFixtureInventory() {
  return {
    repositories: DOCKER_HUB_FIXTURE_REPOSITORIES,
    tagsByRepository: DOCKER_HUB_FIXTURE_TAGS
  };
}

async function loadDockerHubInventory(config: DockerHubAccessTokenConfig) {
  const repositories = await listDockerHubRepositories(config);
  const tagsByRepository: Record<string, DockerHubTag[]> = {};

  for (const repository of repositories) {
    tagsByRepository[repository.name] = await listDockerHubTags(
      config,
      repository
    );
  }

  return {
    repositories,
    tagsByRepository
  };
}

function dockerHubRepositoryName(
  config: DockerHubAccessTokenConfig,
  repository: DockerHubRepository
) {
  return `${repository.namespace ?? config.namespace}/${repository.name}`;
}

function createDockerHubAssets(input: {
  config: DockerHubAccessTokenConfig;
  repositories: DockerHubRepository[];
}): ConnectorAssetInput[] {
  return input.repositories.map((repository) =>
    createMockAsset({
      assetType: "Container",
      businessCriticality:
        repository.is_private === false ? "Moderate" : "High",
      environment: "container-registry",
      identifiers: {
        namespace: repository.namespace ?? input.config.namespace,
        pullCount: repository.pull_count ?? null,
        repositoryName: repository.name,
        repositoryType: repository.repository_type ?? null,
        starCount: repository.star_count ?? null,
        visibility: repository.is_private === false ? "public" : "private"
      },
      internetExposed: repository.is_private === false,
      name: `docker-hub/${dockerHubRepositoryName(input.config, repository)}`,
      owner: repository.user ?? repository.namespace ?? input.config.namespace,
      status: repository.status === 0 ? "Inactive" : "Active",
      tags: [
        "container-registry",
        "docker-hub",
        repository.is_private === false ? "public" : "private"
      ]
    })
  );
}

function createDockerHubSignals(input: {
  config: DockerHubAccessTokenConfig;
  repositories: DockerHubRepository[];
  tagsByRepository: Record<string, DockerHubTag[]>;
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const repository of input.repositories) {
    const repositoryName = dockerHubRepositoryName(input.config, repository);
    const repoBase = `docker-hub://repository/${repositoryName}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: repoBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: repository.is_private === false ? "Low" : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "ContainerImageRepository",
        sourceType: "docker_hub.repository.metadata",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${repoBase}/visibility`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: repository.is_private === false ? "Moderate" : "Low",
        signalCategory: "Exposure",
        signalSubcategory:
          repository.is_private === false
            ? "PublicContainerRepository"
            : "PrivateContainerRepository",
        sourceType: "docker_hub.repository.visibility",
        timestampObserved
      })
    );

    for (const tag of input.tagsByRepository[repository.name] ?? []) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `${repoBase}/tags/${tag.name}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "ContainerImageTag",
          sourceType: "docker_hub.repository.tag",
          timestampObserved:
            tag.last_pushed ?? tag.last_updated ?? timestampObserved
        })
      );
    }
  }

  return signals;
}

async function getDockerHubHealth(context: ConnectorExecutionContext) {
  const parsedContext = ConnectorExecutionContextSchema.parse(context);

  if (parsedContext.mockMode) {
    return createMockHealth(DOCKER_HUB_CONNECTOR_MANIFEST, parsedContext);
  }

  const startedAt = Date.now();
  const config = DockerHubAccessTokenConfigSchema.parse(parsedContext.config);
  const repositories = await listDockerHubRepositories(config);

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Docker Hub read-only metadata access verified for ${repositories.length} repository record(s).`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createDockerHubConnector(): Connector {
  return {
    manifest: DOCKER_HUB_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = DockerHubAccessTokenConfigSchema.parse(
        parsedContext.mockMode
          ? {
              namespace: "periscan-fixtures"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadDockerHubFixtureInventory()
        : await loadDockerHubInventory(config);

      return createDockerHubSignals({
        config,
        repositories: inventory.repositories,
        tagsByRepository: inventory.tagsByRepository
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getDockerHubHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = DockerHubAccessTokenConfigSchema.parse(
        parsedContext.mockMode
          ? {
              namespace: "periscan-fixtures"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadDockerHubFixtureInventory()
        : await loadDockerHubInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createDockerHubAssets({
          config,
          repositories: inventory.repositories
        }),
        health: await getDockerHubHealth(parsedContext),
        signals: createDockerHubSignals({
          config,
          repositories: inventory.repositories,
          tagsByRepository: inventory.tagsByRepository
        }).map((signal) =>
          createTimestampedSignal(
            DOCKER_HUB_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

