function normalizeGitHubContainerRegistryApiBaseUrl(
  config: GitHubContainerRegistryConfig
) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function gitHubContainerRegistryUrl(
  config: GitHubContainerRegistryConfig,
  pathName: string
) {
  return `${normalizeGitHubContainerRegistryApiBaseUrl(config)}${pathName}`;
}

function gitHubContainerRegistryOwnerPath(
  config: GitHubContainerRegistryConfig
) {
  const owner = encodeURIComponent(config.owner);

  return config.ownerType === "org" ? `/orgs/${owner}` : `/users/${owner}`;
}

async function fetchGitHubContainerRegistryJson<T>(
  config: GitHubContainerRegistryConfig,
  pathName: string
) {
  const response = await connectorFetch(
    gitHubContainerRegistryUrl(config, pathName),
    {
      headers: {
        accept: "application/vnd.github+json",
        authorization: `Bearer ${config.token}`,
        "x-github-api-version": "2022-11-28"
      }
    }
  );

  if (!response.ok) {
    throw new Error(
      `GitHub Container Registry API request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function listGitHubContainerPackages(
  config: GitHubContainerRegistryConfig
) {
  const ownerPath = gitHubContainerRegistryOwnerPath(config);

  if (config.packages.length > 0) {
    const packages = await Promise.all(
      config.packages.map((packageName) =>
        fetchGitHubContainerRegistryJson<unknown>(
          config,
          `${ownerPath}/packages/container/${encodeURIComponent(packageName)}`
        )
      )
    );

    return packages.map((item) => GitHubContainerPackageSchema.parse(item));
  }

  const packages = await fetchGitHubContainerRegistryJson<unknown>(
    config,
    `${ownerPath}/packages?package_type=container&per_page=100`
  );

  return z.array(GitHubContainerPackageSchema).parse(packages);
}

async function listGitHubContainerPackageVersions(
  config: GitHubContainerRegistryConfig,
  packageRecord: GitHubContainerPackage
) {
  const ownerPath = gitHubContainerRegistryOwnerPath(config);
  const versions = await fetchGitHubContainerRegistryJson<unknown>(
    config,
    `${ownerPath}/packages/container/${encodeURIComponent(
      packageRecord.name
    )}/versions?per_page=25`
  );

  return z.array(GitHubContainerPackageVersionSchema).parse(versions);
}

function loadGitHubContainerRegistryFixtureInventory() {
  return {
    packages: GITHUB_CONTAINER_REGISTRY_FIXTURE_PACKAGES,
    versionsByPackage: GITHUB_CONTAINER_REGISTRY_FIXTURE_VERSIONS
  };
}

async function loadGitHubContainerRegistryInventory(
  config: GitHubContainerRegistryConfig
) {
  const packages = await listGitHubContainerPackages(config);
  const versionsByPackage: Record<string, GitHubContainerPackageVersion[]> = {};

  for (const packageRecord of packages) {
    versionsByPackage[packageRecord.name] =
      await listGitHubContainerPackageVersions(config, packageRecord);
  }

  return {
    packages,
    versionsByPackage
  };
}

function githubContainerRegistryOwner(
  config: GitHubContainerRegistryConfig,
  packageRecord: GitHubContainerPackage
) {
  return packageRecord.owner?.login ?? config.owner;
}

function githubContainerRegistryPackageName(
  config: GitHubContainerRegistryConfig,
  packageRecord: GitHubContainerPackage
) {
  return `${githubContainerRegistryOwner(config, packageRecord)}/${
    packageRecord.name
  }`;
}

function githubContainerRegistryVisibility(
  packageRecord: GitHubContainerPackage
) {
  return packageRecord.visibility?.toLowerCase() === "public"
    ? "public"
    : "private";
}

function createGitHubContainerRegistryAssets(input: {
  config: GitHubContainerRegistryConfig;
  packages: GitHubContainerPackage[];
}): ConnectorAssetInput[] {
  return input.packages.map((packageRecord) => {
    const visibility = githubContainerRegistryVisibility(packageRecord);

    return createMockAsset({
      assetType: "Container",
      businessCriticality: visibility === "public" ? "Moderate" : "High",
      environment: "container-registry",
      identifiers: {
        htmlUrl: packageRecord.html_url ?? null,
        owner: githubContainerRegistryOwner(input.config, packageRecord),
        ownerType: input.config.ownerType,
        packageId: packageRecord.id,
        packageName: packageRecord.name,
        packageType: packageRecord.package_type,
        repository: packageRecord.repository?.full_name ?? null,
        versionCount: packageRecord.version_count ?? null,
        visibility
      },
      internetExposed: visibility === "public",
      name: `ghcr/${githubContainerRegistryPackageName(
        input.config,
        packageRecord
      )}`,
      owner:
        packageRecord.repository?.full_name ??
        githubContainerRegistryOwner(input.config, packageRecord),
      status: "Active",
      tags: ["container-registry", "ghcr", visibility]
    });
  });
}

function createGitHubContainerRegistrySignals(input: {
  config: GitHubContainerRegistryConfig;
  packages: GitHubContainerPackage[];
  versionsByPackage: Record<string, GitHubContainerPackageVersion[]>;
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const packageRecord of input.packages) {
    const packageName = githubContainerRegistryPackageName(
      input.config,
      packageRecord
    );
    const packageBase = `ghcr://package/${packageName}`;
    const visibility = githubContainerRegistryVisibility(packageRecord);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: packageBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: visibility === "public" ? "Low" : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "ContainerImageRepository",
        sourceType: "github_container_registry.package.metadata",
        timestampObserved: packageRecord.updated_at ?? timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${packageBase}/visibility`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: visibility === "public" ? "Moderate" : "Low",
        signalCategory: "Exposure",
        signalSubcategory:
          visibility === "public"
            ? "PublicContainerRepository"
            : "PrivateContainerRepository",
        sourceType: "github_container_registry.package.visibility",
        timestampObserved: packageRecord.updated_at ?? timestampObserved
      })
    );

    for (const version of input.versionsByPackage[packageRecord.name] ?? []) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `${packageBase}/versions/${version.id}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "ContainerImageVersion",
          sourceType: "github_container_registry.package.version",
          timestampObserved: version.updated_at ?? timestampObserved
        })
      );

      for (const tag of version.metadata?.container?.tags ?? []) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.8,
            freshness: "Fresh",
            rawPayloadPointer: `${packageBase}/tags/${tag}`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "Asset",
            signalSubcategory: "ContainerImageTag",
            sourceType: "github_container_registry.package.tag",
            timestampObserved: version.updated_at ?? timestampObserved
          })
        );
      }
    }
  }

  return signals;
}

async function getGitHubContainerRegistryHealth(
  context: ConnectorExecutionContext
) {
  const parsedContext = ConnectorExecutionContextSchema.parse(context);

  if (parsedContext.mockMode) {
    return createMockHealth(
      GITHUB_CONTAINER_REGISTRY_CONNECTOR_MANIFEST,
      parsedContext
    );
  }

  const startedAt = Date.now();
  const config = GitHubContainerRegistryConfigSchema.parse(
    parsedContext.config
  );
  const packages = await listGitHubContainerPackages(config);

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `GitHub Container Registry read-only metadata access verified for ${packages.length} package record(s).`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createGitHubContainerRegistryConnector(): Connector {
  return {
    manifest: GITHUB_CONTAINER_REGISTRY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = GitHubContainerRegistryConfigSchema.parse(
        parsedContext.mockMode
          ? {
              owner: "periscan-fixtures",
              token: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadGitHubContainerRegistryFixtureInventory()
        : await loadGitHubContainerRegistryInventory(config);

      return createGitHubContainerRegistrySignals({
        config,
        packages: inventory.packages,
        versionsByPackage: inventory.versionsByPackage
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGitHubContainerRegistryHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = GitHubContainerRegistryConfigSchema.parse(
        parsedContext.mockMode
          ? {
              owner: "periscan-fixtures",
              token: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadGitHubContainerRegistryFixtureInventory()
        : await loadGitHubContainerRegistryInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createGitHubContainerRegistryAssets({
          config,
          packages: inventory.packages
        }),
        health: await getGitHubContainerRegistryHealth(parsedContext),
        signals: createGitHubContainerRegistrySignals({
          config,
          packages: inventory.packages,
          versionsByPackage: inventory.versionsByPackage
        }).map((signal) =>
          createTimestampedSignal(
            GITHUB_CONTAINER_REGISTRY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

