class MicrosoftGraphHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeMicrosoftUrl(value: string) {
  return value.replace(/\/+$/u, "");
}

function microsoftGraphUrl(
  config: MicrosoftEntraOAuthConfig,
  pathName: string
) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeMicrosoftUrl(config.graphBaseUrl)}${pathName}`;
}

async function getMicrosoftGraphAccessToken(config: MicrosoftEntraOAuthConfig) {
  const tokenUrl = `${normalizeMicrosoftUrl(
    config.authorityHost
  )}/${encodeURIComponent(config.tenantId)}/oauth2/v2.0/token`;
  const response = await connectorFetch(tokenUrl, {
    body: new URLSearchParams({
      client_id: config.clientId,
      client_secret: config.clientSecret,
      grant_type: "client_credentials",
      scope: "https://graph.microsoft.com/.default"
    }),
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new MicrosoftGraphHttpError(
      response.status,
      `Microsoft identity platform token request failed with status ${response.status}.`
    );
  }

  return MicrosoftGraphTokenSchema.parse(await response.json()).access_token;
}

async function fetchMicrosoftGraphJson<T>(input: {
  accessToken: string;
  config: MicrosoftEntraOAuthConfig;
  pathName: string;
}) {
  const response = await connectorFetch(
    microsoftGraphUrl(input.config, input.pathName),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${input.accessToken}`
      }
    }
  );

  if (!response.ok) {
    throw new MicrosoftGraphHttpError(
      response.status,
      `Microsoft Graph request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

async function fetchMicrosoftGraphCollection<T>(input: {
  accessToken: string;
  config: MicrosoftEntraOAuthConfig;
  pathName: string;
  schema: z.ZodType<T>;
}) {
  const rows: T[] = [];
  let nextPath: string | null = input.pathName;
  let pageCount = 0;

  while (nextPath && pageCount < 10) {
    const collection = MicrosoftGraphCollectionSchema.parse(
      await fetchMicrosoftGraphJson({
        accessToken: input.accessToken,
        config: input.config,
        pathName: nextPath
      })
    );

    rows.push(...collection.value.map((row) => input.schema.parse(row)));
    nextPath = collection["@odata.nextLink"] ?? null;
    pageCount += 1;
  }

  return rows;
}

function microsoftIdentityName(value: {
  displayName?: string | null;
  id: string;
}) {
  return value.displayName ?? value.id;
}

function isPrivilegedMicrosoftName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|global|owner)\b/iu.test(
    value
  );
}

function createMicrosoftEntraAssets(input: {
  applications: MicrosoftGraphApplication[];
  tenantId: string;
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "microsoft-entra-id",
        tenantId: input.tenantId
      },
      internetExposed: false,
      name: "Microsoft Entra ID",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "microsoft", "entra"]
    }),
    ...input.applications.map((app) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: "High",
        environment: "production",
        identifiers: {
          appId: app.appId ?? null,
          objectId: app.id,
          signInAudience: app.signInAudience ?? null
        },
        internetExposed: false,
        name: microsoftIdentityName(app),
        owner: "identity-security",
        status: "Active",
        tags: ["identity", "microsoft", "application-registration"]
      })
    )
  ];
}

function createMicrosoftEntraSignals(input: {
  applications: MicrosoftGraphApplication[];
  groups: MicrosoftGraphGroup[];
  roles: MicrosoftGraphDirectoryRole[];
  users: MicrosoftGraphUser[];
}) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "microsoft-graph://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "microsoft.graph.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const principal =
      user.userPrincipalName ?? user.mail ?? user.displayName ?? user.id;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://user/${user.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: isPrivilegedMicrosoftName(principal)
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "microsoft.graph.user.metadata",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    const name = microsoftIdentityName(group);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: isPrivilegedMicrosoftName(name)
          ? "PrivilegedGroup"
          : "Group",
        sourceType: "microsoft.graph.group.metadata",
        timestampObserved
      })
    );
  }

  for (const role of input.roles) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://directory-role/${role.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: "DirectoryRole",
        sourceType: "microsoft.graph.directory_role.metadata",
        timestampObserved
      })
    );
  }

  for (const app of input.applications) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://application/${app.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SaaSApplication",
        sourceType: "microsoft.graph.application.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadMicrosoftEntraFixtureInventory() {
  return {
    applications: ENTRA_FIXTURE_APPLICATIONS,
    groups: ENTRA_FIXTURE_GROUPS,
    roles: ENTRA_FIXTURE_ROLES,
    users: ENTRA_FIXTURE_USERS
  };
}

async function loadMicrosoftEntraInventory(
  config: MicrosoftEntraOAuthConfig,
  accessToken: string
) {
  const [users, groups, applications, roles] = await Promise.all([
    fetchMicrosoftGraphCollection({
      accessToken,
      config,
      pathName:
        "/users?$select=id,displayName,userPrincipalName,mail,accountEnabled,userType&$top=999",
      schema: MicrosoftGraphUserSchema
    }),
    config.includeGroups
      ? fetchMicrosoftGraphCollection({
          accessToken,
          config,
          pathName:
            "/groups?$select=id,displayName,description,securityEnabled&$top=999",
          schema: MicrosoftGraphGroupSchema
        })
      : Promise.resolve([]),
    config.includeApplications
      ? fetchMicrosoftGraphCollection({
          accessToken,
          config,
          pathName:
            "/applications?$select=id,appId,displayName,signInAudience&$top=999",
          schema: MicrosoftGraphApplicationSchema
        })
      : Promise.resolve([]),
    config.includeRoles
      ? fetchMicrosoftGraphCollection({
          accessToken,
          config,
          pathName:
            "/directoryRoles?$select=id,displayName,description&$top=999",
          schema: MicrosoftGraphDirectoryRoleSchema
        })
      : Promise.resolve([])
  ]);

  return {
    applications,
    groups,
    roles,
    users
  };
}

async function getMicrosoftEntraHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(MICROSOFT_ENTRA_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = MicrosoftEntraOAuthConfigSchema.parse(context.config);
  const accessToken = await getMicrosoftGraphAccessToken(config);
  const organization = MicrosoftGraphOrganizationSchema.parse(
    await fetchMicrosoftGraphJson({
      accessToken,
      config,
      pathName: "/organization?$select=id,displayName&$top=1"
    })
  );
  const displayName =
    organization.value[0]?.displayName ??
    organization.value[0]?.id ??
    config.tenantId;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Microsoft Graph read-only access verified for ${displayName}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createMicrosoftEntraConnector(): Connector {
  return {
    manifest: MICROSOFT_ENTRA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = MicrosoftEntraOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              tenantId: "mock-tenant"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadMicrosoftEntraFixtureInventory()
        : await loadMicrosoftEntraInventory(
            config,
            await getMicrosoftGraphAccessToken(config)
          );

      return createMicrosoftEntraSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getMicrosoftEntraHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = MicrosoftEntraOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              tenantId: "mock-tenant"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadMicrosoftEntraFixtureInventory()
        : await loadMicrosoftEntraInventory(
            config,
            await getMicrosoftGraphAccessToken(config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createMicrosoftEntraAssets({
          applications: inventory.applications,
          tenantId: config.tenantId
        }),
        health: await getMicrosoftEntraHealth(parsedContext),
        signals: createMicrosoftEntraSignals(inventory).map((signal) =>
          createTimestampedSignal(
            MICROSOFT_ENTRA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

