function createMicrosoftDefenderEmailSignals(input: {
  alerts: MicrosoftDefenderEmailAlert[];
  incidents: MicrosoftDefenderEmailIncident[];
}) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.86,
      freshness: "Fresh",
      rawPayloadPointer: "microsoft-graph://security/defender-email",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "EmailSecurityControl",
      sourceType: "microsoft.graph.security.defender_email.metadata",
      timestampObserved
    })
  ];

  for (const incident of input.incidents) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://security/incidents/${incident.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: isHighSensitivityDefenderSeverity(incident.severity)
          ? "High"
          : "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "EmailThreatIncident",
        sourceType: "microsoft.graph.security.incident",
        timestampObserved: incident.lastUpdateDateTime ?? timestampObserved
      })
    );
  }

  for (const alert of input.alerts) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `microsoft-graph://security/alerts_v2/${alert.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: isHighSensitivityDefenderSeverity(alert.severity)
          ? "High"
          : "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "EmailSecurityAlert",
        sourceType: "microsoft.graph.security.alert",
        techniqueIds: alert.mitreTechniques ?? [],
        timestampObserved: alert.lastUpdateDateTime ?? timestampObserved
      })
    );

    for (const techniqueId of alert.mitreTechniques ?? []) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.74,
          freshness: "Fresh",
          rawPayloadPointer: `microsoft-graph://security/alerts_v2/${alert.id}/techniques/${techniqueId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "ControlObservation",
          signalSubcategory: "MitreTechniqueObserved",
          sourceType: "microsoft.graph.security.alert.mitre_technique",
          techniqueIds: [techniqueId],
          timestampObserved: alert.lastUpdateDateTime ?? timestampObserved
        })
      );
    }
  }

  if (input.alerts.length === 0 && input.incidents.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.7,
        freshness: "Fresh",
        rawPayloadPointer:
          "microsoft-graph://security/defender-email/no-alerts",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoEmailThreatEvidence",
        sourceType: "microsoft.graph.security.defender_email.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadMicrosoftDefenderEmailFixtureInventory() {
  return {
    alerts: DEFENDER_EMAIL_FIXTURE_ALERTS,
    incidents: DEFENDER_EMAIL_FIXTURE_INCIDENTS
  };
}

async function loadMicrosoftDefenderEmailInventory(
  config: MicrosoftDefenderEmailOAuthConfig,
  accessToken: string
) {
  const [incidents, alerts] = await Promise.all([
    config.includeIncidents
      ? fetchMicrosoftGraphCollection({
          accessToken,
          config,
          pathName: `/security/incidents?$top=${config.maxItems}`,
          schema: MicrosoftDefenderEmailIncidentSchema
        })
      : Promise.resolve([]),
    config.includeAlerts
      ? fetchMicrosoftGraphCollection({
          accessToken,
          config,
          pathName: `/security/alerts_v2?$top=${config.maxItems}`,
          schema: MicrosoftDefenderEmailAlertSchema
        })
      : Promise.resolve([])
  ]);

  return {
    alerts,
    incidents
  };
}

async function getMicrosoftDefenderEmailHealth(
  context: ConnectorExecutionContext
) {
  if (context.mockMode) {
    return createMockHealth(
      MICROSOFT_DEFENDER_EMAIL_CONNECTOR_MANIFEST,
      context
    );
  }

  const startedAt = Date.now();
  const config = MicrosoftDefenderEmailOAuthConfigSchema.parse(context.config);
  const accessToken = await getMicrosoftGraphAccessToken(config);
  const alerts = await fetchMicrosoftGraphCollection({
    accessToken,
    config,
    pathName: "/security/alerts_v2?$top=1",
    schema: MicrosoftDefenderEmailAlertSchema
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Microsoft Graph Defender for Office 365 read-only access verified; ${alerts.length} sample alert record(s) accessible.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observeMicrosoftDefenderEmailControl(
  context: ConnectorExecutionContext
) {
  const startedAt = Date.now();

  if (context.mockMode) {
    return {
      confidence: 0.8,
      detail:
        "Microsoft Defender for Office 365 fixture contains alert evidence for the validation context.",
      latencyMs: Date.now() - startedAt,
      outcome: "Alerted",
      sourceType: "microsoft_defender_email.observer"
    };
  }

  try {
    const config = MicrosoftDefenderEmailOAuthConfigSchema.parse(
      context.config
    );
    const inventory = await loadMicrosoftDefenderEmailInventory(
      config,
      await getMicrosoftGraphAccessToken(config)
    );
    const hasEvidence =
      inventory.alerts.length > 0 || inventory.incidents.length > 0;

    return {
      confidence: hasEvidence ? 0.82 : 0.58,
      detail: hasEvidence
        ? "Microsoft Defender for Office 365 returned alert or incident evidence for the validation context."
        : "Microsoft Defender for Office 365 read-only lookup completed but returned no matching alert or incident evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasEvidence ? "Alerted" : "NoEvidence",
      sourceType: "microsoft_defender_email.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Microsoft Defender for Office 365 lookup failed: ${
        error instanceof Error
          ? error.message
          : "Unknown Microsoft Graph error."
      }`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "microsoft_defender_email.observer"
    };
  }
}

function createMicrosoftDefenderEmailConnector(): Connector {
  return {
    manifest: MICROSOFT_DEFENDER_EMAIL_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = MicrosoftDefenderEmailOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              tenantId: "mock-tenant"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadMicrosoftDefenderEmailFixtureInventory()
        : await loadMicrosoftDefenderEmailInventory(
            config,
            await getMicrosoftGraphAccessToken(config)
          );

      return createMicrosoftDefenderEmailSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getMicrosoftDefenderEmailHealth(parsedContext);
    },
    observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return observeMicrosoftDefenderEmailControl(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = MicrosoftDefenderEmailOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              tenantId: "mock-tenant"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadMicrosoftDefenderEmailFixtureInventory()
        : await loadMicrosoftDefenderEmailInventory(
            config,
            await getMicrosoftGraphAccessToken(config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createMicrosoftDefenderEmailAssets(),
        health: await getMicrosoftDefenderEmailHealth(parsedContext),
        signals: createMicrosoftDefenderEmailSignals(inventory).map((signal) =>
          createTimestampedSignal(
            MICROSOFT_DEFENDER_EMAIL_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

