function googleGmailSecurityConfigFromContext(
  context: ConnectorExecutionContext
) {
  return GoogleGmailSecurityConfigSchema.parse(
    context.mockMode
      ? {
          ...context.config,
          accessToken: "mock-google-gmail-security-token",
          alertCenterBaseUrl:
            "https://alertcenter.googleapis.example.test/v1beta1"
        }
      : context.config
  );
}

function googleGmailSecurityApiUrl(
  config: Pick<GoogleGmailSecurityConfig, "alertCenterBaseUrl">,
  pathName: string
) {
  return `${config.alertCenterBaseUrl.replace(/\/+$/u, "")}/${pathName.replace(/^\/+/u, "")}`;
}

function isGoogleGmailAlertRecord(
  value: unknown
): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function parseGoogleGmailSecurityAlerts(payload: unknown): GoogleGmailAlert[] {
  if (Array.isArray(payload)) {
    return payload
      .filter(isGoogleGmailAlertRecord)
      .map((item) => GoogleGmailAlertSchema.parse(item));
  }

  if (!payload || typeof payload !== "object") {
    return [];
  }

  const record = payload as Record<string, unknown>;
  const listKeys = ["alerts", "data", "items", "results"];
  const alerts = listKeys.flatMap((key) => {
    const value = record[key];

    return Array.isArray(value)
      ? value
          .filter(isGoogleGmailAlertRecord)
          .map((item) => GoogleGmailAlertSchema.parse(item))
      : [];
  });

  if (alerts.length > 0) {
    return alerts;
  }

  if ("alertId" in record || "type" in record || "source" in record) {
    return [GoogleGmailAlertSchema.parse(record)];
  }

  return [];
}

async function fetchGoogleGmailSecurityAlerts(
  config: GoogleGmailSecurityConfig
) {
  const url = new URL(googleGmailSecurityApiUrl(config, "/alerts"));

  url.searchParams.set("pageSize", String(config.maxAlerts));

  if (config.filter) {
    url.searchParams.set("filter", config.filter);
  }

  const response = await connectorFetch(url, {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${config.accessToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(
      `Google Alert Center request failed with status ${response.status}.`
    );
  }

  return parseGoogleGmailSecurityAlerts(await response.json()).slice(
    0,
    config.maxAlerts
  );
}

function googleGmailAlertValue(alert: GoogleGmailAlert, keys: string[]) {
  for (const key of keys) {
    const value = alert[key];

    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }
  }

  return null;
}

function googleGmailAlertText(alert: GoogleGmailAlert) {
  return JSON.stringify(alert).toLowerCase();
}

function googleGmailAlertId(alert: GoogleGmailAlert, index: number) {
  return (
    googleGmailAlertValue(alert, ["alertId", "id", "alert_id"]) ??
    `google-gmail-alert-${index + 1}`
  );
}

function googleGmailAlertTimestamp(alert: GoogleGmailAlert, fallback: string) {
  const value = googleGmailAlertValue(alert, [
    "createTime",
    "create_time",
    "updateTime",
    "updated_at",
    "created_at"
  ]);

  if (!value) {
    return fallback;
  }

  const parsed = new Date(value);

  return Number.isNaN(parsed.getTime()) ? fallback : parsed.toISOString();
}

function googleGmailAlertSensitivity(alert: GoogleGmailAlert) {
  return /\b(critical|high|severe|malware|phish|credential)\b/iu.test(
    googleGmailAlertText(alert)
  )
    ? "High"
    : "Moderate";
}

function loadGoogleGmailSecurityFixtureAlerts(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureAlerts)) {
    return parseGoogleGmailSecurityAlerts(config.fixtureAlerts);
  }

  return GOOGLE_GMAIL_SECURITY_FIXTURE_ALERTS;
}

function createGoogleGmailSecurityAssets(): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "Service",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "google-gmail-security"
      },
      internetExposed: false,
      name: "Google Gmail Security",
      owner: "email-security",
      status: "Active",
      tags: ["email-security", "google", "gmail", "alert-center"]
    })
  ];
}

function createGoogleGmailSecuritySignals(alerts: GoogleGmailAlert[]) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.84,
      freshness: "Fresh",
      rawPayloadPointer: "google-alert-center://gmail-security",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "EmailSecurityControl",
      sourceType: "google.alert_center.gmail.metadata",
      timestampObserved
    })
  ];

  alerts.forEach((alert, index) => {
    const alertId = googleGmailAlertId(alert, index);
    const observedAt = googleGmailAlertTimestamp(alert, timestampObserved);
    const text = googleGmailAlertText(alert);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `google-alert-center://alerts/${encodeURIComponent(
          alertId
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: googleGmailAlertSensitivity(alert),
        signalCategory: "ControlObservation",
        signalSubcategory: "GmailSecurityAlert",
        sourceType: "google.alert_center.gmail.alert",
        timestampObserved: observedAt
      })
    );

    if (/\b(phish\w*|credential\w*|spoof\w*)\b/iu.test(text)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `google-alert-center://alerts/${encodeURIComponent(
            alertId
          )}/phishing`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "PhishingObserved",
          sourceType: "google.alert_center.gmail.phishing",
          timestampObserved: observedAt
        })
      );
    }

    if (/\b(malware|virus|attachment)\b/iu.test(text)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `google-alert-center://alerts/${encodeURIComponent(
            alertId
          )}/malware`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "MalwareObserved",
          sourceType: "google.alert_center.gmail.malware",
          timestampObserved: observedAt
        })
      );
    }
  });

  if (alerts.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.68,
        freshness: "Fresh",
        rawPayloadPointer: "google-alert-center://gmail-security/no-alerts",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoEmailThreatEvidence",
        sourceType: "google.alert_center.gmail.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

async function getGoogleGmailSecurityHealth(
  context: ConnectorExecutionContext
) {
  if (context.mockMode) {
    return createMockHealth(GOOGLE_GMAIL_SECURITY_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const alerts = await fetchGoogleGmailSecurityAlerts({
    ...googleGmailSecurityConfigFromContext(context),
    maxAlerts: 1
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Google Alert Center read-only access verified with ${alerts.length} sample Gmail security alert(s).`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function observeGoogleGmailSecurityControl(
  context: ConnectorExecutionContext
) {
  const startedAt = Date.now();

  try {
    const alerts = context.mockMode
      ? loadGoogleGmailSecurityFixtureAlerts(context.config)
      : await fetchGoogleGmailSecurityAlerts(
          googleGmailSecurityConfigFromContext(context)
        );
    const hasEvidence = alerts.length > 0;

    return {
      confidence: hasEvidence ? 0.82 : 0.58,
      detail: hasEvidence
        ? "Google Alert Center returned Gmail security alert evidence for the validation context."
        : "Google Alert Center read-only lookup completed but returned no matching Gmail security alert evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasEvidence ? "Alerted" : "NoEvidence",
      sourceType: "google_gmail_security.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Google Alert Center lookup failed: ${
        error instanceof Error ? error.message : "Unknown Google API error."
      }`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "google_gmail_security.observer"
    };
  }
}

function createGoogleGmailSecurityConnector(): Connector {
  return {
    manifest: GOOGLE_GMAIL_SECURITY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const alerts = parsedContext.mockMode
        ? loadGoogleGmailSecurityFixtureAlerts(parsedContext.config)
        : await fetchGoogleGmailSecurityAlerts(
            googleGmailSecurityConfigFromContext(parsedContext)
          );

      return createGoogleGmailSecuritySignals(alerts);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGoogleGmailSecurityHealth(parsedContext);
    },
    observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return observeGoogleGmailSecurityControl(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const alerts = parsedContext.mockMode
        ? loadGoogleGmailSecurityFixtureAlerts(parsedContext.config)
        : await fetchGoogleGmailSecurityAlerts(
            googleGmailSecurityConfigFromContext(parsedContext)
          );
      const health = parsedContext.mockMode
        ? await getGoogleGmailSecurityHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Google Alert Center read-only sync returned ${alerts.length} Gmail security alert(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createGoogleGmailSecurityAssets(),
        health,
        signals: createGoogleGmailSecuritySignals(alerts).map((signal) =>
          createTimestampedSignal(
            GOOGLE_GMAIL_SECURITY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const ProofpointTapSiemEndpointSchema = z
  .enum([
    "all",
    "issues",
    "messagesBlocked",
    "messagesDelivered",
    "clicksBlocked",
    "clicksPermitted"
  ])
  .default("all");

const ProofpointTapFixtureOutcomeSchema = z
  .enum(["Blocked", "Detected", "Missed", "NoEvidence"])
  .default("Blocked");

const ProofpointTapSiemConfigSchema = z.object({
  baseUrl: z.url().default("https://tap-api-v2.proofpoint.com"),
  endpoint: ProofpointTapSiemEndpointSchema,
  fixtureOutcome: ProofpointTapFixtureOutcomeSchema.optional(),
  principal: z.string().min(1),
  secret: z.string().min(1),
  sinceSeconds: z.number().int().min(1).max(3600).default(3600),
  threatStatus: z.enum(["active", "cleared", "falsePositive"]).optional(),
  threatType: z.enum(["attachment", "url", "messageText"]).optional()
});

const ProofpointTapEventSchema = z.record(z.string(), z.unknown());

type ProofpointTapSiemConfig = z.infer<typeof ProofpointTapSiemConfigSchema>;
type ProofpointTapEndpoint = z.infer<typeof ProofpointTapSiemEndpointSchema>;
type ProofpointTapEvent = z.infer<typeof ProofpointTapEventSchema>;

const PROOFPOINT_TAP_SIEM_ENDPOINT_PATHS: Record<
  ProofpointTapEndpoint,
  string
> = {
  all: "all",
  clicksBlocked: "clicks/blocked",
  clicksPermitted: "clicks/permitted",
  issues: "issues",
  messagesBlocked: "messages/blocked",
  messagesDelivered: "messages/delivered"
};

