function abnormalConfigFromContext(context: ConnectorExecutionContext) {
  return AbnormalSecurityConfigSchema.parse(
    context.mockMode
      ? {
          ...context.config,
          accessToken: "mock-abnormal-access-token",
          apiBaseUrl: "https://api.abnormalplatform.example.test"
        }
      : context.config
  );
}

function abnormalApiUrl(config: AbnormalSecurityConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}${pathName}`;
}

function abnormalHeaders(config: AbnormalSecurityConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.accessToken}`
  };
}

function isAbnormalRecord(item: unknown): item is Record<string, unknown> {
  return Boolean(item) && typeof item === "object" && !Array.isArray(item);
}

function extractAbnormalThreats(payload: unknown): AbnormalThreatRecord[] {
  if (Array.isArray(payload)) {
    return payload
      .filter(isAbnormalRecord)
      .map((item) => AbnormalThreatRecordSchema.parse(item));
  }

  if (!payload || typeof payload !== "object") {
    return [];
  }

  const container = payload as Record<string, unknown>;
  const threatKeys = [
    "threats",
    "threatsData",
    "data",
    "items",
    "records",
    "results",
    "value"
  ];

  const records = threatKeys.flatMap((key) => {
    const value = container[key];

    return Array.isArray(value)
      ? value
          .filter(isAbnormalRecord)
          .map((item) => AbnormalThreatRecordSchema.parse(item))
      : [];
  });

  if (records.length > 0) {
    return records;
  }

  if (
    "threatId" in container ||
    "abxMessageId" in container ||
    "attackType" in container ||
    "remediationStatus" in container
  ) {
    return [AbnormalThreatRecordSchema.parse(container)];
  }

  return [];
}

function loadAbnormalFixtureThreats(config: AbnormalSecurityConfig) {
  const outcome = config.fixtureOutcome ?? "Blocked";

  if (outcome === "Missed" || outcome === "NoEvidence") {
    return [];
  }

  const remediated = outcome === "Blocked";

  return [
    AbnormalThreatRecordSchema.parse({
      abxMessageId: "abnormal-fixture-message",
      attackStrategy: "Credential Phishing",
      attackType: "Phishing",
      attackVector: "Link",
      attackedParty: "user@example.invalid",
      autoRemediated: remediated,
      fromAddress: "sender@example.invalid",
      postRemediated: remediated,
      receivedTime: "2026-06-01T12:00:00.000Z",
      remediationStatus: remediated ? "Auto Remediated" : "Detected",
      severity: "High",
      threatId: "abnormal-fixture-threat"
    })
  ];
}

async function fetchAbnormalThreats(config: AbnormalSecurityConfig) {
  const url = new URL(abnormalApiUrl(config, ABNORMAL_THREATS_URI));

  url.searchParams.set("pageSize", String(config.maxEvents));
  url.searchParams.set("pageNumber", String(config.pageNumber));

  const response = await connectorFetch(url, {
    headers: abnormalHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(
      `Abnormal Security threats API returned status ${response.status}.`
    );
  }

  return extractAbnormalThreats(await response.json()).slice(
    0,
    config.maxEvents
  );
}

function abnormalRecordValue(
  record: AbnormalThreatRecord,
  keys: string[]
): string | null {
  for (const key of keys) {
    const value = record[key];

    if (typeof value === "string" && value.trim().length > 0) {
      return value;
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }
  }

  return null;
}

function abnormalThreatId(record: AbnormalThreatRecord, index: number) {
  return (
    abnormalRecordValue(record, [
      "threatId",
      "threatID",
      "abxMessageId",
      "abx_message_id",
      "internetMessageId",
      "messageId",
      "id"
    ]) ?? `threat-${index + 1}`
  );
}

function abnormalBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return /^(true|yes|1)$/iu.test(value.trim());
  }

  return false;
}

function abnormalThreatTimestamp(
  record: AbnormalThreatRecord,
  fallback: string
) {
  const value = abnormalRecordValue(record, [
    "receivedTime",
    "received_time",
    "createdTime",
    "detectedTime",
    "timestamp"
  ]);

  if (!value) {
    return fallback;
  }

  const parsed = new Date(value);

  return Number.isNaN(parsed.getTime()) ? fallback : parsed.toISOString();
}

function isAbnormalBlockedThreat(record: AbnormalThreatRecord) {
  if (
    abnormalBoolean(record.autoRemediated) ||
    abnormalBoolean(record.postRemediated)
  ) {
    return true;
  }

  return /(^|[^a-z])(auto[ -]?remediated|post[ -]?remediated|remediated|blocked|quarantined|moved|trashed|deleted|removed)([^a-z]|$)/iu.test(
    JSON.stringify(record)
  );
}

function createAbnormalSignals(input: { threats: AbnormalThreatRecord[] }) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: "abnormal-security://threats",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "ControlObservation",
      signalSubcategory: "EmailSecurityControl",
      sourceType: "abnormal_security.threats.metadata",
      timestampObserved
    })
  ];

  input.threats.forEach((threat, index) => {
    const blocked = isAbnormalBlockedThreat(threat);
    const threatId = abnormalThreatId(threat, index);
    const observedAt = abnormalThreatTimestamp(threat, timestampObserved);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: blocked ? 0.86 : 0.78,
        freshness: "Fresh",
        rawPayloadPointer: `abnormal-security://threats/${encodeURIComponent(
          threatId
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: blocked
          ? "EmailThreatBlocked"
          : "EmailThreatDetected",
        sourceType: blocked
          ? "abnormal_security.threats.threat_blocked"
          : "abnormal_security.threats.threat_detected",
        timestampObserved: observedAt
      })
    );
  });

  if (input.threats.length === 0) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.6,
        freshness: "Fresh",
        rawPayloadPointer: "abnormal-security://threats/no-evidence",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NoEmailThreatEvidence",
        sourceType: "abnormal_security.threats.no_evidence",
        timestampObserved
      })
    );
  }

  return signals;
}

async function getAbnormalHealth(context: ConnectorExecutionContext) {
  const startedAt = Date.now();
  const config = abnormalConfigFromContext(context);

  if (context.mockMode) {
    return createMockHealth(ABNORMAL_SECURITY_CONNECTOR_MANIFEST, context);
  }

  try {
    const threats = await fetchAbnormalThreats(config);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Abnormal Security threat-log read-only access verified; ${threats.length} threat record(s) accessible.`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Abnormal Security health check failed: ${
        error instanceof Error
          ? error.message
          : "Unknown Abnormal Security API error."
      }`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

async function observeAbnormalControl(context: ConnectorExecutionContext) {
  const startedAt = Date.now();
  const config = abnormalConfigFromContext(context);

  try {
    const threats = context.mockMode
      ? loadAbnormalFixtureThreats(config)
      : await fetchAbnormalThreats(config);
    const blocked = threats.some((threat) => isAbnormalBlockedThreat(threat));

    return {
      confidence: threats.length > 0 ? 0.82 : 0.54,
      detail:
        threats.length > 0
          ? `Abnormal Security returned ${threats.length} threat-log record(s) for the validation context.`
          : "Abnormal Security threat-log lookup completed but returned no matching email-security evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: blocked
        ? "Blocked"
        : threats.length > 0
          ? "Detected"
          : "NoEvidence",
      sourceType: "abnormal_security.observer"
    };
  } catch (error) {
    return {
      confidence: 0.32,
      detail: `Abnormal Security lookup failed: ${
        error instanceof Error
          ? error.message
          : "Unknown Abnormal Security API error."
      }`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "abnormal_security.observer"
    };
  }
}

function createAbnormalSecurityConnector(): Connector {
  return {
    manifest: ABNORMAL_SECURITY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = abnormalConfigFromContext(parsedContext);
      const threats = parsedContext.mockMode
        ? loadAbnormalFixtureThreats(config)
        : await fetchAbnormalThreats(config);

      return createAbnormalSignals({ threats });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAbnormalHealth(parsedContext);
    },
    observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return observeAbnormalControl(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = abnormalConfigFromContext(parsedContext);
      const threats = parsedContext.mockMode
        ? loadAbnormalFixtureThreats(config)
        : await fetchAbnormalThreats(config);

      return ConnectorSyncResultSchema.parse({
        assets: createAbnormalSecurityAssets(),
        health: await getAbnormalHealth(parsedContext),
        signals: createAbnormalSignals({ threats }).map((signal) =>
          createTimestampedSignal(
            ABNORMAL_SECURITY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

