class GoogleWorkspaceHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeGoogleWorkspaceUrl(value: string) {
  return value.replace(/\/+$/u, "");
}

function googleWorkspaceDirectoryUrl(
  config: Pick<GoogleWorkspaceRuntimeConfig, "directoryBaseUrl">,
  pathName: string
) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeGoogleWorkspaceUrl(config.directoryBaseUrl)}${pathName}`;
}

function base64UrlJson(value: unknown) {
  return Buffer.from(JSON.stringify(value)).toString("base64url");
}

function normalizeGoogleWorkspacePrivateKey(privateKey: string) {
  return privateKey.replace(/\\n/gu, "\n");
}

function createGoogleWorkspaceJwt(config: GoogleWorkspaceServiceAccountConfig) {
  const nowSeconds = Math.floor(Date.now() / 1000);
  const signingInput = [
    base64UrlJson({
      alg: "RS256",
      typ: "JWT"
    }),
    base64UrlJson({
      aud: config.tokenUri,
      exp: nowSeconds + 3600,
      iat: nowSeconds,
      iss: config.clientEmail,
      scope: [
        "https://www.googleapis.com/auth/admin.directory.user.readonly",
        "https://www.googleapis.com/auth/admin.directory.group.readonly"
      ].join(" "),
      sub: config.delegatedAdminEmail
    })
  ].join(".");
  const signer = createSign("RSA-SHA256");

  signer.update(signingInput);
  signer.end();

  return `${signingInput}.${signer
    .sign(normalizeGoogleWorkspacePrivateKey(config.privateKey))
    .toString("base64url")}`;
}

async function getGoogleWorkspaceServiceAccountAccessToken(
  config: GoogleWorkspaceServiceAccountConfig
) {
  const response = await connectorFetch(config.tokenUri, {
    body: new URLSearchParams({
      assertion: createGoogleWorkspaceJwt(config),
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer"
    }),
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new GoogleWorkspaceHttpError(
      response.status,
      `Google OAuth token request failed with status ${response.status}.`
    );
  }

  return GoogleWorkspaceTokenSchema.parse(await response.json()).access_token;
}

async function createGoogleWorkspaceRuntimeConfig(
  context: ConnectorExecutionContext
): Promise<GoogleWorkspaceRuntimeConfig> {
  if (context.mockMode) {
    return {
      accessToken: "mock",
      customerId: "my_customer",
      directoryBaseUrl: GOOGLE_WORKSPACE_DIRECTORY_BASE_URL,
      includeGroups: true
    };
  }

  if (context.authType === "serviceAccount") {
    const config = GoogleWorkspaceServiceAccountConfigSchema.parse(
      context.config
    );

    return {
      accessToken: await getGoogleWorkspaceServiceAccountAccessToken(config),
      customerId: config.customerId,
      directoryBaseUrl: config.directoryBaseUrl,
      includeGroups: config.includeGroups
    };
  }

  const config = GoogleWorkspaceOAuthAccessTokenConfigSchema.parse(
    context.config
  );

  return {
    accessToken: config.accessToken,
    customerId: config.customerId,
    directoryBaseUrl: config.directoryBaseUrl,
    includeGroups: config.includeGroups
  };
}

async function fetchGoogleWorkspaceJson<T>(input: {
  config: GoogleWorkspaceRuntimeConfig;
  pathName: string;
}) {
  const response = await connectorFetch(
    googleWorkspaceDirectoryUrl(input.config, input.pathName),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${input.config.accessToken}`
      }
    }
  );

  if (!response.ok) {
    throw new GoogleWorkspaceHttpError(
      response.status,
      `Google Admin Directory request failed with status ${response.status}.`
    );
  }

  return (await response.json()) as T;
}

function createGoogleWorkspacePagedUrl(
  config: GoogleWorkspaceRuntimeConfig,
  pathName: string,
  pageToken: string
) {
  const url = new URL(googleWorkspaceDirectoryUrl(config, pathName));

  url.searchParams.set("pageToken", pageToken);

  return url.toString();
}

async function fetchGoogleWorkspaceUsers(
  config: GoogleWorkspaceRuntimeConfig,
  maxResults = 200
) {
  const users: GoogleWorkspaceUser[] = [];
  let nextPath: string | null = `/users?customer=${encodeURIComponent(
    config.customerId
  )}&maxResults=${maxResults}&projection=full`;
  let pageCount = 0;

  while (nextPath && pageCount < 10) {
    const collection = GoogleWorkspaceUsersCollectionSchema.parse(
      await fetchGoogleWorkspaceJson({
        config,
        pathName: nextPath
      })
    );

    users.push(...collection.users);
    nextPath = collection.nextPageToken
      ? createGoogleWorkspacePagedUrl(
          config,
          nextPath,
          collection.nextPageToken
        )
      : null;
    pageCount += 1;
  }

  return users;
}

async function fetchGoogleWorkspaceGroups(
  config: GoogleWorkspaceRuntimeConfig
) {
  const groups: GoogleWorkspaceGroup[] = [];
  let nextPath: string | null = `/groups?customer=${encodeURIComponent(
    config.customerId
  )}&maxResults=200`;
  let pageCount = 0;

  while (nextPath && pageCount < 10) {
    const collection = GoogleWorkspaceGroupsCollectionSchema.parse(
      await fetchGoogleWorkspaceJson({
        config,
        pathName: nextPath
      })
    );

    groups.push(...collection.groups);
    nextPath = collection.nextPageToken
      ? createGoogleWorkspacePagedUrl(
          config,
          nextPath,
          collection.nextPageToken
        )
      : null;
    pageCount += 1;
  }

  return groups;
}

function googleWorkspaceUserName(user: GoogleWorkspaceUser) {
  return user.name?.fullName ?? user.primaryEmail;
}

function googleWorkspaceGroupName(group: GoogleWorkspaceGroup) {
  return group.name ?? group.email;
}

function isPrivilegedGoogleWorkspaceName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|super(?:user)?|owner)\b/iu.test(
    value
  );
}

function createGoogleWorkspaceAssets(): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "google-workspace"
      },
      internetExposed: false,
      name: "Google Workspace",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "google-workspace", "mfa"]
    })
  ];
}

function createGoogleWorkspaceSignals(input: {
  groups: GoogleWorkspaceGroup[];
  users: GoogleWorkspaceUser[];
}) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "google-workspace://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "google.workspace.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const name = googleWorkspaceUserName(user);
    const privileged =
      user.isAdmin === true ||
      user.isDelegatedAdmin === true ||
      isPrivilegedGoogleWorkspaceName(name) ||
      isPrivilegedGoogleWorkspaceName(user.primaryEmail);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: user.suspended ? "Stale" : "Fresh",
        rawPayloadPointer: `google-workspace://user/${user.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: privileged ? "PrivilegedIdentity" : "UserAccount",
        sourceType: "google.workspace.user.metadata",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: user.suspended ? "Stale" : "Fresh",
        rawPayloadPointer: `google-workspace://user/${user.id}/mfa`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory:
          user.isEnrolledIn2Sv === true
            ? "MFAEnabled"
            : user.isEnrolledIn2Sv === false
              ? "MFADisabled"
              : "MFAUnknown",
        sourceType: "google.workspace.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    const name = googleWorkspaceGroupName(group);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `google-workspace://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: isPrivilegedGoogleWorkspaceName(name)
          ? "PrivilegedGroup"
          : "Group",
        sourceType: "google.workspace.group.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

function loadGoogleWorkspaceFixtureInventory() {
  return {
    groups: GOOGLE_WORKSPACE_FIXTURE_GROUPS,
    users: GOOGLE_WORKSPACE_FIXTURE_USERS
  };
}

async function loadGoogleWorkspaceInventory(
  config: GoogleWorkspaceRuntimeConfig
) {
  const [users, groups] = await Promise.all([
    fetchGoogleWorkspaceUsers(config),
    config.includeGroups
      ? fetchGoogleWorkspaceGroups(config)
      : Promise.resolve([])
  ]);

  return {
    groups,
    users
  };
}

async function getGoogleWorkspaceHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GOOGLE_WORKSPACE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = await createGoogleWorkspaceRuntimeConfig(context);
  const users = await fetchGoogleWorkspaceUsers(config, 1);
  const principal =
    users[0]?.primaryEmail ??
    (context.authType === "serviceAccount"
      ? GoogleWorkspaceServiceAccountConfigSchema.parse(context.config)
          .delegatedAdminEmail
      : "authorized Google Workspace token");

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Google Admin Directory read-only access verified for ${principal}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createGoogleWorkspaceConnector(): Connector {
  return {
    manifest: GOOGLE_WORKSPACE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadGoogleWorkspaceFixtureInventory()
        : await loadGoogleWorkspaceInventory(
            await createGoogleWorkspaceRuntimeConfig(parsedContext)
          );

      return createGoogleWorkspaceSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGoogleWorkspaceHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadGoogleWorkspaceFixtureInventory()
        : await loadGoogleWorkspaceInventory(
            await createGoogleWorkspaceRuntimeConfig(parsedContext)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createGoogleWorkspaceAssets(),
        health: await getGoogleWorkspaceHealth(parsedContext),
        signals: createGoogleWorkspaceSignals(inventory).map((signal) =>
          createTimestampedSignal(
            GOOGLE_WORKSPACE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

