class OktaHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function normalizeOktaOrgUrl(config: OktaApiTokenConfig) {
  return config.orgUrl.replace(/\/+$/u, "");
}

function oktaApiUrl(config: OktaApiTokenConfig, pathName: string) {
  if (pathName.startsWith("http://") || pathName.startsWith("https://")) {
    return pathName;
  }

  return `${normalizeOktaOrgUrl(config)}${pathName}`;
}

async function fetchOktaJson<T>(config: OktaApiTokenConfig, pathName: string) {
  const response = await connectorFetch(oktaApiUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: `SSWS ${config.apiToken}`
    }
  });

  if (!response.ok) {
    throw new OktaHttpError(
      response.status,
      `Okta API request failed with status ${response.status}.`
    );
  }

  return {
    body: (await response.json()) as T,
    headers: response.headers
  };
}

function getOktaNextLink(headers: Headers) {
  const link = headers.get("link");

  if (!link) {
    return null;
  }

  const next = link
    .split(",")
    .map((part) => part.trim())
    .find((part) => /\brel="next"\b/u.test(part));
  const match = next?.match(/<([^>]+)>/u);

  return match?.[1] ?? null;
}

async function fetchOktaArray<T>(
  config: OktaApiTokenConfig,
  pathName: string,
  schema: z.ZodType<T>
) {
  const rows: T[] = [];
  let nextPath: string | null = pathName;
  let pageCount = 0;

  while (nextPath && pageCount < 10) {
    const result = await fetchOktaJson<unknown[]>(config, nextPath);

    rows.push(...result.body.map((row) => schema.parse(row)));
    nextPath = getOktaNextLink(result.headers);
    pageCount += 1;
  }

  return rows;
}

async function fetchOktaFactors(
  config: OktaApiTokenConfig,
  userId: string
): Promise<OktaFactor[]> {
  if (!config.includeFactors) {
    return [];
  }

  try {
    return fetchOktaArray(
      config,
      `/api/v1/users/${encodeURIComponent(userId)}/factors`,
      OktaFactorSchema
    );
  } catch (error) {
    if (
      error instanceof OktaHttpError &&
      (error.status === 403 || error.status === 404)
    ) {
      return [];
    }

    throw error;
  }
}

function oktaUserLabel(user: OktaUser) {
  return (
    user.profile.displayName ??
    user.profile.email ??
    user.profile.login ??
    user.id
  );
}

function oktaUserLogin(user: OktaUser) {
  return user.profile.login ?? user.profile.email ?? user.id;
}

function oktaGroupName(group: OktaGroup) {
  return group.profile.name ?? group.id;
}

function oktaAppLabel(app: OktaApplication) {
  return app.label ?? app.name ?? app.id;
}

function isPrivilegedOktaName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|superuser|root|security)\b/iu.test(
    value
  );
}

function createOktaAssets(input: {
  apps: OktaApplication[];
  orgUrl: string;
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "okta",
        url: input.orgUrl
      },
      internetExposed: false,
      name: "Okta identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "okta", "mfa"]
    }),
    ...input.apps.map((app) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: app.status === "ACTIVE" ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          appId: app.id,
          name: app.name ?? null,
          signOnMode: app.signOnMode ?? null,
          status: app.status ?? "UNKNOWN"
        },
        internetExposed: true,
        name: oktaAppLabel(app),
        owner: "identity-security",
        status: app.status === "ACTIVE" ? "Active" : "Inactive",
        tags: ["identity", "okta", "sso", app.signOnMode ?? "unknown"]
      })
    )
  ];
}

function createOktaSignals(input: {
  apps: OktaApplication[];
  factorsByUserId: Map<string, OktaFactor[]>;
  groups: OktaGroup[];
  orgUrl: string;
  users: OktaUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "okta://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "okta.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const factors = input.factorsByUserId.get(user.id) ?? [];
    const login = oktaUserLogin(user);
    const privileged =
      isPrivilegedOktaName(login) || isPrivilegedOktaName(oktaUserLabel(user));
    const mfaEnabled = factors.some((factor) => factor.status === "ACTIVE");
    const userPointer = `okta://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: privileged ? "PrivilegedIdentity" : "UserAccount",
        sourceType: "okta.user.metadata",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/factors`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: mfaEnabled ? "MFAEnabled" : "MFADisabled",
        sourceType: "okta.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    const name = oktaGroupName(group);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `okta://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: isPrivilegedOktaName(name)
          ? "PrivilegedGroup"
          : "Group",
        sourceType: "okta.group.metadata",
        timestampObserved
      })
    );
  }

  for (const app of input.apps) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `okta://app/${app.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SaaSApplication",
        sourceType: "okta.application.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadOktaInventory(config: OktaApiTokenConfig) {
  const [users, groups, apps] = await Promise.all([
    fetchOktaArray(config, "/api/v1/users?limit=200", OktaUserSchema),
    config.includeGroups
      ? fetchOktaArray(config, "/api/v1/groups?limit=200", OktaGroupSchema)
      : Promise.resolve([]),
    config.includeApps
      ? fetchOktaArray(config, "/api/v1/apps?limit=200", OktaApplicationSchema)
      : Promise.resolve([])
  ]);
  const factorsByUserId = new Map<string, OktaFactor[]>();

  for (const user of users) {
    factorsByUserId.set(user.id, await fetchOktaFactors(config, user.id));
  }

  return {
    apps,
    factorsByUserId,
    groups,
    users
  };
}

function loadOktaFixtureInventory() {
  return {
    apps: OKTA_FIXTURE_APPS,
    factorsByUserId: OKTA_FIXTURE_FACTORS,
    groups: OKTA_FIXTURE_GROUPS,
    users: OKTA_FIXTURE_USERS
  };
}

async function getOktaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(OKTA_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = OktaApiTokenConfigSchema.parse(context.config);
  const result = await fetchOktaJson<unknown>(config, "/api/v1/users/me");
  const me = OktaMeSchema.parse(result.body);
  const login = me.profile?.login ?? me.id ?? "authorized Okta token";

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Okta API token verified for ${login}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createOktaConnector(): Connector {
  return {
    manifest: OKTA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = OktaApiTokenConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiToken: "mock",
              orgUrl: "https://periscan.okta.test"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadOktaFixtureInventory()
        : await loadOktaInventory(config);

      return createOktaSignals({
        ...inventory,
        orgUrl: config.orgUrl
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getOktaHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = OktaApiTokenConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiToken: "mock",
              orgUrl: "https://periscan.okta.test"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadOktaFixtureInventory()
        : await loadOktaInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createOktaAssets({
          apps: inventory.apps,
          orgUrl: config.orgUrl
        }),
        health: await getOktaHealth(parsedContext),
        signals: createOktaSignals({
          ...inventory,
          orgUrl: config.orgUrl
        }).map((signal) =>
          createTimestampedSignal(
            OKTA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

