class DuoHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function duoRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function duoRecordArray(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value) ? value.map(duoRecord) : [];
}

function duoString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function duoNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function duoNumber(value: unknown, fallback = 0) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.trunc(value));
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  }

  return fallback;
}

function duoBoolean(value: unknown, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value > 0;
  }

  if (typeof value === "string") {
    return /^(?:1|true|yes|active)$/iu.test(value.trim());
  }

  return fallback;
}

function isPrivilegedDuoName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|owner|root|superuser)\b/iu.test(
    value
  );
}

function duoSafeSlug(value: string) {
  const slug = value
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "");

  return slug.length > 0 ? slug : "item";
}

function parseDuoUser(value: unknown, index: number): DuoUser {
  const row = duoRecord(value);
  const groups = duoRecordArray(row.groups);
  const phones = duoRecordArray(row.phones);
  const tokens = [
    ...duoRecordArray(row.tokens),
    ...duoRecordArray(row.u2ftokens),
    ...duoRecordArray(row.webauthncredentials)
  ];
  const username = duoString(row.username, `duo-user-${index + 1}`);
  const realName = duoNullableString(row.realname ?? row.realName);
  const groupNames = groups.map((group) => duoString(group.name, ""));
  const privileged =
    isPrivilegedDuoName(username) ||
    (realName ? isPrivilegedDuoName(realName) : false) ||
    groupNames.some((name) => isPrivilegedDuoName(name));
  const phoneCount =
    phones.length > 0 ? phones.length : duoNumber(row.phone_count, 0);
  const hasHardwareToken = tokens.length > 0 || duoBoolean(row.has_token);

  return DuoUserSchema.parse({
    bypassStatus: duoNullableString(row.bypass_status ?? row.status),
    enrolled: duoBoolean(row.is_enrolled ?? row.enrolled, false),
    hasHardwareToken,
    id: duoString(
      row.user_id ?? row.userId ?? row.object_id,
      `duo-user-${index + 1}`
    ),
    phoneCount,
    privileged,
    realName,
    status: duoString(row.status, "unknown"),
    username
  });
}

function parseDuoGroup(value: unknown, index: number): DuoGroup {
  const row = duoRecord(value);
  const name = duoString(row.name, `Duo Group ${index + 1}`);

  return DuoGroupSchema.parse({
    id: duoString(
      row.group_id ?? row.groupId ?? row.object_id,
      `duo-group-${index + 1}`
    ),
    name,
    privileged: isPrivilegedDuoName(name),
    status: duoString(row.status, "active"),
    userCount:
      duoRecordArray(row.users).length > 0
        ? duoRecordArray(row.users).length
        : duoNumber(row.user_count, 0)
  });
}

function parseDuoPhone(value: unknown, index: number): DuoPhone {
  const row = duoRecord(value);

  return DuoPhoneSchema.parse({
    activated: duoBoolean(row.activated ?? row.is_enrolled, false),
    id: duoString(
      row.phone_id ?? row.phoneId ?? row.object_id,
      `duo-phone-${index + 1}`
    ),
    platform: duoNullableString(row.platform),
    type: duoNullableString(row.type),
    userCount:
      duoRecordArray(row.users).length > 0
        ? duoRecordArray(row.users).length
        : duoNumber(row.user_count, 0)
  });
}

function parseDuoIntegration(value: unknown, index: number): DuoIntegration {
  const row = duoRecord(value);
  const name = duoString(
    row.name ?? row.integration_name ?? row.type,
    `Duo Protected Application ${index + 1}`
  );

  return DuoIntegrationSchema.parse({
    id: duoString(
      row.application_id ?? row.app_id ?? row.object_id,
      `duo-app-${duoSafeSlug(name)}-${index + 1}`
    ),
    name,
    status: duoNullableString(row.status),
    type: duoNullableString(row.type ?? row.integration_type)
  });
}

function normalizeDuoApiHostname(config: DuoAdminApiConfig) {
  return config.apiHostname.trim().toLowerCase().replace(/\/+$/u, "");
}

function duoEncode(value: string) {
  return encodeURIComponent(value).replace(
    /[!'()*]/gu,
    (character) => `%${character.charCodeAt(0).toString(16).toUpperCase()}`
  );
}

function duoCanonicalQuery(params: Record<string, string>) {
  return Object.entries(params)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, value]) => `${duoEncode(key)}=${duoEncode(value)}`)
    .join("&");
}

function assertDuoReadOnlyPath(pathName: string) {
  const allowedPaths = new Set([
    "/admin/v1/users",
    "/admin/v1/groups",
    "/admin/v1/phones",
    "/admin/v1/integrations"
  ]);

  if (!allowedPaths.has(pathName)) {
    throw new DuoHttpError(
      403,
      `Duo connector only permits read-only inventory paths; blocked ${pathName}.`
    );
  }
}

function createDuoAuthorizationHeader(input: {
  config: DuoAdminApiConfig;
  date: string;
  host: string;
  pathName: string;
  query: string;
}) {
  const canonical = [
    input.date,
    "GET",
    input.host,
    input.pathName,
    input.query
  ].join("\n");
  const signature = createHmac("sha1", input.config.secretKey)
    .update(canonical)
    .digest("hex");

  return `Basic ${Buffer.from(
    `${input.config.integrationKey}:${signature}`
  ).toString("base64")}`;
}

async function fetchDuoJson(
  config: DuoAdminApiConfig,
  pathName: string,
  params: Record<string, string>
) {
  assertDuoReadOnlyPath(pathName);

  const host = normalizeDuoApiHostname(config);
  const query = duoCanonicalQuery(params);
  const date = new Date().toUTCString();
  const url = `https://${host}${pathName}${query ? `?${query}` : ""}`;
  const response = await connectorFetch(url, {
    headers: {
      accept: "application/json",
      authorization: createDuoAuthorizationHeader({
        config,
        date,
        host,
        pathName,
        query
      }),
      date
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new DuoHttpError(
      response.status,
      `Duo Admin API request failed with status ${response.status}.`
    );
  }

  const body = DuoAdminApiEnvelopeSchema.parse(await response.json());

  if (body.stat.toUpperCase() !== "OK") {
    throw new DuoHttpError(
      body.code ?? response.status,
      body.message ?? "Duo Admin API returned a non-OK response."
    );
  }

  return body.response;
}

function duoResponseRows(response: unknown): unknown[] {
  if (Array.isArray(response)) {
    return response;
  }

  const record = duoRecord(response);

  if (Array.isArray(record.items)) {
    return record.items;
  }

  return [];
}

async function fetchDuoArray<T>(
  config: DuoAdminApiConfig,
  pathName: string,
  params: Record<string, string>,
  parser: (value: unknown, index: number) => T
) {
  const response = await fetchDuoJson(config, pathName, params);

  return duoResponseRows(response).map((row, index) => parser(row, index));
}

function createDuoAssets(input: {
  apiHostname: string;
  integrations: DuoIntegration[];
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        apiHostname: input.apiHostname,
        provider: "duo"
      },
      internetExposed: false,
      name: "Cisco Duo identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "duo", "mfa"]
    }),
    ...input.integrations.map((integration) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality:
          integration.status?.toLowerCase() === "inactive"
            ? "Moderate"
            : "High",
        environment: "production",
        identifiers: {
          applicationId: integration.id,
          provider: "duo",
          status: integration.status ?? "unknown",
          type: integration.type ?? "unknown"
        },
        internetExposed: true,
        name: integration.name,
        owner: "identity-security",
        status:
          integration.status?.toLowerCase() === "inactive"
            ? "Inactive"
            : "Active",
        tags: ["identity", "duo", "protected-application"]
      })
    )
  ];
}

function createDuoSignals(input: {
  groups: DuoGroup[];
  integrations: DuoIntegration[];
  phones: DuoPhone[];
  users: DuoUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "duo://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "duo.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const mfaEnabled =
      user.enrolled || user.phoneCount > 0 || user.hasHardwareToken;
    const userPointer = `duo://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "duo.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: mfaEnabled ? "MFAEnabled" : "MFADisabled",
        sourceType: "duo.user.mfa_posture",
        timestampObserved
      })
    );

    if (user.bypassStatus?.toLowerCase() === "bypass") {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `${userPointer}/status`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "DuoBypassEnabled",
          sourceType: "duo.user.bypass_posture",
          timestampObserved
        })
      );
    }
  }

  for (const group of input.groups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `duo://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: group.privileged ? "PrivilegedGroup" : "Group",
        sourceType: "duo.group.metadata",
        timestampObserved
      })
    );
  }

  for (const phone of input.phones) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.78,
        freshness: "Fresh",
        rawPayloadPointer: `duo://phone/${phone.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: phone.activated
          ? "DuoDeviceActivated"
          : "DuoDeviceNotActivated",
        sourceType: "duo.phone.metadata",
        timestampObserved
      })
    );
  }

  for (const integration of input.integrations) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `duo://integration/${integration.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "DuoProtectedApplication",
        sourceType: "duo.integration.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadDuoInventory(config: DuoAdminApiConfig) {
  const limit = String(config.limit);
  const [users, groups, phones, integrations] = await Promise.all([
    fetchDuoArray(config, "/admin/v1/users", { limit }, parseDuoUser),
    config.includeGroups
      ? fetchDuoArray(config, "/admin/v1/groups", { limit }, parseDuoGroup)
      : Promise.resolve([]),
    config.includePhones
      ? fetchDuoArray(config, "/admin/v1/phones", { limit }, parseDuoPhone)
      : Promise.resolve([]),
    config.includeIntegrations
      ? fetchDuoArray(
          config,
          "/admin/v1/integrations",
          { limit },
          parseDuoIntegration
        )
      : Promise.resolve([])
  ]);

  return {
    groups,
    integrations,
    phones,
    users
  };
}

function loadDuoFixtureInventory() {
  return {
    groups: DUO_FIXTURE_GROUPS,
    integrations: DUO_FIXTURE_INTEGRATIONS,
    phones: DUO_FIXTURE_PHONES,
    users: DUO_FIXTURE_USERS
  };
}

async function getDuoHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(DUO_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = DuoAdminApiConfigSchema.parse(context.config);

  await fetchDuoArray(config, "/admin/v1/users", { limit: "1" }, parseDuoUser);

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Duo Admin API read-resource access verified for ${normalizeDuoApiHostname(config)}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createDuoConnector(): Connector {
  return {
    manifest: DUO_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = DuoAdminApiConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiHostname: "api-fixture.duosecurity.test",
              integrationKey: "mock",
              secretKey: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadDuoFixtureInventory()
        : await loadDuoInventory(config);

      return createDuoSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getDuoHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = DuoAdminApiConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiHostname: "api-fixture.duosecurity.test",
              integrationKey: "mock",
              secretKey: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadDuoFixtureInventory()
        : await loadDuoInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createDuoAssets({
          apiHostname: normalizeDuoApiHostname(config),
          integrations: inventory.integrations
        }),
        health: await getDuoHealth(parsedContext),
        signals: createDuoSignals(inventory).map((signal) =>
          createTimestampedSignal(DUO_CONNECTOR_MANIFEST, parsedContext, signal)
        )
      });
    }
  };
}

const OneLoginOAuthConfigSchema = z.object({
  accountUrl: z.url(),
  clientId: z.string().min(1),
  clientSecret: z.string().min(1),
  includeApps: z.boolean().default(true),
  includeRoles: z.boolean().default(true),
  limit: z.number().int().min(1).max(1000).default(100)
});

const OneLoginUserSchema = z.object({
  displayName: z.string().nullable(),
  id: z.string().min(1),
  mfaEnabled: z.boolean().nullable(),
  privileged: z.boolean(),
  state: z.number().nullable(),
  status: z.number().nullable(),
  username: z.string().min(1)
});

const OneLoginRoleSchema = z.object({
  appCount: z.number().int().nonnegative(),
  id: z.string().min(1),
  name: z.string().min(1),
  privileged: z.boolean(),
  userCount: z.number().int().nonnegative()
});

const OneLoginAppSchema = z.object({
  authMethod: z.string().nullable(),
  id: z.string().min(1),
  name: z.string().min(1),
  roleCount: z.number().int().nonnegative(),
  visible: z.boolean().nullable()
});

const OneLoginTokenResponseSchema = z.object({
  access_token: z.string().min(1),
  account_id: z.union([z.number(), z.string()]).optional(),
  expires_in: z.number().int().positive().optional(),
  token_type: z.string().optional()
});

type OneLoginOAuthConfig = z.infer<typeof OneLoginOAuthConfigSchema>;
type OneLoginUser = z.infer<typeof OneLoginUserSchema>;
type OneLoginRole = z.infer<typeof OneLoginRoleSchema>;
type OneLoginApp = z.infer<typeof OneLoginAppSchema>;

