class OneLoginHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function oneLoginRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function oneLoginRows(value: unknown): unknown[] {
  if (Array.isArray(value)) {
    return value;
  }

  const record = oneLoginRecord(value);

  if (Array.isArray(record.data)) {
    return record.data;
  }

  if (Array.isArray(record.items)) {
    return record.items;
  }

  if (Array.isArray(record.result)) {
    return record.result;
  }

  return [];
}

function oneLoginString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function oneLoginNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function oneLoginId(value: unknown, fallback: string) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(Math.trunc(value));
  }

  return oneLoginString(value, fallback);
}

function oneLoginNumber(value: unknown) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.trunc(value);
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? parsed : null;
  }

  return null;
}

function oneLoginBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value > 0;
  }

  if (typeof value === "string") {
    return /^(?:1|true|yes|visible|active)$/iu.test(value.trim());
  }

  return null;
}

function isPrivilegedOneLoginName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|owner|root|superuser)\b/iu.test(
    value
  );
}

function oneLoginBaseUrl(config: OneLoginOAuthConfig) {
  return new URL(config.accountUrl).origin.replace(/\/+$/u, "");
}

function assertOneLoginReadOnlyPath(pathName: string) {
  const allowedPaths = new Set(["/api/2/users", "/api/2/roles", "/api/2/apps"]);

  if (!allowedPaths.has(pathName)) {
    throw new OneLoginHttpError(
      403,
      `OneLogin connector only permits read-only inventory paths; blocked ${pathName}.`
    );
  }
}

function oneLoginApiUrl(
  config: OneLoginOAuthConfig,
  pathName: string,
  params: Record<string, string>
) {
  assertOneLoginReadOnlyPath(pathName);

  const url = new URL(`${oneLoginBaseUrl(config)}${pathName}`);

  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }

  return url.toString();
}

async function fetchOneLoginAccessToken(config: OneLoginOAuthConfig) {
  const response = await connectorFetch(
    `${oneLoginBaseUrl(config)}/auth/oauth2/v2/token`,
    {
      body: JSON.stringify({
        grant_type: "client_credentials"
      }),
      headers: {
        accept: "application/json",
        authorization: `Basic ${Buffer.from(
          `${config.clientId}:${config.clientSecret}`
        ).toString("base64")}`,
        "content-type": "application/json"
      },
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new OneLoginHttpError(
      response.status,
      `OneLogin token request failed with status ${response.status}.`
    );
  }

  return OneLoginTokenResponseSchema.parse(await response.json()).access_token;
}

async function fetchOneLoginJson(
  config: OneLoginOAuthConfig,
  accessToken: string,
  pathName: string,
  params: Record<string, string>
) {
  const response = await connectorFetch(
    oneLoginApiUrl(config, pathName, params),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${accessToken}`
      },
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new OneLoginHttpError(
      response.status,
      `OneLogin API request failed with status ${response.status}.`
    );
  }

  return response.json() as Promise<unknown>;
}

async function fetchOneLoginArray<T>(
  config: OneLoginOAuthConfig,
  accessToken: string,
  pathName: string,
  params: Record<string, string>,
  parser: (value: unknown, index: number) => T
) {
  const response = await fetchOneLoginJson(
    config,
    accessToken,
    pathName,
    params
  );

  return oneLoginRows(response).map((row, index) => parser(row, index));
}

function parseOneLoginUser(value: unknown, index: number): OneLoginUser {
  const row = oneLoginRecord(value);
  const username = oneLoginString(
    row.username ?? row.email ?? row.samaccountname,
    `onelogin-user-${index + 1}`
  );
  const displayName =
    oneLoginNullableString(
      [row.firstname, row.lastname]
        .filter((name) => typeof name === "string" && name.length > 0)
        .join(" ")
    ) ?? oneLoginNullableString(row.name ?? row.email);
  const roleIds = Array.isArray(row.role_ids) ? row.role_ids : [];
  const privileged =
    isPrivilegedOneLoginName(username) ||
    (displayName ? isPrivilegedOneLoginName(displayName) : false) ||
    roleIds.some((roleId) => isPrivilegedOneLoginName(String(roleId)));
  const mfaEnabled =
    row.otp_device_id || row.mfa_device_count || row.mfa_enrolled
      ? oneLoginBoolean(
          row.otp_device_id ?? row.mfa_device_count ?? row.mfa_enrolled
        )
      : null;

  return OneLoginUserSchema.parse({
    displayName,
    id: oneLoginId(row.id, `onelogin-user-${index + 1}`),
    mfaEnabled,
    privileged,
    state: oneLoginNumber(row.state),
    status: oneLoginNumber(row.status),
    username
  });
}

function parseOneLoginRole(value: unknown, index: number): OneLoginRole {
  const row = oneLoginRecord(value);
  const apps = Array.isArray(row.apps) ? row.apps : [];
  const users = Array.isArray(row.users) ? row.users : [];
  const name = oneLoginString(row.name, `OneLogin Role ${index + 1}`);

  return OneLoginRoleSchema.parse({
    appCount: apps.length,
    id: oneLoginId(row.id, `onelogin-role-${index + 1}`),
    name,
    privileged: isPrivilegedOneLoginName(name),
    userCount: users.length
  });
}

function parseOneLoginApp(value: unknown, index: number): OneLoginApp {
  const row = oneLoginRecord(value);
  const roleIds = Array.isArray(row.role_ids) ? row.role_ids : [];

  return OneLoginAppSchema.parse({
    authMethod: oneLoginNullableString(
      row.auth_method_description ?? row.auth_method
    ),
    id: oneLoginId(row.id, `onelogin-app-${index + 1}`),
    name: oneLoginString(row.name, `OneLogin Application ${index + 1}`),
    roleCount: roleIds.length,
    visible: oneLoginBoolean(row.visible)
  });
}

function createOneLoginAssets(input: {
  accountUrl: string;
  apps: OneLoginApp[];
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        provider: "onelogin",
        url: input.accountUrl
      },
      internetExposed: false,
      name: "OneLogin identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "onelogin", "sso"]
    }),
    ...input.apps.map((app) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: app.visible === false ? "Moderate" : "High",
        environment: "production",
        identifiers: {
          appId: app.id,
          authMethod: app.authMethod,
          provider: "onelogin",
          visible: app.visible
        },
        internetExposed: true,
        name: app.name,
        owner: "identity-security",
        status: app.visible === false ? "Inactive" : "Active",
        tags: ["identity", "onelogin", "sso", app.authMethod ?? "unknown"]
      })
    )
  ];
}

function createOneLoginSignals(input: {
  apps: OneLoginApp[];
  roles: OneLoginRole[];
  users: OneLoginUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "onelogin://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "onelogin.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const userPointer = `onelogin://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.85,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "onelogin.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: user.mfaEnabled === null ? 0.55 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          user.mfaEnabled === null
            ? "MFAUnknown"
            : user.mfaEnabled
              ? "MFAEnabled"
              : "MFADisabled",
        sourceType: "onelogin.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const role of input.roles) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `onelogin://role/${role.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: role.privileged ? "PrivilegedRole" : "Role",
        sourceType: "onelogin.role.metadata",
        timestampObserved
      })
    );
  }

  for (const app of input.apps) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.83,
        freshness: "Fresh",
        rawPayloadPointer: `onelogin://app/${app.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SaaSApplication",
        sourceType: "onelogin.application.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadOneLoginInventory(
  config: OneLoginOAuthConfig,
  accessToken: string
) {
  const usersLimit = String(Math.min(config.limit, 50));
  const inventoryLimit = String(config.limit);
  const [users, roles, apps] = await Promise.all([
    fetchOneLoginArray(
      config,
      accessToken,
      "/api/2/users",
      { limit: usersLimit },
      parseOneLoginUser
    ),
    config.includeRoles
      ? fetchOneLoginArray(
          config,
          accessToken,
          "/api/2/roles",
          { limit: inventoryLimit },
          parseOneLoginRole
        )
      : Promise.resolve([]),
    config.includeApps
      ? fetchOneLoginArray(
          config,
          accessToken,
          "/api/2/apps",
          { limit: inventoryLimit },
          parseOneLoginApp
        )
      : Promise.resolve([])
  ]);

  return {
    apps,
    roles,
    users
  };
}

function loadOneLoginFixtureInventory() {
  return {
    apps: ONELOGIN_FIXTURE_APPS,
    roles: ONELOGIN_FIXTURE_ROLES,
    users: ONELOGIN_FIXTURE_USERS
  };
}

function createOneLoginHealthyStatus(
  config: OneLoginOAuthConfig,
  startedAt: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `OneLogin read-only API access verified for ${oneLoginBaseUrl(config)}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getOneLoginHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ONELOGIN_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = OneLoginOAuthConfigSchema.parse(context.config);
  const accessToken = await fetchOneLoginAccessToken(config);

  await fetchOneLoginArray(
    config,
    accessToken,
    "/api/2/users",
    { limit: "1" },
    parseOneLoginUser
  );

  return createOneLoginHealthyStatus(config, startedAt);
}

function createOneLoginConnector(): Connector {
  return {
    manifest: ONELOGIN_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = OneLoginOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              accountUrl: "https://periscan.onelogin.test",
              clientId: "mock",
              clientSecret: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadOneLoginFixtureInventory()
        : await loadOneLoginInventory(
            config,
            await fetchOneLoginAccessToken(config)
          );

      return createOneLoginSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getOneLoginHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = OneLoginOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              accountUrl: "https://periscan.onelogin.test",
              clientId: "mock",
              clientSecret: "mock"
            }
          : parsedContext.config
      );
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadOneLoginFixtureInventory()
        : await loadOneLoginInventory(
            config,
            await fetchOneLoginAccessToken(config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createOneLoginAssets({
          accountUrl: oneLoginBaseUrl(config),
          apps: inventory.apps
        }),
        health: parsedContext.mockMode
          ? createMockHealth(ONELOGIN_CONNECTOR_MANIFEST, parsedContext)
          : createOneLoginHealthyStatus(config, startedAt),
        signals: createOneLoginSignals(inventory).map((signal) =>
          createTimestampedSignal(
            ONELOGIN_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const PingOneOAuthConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.pingone.com"),
  authBaseUrl: z.url().default("https://auth.pingone.com"),
  clientId: z.string().min(1),
  clientSecret: z.string().min(1),
  environmentId: z.string().min(1),
  includeApplications: z.boolean().default(true),
  includeGroups: z.boolean().default(true),
  limit: z.number().int().min(1).max(100).default(100),
  tokenEndpointAuthMethod: z
    .enum(["clientSecretBasic", "clientSecretPost"])
    .default("clientSecretBasic")
});

const PingOneUserSchema = z.object({
  displayName: z.string().nullable(),
  enabled: z.boolean().nullable(),
  id: z.string().min(1),
  mfaEnabled: z.boolean().nullable(),
  privileged: z.boolean(),
  username: z.string().min(1)
});

const PingOneGroupSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  privileged: z.boolean(),
  userCount: z.number().int().nonnegative()
});

const PingOneApplicationSchema = z.object({
  enabled: z.boolean().nullable(),
  id: z.string().min(1),
  name: z.string().min(1),
  protocol: z.string().nullable(),
  type: z.string().nullable()
});

const PingOneTokenResponseSchema = z.object({
  access_token: z.string().min(1),
  expires_in: z.number().int().positive().optional(),
  token_type: z.string().optional()
});

type PingOneOAuthConfig = z.infer<typeof PingOneOAuthConfigSchema>;
type PingOneUser = z.infer<typeof PingOneUserSchema>;
type PingOneGroup = z.infer<typeof PingOneGroupSchema>;
type PingOneApplication = z.infer<typeof PingOneApplicationSchema>;

