class PingOneHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function pingOneRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function pingOneRows(value: unknown, embeddedKey: string): unknown[] {
  if (Array.isArray(value)) {
    return value;
  }

  const record = pingOneRecord(value);
  const embedded = pingOneRecord(record._embedded);

  if (Array.isArray(embedded[embeddedKey])) {
    return embedded[embeddedKey];
  }

  if (Array.isArray(record[embeddedKey])) {
    return record[embeddedKey];
  }

  return [];
}

function pingOneString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function pingOneNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function pingOneBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return /^(?:true|enabled|active|1)$/iu.test(value.trim());
  }

  if (typeof value === "number") {
    return value > 0;
  }

  return null;
}

function pingOneNumber(value: unknown) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.trunc(value));
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
  }

  return 0;
}

function isPrivilegedPingOneName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|owner|root|superuser)\b/iu.test(
    value
  );
}

function pingOneBaseUrl(value: string) {
  return new URL(value).origin.replace(/\/+$/u, "");
}

function pingOneTokenUrl(config: PingOneOAuthConfig) {
  return `${pingOneBaseUrl(config.authBaseUrl)}/${encodeURIComponent(
    config.environmentId
  )}/as/token`;
}

function assertPingOneReadOnlyPath(
  config: PingOneOAuthConfig,
  pathName: string
) {
  const environmentPrefix = `/v1/environments/${config.environmentId}`;
  const allowedPaths = new Set([
    `${environmentPrefix}/users`,
    `${environmentPrefix}/groups`,
    `${environmentPrefix}/applications`
  ]);

  if (!allowedPaths.has(pathName)) {
    throw new PingOneHttpError(
      403,
      `PingOne connector only permits read-only inventory paths; blocked ${pathName}.`
    );
  }
}

function pingOneApiUrl(
  config: PingOneOAuthConfig,
  pathName: string,
  params: Record<string, string>
) {
  assertPingOneReadOnlyPath(config, pathName);

  const url = new URL(`${pingOneBaseUrl(config.apiBaseUrl)}${pathName}`);

  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }

  return url.toString();
}

async function fetchPingOneAccessToken(config: PingOneOAuthConfig) {
  const body = new URLSearchParams({
    grant_type: "client_credentials"
  });
  const headers: Record<string, string> = {
    accept: "application/json",
    "content-type": "application/x-www-form-urlencoded"
  };

  if (config.tokenEndpointAuthMethod === "clientSecretPost") {
    body.set("client_id", config.clientId);
    body.set("client_secret", config.clientSecret);
  } else {
    headers.authorization = `Basic ${Buffer.from(
      `${config.clientId}:${config.clientSecret}`
    ).toString("base64")}`;
  }

  const response = await connectorFetch(pingOneTokenUrl(config), {
    body: body.toString(),
    headers,
    method: "POST"
  });

  if (!response.ok) {
    throw new PingOneHttpError(
      response.status,
      `PingOne token request failed with status ${response.status}.`
    );
  }

  return PingOneTokenResponseSchema.parse(await response.json()).access_token;
}

async function fetchPingOneJson(
  config: PingOneOAuthConfig,
  accessToken: string,
  pathName: string,
  params: Record<string, string>
) {
  const response = await connectorFetch(
    pingOneApiUrl(config, pathName, params),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${accessToken}`
      },
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new PingOneHttpError(
      response.status,
      `PingOne API request failed with status ${response.status}.`
    );
  }

  return response.json() as Promise<unknown>;
}

async function fetchPingOneArray<T>(
  config: PingOneOAuthConfig,
  accessToken: string,
  pathName: string,
  params: Record<string, string>,
  embeddedKey: string,
  parser: (value: unknown, index: number) => T
) {
  const response = await fetchPingOneJson(
    config,
    accessToken,
    pathName,
    params
  );

  return pingOneRows(response, embeddedKey).map((row, index) =>
    parser(row, index)
  );
}

function parsePingOneUser(value: unknown, index: number): PingOneUser {
  const row = pingOneRecord(value);
  const account = pingOneRecord(row.account);
  const username = pingOneString(
    row.username ?? row.email ?? row.externalId,
    `pingone-user-${index + 1}`
  );
  const displayName =
    pingOneNullableString(row.name) ??
    pingOneNullableString(
      [row.givenName, row.familyName]
        .filter((name) => typeof name === "string" && name.length > 0)
        .join(" ")
    );
  const mfaEnabled =
    row.mfaEnabled ??
    row.mfa_enrolled ??
    row.mfaDeviceCount ??
    pingOneRecord(row._embedded).devices;

  return PingOneUserSchema.parse({
    displayName,
    enabled: pingOneBoolean(row.enabled ?? account.canAuthenticate),
    id: pingOneString(row.id, `pingone-user-${index + 1}`),
    mfaEnabled:
      mfaEnabled === undefined
        ? null
        : Array.isArray(mfaEnabled)
          ? mfaEnabled.length > 0
          : pingOneBoolean(mfaEnabled),
    privileged:
      isPrivilegedPingOneName(username) ||
      (displayName ? isPrivilegedPingOneName(displayName) : false),
    username
  });
}

function parsePingOneGroup(value: unknown, index: number): PingOneGroup {
  const row = pingOneRecord(value);
  const name = pingOneString(row.name, `PingOne Group ${index + 1}`);
  const users = row.users;

  return PingOneGroupSchema.parse({
    id: pingOneString(row.id, `pingone-group-${index + 1}`),
    name,
    privileged: isPrivilegedPingOneName(name),
    userCount: Array.isArray(users)
      ? users.length
      : pingOneNumber(users ?? row.userCount ?? row.memberCount)
  });
}

function parsePingOneApplication(
  value: unknown,
  index: number
): PingOneApplication {
  const row = pingOneRecord(value);
  const oidc = pingOneRecord(row.oidc);
  const saml = pingOneRecord(row.saml);

  return PingOneApplicationSchema.parse({
    enabled: pingOneBoolean(row.enabled),
    id: pingOneString(row.id, `pingone-app-${index + 1}`),
    name: pingOneString(row.name, `PingOne Application ${index + 1}`),
    protocol:
      pingOneNullableString(row.protocol) ??
      (Object.keys(oidc).length > 0
        ? "OPENID_CONNECT"
        : Object.keys(saml).length > 0
          ? "SAML"
          : null),
    type: pingOneNullableString(row.type)
  });
}

function createPingOneAssets(input: {
  applications: PingOneApplication[];
  environmentId: string;
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        environmentId: input.environmentId,
        provider: "pingone"
      },
      internetExposed: false,
      name: "PingOne identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "pingone", "sso"]
    }),
    ...input.applications.map((application) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality:
          application.enabled === false ? "Moderate" : "High",
        environment: "production",
        identifiers: {
          applicationId: application.id,
          protocol: application.protocol,
          provider: "pingone",
          type: application.type
        },
        internetExposed: true,
        name: application.name,
        owner: "identity-security",
        status: application.enabled === false ? "Inactive" : "Active",
        tags: ["identity", "pingone", "sso", application.protocol ?? "unknown"]
      })
    )
  ];
}

function createPingOneSignals(input: {
  applications: PingOneApplication[];
  groups: PingOneGroup[];
  users: PingOneUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "pingone://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "pingone.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const userPointer = `pingone://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.85,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "pingone.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: user.mfaEnabled === null ? 0.55 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          user.mfaEnabled === null
            ? "MFAUnknown"
            : user.mfaEnabled
              ? "MFAEnabled"
              : "MFADisabled",
        sourceType: "pingone.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `pingone://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: group.privileged ? "PrivilegedGroup" : "Group",
        sourceType: "pingone.group.metadata",
        timestampObserved
      })
    );
  }

  for (const application of input.applications) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.83,
        freshness: "Fresh",
        rawPayloadPointer: `pingone://application/${application.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SaaSApplication",
        sourceType: "pingone.application.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadPingOneInventory(
  config: PingOneOAuthConfig,
  accessToken: string
) {
  const environmentPrefix = `/v1/environments/${config.environmentId}`;
  const limit = String(config.limit);
  const [users, groups, applications] = await Promise.all([
    fetchPingOneArray(
      config,
      accessToken,
      `${environmentPrefix}/users`,
      { limit },
      "users",
      parsePingOneUser
    ),
    config.includeGroups
      ? fetchPingOneArray(
          config,
          accessToken,
          `${environmentPrefix}/groups`,
          { limit },
          "groups",
          parsePingOneGroup
        )
      : Promise.resolve([]),
    config.includeApplications
      ? fetchPingOneArray(
          config,
          accessToken,
          `${environmentPrefix}/applications`,
          { limit },
          "applications",
          parsePingOneApplication
        )
      : Promise.resolve([])
  ]);

  return {
    applications,
    groups,
    users
  };
}

function loadPingOneFixtureInventory() {
  return {
    applications: PINGONE_FIXTURE_APPLICATIONS,
    groups: PINGONE_FIXTURE_GROUPS,
    users: PINGONE_FIXTURE_USERS
  };
}

function createPingOneHealthyStatus(
  config: PingOneOAuthConfig,
  startedAt: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `PingOne read-only API access verified for environment ${config.environmentId}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getPingOneHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(PINGONE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = PingOneOAuthConfigSchema.parse(context.config);
  const accessToken = await fetchPingOneAccessToken(config);

  await fetchPingOneArray(
    config,
    accessToken,
    `/v1/environments/${config.environmentId}/users`,
    { limit: "1" },
    "users",
    parsePingOneUser
  );

  return createPingOneHealthyStatus(config, startedAt);
}

function createPingOneConnector(): Connector {
  return {
    manifest: PINGONE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = PingOneOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              environmentId: "env-fixture"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadPingOneFixtureInventory()
        : await loadPingOneInventory(
            config,
            await fetchPingOneAccessToken(config)
          );

      return createPingOneSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getPingOneHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = PingOneOAuthConfigSchema.parse(
        parsedContext.mockMode
          ? {
              clientId: "mock",
              clientSecret: "mock",
              environmentId: "env-fixture"
            }
          : parsedContext.config
      );
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadPingOneFixtureInventory()
        : await loadPingOneInventory(
            config,
            await fetchPingOneAccessToken(config)
          );

      return ConnectorSyncResultSchema.parse({
        assets: createPingOneAssets({
          applications: inventory.applications,
          environmentId: config.environmentId
        }),
        health: parsedContext.mockMode
          ? createMockHealth(PINGONE_CONNECTOR_MANIFEST, parsedContext)
          : createPingOneHealthyStatus(config, startedAt),
        signals: createPingOneSignals(inventory).map((signal) =>
          createTimestampedSignal(
            PINGONE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const Auth0OAuthConfigSchema = z.object({
  audience: z.url().optional(),
  clientId: z.string().min(1),
  clientSecret: z.string().min(1),
  domain: z.string().min(1),
  includeApplications: z.boolean().default(true),
  includeRoles: z.boolean().default(true),
  perPage: z.number().int().min(1).max(100).default(50)
});

const Auth0UserSchema = z.object({
  blocked: z.boolean().nullable(),
  displayName: z.string().nullable(),
  id: z.string().min(1),
  mfaEnabled: z.boolean().nullable(),
  privileged: z.boolean(),
  username: z.string().min(1)
});

const Auth0RoleSchema = z.object({
  description: z.string().nullable(),
  id: z.string().min(1),
  name: z.string().min(1),
  privileged: z.boolean()
});

const Auth0ApplicationSchema = z.object({
  firstParty: z.boolean().nullable(),
  grantTypes: z.array(z.string()),
  id: z.string().min(1),
  name: z.string().min(1),
  type: z.string().nullable()
});

const Auth0TokenResponseSchema = z.object({
  access_token: z.string().min(1),
  expires_in: z.number().int().positive().optional(),
  token_type: z.string().optional()
});

type Auth0OAuthConfig = z.infer<typeof Auth0OAuthConfigSchema>;
type Auth0User = z.infer<typeof Auth0UserSchema>;
type Auth0Role = z.infer<typeof Auth0RoleSchema>;
type Auth0Application = z.infer<typeof Auth0ApplicationSchema>;

