class JumpCloudHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function jumpCloudRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function jumpCloudRows(value: unknown): unknown[] {
  if (Array.isArray(value)) {
    return value;
  }

  const record = jumpCloudRecord(value);

  for (const key of ["results", "items", "data"]) {
    if (Array.isArray(record[key])) {
      return record[key];
    }
  }

  return [];
}

function jumpCloudString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function jumpCloudNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function jumpCloudBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return /^(?:true|enabled|active|1|activated)$/iu.test(value.trim());
  }

  if (typeof value === "number") {
    return value > 0;
  }

  return null;
}

function isPrivilegedJumpCloudName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|owner|root|superuser)\b/iu.test(
    value
  );
}

function jumpCloudBaseUrl(value: string) {
  return new URL(value).origin.replace(/\/+$/u, "");
}

function assertJumpCloudReadOnlyPath(pathName: string) {
  const allowedPaths = new Set([
    "/api/systemusers",
    "/api/v2/usergroups",
    "/api/applications"
  ]);

  if (!allowedPaths.has(pathName)) {
    throw new JumpCloudHttpError(
      403,
      `JumpCloud connector only permits read-only inventory paths; blocked ${pathName}.`
    );
  }
}

function jumpCloudApiUrl(
  config: JumpCloudApiKeyConfig,
  pathName: string,
  params: Record<string, string>
) {
  assertJumpCloudReadOnlyPath(pathName);

  const url = new URL(`${jumpCloudBaseUrl(config.baseUrl)}${pathName}`);

  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }

  return url.toString();
}

function jumpCloudHeaders(config: JumpCloudApiKeyConfig) {
  return {
    accept: "application/json",
    ...(config.organizationId ? { "x-org-id": config.organizationId } : {}),
    "x-api-key": config.apiKey
  };
}

async function fetchJumpCloudArray<T>(
  config: JumpCloudApiKeyConfig,
  pathName: string,
  params: Record<string, string>,
  parser: (value: unknown, index: number) => T
) {
  const response = await connectorFetch(
    jumpCloudApiUrl(config, pathName, params),
    {
      headers: jumpCloudHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new JumpCloudHttpError(
      response.status,
      `JumpCloud API request failed with status ${response.status}.`
    );
  }

  return jumpCloudRows(await response.json()).map((row, index) =>
    parser(row, index)
  );
}

function parseJumpCloudUser(value: unknown, index: number): JumpCloudUser {
  const row = jumpCloudRecord(value);
  const username = jumpCloudString(
    row.username ?? row.email,
    `jumpcloud-user-${index + 1}`
  );
  const displayName =
    jumpCloudNullableString(row.displayname ?? row.displayName) ??
    jumpCloudNullableString(
      [row.firstname ?? row.firstName, row.lastname ?? row.lastName]
        .filter((name) => typeof name === "string" && name.length > 0)
        .join(" ")
    );
  const mfaEnabled =
    row.mfaEnabled ??
    row.totpEnabled ??
    row.totp_enabled ??
    row.enable_user_portal_multifactor ??
    row.mfa;

  return JumpCloudUserSchema.parse({
    displayName,
    enabled: jumpCloudBoolean(row.activated ?? row.active ?? row.suspended),
    id: jumpCloudString(row._id ?? row.id, `jumpcloud-user-${index + 1}`),
    mfaEnabled:
      mfaEnabled === undefined
        ? null
        : Array.isArray(mfaEnabled)
          ? mfaEnabled.length > 0
          : jumpCloudBoolean(mfaEnabled),
    privileged:
      isPrivilegedJumpCloudName(username) ||
      (displayName ? isPrivilegedJumpCloudName(displayName) : false),
    username
  });
}

function parseJumpCloudUserGroup(
  value: unknown,
  index: number
): JumpCloudUserGroup {
  const row = jumpCloudRecord(value);
  const name = jumpCloudString(row.name, `JumpCloud User Group ${index + 1}`);

  return JumpCloudUserGroupSchema.parse({
    id: jumpCloudString(row.id ?? row._id, `jumpcloud-group-${index + 1}`),
    name,
    privileged: isPrivilegedJumpCloudName(name)
  });
}

function parseJumpCloudApplication(
  value: unknown,
  index: number
): JumpCloudApplication {
  const row = jumpCloudRecord(value);
  const sso = jumpCloudRecord(row.sso);

  return JumpCloudApplicationSchema.parse({
    active: jumpCloudBoolean(row.active),
    id: jumpCloudString(row._id ?? row.id, `jumpcloud-app-${index + 1}`),
    name: jumpCloudString(
      row.displayLabel ?? row.displayName ?? row.name,
      `JumpCloud Application ${index + 1}`
    ),
    ssoEnabled: jumpCloudBoolean(sso.sso_enabled ?? sso.enabled ?? row.ssoUrl),
    type:
      jumpCloudNullableString(row.type) ??
      (Object.keys(sso).length > 0 ? "sso" : null)
  });
}

