function createJumpCloudSignals(input: {
  applications: JumpCloudApplication[];
  groups: JumpCloudUserGroup[];
  users: JumpCloudUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "jumpcloud://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "jumpcloud.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const userPointer = `jumpcloud://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: user.enabled === false ? 0.72 : 0.85,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "jumpcloud.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: user.mfaEnabled === null ? 0.55 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          user.mfaEnabled === null
            ? "MFAUnknown"
            : user.mfaEnabled
              ? "MFAEnabled"
              : "MFADisabled",
        sourceType: "jumpcloud.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `jumpcloud://user-group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: group.privileged ? "PrivilegedGroup" : "Group",
        sourceType: "jumpcloud.user_group.metadata",
        timestampObserved
      })
    );
  }

  for (const application of input.applications) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.83,
        freshness: "Fresh",
        rawPayloadPointer: `jumpcloud://application/${application.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SaaSApplication",
        sourceType: "jumpcloud.application.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadJumpCloudInventory(config: JumpCloudApiKeyConfig) {
  const limit = String(config.limit);
  const [users, groups, applications] = await Promise.all([
    fetchJumpCloudArray(
      config,
      "/api/systemusers",
      { limit, skip: "0" },
      parseJumpCloudUser
    ),
    config.includeUserGroups
      ? fetchJumpCloudArray(
          config,
          "/api/v2/usergroups",
          { limit, skip: "0" },
          parseJumpCloudUserGroup
        )
      : Promise.resolve([]),
    config.includeApplications
      ? fetchJumpCloudArray(
          config,
          "/api/applications",
          { limit, skip: "0" },
          parseJumpCloudApplication
        )
      : Promise.resolve([])
  ]);

  return {
    applications,
    groups,
    users
  };
}

function loadJumpCloudFixtureInventory() {
  return {
    applications: JUMPCLOUD_FIXTURE_APPLICATIONS,
    groups: JUMPCLOUD_FIXTURE_USER_GROUPS,
    users: JUMPCLOUD_FIXTURE_USERS
  };
}

function createJumpCloudHealthyStatus(
  config: JumpCloudApiKeyConfig,
  startedAt: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `JumpCloud read-only API access verified for ${jumpCloudBaseUrl(
      config.baseUrl
    )}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getJumpCloudHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(JUMPCLOUD_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = JumpCloudApiKeyConfigSchema.parse(context.config);

  await fetchJumpCloudArray(
    config,
    "/api/systemusers",
    { limit: "1", skip: "0" },
    parseJumpCloudUser
  );

  return createJumpCloudHealthyStatus(config, startedAt);
}

function createJumpCloudConnector(): Connector {
  return {
    manifest: JUMPCLOUD_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = JumpCloudApiKeyConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiKey: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadJumpCloudFixtureInventory()
        : await loadJumpCloudInventory(config);

      return createJumpCloudSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getJumpCloudHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = JumpCloudApiKeyConfigSchema.parse(
        parsedContext.mockMode
          ? {
              apiKey: "mock"
            }
          : parsedContext.config
      );
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadJumpCloudFixtureInventory()
        : await loadJumpCloudInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createJumpCloudAssets({
          applications: inventory.applications,
          baseUrl: config.baseUrl
        }),
        health: parsedContext.mockMode
          ? createMockHealth(JUMPCLOUD_CONNECTOR_MANIFEST, parsedContext)
          : createJumpCloudHealthyStatus(config, startedAt),
        signals: createJumpCloudSignals(inventory).map((signal) =>
          createTimestampedSignal(
            JUMPCLOUD_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

