class CyberArkHttpError extends Error {
  constructor(
    readonly status: number,
    message: string
  ) {
    super(message);
  }
}

function cyberArkRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function cyberArkRows(value: unknown): unknown[] {
  if (Array.isArray(value)) {
    return value;
  }

  const record = cyberArkRecord(value);

  return Array.isArray(record.Resources) ? record.Resources : [];
}

function cyberArkString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function cyberArkNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function cyberArkBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return /^(?:true|enabled|active|1|enrolled|required)$/iu.test(value.trim());
  }

  if (typeof value === "number") {
    return value > 0;
  }

  return null;
}

function cyberArkMemberCount(value: unknown) {
  if (Array.isArray(value)) {
    return value.length;
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.trunc(value));
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
  }

  return 0;
}

function isPrivilegedCyberArkName(value: string) {
  return /\b(admin(?:istrator)?s?|privileged|security|owner|root|superuser|vault|safe)\b/iu.test(
    value
  );
}

function cyberArkBaseUrl(value: string) {
  return new URL(value).origin.replace(/\/+$/u, "");
}

function assertCyberArkReadOnlyPath(pathName: string) {
  const allowedPaths = new Set(["/scim/v2/Users", "/scim/v2/Groups"]);

  if (!allowedPaths.has(pathName)) {
    throw new CyberArkHttpError(
      403,
      `CyberArk connector only permits read-only SCIM inventory paths; blocked ${pathName}.`
    );
  }
}

function cyberArkApiUrl(
  config: CyberArkScimConfig,
  pathName: string,
  params: Record<string, string>
) {
  assertCyberArkReadOnlyPath(pathName);

  const url = new URL(`${cyberArkBaseUrl(config.baseUrl)}${pathName}`);

  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }

  return url.toString();
}

function cyberArkHeaders(config: CyberArkScimConfig) {
  return {
    accept: "application/scim+json, application/json",
    authorization: `Bearer ${config.bearerToken}`
  };
}

function cyberArkMfaValue(record: Record<string, unknown>): boolean | null {
  for (const [key, value] of Object.entries(record)) {
    if (/mfa|multifactor|totp|authenticator/iu.test(key)) {
      const parsed = cyberArkBoolean(value);

      if (parsed !== null) {
        return parsed;
      }
    }

    if (value && typeof value === "object" && !Array.isArray(value)) {
      const nested: boolean | null = cyberArkMfaValue(
        value as Record<string, unknown>
      );

      if (nested !== null) {
        return nested;
      }
    }
  }

  return null;
}

async function fetchCyberArkArray<T>(
  config: CyberArkScimConfig,
  pathName: string,
  params: Record<string, string>,
  parser: (value: unknown, index: number) => T
) {
  const response = await connectorFetch(
    cyberArkApiUrl(config, pathName, params),
    {
      headers: cyberArkHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new CyberArkHttpError(
      response.status,
      `CyberArk SCIM request failed with status ${response.status}.`
    );
  }

  return cyberArkRows(await response.json()).map((row, index) =>
    parser(row, index)
  );
}

function parseCyberArkUser(value: unknown, index: number): CyberArkScimUser {
  const row = cyberArkRecord(value);
  const name = cyberArkRecord(row.name);
  const username = cyberArkString(
    row.userName ?? row.username ?? row.externalId,
    `cyberark-user-${index + 1}`
  );
  const displayName =
    cyberArkNullableString(row.displayName) ??
    cyberArkNullableString(row.formatted) ??
    cyberArkNullableString(name.formatted);

  return CyberArkScimUserSchema.parse({
    active: cyberArkBoolean(row.active),
    displayName,
    id: cyberArkString(row.id, `cyberark-user-${index + 1}`),
    mfaEnabled: cyberArkMfaValue(row),
    privileged:
      isPrivilegedCyberArkName(username) ||
      (displayName ? isPrivilegedCyberArkName(displayName) : false),
    username
  });
}

function parseCyberArkGroup(value: unknown, index: number): CyberArkScimGroup {
  const row = cyberArkRecord(value);
  const name = cyberArkString(
    row.displayName ?? row.name,
    `CyberArk Group ${index + 1}`
  );

  return CyberArkScimGroupSchema.parse({
    id: cyberArkString(row.id, `cyberark-group-${index + 1}`),
    memberCount: cyberArkMemberCount(row.members ?? row.memberCount),
    name,
    privileged: isPrivilegedCyberArkName(name)
  });
}

function createCyberArkAssets(
  config: CyberArkScimConfig
): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: "production",
      identifiers: {
        baseUrl: cyberArkBaseUrl(config.baseUrl),
        provider: "cyberark-identity-scim"
      },
      internetExposed: false,
      name: "CyberArk Identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "cyberark", "scim"]
    })
  ];
}

function createCyberArkSignals(input: {
  groups: CyberArkScimGroup[];
  users: CyberArkScimUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "cyberark-scim://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "cyberark.scim.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const userPointer = `cyberark-scim://user/${user.id}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: user.active === false ? 0.72 : 0.85,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "cyberark.scim.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: user.mfaEnabled === null ? 0.55 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          user.mfaEnabled === null
            ? "MFAUnknown"
            : user.mfaEnabled
              ? "MFAEnabled"
              : "MFADisabled",
        sourceType: "cyberark.scim.user.mfa_posture",
        timestampObserved
      })
    );
  }

  for (const group of input.groups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `cyberark-scim://group/${group.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: group.privileged ? "PrivilegedGroup" : "Group",
        sourceType: "cyberark.scim.group.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadCyberArkInventory(config: CyberArkScimConfig) {
  const params = {
    count: String(config.count),
    startIndex: String(config.startIndex)
  };
  const [users, groups] = await Promise.all([
    fetchCyberArkArray(config, "/scim/v2/Users", params, parseCyberArkUser),
    config.includeGroups
      ? fetchCyberArkArray(
          config,
          "/scim/v2/Groups",
          params,
          parseCyberArkGroup
        )
      : Promise.resolve([])
  ]);

  return {
    groups,
    users
  };
}

function loadCyberArkFixtureInventory() {
  return {
    groups: CYBERARK_FIXTURE_GROUPS,
    users: CYBERARK_FIXTURE_USERS
  };
}

function createCyberArkHealthyStatus(
  config: CyberArkScimConfig,
  startedAt: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `CyberArk Identity SCIM read-only access verified for ${cyberArkBaseUrl(
      config.baseUrl
    )}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getCyberArkHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CYBERARK_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = CyberArkScimConfigSchema.parse(context.config);

  await fetchCyberArkArray(
    config,
    "/scim/v2/Users",
    { count: "1", startIndex: "1" },
    parseCyberArkUser
  );

  return createCyberArkHealthyStatus(config, startedAt);
}

function createCyberArkConnector(): Connector {
  return {
    manifest: CYBERARK_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = CyberArkScimConfigSchema.parse(
        parsedContext.mockMode
          ? {
              baseUrl: "https://example.id.cyberark.cloud",
              bearerToken: "mock"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadCyberArkFixtureInventory()
        : await loadCyberArkInventory(config);

      return createCyberArkSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getCyberArkHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = CyberArkScimConfigSchema.parse(
        parsedContext.mockMode
          ? {
              baseUrl: "https://example.id.cyberark.cloud",
              bearerToken: "mock"
            }
          : parsedContext.config
      );
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadCyberArkFixtureInventory()
        : await loadCyberArkInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createCyberArkAssets(config),
        health: parsedContext.mockMode
          ? createMockHealth(CYBERARK_CONNECTOR_MANIFEST, parsedContext)
          : createCyberArkHealthyStatus(config, startedAt),
        signals: createCyberArkSignals(inventory).map((signal) =>
          createTimestampedSignal(
            CYBERARK_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

