function activeDirectoryRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function activeDirectoryString(value: unknown, fallback: string) {
  if (Array.isArray(value)) {
    return activeDirectoryString(value[0], fallback);
  }

  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function activeDirectoryNullableString(value: unknown) {
  if (Array.isArray(value)) {
    return activeDirectoryNullableString(value[0]);
  }

  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function activeDirectoryStringArray(value: unknown) {
  if (Array.isArray(value)) {
    return value.filter(
      (item): item is string =>
        typeof item === "string" && item.trim().length > 0
    );
  }

  return typeof value === "string" && value.trim().length > 0 ? [value] : [];
}

function activeDirectoryNumber(value: unknown) {
  if (Array.isArray(value)) {
    return activeDirectoryNumber(value[0]);
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.trunc(value);
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? parsed : 0;
  }

  return 0;
}

function activeDirectoryBooleanFromUac(
  userAccountControl: unknown
): boolean | null {
  const uac = activeDirectoryNumber(userAccountControl);

  return uac > 0 ? (uac & 0x2) === 0 : null;
}

function hasActiveDirectoryDelegation(userAccountControl: unknown) {
  const uac = activeDirectoryNumber(userAccountControl);

  return (uac & 0x80000) !== 0 || (uac & 0x1000000) !== 0;
}

function activeDirectoryMemberCount(value: unknown) {
  if (Array.isArray(value)) {
    return value.length;
  }

  return activeDirectoryNumber(value);
}

function isPrivilegedActiveDirectoryName(value: string) {
  return /\b(domain admins|enterprise admins|schema admins|administrators|account operators|backup operators|server operators|print operators|dnsadmins|admin(?:istrator)?s?|privileged|security|owner|root)\b/iu.test(
    value
  );
}

function isPrivilegedActiveDirectoryMembership(memberships: string[]) {
  return memberships.some((membership) =>
    isPrivilegedActiveDirectoryName(membership)
  );
}

function parseActiveDirectoryUser(
  value: unknown,
  index: number
): ActiveDirectoryUser {
  const row = activeDirectoryRecord(value);
  const distinguishedName = activeDirectoryString(
    row.distinguishedName ?? row.dn,
    `CN=ActiveDirectoryUser${index + 1}`
  );
  const username = activeDirectoryString(
    row.sAMAccountName ?? row.userPrincipalName ?? row.cn,
    `ad-user-${index + 1}`
  );
  const displayName = activeDirectoryNullableString(row.displayName ?? row.cn);
  const memberOf = activeDirectoryStringArray(row.memberOf);
  const servicePrincipalNames = activeDirectoryStringArray(
    row.servicePrincipalName
  );
  const adminCount = activeDirectoryString(row.adminCount, "0") === "1";

  return ActiveDirectoryUserSchema.parse({
    delegated:
      hasActiveDirectoryDelegation(row.userAccountControl) ||
      servicePrincipalNames.length > 0,
    displayName,
    distinguishedName,
    enabled: activeDirectoryBooleanFromUac(row.userAccountControl),
    id: distinguishedName,
    memberOf,
    mfaEnabled: null,
    privileged:
      adminCount ||
      isPrivilegedActiveDirectoryName(username) ||
      (displayName ? isPrivilegedActiveDirectoryName(displayName) : false) ||
      isPrivilegedActiveDirectoryMembership(memberOf),
    servicePrincipalNames,
    username
  });
}

function parseActiveDirectoryGroup(
  value: unknown,
  index: number
): ActiveDirectoryGroup {
  const row = activeDirectoryRecord(value);
  const distinguishedName = activeDirectoryString(
    row.distinguishedName ?? row.dn,
    `CN=ActiveDirectoryGroup${index + 1}`
  );
  const name = activeDirectoryString(
    row.cn ?? row.name,
    `AD Group ${index + 1}`
  );
  const adminCount = activeDirectoryString(row.adminCount, "0") === "1";

  return ActiveDirectoryGroupSchema.parse({
    distinguishedName,
    id: distinguishedName,
    memberCount: activeDirectoryMemberCount(row.member),
    name,
    privileged: adminCount || isPrivilegedActiveDirectoryName(name)
  });
}

function parseActiveDirectoryComputer(
  value: unknown,
  index: number
): ActiveDirectoryComputer {
  const row = activeDirectoryRecord(value);
  const distinguishedName = activeDirectoryString(
    row.distinguishedName ?? row.dn,
    `CN=ActiveDirectoryComputer${index + 1}`
  );
  const name = activeDirectoryString(
    row.name ?? row.cn ?? row.dNSHostName,
    `AD Computer ${index + 1}`
  );

  return ActiveDirectoryComputerSchema.parse({
    delegated: hasActiveDirectoryDelegation(row.userAccountControl),
    distinguishedName,
    dnsHostName: activeDirectoryNullableString(row.dNSHostName),
    enabled: activeDirectoryBooleanFromUac(row.userAccountControl),
    id: distinguishedName,
    name,
    operatingSystem: activeDirectoryNullableString(row.operatingSystem)
  });
}

async function withActiveDirectoryClient<T>(
  config: ActiveDirectoryLdapConfig,
  callback: (client: LdapClient) => Promise<T>
) {
  const client = new LdapClient({
    connectTimeout: config.connectTimeoutMs,
    strictDN: false,
    timeout: config.connectTimeoutMs + config.timeLimitSeconds * 1000,
    tlsOptions: {
      rejectUnauthorized: config.tlsRejectUnauthorized
    },
    url: config.url
  });

  try {
    await client.bind(config.bindDn, config.bindPassword);

    return await callback(client);
  } finally {
    await client.unbind().catch(() => undefined);
  }
}

async function searchActiveDirectory<T>(
  client: LdapClient,
  config: ActiveDirectoryLdapConfig,
  filter: string,
  attributes: string[],
  parser: (value: unknown, index: number) => T
) {
  const result = await client.search(config.baseDn, {
    attributes,
    filter,
    paged: {
      pageSize: config.pageSize
    },
    scope: "sub",
    sizeLimit: config.sizeLimit,
    timeLimit: config.timeLimitSeconds
  });

  return result.searchEntries.map((entry, index) => parser(entry, index));
}

async function loadActiveDirectoryInventory(config: ActiveDirectoryLdapConfig) {
  return withActiveDirectoryClient(config, async (client) => {
    const users = await searchActiveDirectory(
      client,
      config,
      "(&(objectCategory=person)(objectClass=user))",
      [
        "distinguishedName",
        "sAMAccountName",
        "userPrincipalName",
        "displayName",
        "cn",
        "memberOf",
        "adminCount",
        "userAccountControl",
        "servicePrincipalName"
      ],
      parseActiveDirectoryUser
    );
    const groups = config.includeGroups
      ? await searchActiveDirectory(
          client,
          config,
          "(&(objectCategory=group)(objectClass=group))",
          ["distinguishedName", "cn", "name", "member", "adminCount"],
          parseActiveDirectoryGroup
        )
      : [];
    const computers = config.includeComputers
      ? await searchActiveDirectory(
          client,
          config,
          "(&(objectCategory=computer)(objectClass=computer))",
          [
            "distinguishedName",
            "cn",
            "name",
            "dNSHostName",
            "operatingSystem",
            "userAccountControl"
          ],
          parseActiveDirectoryComputer
        )
      : [];

    return {
      computers,
      groups,
      users
    };
  });
}

function loadActiveDirectoryFixtureInventory() {
  return {
    computers: ACTIVE_DIRECTORY_FIXTURE_COMPUTERS,
    groups: ACTIVE_DIRECTORY_FIXTURE_GROUPS,
    users: ACTIVE_DIRECTORY_FIXTURE_USERS
  };
}

function createActiveDirectoryAssets(input: {
  baseDn: string;
  computers: ActiveDirectoryComputer[];
}): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "Critical",
      environment: "production",
      identifiers: {
        baseDn: input.baseDn,
        provider: "active-directory"
      },
      internetExposed: false,
      name: "Active Directory identity store",
      owner: "identity-security",
      status: "Active",
      tags: ["identity", "active-directory", "ldap"]
    }),
    ...input.computers.map((computer) =>
      createMockAsset({
        assetType: "Host",
        businessCriticality: computer.delegated ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          delegated: computer.delegated,
          distinguishedName: computer.distinguishedName,
          dnsHostName: computer.dnsHostName,
          provider: "active-directory"
        },
        internetExposed: false,
        name: computer.dnsHostName ?? computer.name,
        owner: "identity-security",
        status: computer.enabled === false ? "Inactive" : "Active",
        tags: [
          "identity",
          "active-directory",
          "computer",
          computer.operatingSystem ?? "unknown"
        ]
      })
    )
  ];
}

function createActiveDirectorySignals(input: {
  computers: ActiveDirectoryComputer[];
  groups: ActiveDirectoryGroup[];
  includeServiceAccounts: boolean;
  users: ActiveDirectoryUser[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: "active-directory://identity-store",
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "High",
      signalCategory: "Identity",
      signalSubcategory: "IdentityStore",
      sourceType: "active_directory.identity_store.metadata",
      timestampObserved
    })
  ];

  for (const user of input.users) {
    const userPointer = `active-directory://user/${encodeURIComponent(
      user.distinguishedName
    )}`;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: user.enabled === false ? 0.72 : 0.85,
        freshness: "Fresh",
        rawPayloadPointer: userPointer,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: user.privileged
          ? "PrivilegedIdentity"
          : "UserAccount",
        sourceType: "active_directory.user.metadata",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: 0.52,
        freshness: "Fresh",
        rawPayloadPointer: `${userPointer}/mfa-posture`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: "MFAUnknown",
        sourceType: "active_directory.user.mfa_posture",
        timestampObserved
      })
    );

    if (input.includeServiceAccounts && user.servicePrincipalNames.length > 0) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: user.delegated ? 0.86 : 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `${userPointer}/service-principal-names`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Identity",
          signalSubcategory: user.delegated
            ? "DelegatedServiceAccount"
            : "ServiceAccount",
          sourceType: "active_directory.service_account.metadata",
          timestampObserved
        })
      );
    }
  }

  for (const group of input.groups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `active-directory://group/${encodeURIComponent(
          group.distinguishedName
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: group.privileged ? "PrivilegedGroup" : "Group",
        sourceType: "active_directory.group.metadata",
        timestampObserved
      })
    );
  }

  for (const computer of input.computers) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: computer.delegated ? 0.86 : 0.8,
        freshness: "Fresh",
        rawPayloadPointer: `active-directory://computer/${encodeURIComponent(
          computer.distinguishedName
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: computer.delegated
          ? "DelegatedComputer"
          : "Computer",
        sourceType: "active_directory.computer.metadata",
        timestampObserved
      })
    );
  }

  return signals;
}

function createActiveDirectoryHealthyStatus(
  config: ActiveDirectoryLdapConfig,
  startedAt: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Active Directory read-only LDAP access verified for base DN ${config.baseDn}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getActiveDirectoryHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ACTIVE_DIRECTORY_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = ActiveDirectoryLdapConfigSchema.parse(context.config);

  await withActiveDirectoryClient(config, async (client) => {
    await searchActiveDirectory(
      client,
      {
        ...config,
        sizeLimit: 1
      },
      "(&(objectCategory=person)(objectClass=user))",
      ["distinguishedName", "sAMAccountName", "userAccountControl"],
      parseActiveDirectoryUser
    );
  });

  return createActiveDirectoryHealthyStatus(config, startedAt);
}

function createActiveDirectoryConnector(): Connector {
  return {
    manifest: ACTIVE_DIRECTORY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = ActiveDirectoryLdapConfigSchema.parse(
        parsedContext.mockMode
          ? {
              baseDn: "DC=example,DC=local",
              bindDn: "CN=readonly,DC=example,DC=local",
              bindPassword: "mock",
              url: "ldaps://ad.example.local"
            }
          : parsedContext.config
      );
      const inventory = parsedContext.mockMode
        ? loadActiveDirectoryFixtureInventory()
        : await loadActiveDirectoryInventory(config);

      return createActiveDirectorySignals({
        ...inventory,
        includeServiceAccounts: config.includeServiceAccounts
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getActiveDirectoryHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = ActiveDirectoryLdapConfigSchema.parse(
        parsedContext.mockMode
          ? {
              baseDn: "DC=example,DC=local",
              bindDn: "CN=readonly,DC=example,DC=local",
              bindPassword: "mock",
              url: "ldaps://ad.example.local"
            }
          : parsedContext.config
      );
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadActiveDirectoryFixtureInventory()
        : await loadActiveDirectoryInventory(config);

      return ConnectorSyncResultSchema.parse({
        assets: createActiveDirectoryAssets({
          baseDn: config.baseDn,
          computers: inventory.computers
        }),
        health: parsedContext.mockMode
          ? createMockHealth(ACTIVE_DIRECTORY_CONNECTOR_MANIFEST, parsedContext)
          : createActiveDirectoryHealthyStatus(config, startedAt),
        signals: createActiveDirectorySignals({
          ...inventory,
          includeServiceAccounts: config.includeServiceAccounts
        }).map((signal) =>
          createTimestampedSignal(
            ACTIVE_DIRECTORY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const SlackWebhookConfigSchema = z.object({
  channel: z.string().min(1).optional(),
  username: z.string().min(1).optional(),
  webhookUrl: z.url()
});

const SlackWorkflowEventSchema = z
  .object({
    evidenceIds: z.array(z.string().uuid()).optional(),
    missionId: z.string().uuid().optional(),
    policyDecisionId: z.string().uuid().optional(),
    summary: z.string().min(1).optional(),
    title: z.string().min(1).optional(),
    triggerId: z.string().min(1).optional(),
    type: z.string().min(1).optional()
  })
  .passthrough();

type SlackWebhookConfig = z.infer<typeof SlackWebhookConfigSchema>;
type SlackWorkflowEvent = z.infer<typeof SlackWorkflowEventSchema>;

const SLACK_CONNECTOR_MANIFEST = ConnectorManifestSchema.parse({
  authMethods: [
    {
      description: "Use fixture-backed mock Slack workflow data.",
      fields: [],
      kind: "mock",
      label: "Mock",
      mockSupported: true
    },
    {
      description:
        "Use a Slack incoming webhook URL for outbound workflow notifications.",
      fields: [
        {
          key: "webhookUrl",
          label: "Incoming Webhook URL",
          required: true,
          secret: true
        },
        {
          key: "channel",
          label: "Channel Override",
          required: false,
          secret: false
        },
        {
          key: "username",
          label: "Bot Username",
          required: false,
          secret: false
        }
      ],
      kind: "webhook",
      label: "Incoming Webhook",
      mockSupported: false
    }
  ],
  availability: "Beta",
  category: "Ticketing",
  connectorKey: "slack",
  controlObservationCapabilities: [],
  customerVisibleDescription:
    "Routes validation and remediation workflow notifications to authorized Slack workspaces.",
  dataSensitivity: "Moderate",
  healthCheckMethod:
    "Webhook URL configuration check; delivery verified on send",
  marketplaceCategory: "SOAR/ITSM",
  mockSupported: true,
  permissionsSummary:
    "Writes workflow notifications to customer-authorized Slack channels through an incoming webhook.",
  product: "Slack",
  requiredPermissions: ["incoming-webhook:write"],
  setupComplexity: "Low",
  signalCategories: ["Audit"],
  supportedMissionTypes: ["ValidationSnapshot", "FixVerification"],
  validationCapabilities: [],
  vendor: "Slack",
  workflowCapabilities: ["Send validation workflow updates"]
});

function slackWorkflowEventFromContext(
  context: ConnectorExecutionContext
): SlackWorkflowEvent {
  const rawEvent =
    typeof context.config.workflowEvent === "object" &&
    context.config.workflowEvent
      ? context.config.workflowEvent
      : {};

  return SlackWorkflowEventSchema.parse(rawEvent);
}

function buildSlackWorkflowText(event: SlackWorkflowEvent) {
  const lines = [event.title ?? "Periscan workflow update"];

  if (event.summary) {
    lines.push(event.summary);
  }

  if (event.triggerId) {
    lines.push(`Trigger: ${event.triggerId}`);
  }

  if (event.missionId) {
    lines.push(`Draft mission: ${event.missionId}`);
  }

  if (event.evidenceIds?.length) {
    lines.push(`Evidence IDs: ${event.evidenceIds.join(", ")}`);
  }

  return lines.join("\n");
}

function buildSlackWorkflowPayload(
  config: SlackWebhookConfig,
  event: SlackWorkflowEvent
) {
  return {
    channel: config.channel,
    text: buildSlackWorkflowText(event),
    username: config.username
  };
}

function createSlackConnector(): Connector {
  return {
    manifest: SLACK_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      ConnectorExecutionContextSchema.parse(context);

      return [createMockSignal("Audit", "WorkflowDestination", "Moderate")].map(
        (signal) => ConnectorSignalInputSchema.parse(signal)
      );
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(SLACK_CONNECTOR_MANIFEST, parsedContext);
      }

      const parsedConfig = SlackWebhookConfigSchema.safeParse(
        parsedContext.config
      );

      if (!parsedConfig.success) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail: "Slack webhook URL is missing or invalid.",
          latencyMs: null,
          status: "Unhealthy"
        });
      }

      return ConnectorHealthSchema.parse({
        authorizationVerified: false,
        checkedAt: new Date().toISOString(),
        detail:
          "Slack webhook is configured; delivery is verified when a workflow event is sent.",
        latencyMs: null,
        status: "Unknown"
      });
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            SLACK_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async sendWorkflowEvent(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const event = slackWorkflowEventFromContext(parsedContext);

      if (parsedContext.mockMode) {
        return {
          deliveredAt: new Date().toISOString(),
          destination: "Slack",
          mode: "mock",
          status: "Delivered",
          summary: buildSlackWorkflowText(event)
        };
      }

      const config = SlackWebhookConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      const response = await connectorFetch(config.webhookUrl, {
        body: JSON.stringify(buildSlackWorkflowPayload(config, event)),
        headers: {
          "content-type": "application/json"
        },
        method: "POST"
      });

      if (!response.ok) {
        return {
          destination: "Slack",
          detail: `Slack webhook returned status ${response.status}.`,
          status: "Failed"
        };
      }

      return {
        deliveredAt: new Date().toISOString(),
        destination: "Slack",
        latencyMs: Date.now() - startedAt,
        mode: "webhook",
        status: "Delivered"
      };
    }
  };
}

