function jiraWorkflowEventFromContext(
  context: ConnectorExecutionContext
): JiraWorkflowEvent {
  const rawEvent =
    typeof context.config.workflowEvent === "object" &&
    context.config.workflowEvent
      ? context.config.workflowEvent
      : {};

  return JiraWorkflowEventSchema.parse(rawEvent);
}

function buildJiraIssueSummary(event: JiraWorkflowEvent) {
  return event.title ?? "Periscan validation workflow item";
}

function buildJiraIssueDescription(event: JiraWorkflowEvent) {
  const lines = [
    event.summary ??
      "Periscan created this workflow item from normalized validation context."
  ];

  if (event.triggerId) {
    lines.push(`Trigger: ${event.triggerId}`);
  }

  if (event.missionId) {
    lines.push(`Draft mission: ${event.missionId}`);
  }

  if (event.policyDecisionId) {
    lines.push(`Policy decision: ${event.policyDecisionId}`);
  }

  if (event.remediationId) {
    lines.push(`Remediation: ${event.remediationId}`);
  }

  if (event.evidenceIds?.length) {
    lines.push(`Evidence IDs: ${event.evidenceIds.join(", ")}`);
  }

  return {
    content: [
      {
        content: [
          {
            text: lines.join("\n"),
            type: "text"
          }
        ],
        type: "paragraph"
      }
    ],
    type: "doc",
    version: 1
  };
}

function buildJiraIssuePayload(
  config: JiraCloudConfig,
  event: JiraWorkflowEvent
) {
  return {
    fields: {
      description: buildJiraIssueDescription(event),
      issuetype: {
        name: config.issueType ?? "Task"
      },
      labels: ["periscan", "security-validation"],
      project: {
        key: config.projectKey
      },
      summary: buildJiraIssueSummary(event)
    }
  };
}

function jiraAuthorizationHeader(config: JiraCloudConfig) {
  return `Basic ${Buffer.from(`${config.email}:${config.apiToken}`).toString(
    "base64"
  )}`;
}

function jiraApiUrl(config: JiraCloudConfig, pathName: string) {
  return new URL(pathName, config.siteUrl).toString();
}

function workflowTicketId(context: ConnectorExecutionContext) {
  const event = context.config.workflowEvent;
  const ticketId =
    event && typeof event === "object" && !Array.isArray(event)
      ? (event as Record<string, unknown>).ticketId
      : null;

  if (typeof ticketId !== "string" || ticketId.trim().length === 0) {
    throw new Error("A ticketId is required to read external workflow state.");
  }

  return ticketId.trim();
}

function mockWorkflowState(context: ConnectorExecutionContext) {
  const event = context.config.workflowEvent;
  const fixtureState =
    event && typeof event === "object" && !Array.isArray(event)
      ? (event as Record<string, unknown>).fixtureTicketState
      : null;
  const state =
    fixtureState === "Open" ||
    fixtureState === "InProgress" ||
    fixtureState === "Closed" ||
    fixtureState === "Unknown"
      ? fixtureState
      : "InProgress";

  return {
    observedAt: new Date().toISOString(),
    state,
    stateLabel: state === "InProgress" ? "In progress" : state,
    ticketId: workflowTicketId(context)
  };
}

function createJiraConnector(): Connector {
  return {
    manifest: JIRA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      ConnectorExecutionContextSchema.parse(context);

      return [createMockSignal("Remediation", "TicketStatus", "Moderate")].map(
        (signal) => ConnectorSignalInputSchema.parse(signal)
      );
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(JIRA_CONNECTOR_MANIFEST, parsedContext);
      }

      const config = JiraCloudConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      const response = await connectorFetch(
        jiraApiUrl(config, "/rest/api/3/myself"),
        {
          headers: {
            authorization: jiraAuthorizationHeader(config)
          }
        }
      );

      return ConnectorHealthSchema.parse({
        authorizationVerified: response.ok,
        checkedAt: new Date().toISOString(),
        detail: response.ok
          ? "Jira Cloud API token verified."
          : `Jira Cloud health check returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        status: response.ok ? "Healthy" : "Unhealthy"
      });
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            JIRA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async sendWorkflowEvent(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const event = jiraWorkflowEventFromContext(parsedContext);

      if (parsedContext.mockMode) {
        return {
          deliveredAt: new Date().toISOString(),
          destination: "Jira",
          mode: "mock",
          status: "Delivered",
          ticketId: `PSCAN-${parsedContext.integrationId.replace(/-/g, "").slice(0, 8).toUpperCase()}`
        };
      }

      const config = JiraCloudConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      const response = await connectorFetch(
        jiraApiUrl(config, "/rest/api/3/issue"),
        {
          body: JSON.stringify(buildJiraIssuePayload(config, event)),
          headers: {
            authorization: jiraAuthorizationHeader(config),
            "content-type": "application/json"
          },
          method: "POST"
        }
      );

      if (!response.ok) {
        return {
          destination: "Jira",
          detail: `Jira Cloud issue creation returned status ${response.status}.`,
          status: "Failed"
        };
      }

      const payload = (await response.json().catch(() => ({}))) as {
        id?: string;
        key?: string;
      };

      return {
        deliveredAt: new Date().toISOString(),
        destination: "Jira",
        latencyMs: Date.now() - startedAt,
        mode: "apiToken",
        status: "Delivered",
        ticketId: payload.key ?? payload.id ?? null
      };
    },
    async readWorkflowState(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      if (parsedContext.mockMode) {
        return mockWorkflowState(parsedContext);
      }

      const config = JiraCloudConfigSchema.parse(parsedContext.config);
      const ticketId = workflowTicketId(parsedContext);
      const response = await connectorFetch(
        jiraApiUrl(
          config,
          `/rest/api/3/issue/${encodeURIComponent(ticketId)}?fields=status,updated,resolutiondate`
        ),
        {
          headers: {
            accept: "application/json",
            authorization: jiraAuthorizationHeader(config)
          }
        }
      );

      if (!response.ok) {
        throw new Error(
          `Jira Cloud ticket state lookup returned status ${response.status}.`
        );
      }

      const payload = (await response.json()) as {
        fields?: {
          resolutiondate?: string | null;
          status?: {
            name?: string;
            statusCategory?: { key?: string; name?: string };
          };
          updated?: string;
        };
      };
      const categoryKey = payload.fields?.status?.statusCategory?.key;
      const state =
        categoryKey === "done" || payload.fields?.resolutiondate
          ? "Closed"
          : categoryKey === "indeterminate"
            ? "InProgress"
            : categoryKey === "new"
              ? "Open"
              : "Unknown";

      return {
        observedAt: new Date().toISOString(),
        sourceUpdatedAt: payload.fields?.updated ?? null,
        state,
        stateLabel:
          payload.fields?.status?.name ??
          payload.fields?.status?.statusCategory?.name ??
          "Unknown",
        ticketId
      };
    }
  };
}

