function opsgenieWorkflowEventFromContext(
  context: ConnectorExecutionContext
): OpsgenieWorkflowEvent {
  const rawEvent =
    typeof context.config.workflowEvent === "object" &&
    context.config.workflowEvent
      ? context.config.workflowEvent
      : {};

  return OpsgenieWorkflowEventSchema.parse(rawEvent);
}

function normalizeOpsgenieBaseUrl(config: OpsgenieApiKeyConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function opsgenieApiUrl(config: OpsgenieApiKeyConfig, pathName: string) {
  return `${normalizeOpsgenieBaseUrl(config)}${pathName}`;
}

function opsgenieAuthorizationHeader(config: OpsgenieApiKeyConfig) {
  return `GenieKey ${config.apiKey}`;
}

function buildOpsgenieAlias(
  config: OpsgenieApiKeyConfig,
  event: OpsgenieWorkflowEvent
) {
  const stableSource =
    event.remediationId ?? event.missionId ?? event.triggerId ?? event.title;

  if (!stableSource) {
    return undefined;
  }

  return `${config.aliasPrefix}:${stableSource}`
    .replace(/[^A-Za-z0-9:._-]/gu, "-")
    .slice(0, 512);
}

function buildOpsgenieDescription(event: OpsgenieWorkflowEvent) {
  const lines = [
    event.summary ??
      "Periscan created this workflow alert from normalized validation context."
  ];

  if (event.triggerId) {
    lines.push(`Trigger: ${event.triggerId}`);
  }

  if (event.missionId) {
    lines.push(`Draft mission: ${event.missionId}`);
  }

  if (event.policyDecisionId) {
    lines.push(`Policy decision: ${event.policyDecisionId}`);
  }

  if (event.remediationId) {
    lines.push(`Remediation: ${event.remediationId}`);
  }

  if (event.evidenceIds?.length) {
    lines.push(`Evidence IDs: ${event.evidenceIds.join(", ")}`);
  }

  return lines.join("\n");
}

function buildOpsgenieDetails(event: OpsgenieWorkflowEvent) {
  return {
    ...(event.triggerId ? { triggerId: event.triggerId } : {}),
    ...(event.missionId ? { missionId: event.missionId } : {}),
    ...(event.policyDecisionId
      ? { policyDecisionId: event.policyDecisionId }
      : {}),
    ...(event.remediationId ? { remediationId: event.remediationId } : {}),
    ...(event.evidenceIds?.length
      ? { evidenceIds: event.evidenceIds.join(",") }
      : {})
  };
}

function buildOpsgenieAlertPayload(
  config: OpsgenieApiKeyConfig,
  event: OpsgenieWorkflowEvent
) {
  return {
    alias: buildOpsgenieAlias(config, event),
    description: buildOpsgenieDescription(event),
    details: buildOpsgenieDetails(event),
    message:
      event.title ?? event.summary ?? "Periscan validation workflow alert",
    priority: config.priority,
    source: config.source,
    tags: config.tags
  };
}

function createOpsgenieConnector(): Connector {
  return {
    manifest: OPSGENIE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      ConnectorExecutionContextSchema.parse(context);

      return [createMockSignal("Remediation", "TicketStatus", "Moderate")].map(
        (signal) => ConnectorSignalInputSchema.parse(signal)
      );
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(OPSGENIE_CONNECTOR_MANIFEST, parsedContext);
      }

      const config = OpsgenieApiKeyConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      const response = await connectorFetch(
        opsgenieApiUrl(config, "/v2/account"),
        {
          headers: {
            accept: "application/json",
            authorization: opsgenieAuthorizationHeader(config)
          }
        }
      );

      return ConnectorHealthSchema.parse({
        authorizationVerified: response.ok,
        checkedAt: new Date().toISOString(),
        detail: response.ok
          ? "Opsgenie API key verified for account metadata access."
          : `Opsgenie health check returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        status: response.ok ? "Healthy" : "Unhealthy"
      });
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            OPSGENIE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async sendWorkflowEvent(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const event = opsgenieWorkflowEventFromContext(parsedContext);

      if (parsedContext.mockMode) {
        return {
          deliveredAt: new Date().toISOString(),
          destination: "Opsgenie",
          mode: "mock",
          status: "Delivered",
          ticketId: `OG-${parsedContext.integrationId.replace(/-/g, "").slice(0, 8).toUpperCase()}`
        };
      }

      const config = OpsgenieApiKeyConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      const alertPayload = buildOpsgenieAlertPayload(config, event);
      const response = await connectorFetch(
        opsgenieApiUrl(config, "/v2/alerts"),
        {
          body: JSON.stringify(alertPayload),
          headers: {
            authorization: opsgenieAuthorizationHeader(config),
            "content-type": "application/json"
          },
          method: "POST"
        }
      );

      if (!response.ok) {
        return {
          destination: "Opsgenie",
          detail: `Opsgenie alert routing returned status ${response.status}.`,
          status: "Failed"
        };
      }

      const payload = (await response.json().catch(() => ({}))) as {
        message?: string;
        requestId?: string;
        result?: string;
      };

      return {
        deliveredAt: new Date().toISOString(),
        destination: "Opsgenie",
        latencyMs: Date.now() - startedAt,
        mode: "apiKey",
        status: "Delivered",
        ticketId: payload.requestId ?? alertPayload.alias ?? null
      };
    }
  };
}

