function connectWiseRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function connectWiseRecordArray(value: unknown) {
  return Array.isArray(value)
    ? value.map(connectWiseRecord)
    : Array.isArray(connectWiseRecord(value).items)
      ? (connectWiseRecord(value).items as unknown[]).map(connectWiseRecord)
      : [];
}

function connectWiseString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function connectWiseNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function connectWiseNumber(value: unknown, fallback = 0) {
  return typeof value === "number" && Number.isFinite(value)
    ? value
    : typeof value === "string" && /^\d+$/u.test(value)
      ? Number(value)
      : fallback;
}

function connectWiseNestedName(value: unknown) {
  return connectWiseNullableString(connectWiseRecord(value).name);
}

function normalizeConnectWiseApiBaseUrl(config: ConnectWiseManageApiKeyConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function connectWiseApiUrl(
  config: ConnectWiseManageApiKeyConfig,
  pathName: string
) {
  return `${normalizeConnectWiseApiBaseUrl(config)}${pathName}`;
}

function connectWiseAuthorizationHeader(config: ConnectWiseManageApiKeyConfig) {
  return `Basic ${Buffer.from(`${config.companyId}+${config.publicKey}:${config.privateKey}`).toString("base64")}`;
}

function connectWiseHeaders(config: ConnectWiseManageApiKeyConfig) {
  return {
    accept: "application/json",
    authorization: connectWiseAuthorizationHeader(config),
    ...(config.clientId ? { "x-cw-clientid": config.clientId } : {})
  };
}

function assertConnectWiseReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();
  const allowedPrefixes = [
    "/system/info",
    "/company/companies",
    "/service/tickets"
  ];

  if (
    !allowedPrefixes.some(
      (prefix) => normalized === prefix || normalized.startsWith(`${prefix}?`)
    ) ||
    /(?:\/|^)(?:delete|update|patch|merge|execute|action|config|setup|invoice|agreement|project|device|agent)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "ConnectWise Manage connector only allows read-only system, company, and service-ticket inventory paths."
    );
  }
}

function buildConnectWiseQuery(params: Record<string, string | number>) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    search.set(key, String(value));
  }

  return search.toString();
}

async function connectWiseGetJson(
  config: ConnectWiseManageApiKeyConfig,
  pathName: string
) {
  assertConnectWiseReadOnlyPath(pathName);
  const response = await connectorFetch(connectWiseApiUrl(config, pathName), {
    headers: connectWiseHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(
      `ConnectWise Manage API returned status ${response.status}.`
    );
  }

  return response.json();
}

function parseConnectWiseCompany(row: Record<string, unknown>) {
  return {
    id: connectWiseNumber(row.id),
    identifier: connectWiseNullableString(row.identifier),
    name: connectWiseString(row.name, `company-${connectWiseNumber(row.id)}`),
    statusName: connectWiseNestedName(row.status),
    typeName: connectWiseNestedName(row.type)
  } satisfies ConnectWiseCompany;
}

function parseConnectWiseTicket(row: Record<string, unknown>) {
  return {
    boardName: connectWiseNestedName(row.board),
    companyName: connectWiseNestedName(row.company),
    id: connectWiseNumber(row.id),
    lastUpdated: connectWiseNullableString(
      row.lastUpdated ?? connectWiseRecord(row._info).lastUpdated
    ),
    priorityName: connectWiseNestedName(row.priority),
    statusName: connectWiseNestedName(row.status),
    summary: connectWiseString(
      row.summary,
      `ticket-${connectWiseNumber(row.id)}`
    )
  } satisfies ConnectWiseTicket;
}

