async function loadConnectWiseLiveInventory(
  config: ConnectWiseManageApiKeyConfig
): Promise<ConnectWiseInventory> {
  const pageSize = config.pageSize;
  const [companies, tickets] = await Promise.all([
    config.includeCompanies
      ? connectWiseGetJson(
          config,
          `/company/companies?${buildConnectWiseQuery({
            fields: "id,identifier,name,status/name,type/name",
            pageSize
          })}`
        )
      : [],
    config.includeTickets
      ? connectWiseGetJson(
          config,
          `/service/tickets?${buildConnectWiseQuery({
            fields:
              "id,summary,status/name,board/name,company/name,priority/name,lastUpdated",
            pageSize
          })}`
        )
      : []
  ]);

  return {
    companies: connectWiseRecordArray(companies).map(parseConnectWiseCompany),
    tickets: connectWiseRecordArray(tickets).map(parseConnectWiseTicket)
  };
}

async function loadConnectWiseInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadConnectWiseFixtureInventory();
  }

  return loadConnectWiseLiveInventory(
    ConnectWiseManageApiKeyConfigSchema.parse(context.config)
  );
}

function createConnectWiseAssets(inventory: ConnectWiseInventory) {
  return inventory.companies.map((company) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Other",
      businessCriticality: "Moderate",
      environment: "mssp-psa",
      identifiers: {
        identifier: company.identifier,
        provider: "connectwise-manage",
        providerId: company.id
      },
      internetExposed: false,
      name: `connectwise-company/${company.name}`,
      owner: company.typeName,
      status:
        company.statusName?.toLowerCase() === "inactive"
          ? "Inactive"
          : "Active",
      tags: ["connectwise", "psa", "mssp-client"]
    })
  );
}

function isConnectWiseOpenTicket(ticket: ConnectWiseTicket) {
  return !/(?:closed|complete|resolved|cancel)/iu.test(ticket.statusName ?? "");
}

function createConnectWiseSignals(inventory: ConnectWiseInventory) {
  const observedAt = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const company of inventory.companies) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `connectwise://companies/${company.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "ConnectWiseCompanyObserved",
        sourceType: "connectwise.company",
        timestampObserved: observedAt
      })
    );
  }

  for (const ticket of inventory.tickets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `connectwise://tickets/${ticket.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: ticket.priorityName?.toLowerCase().includes("high")
          ? "High"
          : "Moderate",
        signalCategory: "Remediation",
        signalSubcategory: "ConnectWiseTicketObserved",
        sourceType: "connectwise.ticket",
        timestampObserved: ticket.lastUpdated ?? observedAt
      })
    );

    if (isConnectWiseOpenTicket(ticket)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `connectwise://tickets/${ticket.id}/open`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Remediation",
          signalSubcategory: "ConnectWiseOpenTicketObserved",
          sourceType: "connectwise.ticket.open",
          timestampObserved: ticket.lastUpdated ?? observedAt
        })
      );
    }
  }

  return signals;
}

function connectWiseWorkflowEventFromContext(
  context: ConnectorExecutionContext
): ConnectWiseManageWorkflowEvent {
  const rawEvent =
    typeof context.config.workflowEvent === "object" &&
    context.config.workflowEvent
      ? context.config.workflowEvent
      : {};

  return ConnectWiseManageWorkflowEventSchema.parse(rawEvent);
}

function buildConnectWiseTicketPayload(
  config: ConnectWiseManageApiKeyConfig,
  event: ConnectWiseManageWorkflowEvent
) {
  const companyId = event.companyId ?? config.defaultTicketCompanyId;

  return {
    ...(config.boardId ? { board: { id: config.boardId } } : {}),
    ...(companyId ? { company: { id: companyId } } : {}),
    ...(config.statusId ? { status: { id: config.statusId } } : {}),
    initialDescription: buildServiceNowDescription(event),
    recordType: config.ticketType ?? "ServiceTicket",
    summary: event.title ?? "Periscan validation workflow item"
  };
}

async function getConnectWiseHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CONNECTWISE_MANAGE_CONNECTOR_MANIFEST, context);
  }

  const config = ConnectWiseManageApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();
  const response = await connectorFetch(
    connectWiseApiUrl(config, "/system/info"),
    {
      headers: connectWiseHeaders(config),
      method: "GET"
    }
  );

  return ConnectorHealthSchema.parse({
    authorizationVerified: response.ok,
    checkedAt: new Date().toISOString(),
    detail: response.ok
      ? "ConnectWise Manage API key verified for read-only system metadata."
      : `ConnectWise Manage health check returned status ${response.status}.`,
    latencyMs: Date.now() - startedAt,
    status: response.ok ? "Healthy" : "Unhealthy"
  });
}

function createConnectWiseManageConnector(): Connector {
  return {
    manifest: CONNECTWISE_MANAGE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadConnectWiseInventory(parsedContext);

      return createConnectWiseSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getConnectWiseHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadConnectWiseInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(CONNECTWISE_MANAGE_CONNECTOR_MANIFEST, parsedContext)
        : await getConnectWiseHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createConnectWiseAssets(inventory),
        health,
        signals: createConnectWiseSignals(inventory).map((signal) =>
          createTimestampedSignal(
            CONNECTWISE_MANAGE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async sendWorkflowEvent(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const event = connectWiseWorkflowEventFromContext(parsedContext);

      if (parsedContext.mockMode) {
        return {
          deliveredAt: new Date().toISOString(),
          destination: "ConnectWise Manage",
          mode: "mock",
          status: "Delivered",
          ticketId: `CW-${parsedContext.integrationId.replace(/-/g, "").slice(0, 8).toUpperCase()}`
        };
      }

      const config = ConnectWiseManageApiKeyConfigSchema.parse(
        parsedContext.config
      );
      const startedAt = Date.now();
      const response = await connectorFetch(
        connectWiseApiUrl(config, "/service/tickets"),
        {
          body: JSON.stringify(buildConnectWiseTicketPayload(config, event)),
          headers: {
            ...connectWiseHeaders(config),
            "content-type": "application/json"
          },
          method: "POST"
        }
      );

      if (!response.ok) {
        return {
          destination: "ConnectWise Manage",
          detail: `ConnectWise Manage ticket creation returned status ${response.status}.`,
          status: "Failed"
        };
      }

      const payload = (await response.json().catch(() => ({}))) as {
        id?: number | string;
      };

      return {
        deliveredAt: new Date().toISOString(),
        destination: "ConnectWise Manage",
        latencyMs: Date.now() - startedAt,
        mode: "apiKey",
        status: "Delivered",
        ticketId:
          typeof payload.id === "number" || typeof payload.id === "string"
            ? `CW-${String(payload.id)}`
            : null
      };
    }
  };
}

const ConnectWiseAutomateApiConfigSchema = z
  .object({
    accessToken: z.string().min(1).optional(),
    alertPath: z
      .string()
      .regex(/^\/cwa\/api\/v1\/Alerts$/iu)
      .default("/cwa/api/v1/Alerts"),
    apiBaseUrl: z.url(),
    clientPath: z
      .string()
      .regex(/^\/cwa\/api\/v1\/Clients$/iu)
      .default("/cwa/api/v1/Clients"),
    computerPath: z
      .string()
      .regex(/^\/cwa\/api\/v1\/Computers$/iu)
      .default("/cwa/api/v1/Computers"),
    includeAlerts: z.boolean().default(true),
    includeClients: z.boolean().default(true),
    includeComputers: z.boolean().default(true),
    page: z.number().int().positive().default(1),
    pageSize: z.number().int().min(1).max(500).default(100),
    password: z.string().min(1).optional(),
    username: z.string().min(1).optional()
  })
  .refine(
    (config) => config.accessToken || (config.username && config.password),
    {
      message:
        "ConnectWise Automate live mode requires accessToken or username/password."
    }
  );

type ConnectWiseAutomateApiConfig = z.infer<
  typeof ConnectWiseAutomateApiConfigSchema
>;

type ConnectWiseAutomateClient = {
  id: string;
  name: string;
  status: string | null;
};

type ConnectWiseAutomateComputer = {
  clientId: string | null;
  clientName: string | null;
  id: string;
  lastSeenAt: string | null;
  locationName: string | null;
  name: string;
  online: boolean | null;
  operatingSystem: string | null;
  serialNumber: string | null;
};

type ConnectWiseAutomateAlert = {
  clientId: string | null;
  computerId: string | null;
  computerName: string | null;
  id: string;
  message: string;
  severity: string | null;
  status: string | null;
  updatedAt: string | null;
};

type ConnectWiseAutomateInventory = {
  alerts: ConnectWiseAutomateAlert[];
  clients: ConnectWiseAutomateClient[];
  computers: ConnectWiseAutomateComputer[];
};

