function connectWiseAutomateRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function connectWiseAutomateRecordArray(value: unknown) {
  const record = connectWiseAutomateRecord(value);

  if (Array.isArray(value)) {
    return value.map(connectWiseAutomateRecord);
  }

  for (const key of [
    "items",
    "data",
    "results",
    "Result",
    "Clients",
    "clients",
    "Computers",
    "computers",
    "Alerts",
    "alerts",
    "value"
  ]) {
    if (Array.isArray(record[key])) {
      return record[key].map(connectWiseAutomateRecord);
    }
  }

  return [];
}

function connectWiseAutomateString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : typeof value === "number" && Number.isFinite(value)
      ? String(value)
      : fallback;
}

function connectWiseAutomateNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : typeof value === "number" && Number.isFinite(value)
      ? String(value)
      : null;
}

function connectWiseAutomateNullableBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1 ? true : value === 0 ? false : null;
  }

  if (typeof value === "string") {
    const normalized = value.trim();

    if (/^(?:true|online|up|active|healthy|ok|1)$/iu.test(normalized)) {
      return true;
    }

    if (
      /^(?:false|offline|down|inactive|unhealthy|failed|0)$/iu.test(normalized)
    ) {
      return false;
    }
  }

  return null;
}

function connectWiseAutomateTimestamp(value: unknown) {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return new Date(
      value > 10_000_000_000 ? value : value * 1000
    ).toISOString();
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const trimmed = value.trim();
    const numeric = Number(trimmed);

    if (/^\d{10,13}$/u.test(trimmed) && Number.isFinite(numeric)) {
      return new Date(
        trimmed.length === 10 ? numeric * 1000 : numeric
      ).toISOString();
    }

    return trimmed;
  }

  return null;
}

function normalizeConnectWiseAutomateBaseUrl(
  config: ConnectWiseAutomateApiConfig
) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function connectWiseAutomateApiUrl(
  config: ConnectWiseAutomateApiConfig,
  pathName: string
) {
  return `${normalizeConnectWiseAutomateBaseUrl(config)}${pathName}`;
}

function assertConnectWiseAutomateReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();
  const isAllowed =
    /^\/cwa\/api\/v1\/Clients(?:\?|$)/iu.test(normalized) ||
    /^\/cwa\/api\/v1\/Computers(?:\?|$)/iu.test(normalized) ||
    /^\/cwa\/api\/v1\/Alerts(?:\?|$)/iu.test(normalized);

  if (
    !isAllowed ||
    /(?:\/|^)(?:scripts?|commands?|agentprocs?|procedures?|patch(?:es|ing)?|deploy|install|uninstall|reboot|restart|shutdown|remote-control|control|screenconnect|take-control|files?|logs?|tickets?|clients?\/\d+|computers?\/\d+|users?|roles?|credentials?|password|settings?|configuration|delete|remove|create|update|put|patch|post|execute|run|start|stop)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "ConnectWise Automate connector only allows read-only client, computer, and alert inventory paths."
    );
  }
}

function buildConnectWiseAutomateQuery(
  params: Record<string, string | number | boolean>
) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    search.set(key, String(value));
  }

  return search.toString();
}

function connectWiseAutomateHeaders(config: ConnectWiseAutomateApiConfig) {
  const authorization = config.accessToken
    ? `Bearer ${config.accessToken}`
    : `Basic ${Buffer.from(`${config.username ?? ""}:${config.password ?? ""}`).toString("base64")}`;

  return {
    accept: "application/json",
    authorization,
    "content-type": "application/json"
  };
}

async function connectWiseAutomateGetJson(
  config: ConnectWiseAutomateApiConfig,
  pathName: string
) {
  assertConnectWiseAutomateReadOnlyPath(pathName);
  const response = await connectorFetch(
    connectWiseAutomateApiUrl(config, pathName),
    {
      headers: connectWiseAutomateHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(
      `ConnectWise Automate API returned status ${response.status}.`
    );
  }

  return response.json();
}

function parseConnectWiseAutomateClient(row: Record<string, unknown>) {
  const id = connectWiseAutomateString(
    row.ClientID ?? row.ClientId ?? row.clientId ?? row.id
  );

  return {
    id,
    name: connectWiseAutomateString(
      row.Name ?? row.ClientName ?? row.name,
      `client-${id}`
    ),
    status: connectWiseAutomateNullableString(row.Status ?? row.status)
  } satisfies ConnectWiseAutomateClient;
}

function parseConnectWiseAutomateComputer(row: Record<string, unknown>) {
  const id = connectWiseAutomateString(
    row.ComputerID ?? row.ComputerId ?? row.computerId ?? row.id
  );

  return {
    clientId: connectWiseAutomateNullableString(
      row.ClientID ?? row.ClientId ?? row.clientId
    ),
    clientName: connectWiseAutomateNullableString(
      row.ClientName ?? row.clientName
    ),
    id,
    lastSeenAt: connectWiseAutomateTimestamp(
      row.LastContact ??
        row.LastSeen ??
        row.LastCheckin ??
        row.lastContact ??
        row.lastSeen
    ),
    locationName: connectWiseAutomateNullableString(
      row.LocationName ?? row.locationName
    ),
    name: connectWiseAutomateString(
      row.Name ?? row.ComputerName ?? row.computerName ?? row.Hostname,
      `computer-${id}`
    ),
    online:
      connectWiseAutomateNullableBoolean(row.Online ?? row.online) ??
      connectWiseAutomateNullableBoolean(row.Status ?? row.status),
    operatingSystem: connectWiseAutomateNullableString(
      row.OS ?? row.OperatingSystem ?? row.operatingSystem
    ),
    serialNumber: connectWiseAutomateNullableString(
      row.SerialNumber ?? row.Serial ?? row.serialNumber
    )
  } satisfies ConnectWiseAutomateComputer;
}

function parseConnectWiseAutomateAlert(row: Record<string, unknown>) {
  const id = connectWiseAutomateString(
    row.AlertID ?? row.AlertId ?? row.alertId ?? row.id
  );

  return {
    clientId: connectWiseAutomateNullableString(
      row.ClientID ?? row.ClientId ?? row.clientId
    ),
    computerId: connectWiseAutomateNullableString(
      row.ComputerID ?? row.ComputerId ?? row.computerId
    ),
    computerName: connectWiseAutomateNullableString(
      row.ComputerName ?? row.computerName
    ),
    id,
    message: connectWiseAutomateString(
      row.Message ?? row.Name ?? row.Subject ?? row.message,
      `alert-${id}`
    ),
    severity: connectWiseAutomateNullableString(
      row.Severity ?? row.Priority ?? row.severity
    ),
    status: connectWiseAutomateNullableString(row.Status ?? row.status),
    updatedAt: connectWiseAutomateTimestamp(
      row.LastUpdate ?? row.UpdatedAt ?? row.updatedAt
    )
  } satisfies ConnectWiseAutomateAlert;
}

