function ninjaOneRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function ninjaOneRecordArray(value: unknown) {
  const record = ninjaOneRecord(value);

  if (Array.isArray(value)) {
    return value.map(ninjaOneRecord);
  }

  if (Array.isArray(record.items)) {
    return record.items.map(ninjaOneRecord);
  }

  if (Array.isArray(record.data)) {
    return record.data.map(ninjaOneRecord);
  }

  if (Array.isArray(record.results)) {
    return record.results.map(ninjaOneRecord);
  }

  return [];
}

function ninjaOneString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function ninjaOneNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function ninjaOneNumber(value: unknown, fallback = 0) {
  return typeof value === "number" && Number.isFinite(value)
    ? value
    : typeof value === "string" && /^\d+$/u.test(value)
      ? Number(value)
      : fallback;
}

function ninjaOneNullableNumber(value: unknown) {
  const parsed = ninjaOneNumber(value, Number.NaN);

  return Number.isFinite(parsed) ? parsed : null;
}

function ninjaOneNullableBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    if (/^(?:true|online|up|active|healthy)$/iu.test(value.trim())) {
      return true;
    }

    if (/^(?:false|offline|down|inactive|unhealthy)$/iu.test(value.trim())) {
      return false;
    }
  }

  return null;
}

function ninjaOneNestedName(value: unknown) {
  return ninjaOneNullableString(ninjaOneRecord(value).name);
}

function normalizeNinjaOneApiBaseUrl(config: NinjaOneAccessTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function ninjaOneApiUrl(config: NinjaOneAccessTokenConfig, pathName: string) {
  return `${normalizeNinjaOneApiBaseUrl(config)}${pathName}`;
}

function ninjaOneHeaders(config: NinjaOneAccessTokenConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.accessToken}`
  };
}

function assertNinjaOneReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();
  const isAllowed =
    normalized === "/v2/organizations" ||
    normalized.startsWith("/v2/organizations?") ||
    normalized === "/v2/devices" ||
    normalized.startsWith("/v2/devices?") ||
    /^\/v2\/device\/\d+\/alerts(?:\?|$)/u.test(normalized);

  if (
    !isAllowed ||
    /(?:\/|^)(?:action|script|automation|patch|remote|ticket|policy|organization\/document|archive|delete|reset|run|execute|reboot|shutdown)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "NinjaOne connector only allows read-only organization, device, and alert inventory paths."
    );
  }
}

function buildNinjaOneQuery(params: Record<string, string | number>) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    search.set(key, String(value));
  }

  return search.toString();
}

async function ninjaOneGetJson(
  config: NinjaOneAccessTokenConfig,
  pathName: string
) {
  assertNinjaOneReadOnlyPath(pathName);
  const response = await connectorFetch(ninjaOneApiUrl(config, pathName), {
    headers: ninjaOneHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`NinjaOne API returned status ${response.status}.`);
  }

  return response.json();
}

function parseNinjaOneOrganization(row: Record<string, unknown>) {
  return {
    id: ninjaOneNumber(row.id),
    name: ninjaOneString(row.name, `organization-${ninjaOneNumber(row.id)}`)
  } satisfies NinjaOneOrganization;
}

function parseNinjaOneDevice(row: Record<string, unknown>) {
  const organization = ninjaOneRecord(row.organization);
  const osRecord = ninjaOneRecord(row.os);
  const organizationId =
    ninjaOneNullableNumber(row.organizationId) ??
    ninjaOneNullableNumber(organization.id);

  return {
    approvalStatus: ninjaOneNullableString(row.approvalStatus),
    id: ninjaOneNumber(row.id),
    name: ninjaOneString(
      row.displayName ?? row.name,
      `device-${ninjaOneNumber(row.id)}`
    ),
    online:
      ninjaOneNullableBoolean(row.online) ??
      ninjaOneNullableBoolean(row.status),
    organizationId,
    organizationName:
      ninjaOneNestedName(row.organization) ??
      (organizationId ? `organization-${organizationId}` : null),
    os: ninjaOneNullableString(osRecord.name) ?? ninjaOneNullableString(row.os),
    status: ninjaOneNullableString(row.status),
    type:
      ninjaOneNullableString(row.nodeClass) ?? ninjaOneNullableString(row.type)
  } satisfies NinjaOneDevice;
}

function parseNinjaOneAlert(
  row: Record<string, unknown>,
  deviceId: number | null = null
) {
  const idValue = row.id ?? row.activityId ?? row.uid ?? randomUUID();

  return {
    deviceId: ninjaOneNullableNumber(row.deviceId) ?? deviceId,
    id: String(idValue),
    message: ninjaOneString(
      row.message ?? row.title ?? row.description ?? row.subject,
      "NinjaOne alert"
    ),
    severity: ninjaOneNullableString(row.severity ?? row.priority),
    status: ninjaOneNullableString(row.status ?? row.state),
    timestamp: ninjaOneNullableString(
      row.timestamp ?? row.createTime ?? row.createdAt ?? row.activityTime
    )
  } satisfies NinjaOneAlert;
}

