function haloPsaRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function haloPsaRecordArray(value: unknown) {
  const record = haloPsaRecord(value);

  if (Array.isArray(value)) {
    return value.map(haloPsaRecord);
  }

  if (Array.isArray(record.items)) {
    return record.items.map(haloPsaRecord);
  }

  if (Array.isArray(record.data)) {
    return record.data.map(haloPsaRecord);
  }

  if (Array.isArray(record.results)) {
    return record.results.map(haloPsaRecord);
  }

  return [];
}

function haloPsaString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function haloPsaNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function haloPsaNumber(value: unknown, fallback = 0) {
  return typeof value === "number" && Number.isFinite(value)
    ? value
    : typeof value === "string" && /^\d+$/u.test(value)
      ? Number(value)
      : fallback;
}

function haloPsaNullableNumber(value: unknown) {
  const parsed = haloPsaNumber(value, Number.NaN);

  return Number.isFinite(parsed) ? parsed : null;
}

function haloPsaNestedName(value: unknown) {
  return haloPsaNullableString(haloPsaRecord(value).name);
}

function normalizeHaloPsaBaseUrl(value: string) {
  return value.replace(/\/+$/u, "");
}

function haloPsaApiUrl(
  config: HaloPsaClientCredentialsConfig,
  pathName: string
) {
  return `${normalizeHaloPsaBaseUrl(config.apiBaseUrl)}${pathName}`;
}

function haloPsaAuthUrl(config: HaloPsaClientCredentialsConfig) {
  return `${normalizeHaloPsaBaseUrl(config.authBaseUrl ?? config.apiBaseUrl)}/auth/token`;
}

function assertHaloPsaReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();

  if (
    !/^\/api\/(?:Clients?|Tickets?)(?:\?|$)/iu.test(normalized) ||
    /(?:\/|^)(?:site|users?|assets?|projects?|billing|invoice|configuration|delete|archive|action|update|merge|feedback)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "HaloPSA connector only allows read-only client and ticket inventory paths."
    );
  }
}

function buildHaloPsaQuery(params: Record<string, string | number>) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    search.set(key, String(value));
  }

  return search.toString();
}

async function haloPsaAccessToken(config: HaloPsaClientCredentialsConfig) {
  const body = new URLSearchParams({
    client_id: config.clientId,
    client_secret: config.clientSecret,
    grant_type: "client_credentials",
    scope: config.scope
  });
  const response = await connectorFetch(haloPsaAuthUrl(config), {
    body,
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(
      `HaloPSA token request returned status ${response.status}.`
    );
  }

  const payload = haloPsaRecord(await response.json());
  const token = haloPsaString(payload.access_token ?? payload.token, "");

  if (!token) {
    throw new Error("HaloPSA token response did not include an access token.");
  }

  return token;
}

async function haloPsaGetJson(
  config: HaloPsaClientCredentialsConfig,
  accessToken: string,
  pathName: string
) {
  assertHaloPsaReadOnlyPath(pathName);
  const response = await connectorFetch(haloPsaApiUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${accessToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`HaloPSA API returned status ${response.status}.`);
  }

  return response.json();
}

function parseHaloPsaClient(row: Record<string, unknown>) {
  return {
    id: haloPsaNumber(row.id ?? row.client_id),
    name: haloPsaString(
      row.name ?? row.client_name,
      `client-${haloPsaNumber(row.id ?? row.client_id)}`
    ),
    status:
      haloPsaNestedName(row.status) ??
      haloPsaNullableString(row.status ?? row.status_name)
  } satisfies HaloPsaClient;
}

function parseHaloPsaTicket(row: Record<string, unknown>) {
  return {
    clientId: haloPsaNullableNumber(row.client_id ?? row.clientid),
    clientName:
      haloPsaNestedName(row.client) ??
      haloPsaNullableString(row.client_name ?? row.clientname),
    id: haloPsaNumber(row.id ?? row.ticket_id ?? row.ticketid),
    lastUpdated: haloPsaNullableString(
      row.lastupdated ??
        row.last_updated ??
        row.updated_at ??
        row.dateupdated ??
        row.updateddate
    ),
    priority:
      haloPsaNestedName(row.priority) ??
      haloPsaNullableString(row.priority ?? row.priority_name),
    status:
      haloPsaNestedName(row.status) ??
      haloPsaNullableString(row.status ?? row.status_name),
    summary: haloPsaString(
      row.summary ?? row.title,
      `ticket-${haloPsaNumber(row.id ?? row.ticket_id ?? row.ticketid)}`
    )
  } satisfies HaloPsaTicket;
}

