async function loadHaloPsaLiveInventory(
  config: HaloPsaClientCredentialsConfig
): Promise<HaloPsaInventory> {
  const token = await haloPsaAccessToken(config);
  const query = buildHaloPsaQuery({
    page_size: config.pageSize
  });
  const [clientsPayload, ticketsPayload] = await Promise.all([
    config.includeClients
      ? haloPsaGetJson(config, token, `${config.clientPath}?${query}`)
      : [],
    config.includeTickets
      ? haloPsaGetJson(config, token, `${config.ticketPath}?${query}`)
      : []
  ]);

  return {
    clients: haloPsaRecordArray(clientsPayload).map(parseHaloPsaClient),
    tickets: haloPsaRecordArray(ticketsPayload).map(parseHaloPsaTicket)
  };
}

async function loadHaloPsaInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadHaloPsaFixtureInventory();
  }

  return loadHaloPsaLiveInventory(
    HaloPsaClientCredentialsConfigSchema.parse(context.config)
  );
}

function isHaloPsaOpenTicket(ticket: HaloPsaTicket) {
  return !/(?:closed|complete|resolved|cancel)/iu.test(ticket.status ?? "");
}

function createHaloPsaAssets(inventory: HaloPsaInventory) {
  return inventory.clients.map((client) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Other",
      businessCriticality: "Moderate",
      environment: "mssp-psa",
      identifiers: {
        provider: "halopsa",
        providerId: client.id
      },
      internetExposed: false,
      name: `halopsa-client/${client.name}`,
      owner: "MSSP/PSA",
      status:
        client.status?.toLowerCase() === "inactive" ? "Inactive" : "Active",
      tags: ["halopsa", "psa", "mssp-client"]
    })
  );
}

function createHaloPsaSignals(inventory: HaloPsaInventory) {
  const observedAt = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const client of inventory.clients) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `halopsa://clients/${client.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "HaloPSAClientObserved",
        sourceType: "halopsa.client",
        timestampObserved: observedAt
      })
    );
  }

  for (const ticket of inventory.tickets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `halopsa://tickets/${ticket.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: ticket.priority?.toLowerCase().includes("high")
          ? "High"
          : "Moderate",
        signalCategory: "Remediation",
        signalSubcategory: "HaloPSATicketObserved",
        sourceType: "halopsa.ticket",
        timestampObserved: ticket.lastUpdated ?? observedAt
      })
    );

    if (isHaloPsaOpenTicket(ticket)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.84,
          freshness: "Fresh",
          rawPayloadPointer: `halopsa://tickets/${ticket.id}/open`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Remediation",
          signalSubcategory: "HaloPSAOpenTicketObserved",
          sourceType: "halopsa.ticket.open",
          timestampObserved: ticket.lastUpdated ?? observedAt
        })
      );
    }
  }

  return signals;
}

function haloPsaWorkflowEventFromContext(
  context: ConnectorExecutionContext
): HaloPsaWorkflowEvent {
  const rawEvent =
    typeof context.config.workflowEvent === "object" &&
    context.config.workflowEvent
      ? context.config.workflowEvent
      : {};

  return HaloPsaWorkflowEventSchema.parse(rawEvent);
}

function buildHaloPsaTicketPayload(
  config: HaloPsaClientCredentialsConfig,
  event: HaloPsaWorkflowEvent
) {
  const clientId = event.clientId ?? config.defaultClientId;

  return {
    ...(clientId ? { client_id: clientId } : {}),
    ...(config.ticketPriorityId
      ? { priority_id: config.ticketPriorityId }
      : {}),
    ...(config.ticketStatusId ? { status_id: config.ticketStatusId } : {}),
    ...(config.ticketTypeId ? { tickettype_id: config.ticketTypeId } : {}),
    details: buildServiceNowDescription(event),
    summary: event.title ?? "Periscan validation workflow item"
  };
}

async function getHaloPsaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(HALOPSA_CONNECTOR_MANIFEST, context);
  }

  const config = HaloPsaClientCredentialsConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const token = await haloPsaAccessToken(config);
    await haloPsaGetJson(
      config,
      token,
      `${config.clientPath}?${buildHaloPsaQuery({ page_size: 1 })}`
    );

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "HaloPSA client credentials verified for read-only client/ticket context. No client, site, user, project, billing, asset, configuration, or ticket-state mutation endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `HaloPSA health check failed: ${error.message}`
          : "HaloPSA health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createHaloPsaConnector(): Connector {
  return {
    manifest: HALOPSA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadHaloPsaInventory(parsedContext);

      return createHaloPsaSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getHaloPsaHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadHaloPsaInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(HALOPSA_CONNECTOR_MANIFEST, parsedContext)
        : await getHaloPsaHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createHaloPsaAssets(inventory),
        health,
        signals: createHaloPsaSignals(inventory).map((signal) =>
          createTimestampedSignal(
            HALOPSA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async sendWorkflowEvent(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const event = haloPsaWorkflowEventFromContext(parsedContext);

      if (parsedContext.mockMode) {
        return {
          deliveredAt: new Date().toISOString(),
          destination: "HaloPSA",
          mode: "mock",
          status: "Delivered",
          ticketId: `HALO-${parsedContext.integrationId.replace(/-/g, "").slice(0, 8).toUpperCase()}`
        };
      }

      const config = HaloPsaClientCredentialsConfigSchema.parse(
        parsedContext.config
      );
      const token = await haloPsaAccessToken(config);
      const startedAt = Date.now();
      const response = await connectorFetch(
        haloPsaApiUrl(config, config.ticketPath),
        {
          body: JSON.stringify(buildHaloPsaTicketPayload(config, event)),
          headers: {
            accept: "application/json",
            authorization: `Bearer ${token}`,
            "content-type": "application/json"
          },
          method: "POST"
        }
      );

      if (!response.ok) {
        return {
          destination: "HaloPSA",
          detail: `HaloPSA ticket creation returned status ${response.status}.`,
          status: "Failed"
        };
      }

      const payload = haloPsaRecord(await response.json().catch(() => ({})));
      const ticketId = payload.id ?? payload.ticket_id ?? payload.ticketid;

      return {
        deliveredAt: new Date().toISOString(),
        destination: "HaloPSA",
        latencyMs: Date.now() - startedAt,
        mode: "clientCredentials",
        status: "Delivered",
        ticketId:
          typeof ticketId === "number" || typeof ticketId === "string"
            ? `HALO-${String(ticketId)}`
            : null
      };
    }
  };
}

const AutotaskApiKeyConfigSchema = z.object({
  apiBaseUrl: z.url(),
  apiIntegrationCode: z.string().min(1),
  companyPath: z
    .string()
    .regex(/^\/Companies$/u)
    .default("/Companies"),
  defaultCompanyId: z.number().int().positive().optional(),
  includeCompanies: z.boolean().default(true),
  includeTickets: z.boolean().default(true),
  issueType: z.number().int().positive().optional(),
  pageSize: z.number().int().min(1).max(200).default(50),
  priority: z.number().int().positive().optional(),
  queueId: z.number().int().positive().optional(),
  secret: z.string().min(1),
  status: z.number().int().positive().optional(),
  subIssueType: z.number().int().positive().optional(),
  ticketPath: z
    .string()
    .regex(/^\/Tickets$/u)
    .default("/Tickets"),
  ticketType: z.number().int().positive().optional(),
  username: z.email()
});

const AutotaskWorkflowEventSchema = JiraWorkflowEventSchema.extend({
  companyId: z.number().int().positive().optional()
}).passthrough();

type AutotaskApiKeyConfig = z.infer<typeof AutotaskApiKeyConfigSchema>;
type AutotaskWorkflowEvent = z.infer<typeof AutotaskWorkflowEventSchema>;

type AutotaskCompany = {
  id: number;
  isActive: boolean | null;
  name: string;
  type: string | null;
};

type AutotaskTicket = {
  companyId: number | null;
  companyName: string | null;
  id: number;
  lastActivityDate: string | null;
  priority: string | null;
  status: string | null;
  title: string;
};

type AutotaskInventory = {
  companies: AutotaskCompany[];
  tickets: AutotaskTicket[];
};

