async function loadDattoRmmLiveInventory(
  config: DattoRmmApiKeyConfig
): Promise<DattoRmmInventory> {
  const accessToken = await dattoRmmResolveAccessToken(config);
  const devicesPayload = await dattoRmmGetJson(
    config,
    dattoRmmDeviceQuery(config),
    accessToken
  );

  return {
    devices: dattoRmmRecordArray(devicesPayload).map(parseDattoRmmDevice)
  };
}

async function loadDattoRmmInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadDattoRmmFixtureInventory();
  }

  return loadDattoRmmLiveInventory(
    DattoRmmApiKeyConfigSchema.parse(context.config)
  );
}

function createDattoRmmAssets(inventory: DattoRmmInventory) {
  const sitesByKey = new Map<string, DattoRmmDevice>();

  for (const device of inventory.devices) {
    const key = device.siteUid ?? device.siteName;

    if (key) {
      sitesByKey.set(key, device);
    }
  }

  const siteAssets = [...sitesByKey.entries()].map(([key, device]) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Other",
      businessCriticality: "Moderate",
      environment: "mssp-rmm",
      identifiers: {
        provider: "datto-rmm",
        providerId: key,
        siteName: device.siteName,
        siteUid: device.siteUid
      },
      internetExposed: false,
      name: `datto-rmm-site/${device.siteName ?? key}`,
      owner: "MSSP/RMM",
      status: "Active",
      tags: ["kaseya", "datto-rmm", "mssp-client"]
    })
  );
  const deviceAssets = inventory.devices.map((device) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Host",
      businessCriticality: device.operatingSystem
        ?.toLowerCase()
        .includes("server")
        ? "High"
        : "Moderate",
      environment: "mssp-rmm",
      identifiers: {
        deviceUid: device.deviceUid,
        lastSeenAt: device.lastSeenAt,
        operatingSystem: device.operatingSystem,
        provider: "datto-rmm",
        providerId: device.deviceUid,
        serialNumber: device.serialNumber,
        siteName: device.siteName,
        siteUid: device.siteUid
      },
      internetExposed: false,
      name: `datto-rmm-device/${device.hostname}`,
      owner: device.siteName,
      status:
        device.online === false || device.suspended === true
          ? "Inactive"
          : "Active",
      tags: [
        "kaseya",
        "datto-rmm",
        device.operatingSystem ?? "managed-device"
      ].filter(
        (tag): tag is string => typeof tag === "string" && tag.length > 0
      )
    })
  );

  return [...siteAssets, ...deviceAssets];
}

function createDattoRmmSignals(inventory: DattoRmmInventory) {
  const observedAt = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];
  const observedSites = new Set<string>();

  for (const device of inventory.devices) {
    const siteKey = device.siteUid ?? device.siteName;

    if (siteKey && !observedSites.has(siteKey)) {
      observedSites.add(siteKey);
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.9,
          freshness: "Fresh",
          rawPayloadPointer: `datto-rmm://sites/${encodeURIComponent(siteKey)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "DattoRmmSiteObserved",
          sourceType: "datto_rmm.site",
          timestampObserved: observedAt
        })
      );
    }

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `datto-rmm://devices/${encodeURIComponent(
          device.deviceUid
        )}`,
        redactionStatus: "Redacted",
        relatedAssetHints: [device.hostname],
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: device.operatingSystem
          ?.toLowerCase()
          .includes("server")
          ? "High"
          : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "DattoRmmDeviceObserved",
        sourceType: "datto_rmm.device",
        timestampObserved: device.lastSeenAt ?? observedAt
      })
    );

    if (device.online === false || device.suspended === true) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `datto-rmm://devices/${encodeURIComponent(
            device.deviceUid
          )}/offline`,
          redactionStatus: "Redacted",
          relatedAssetHints: [device.hostname],
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "DattoRmmOfflineDeviceObserved",
          sourceType: "datto_rmm.device.offline",
          timestampObserved: device.lastSeenAt ?? observedAt
        })
      );
    }
  }

  return signals;
}

async function getDattoRmmHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(DATTO_RMM_CONNECTOR_MANIFEST, context);
  }

  const config = DattoRmmApiKeyConfigSchema.parse({
    ...context.config,
    max: 1,
    page: 1
  });
  const startedAt = Date.now();

  try {
    const accessToken = await dattoRmmResolveAccessToken(config);
    await dattoRmmGetJson(config, dattoRmmDeviceQuery(config), accessToken);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Datto RMM API access verified for read-only account device inventory. No script, job, component, patch, remote-control, site, user, or device mutation endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Datto RMM health check failed: ${error.message}`
          : "Datto RMM health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createDattoRmmConnector(): Connector {
  return {
    manifest: DATTO_RMM_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadDattoRmmInventory(parsedContext);

      return createDattoRmmSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getDattoRmmHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadDattoRmmInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(DATTO_RMM_CONNECTOR_MANIFEST, parsedContext)
        : await getDattoRmmHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createDattoRmmAssets(inventory),
        health,
        signals: createDattoRmmSignals(inventory).map((signal) =>
          createTimestampedSignal(
            DATTO_RMM_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const KaseyaVsaPatConfigSchema = z.object({
  accessToken: z.string().min(1),
  agentPath: z
    .string()
    .regex(/^\/api\/v1\.0\/assetmgmt\/agents$/u)
    .default("/api/v1.0/assetmgmt/agents"),
  apiBaseUrl: z.url(),
  assetPath: z
    .string()
    .regex(/^\/api\/v1\.0\/assetmgmt\/assets$/u)
    .default("/api/v1.0/assetmgmt/assets"),
  includeAgents: z.boolean().default(true),
  includeAssets: z.boolean().default(true)
});

type KaseyaVsaPatConfig = z.infer<typeof KaseyaVsaPatConfigSchema>;

