function kaseyaVsaRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function kaseyaVsaRecordArray(value: unknown) {
  const record = kaseyaVsaRecord(value);

  if (Array.isArray(value)) {
    return value.map(kaseyaVsaRecord);
  }

  for (const key of ["Result", "result", "items", "data", "results", "value"]) {
    if (Array.isArray(record[key])) {
      return record[key].map(kaseyaVsaRecord);
    }
  }

  return [];
}

function kaseyaVsaString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : typeof value === "number" && Number.isFinite(value)
      ? String(value)
      : fallback;
}

function kaseyaVsaNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : typeof value === "number" && Number.isFinite(value)
      ? String(value)
      : null;
}

function kaseyaVsaNullableBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1 ? true : value === 0 ? false : null;
  }

  if (typeof value === "string") {
    const normalized = value.trim();

    if (/^(?:true|online|up|active|yes|1)$/iu.test(normalized)) {
      return true;
    }

    if (/^(?:false|offline|down|inactive|no|0)$/iu.test(normalized)) {
      return false;
    }
  }

  return null;
}

function normalizeKaseyaVsaBaseUrl(config: KaseyaVsaPatConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "").replace(/\/api\/v1\.0$/iu, "");
}

function kaseyaVsaApiUrl(config: KaseyaVsaPatConfig, pathName: string) {
  return `${normalizeKaseyaVsaBaseUrl(config)}${pathName}`;
}

function assertKaseyaVsaReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();
  const isAllowed =
    /^\/api\/v1\.0\/assetmgmt\/assets(?:\?|$)/u.test(normalized) ||
    /^\/api\/v1\.0\/assetmgmt\/agents(?:\?|$)/u.test(normalized);

  if (
    !isAllowed ||
    /(?:\/|^)(?:automation|agentprocs?|procedures?|scheduledprocs?|patch|patches|machineupdate|packages?|getfiles?|logs?|remotecontrol|take-control|web-remote|scripts?|jobs?|tasks?|commands?|credential|password|users?|roles?|settings?|polic(?:y|ies)|delete|remove|create|update|put|patch|post|execute|run|start|stop|rename|install|deploy|upload|download)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "Kaseya VSA connector only allows read-only asset and agent inventory paths."
    );
  }
}

async function kaseyaVsaGetJson(config: KaseyaVsaPatConfig, pathName: string) {
  assertKaseyaVsaReadOnlyPath(pathName);
  const response = await connectorFetch(kaseyaVsaApiUrl(config, pathName), {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${config.accessToken}`,
      "content-type": "application/json"
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`Kaseya VSA API returned status ${response.status}.`);
  }

  return response.json();
}

function parseKaseyaVsaAsset(row: Record<string, unknown>) {
  const assetId = kaseyaVsaString(row.AssetId ?? row.assetId ?? row.id);

  return {
    agentId: kaseyaVsaNullableString(row.AgentId ?? row.agentId),
    assetId,
    isComputerAgent: kaseyaVsaNullableBoolean(
      row.IsComputerAgent ?? row.isComputerAgent
    ),
    isMobileAgent: kaseyaVsaNullableBoolean(
      row.IsMobileAgent ?? row.isMobileAgent
    ),
    machineGroup: kaseyaVsaNullableString(row.MachineGroup ?? row.machineGroup),
    name: kaseyaVsaString(
      row.AssetName ?? row.assetName ?? row.DeviceName ?? row.deviceName,
      `asset-${assetId}`
    ),
    orgId: kaseyaVsaNullableString(row.OrgId ?? row.orgId)
  } satisfies KaseyaVsaAsset;
}

function parseKaseyaVsaAgent(row: Record<string, unknown>) {
  const agentId = kaseyaVsaString(row.AgentId ?? row.agentId ?? row.id);

  return {
    agentId,
    computerName: kaseyaVsaString(
      row.ComputerName ?? row.computerName ?? row.AgentName ?? row.agentName,
      `agent-${agentId}`
    ),
    machineGroup: kaseyaVsaNullableString(row.MachineGroup ?? row.machineGroup),
    online: kaseyaVsaNullableBoolean(row.Online ?? row.online),
    orgId: kaseyaVsaNullableString(row.OrgId ?? row.orgId),
    osInfo: kaseyaVsaNullableString(row.OSInfo ?? row.osInfo),
    osType: kaseyaVsaNullableString(row.OSType ?? row.osType)
  } satisfies KaseyaVsaAgent;
}

