async function loadKaseyaVsaLiveInventory(
  config: KaseyaVsaPatConfig
): Promise<KaseyaVsaInventory> {
  const [assetsPayload, agentsPayload] = await Promise.all([
    config.includeAssets
      ? kaseyaVsaGetJson(config, config.assetPath)
      : Promise.resolve([]),
    config.includeAgents
      ? kaseyaVsaGetJson(config, config.agentPath)
      : Promise.resolve([])
  ]);

  return {
    agents: kaseyaVsaRecordArray(agentsPayload).map(parseKaseyaVsaAgent),
    assets: kaseyaVsaRecordArray(assetsPayload).map(parseKaseyaVsaAsset)
  };
}

async function loadKaseyaVsaInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadKaseyaVsaFixtureInventory();
  }

  return loadKaseyaVsaLiveInventory(
    KaseyaVsaPatConfigSchema.parse(context.config)
  );
}

function createKaseyaVsaAssets(inventory: KaseyaVsaInventory) {
  const assetRecords = inventory.assets.map((asset) =>
    ConnectorAssetInputSchema.parse({
      assetType:
        asset.isComputerAgent === true || asset.isMobileAgent === true
          ? "Host"
          : "Other",
      businessCriticality: asset.machineGroup?.toLowerCase().includes("server")
        ? "High"
        : "Moderate",
      environment: "mssp-rmm",
      identifiers: {
        agentId: asset.agentId,
        assetId: asset.assetId,
        isComputerAgent: asset.isComputerAgent,
        isMobileAgent: asset.isMobileAgent,
        machineGroup: asset.machineGroup,
        orgId: asset.orgId,
        provider: "kaseya-vsa",
        providerId: asset.assetId
      },
      internetExposed: false,
      name: `kaseya-vsa-asset/${asset.name}`,
      owner: asset.machineGroup ?? "MSSP/RMM",
      status: "Active",
      tags: ["kaseya", "vsa", "mssp-client"].concat(
        asset.machineGroup ? [asset.machineGroup] : []
      )
    })
  );
  const knownAgentIds = new Set(
    inventory.assets.flatMap((asset) => (asset.agentId ? [asset.agentId] : []))
  );
  const agentOnlyRecords = inventory.agents
    .filter((agent) => !knownAgentIds.has(agent.agentId))
    .map((agent) =>
      ConnectorAssetInputSchema.parse({
        assetType: "Host",
        businessCriticality: agent.osInfo?.toLowerCase().includes("server")
          ? "High"
          : "Moderate",
        environment: "mssp-rmm",
        identifiers: {
          agentId: agent.agentId,
          machineGroup: agent.machineGroup,
          online: agent.online,
          orgId: agent.orgId,
          osInfo: agent.osInfo,
          osType: agent.osType,
          provider: "kaseya-vsa",
          providerId: agent.agentId
        },
        internetExposed: false,
        name: `kaseya-vsa-agent/${agent.computerName}`,
        owner: agent.machineGroup ?? "MSSP/RMM",
        status: agent.online === false ? "Inactive" : "Active",
        tags: ["kaseya", "vsa", agent.osType ?? "managed-agent"].filter(
          (tag): tag is string => typeof tag === "string" && tag.length > 0
        )
      })
    );

  return [...assetRecords, ...agentOnlyRecords];
}

function createKaseyaVsaSignals(inventory: KaseyaVsaInventory) {
  const observedAt = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const asset of inventory.assets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `kaseya-vsa://assets/${encodeURIComponent(
          asset.assetId
        )}`,
        redactionStatus: "Redacted",
        relatedAssetHints: [asset.name],
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: asset.machineGroup?.toLowerCase().includes("server")
          ? "High"
          : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "KaseyaVsaAssetObserved",
        sourceType: "kaseya_vsa.asset",
        timestampObserved: observedAt
      })
    );
  }

  for (const agent of inventory.agents) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `kaseya-vsa://agents/${encodeURIComponent(
          agent.agentId
        )}`,
        redactionStatus: "Redacted",
        relatedAssetHints: [agent.computerName],
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: agent.osInfo?.toLowerCase().includes("server")
          ? "High"
          : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "KaseyaVsaAgentObserved",
        sourceType: "kaseya_vsa.agent",
        timestampObserved: observedAt
      })
    );

    if (agent.online === false) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `kaseya-vsa://agents/${encodeURIComponent(
            agent.agentId
          )}/offline`,
          redactionStatus: "Redacted",
          relatedAssetHints: [agent.computerName],
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "KaseyaVsaOfflineAgentObserved",
          sourceType: "kaseya_vsa.agent.offline",
          timestampObserved: observedAt
        })
      );
    }
  }

  return signals;
}

async function getKaseyaVsaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(KASEYA_VSA_CONNECTOR_MANIFEST, context);
  }

  const config = KaseyaVsaPatConfigSchema.parse({
    ...context.config,
    includeAgents: false,
    includeAssets: true
  });
  const startedAt = Date.now();

  try {
    await kaseyaVsaGetJson(config, config.assetPath);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Kaseya VSA personal access token verified for read-only asset inventory. No agent procedure, patch, remote-control, file/log, delete, rename, or configuration mutation endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Kaseya VSA health check failed: ${error.message}`
          : "Kaseya VSA health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createKaseyaVsaConnector(): Connector {
  return {
    manifest: KASEYA_VSA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadKaseyaVsaInventory(parsedContext);

      return createKaseyaVsaSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getKaseyaVsaHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadKaseyaVsaInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(KASEYA_VSA_CONNECTOR_MANIFEST, parsedContext)
        : await getKaseyaVsaHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createKaseyaVsaAssets(inventory),
        health,
        signals: createKaseyaVsaSignals(inventory).map((signal) =>
          createTimestampedSignal(
            KASEYA_VSA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const NCentralApiTokenConfigSchema = z
  .object({
    accessToken: z.string().min(1).optional(),
    activeIssuesPathTemplate: z
      .string()
      .regex(/^\/api\/org-units\/\{orgUnitId\}\/active-issues$/u)
      .default("/api/org-units/{orgUnitId}/active-issues"),
    apiBaseUrl: z.url(),
    authPath: z
      .string()
      .regex(/^\/api\/auth\/authenticate$/u)
      .default("/api/auth/authenticate"),
    customerPath: z
      .string()
      .regex(/^\/api\/customers$/u)
      .default("/api/customers"),
    devicePath: z
      .string()
      .regex(/^\/api\/devices$/u)
      .default("/api/devices"),
    includeActiveIssues: z.boolean().default(true),
    includeCustomers: z.boolean().default(true),
    includeDevices: z.boolean().default(true),
    jwtToken: z.string().min(1).optional(),
    orgUnitIds: z.array(z.number().int().positive()).default([]),
    pageNumber: z.number().int().positive().default(1),
    pageSize: z.number().int().min(1).max(100).default(50)
  })
  .refine((config) => config.accessToken || config.jwtToken, {
    message: "N-central live mode requires either accessToken or jwtToken."
  });

type NCentralApiTokenConfig = z.infer<typeof NCentralApiTokenConfigSchema>;

type NCentralCustomer = {
  id: number;
  name: string;
  parentId: number | null;
  type: string | null;
};

type NCentralDevice = {
  customerId: number | null;
  deviceClass: string | null;
  id: number;
  name: string;
  online: boolean | null;
  orgUnitId: number | null;
  os: string | null;
  uri: string | null;
};

type NCentralActiveIssue = {
  deviceId: number | null;
  deviceName: string | null;
  notificationState: string | null;
  orgUnitId: number;
  serviceName: string;
  serviceType: string | null;
  taskId: number | null;
};

type NCentralInventory = {
  activeIssues: NCentralActiveIssue[];
  customers: NCentralCustomer[];
  devices: NCentralDevice[];
};

