function nCentralRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function nCentralRecordArray(value: unknown) {
  const record = nCentralRecord(value);

  if (Array.isArray(value)) {
    return value.map(nCentralRecord);
  }

  for (const key of [
    "items",
    "data",
    "results",
    "customers",
    "devices",
    "activeIssues",
    "issues"
  ]) {
    if (Array.isArray(record[key])) {
      return record[key].map(nCentralRecord);
    }
  }

  return [];
}

function nCentralString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function nCentralNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function nCentralNumber(value: unknown, fallback = 0) {
  return typeof value === "number" && Number.isFinite(value)
    ? value
    : typeof value === "string" && /^\d+$/u.test(value)
      ? Number(value)
      : fallback;
}

function nCentralNullableNumber(value: unknown) {
  const parsed = nCentralNumber(value, Number.NaN);

  return Number.isFinite(parsed) ? parsed : null;
}

function nCentralNullableBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    if (/^(?:true|online|up|active|normal|1)$/iu.test(value.trim())) {
      return true;
    }

    if (
      /^(?:false|offline|down|inactive|failed|critical|0)$/iu.test(value.trim())
    ) {
      return false;
    }
  }

  return null;
}

function normalizeNCentralBaseUrl(config: NCentralApiTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "").replace(/\/api$/iu, "");
}

function nCentralApiUrl(config: NCentralApiTokenConfig, pathName: string) {
  return `${normalizeNCentralBaseUrl(config)}${pathName}`;
}

function assertNCentralReadOnlyPath(pathName: string) {
  const normalized = pathName.trim();
  const isAllowed =
    /^\/api\/customers(?:\?|$)/u.test(normalized) ||
    /^\/api\/devices(?:\?|$)/u.test(normalized) ||
    /^\/api\/org-units\/\d+\/active-issues(?:\?|$)/u.test(normalized);

  if (
    !isAllowed ||
    /(?:\/|^)(?:tasks?|scheduled-tasks?|jobs?|scripts?|patch(?:es|ing)?|reboot|restart|shutdown|remote-control|take-control|credentials?|users?|roles?|rules?|polic(?:y|ies)|probes?|agents?|delete|remove|create|update|put|patch|post|execute|run|start|stop)(?:\/|$|\?)/iu.test(
      normalized
    )
  ) {
    throw new Error(
      "N-central connector only allows read-only customer, device, and active issue inventory paths."
    );
  }
}

function buildNCentralQuery(params: Record<string, string | number | boolean>) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    search.set(key, String(value));
  }

  return search.toString();
}

function nCentralHeaders(accessToken: string) {
  return {
    accept: "application/json",
    authorization: `Bearer ${accessToken}`,
    "content-type": "application/json"
  };
}

function extractNCentralAccessToken(payload: unknown) {
  const record = nCentralRecord(payload);
  const tokens = nCentralRecord(record.tokens);
  const access = nCentralRecord(tokens.access);
  const token =
    record.accessToken ??
    record.token ??
    access.token ??
    nCentralRecord(record.data).accessToken;

  return typeof token === "string" && token.trim().length > 0
    ? token.trim()
    : null;
}

async function nCentralResolveAccessToken(config: NCentralApiTokenConfig) {
  if (config.accessToken) {
    return config.accessToken;
  }

  const response = await connectorFetch(
    nCentralApiUrl(config, config.authPath),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${config.jwtToken}`,
        "content-type": "application/json"
      },
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(
      `N-central token exchange returned status ${response.status}.`
    );
  }

  const token = extractNCentralAccessToken(await response.json());

  if (!token) {
    throw new Error("N-central token exchange did not return an access token.");
  }

  return token;
}

async function nCentralGetJson(
  config: NCentralApiTokenConfig,
  pathName: string,
  accessToken: string
) {
  assertNCentralReadOnlyPath(pathName);
  const response = await connectorFetch(nCentralApiUrl(config, pathName), {
    headers: nCentralHeaders(accessToken),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`N-central API returned status ${response.status}.`);
  }

  return response.json();
}

function parseNCentralCustomer(row: Record<string, unknown>) {
  const id = nCentralNumber(
    row.customerId ?? row.customerid ?? row.id ?? row.orgUnitId
  );

  return {
    id,
    name: nCentralString(row.customerName ?? row.name, `customer-${id}`),
    parentId: nCentralNullableNumber(row.parentId ?? row.parentid),
    type: nCentralNullableString(
      row.customerType ?? row.type ?? row.orgUnitType
    )
  } satisfies NCentralCustomer;
}

function parseNCentralDevice(row: Record<string, unknown>) {
  const id = nCentralNumber(row.deviceId ?? row.deviceid ?? row.id);
  const customerId = nCentralNullableNumber(
    row.customerId ?? row.customerid ?? row.orgUnitId
  );

  return {
    customerId,
    deviceClass: nCentralNullableString(
      row.deviceClass ?? row.deviceclass ?? row.class
    ),
    id,
    name: nCentralString(
      row.longName ?? row.deviceName ?? row.name ?? row.uri,
      `device-${id}`
    ),
    online:
      nCentralNullableBoolean(row.online) ??
      nCentralNullableBoolean(row.state) ??
      nCentralNullableBoolean(row.status),
    orgUnitId: nCentralNullableNumber(row.orgUnitId ?? row.orgunitid),
    os: nCentralNullableString(row.operatingSystem ?? row.os),
    uri: nCentralNullableString(row.uri)
  } satisfies NCentralDevice;
}

function parseNCentralActiveIssue(
  row: Record<string, unknown>,
  orgUnitId: number
) {
  return {
    deviceId: nCentralNullableNumber(row.deviceId ?? row.deviceid),
    deviceName: nCentralNullableString(row.deviceName ?? row.name),
    notificationState: nCentralNullableString(
      row.notificationState ?? row.state ?? row.status
    ),
    orgUnitId,
    serviceName: nCentralString(
      row.serviceName ?? row.service ?? row.name,
      "active-issue"
    ),
    serviceType: nCentralNullableString(row.serviceType ?? row.type),
    taskId: nCentralNullableNumber(row.taskId ?? row.taskid)
  } satisfies NCentralActiveIssue;
}

