function nCentralActiveIssuePath(
  config: NCentralApiTokenConfig,
  orgUnitId: number
) {
  return config.activeIssuesPathTemplate.replace(
    "{orgUnitId}",
    String(orgUnitId)
  );
}

async function loadNCentralLiveInventory(
  config: NCentralApiTokenConfig
): Promise<NCentralInventory> {
  const accessToken = await nCentralResolveAccessToken(config);
  const pageQuery = buildNCentralQuery({
    pageNumber: config.pageNumber,
    pageSize: config.pageSize
  });
  const [customersPayload, devicesPayload] = await Promise.all([
    config.includeCustomers
      ? nCentralGetJson(
          config,
          `${config.customerPath}?${pageQuery}`,
          accessToken
        )
      : [],
    config.includeDevices
      ? nCentralGetJson(
          config,
          `${config.devicePath}?${pageQuery}`,
          accessToken
        )
      : []
  ]);
  const customers = nCentralRecordArray(customersPayload).map(
    parseNCentralCustomer
  );
  const devices = nCentralRecordArray(devicesPayload).map(parseNCentralDevice);
  const orgUnitIds =
    config.orgUnitIds.length > 0
      ? config.orgUnitIds
      : customers.map((customer) => customer.id);
  const activeIssuesPayloads =
    config.includeActiveIssues && orgUnitIds.length > 0
      ? await Promise.all(
          orgUnitIds.map(async (orgUnitId) => ({
            orgUnitId,
            payload: await nCentralGetJson(
              config,
              `${nCentralActiveIssuePath(config, orgUnitId)}?${pageQuery}`,
              accessToken
            )
          }))
        )
      : [];

  return {
    activeIssues: activeIssuesPayloads.flatMap(({ orgUnitId, payload }) =>
      nCentralRecordArray(payload).map((row) =>
        parseNCentralActiveIssue(row, orgUnitId)
      )
    ),
    customers,
    devices
  };
}

async function loadNCentralInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadNCentralFixtureInventory();
  }

  return loadNCentralLiveInventory(
    NCentralApiTokenConfigSchema.parse(context.config)
  );
}

function createNCentralAssets(inventory: NCentralInventory) {
  const customerAssets = inventory.customers.map((customer) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Other",
      businessCriticality: "Moderate",
      environment: "mssp-rmm",
      identifiers: {
        parentId: customer.parentId,
        provider: "n-able-ncentral",
        providerId: customer.id,
        type: customer.type
      },
      internetExposed: false,
      name: `ncentral-customer/${customer.name}`,
      owner: "MSSP/RMM",
      status: "Active",
      tags: ["n-able", "ncentral", "mssp-client"]
    })
  );
  const deviceAssets = inventory.devices.map((device) =>
    ConnectorAssetInputSchema.parse({
      assetType: "Host",
      businessCriticality:
        device.deviceClass?.toLowerCase().includes("server") ||
        device.os?.toLowerCase().includes("server")
          ? "High"
          : "Moderate",
      environment: "mssp-rmm",
      identifiers: {
        customerId: device.customerId,
        deviceClass: device.deviceClass,
        orgUnitId: device.orgUnitId,
        provider: "n-able-ncentral",
        providerId: device.id,
        uri: device.uri
      },
      internetExposed: false,
      name: `ncentral-device/${device.name}`,
      owner: device.customerId ? `org-unit-${device.customerId}` : null,
      status: device.online === false ? "Inactive" : "Active",
      tags: ["n-able", "ncentral", device.deviceClass ?? "device"].filter(
        (tag): tag is string => typeof tag === "string" && tag.length > 0
      )
    })
  );

  return [...customerAssets, ...deviceAssets];
}

function createNCentralSignals(inventory: NCentralInventory) {
  const observedAt = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const customer of inventory.customers) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `ncentral://customers/${customer.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "NCentralCustomerObserved",
        sourceType: "ncentral.customer",
        timestampObserved: observedAt
      })
    );
  }

  for (const device of inventory.devices) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `ncentral://devices/${device.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          device.os?.toLowerCase().includes("server") ||
          device.deviceClass?.toLowerCase().includes("server")
            ? "High"
            : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "NCentralDeviceObserved",
        sourceType: "ncentral.device",
        timestampObserved: observedAt
      })
    );

    if (device.online === false) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `ncentral://devices/${device.id}/offline`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "NCentralOfflineDeviceObserved",
          sourceType: "ncentral.device.offline",
          timestampObserved: observedAt
        })
      );
    }
  }

  for (const issue of inventory.activeIssues) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `ncentral://org-units/${issue.orgUnitId}/active-issues/${issue.taskId ?? encodeURIComponent(issue.serviceName)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: /(?:security|endpoint|edr|av|firewall|backup)/iu.test(
          `${issue.serviceName} ${issue.serviceType ?? ""}`
        )
          ? "High"
          : "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "NCentralActiveIssueObserved",
        sourceType: "ncentral.active_issue",
        timestampObserved: observedAt
      })
    );
  }

  return signals;
}

async function getNCentralHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(NCENTRAL_CONNECTOR_MANIFEST, context);
  }

  const config = NCentralApiTokenConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const accessToken = await nCentralResolveAccessToken(config);
    await nCentralGetJson(
      config,
      `${config.devicePath}?${buildNCentralQuery({
        pageNumber: 1,
        pageSize: 1
      })}`,
      accessToken
    );

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "N-central API token verified for read-only customer, device, and active issue context. No scheduled-task, script, patch, reboot, remote-control, credential, user, rule, probe, or agent mutation endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `N-central health check failed: ${error.message}`
          : "N-central health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createNCentralConnector(): Connector {
  return {
    manifest: NCENTRAL_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadNCentralInventory(parsedContext);

      return createNCentralSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getNCentralHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadNCentralInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(NCENTRAL_CONNECTOR_MANIFEST, parsedContext)
        : await getNCentralHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createNCentralAssets(inventory),
        health,
        signals: createNCentralSignals(inventory).map((signal) =>
          createTimestampedSignal(
            NCENTRAL_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

function createSplunkConnector(): Connector {
  return {
    manifest: SPLUNK_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadSplunkFixtureResults(parsedContext.config)
        : await fetchSplunkResults(
            SplunkApiTokenConfigSchema.parse(parsedContext.config),
            parsedContext
          );

      return createSplunkSignals({ results });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(SPLUNK_CONNECTOR_MANIFEST, parsedContext);
      }

      const config = SplunkApiTokenConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();
      let response: Response;

      try {
        response = await connectorFetch(
          splunkApiUrl(config, "/services/server/info?output_mode=json"),
          {
            headers: {
              authorization: `Bearer ${config.token}`
            }
          }
        );
      } catch (error) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail: `Splunk health check failed: ${splunkErrorDetail(error)}`,
          latencyMs: Date.now() - startedAt,
          status: "Unhealthy"
        });
      }

      return ConnectorHealthSchema.parse({
        authorizationVerified: response.ok,
        checkedAt: new Date().toISOString(),
        detail: response.ok
          ? "Splunk API token verified for read-only observer access."
          : `Splunk health check returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        status: response.ok ? "Healthy" : "Unhealthy"
      });
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const startedAt = Date.now();
      const results = parsedContext.mockMode
        ? loadSplunkFixtureResults(parsedContext.config)
        : await fetchSplunkResults(
            SplunkApiTokenConfigSchema.parse(parsedContext.config),
            parsedContext
          );
      const health = parsedContext.mockMode
        ? await this.healthCheck(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Splunk read-only search returned ${results.length} result row(s).`,
            latencyMs: Date.now() - startedAt,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createSplunkSignals({ results }).map((signal) =>
          createTimestampedSignal(
            SPLUNK_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        const outcome = normalizeSplunkOutcome(
          parsedContext.config.fixtureOutcome
        );

        return {
          confidence: outcome === "NoEvidence" ? 0.58 : 0.79,
          correlationMatched:
            typeof parsedContext.config.correlationToken === "string" &&
            parsedContext.config.correlationToken.length > 0 &&
            outcome !== "NoEvidence",
          detail: "Mock Splunk observer verdict.",
          outcome,
          sourceType: "splunk.search.observer"
        };
      }

      return observeSplunkControl(parsedContext);
    }
  };
}

const ElasticSecurityApiKeyConfigSchema = z.object({
  alertIndex: z
    .string()
    .min(1)
    .refine(
      (value) => !value.includes("/"),
      "Elastic Security alert index must not contain path separators."
    )
    .default(".alerts-security.alerts-default"),
  apiKey: z.string().min(1),
  baseUrl: z.url(),
  query: z.string().min(1).optional(),
  size: z.number().int().min(1).max(25).default(1),
  timeWindowHours: z.number().int().min(1).max(168).default(24)
});

type ElasticSecurityApiKeyConfig = z.infer<
  typeof ElasticSecurityApiKeyConfigSchema
>;

const ELASTIC_SECURITY_CONNECTOR_MANIFEST = ConnectorManifestSchema.parse({
  authMethods: [
    {
      description: "Use fixture-backed mock Elastic Security observation data.",
      fields: [],
      kind: "mock",
      label: "Mock",
      mockSupported: true
    },
    {
      description:
        "Use an Elastic API key for read-only Security alert index searches.",
      fields: [
        {
          key: "baseUrl",
          label: "Elastic Base URL",
          required: true,
          secret: false
        },
        {
          key: "apiKey",
          label: "Elastic API Key",
          required: true,
          secret: true
        },
        {
          key: "alertIndex",
          label: "Security Alert Index",
          required: false,
          secret: false
        },
        {
          key: "query",
          label: "Read-Only Alert Query",
          required: false,
          secret: false
        },
        {
          key: "timeWindowHours",
          label: "Time Window Hours",
          required: false,
          secret: false
        },
        {
          key: "size",
          label: "Result Size",
          required: false,
          secret: false
        }
      ],
      kind: "apiToken",
      label: "Elastic API Key",
      mockSupported: false
    }
  ],
  availability: "Beta",
  category: "SecurityControl",
  connectorKey: "elastic-security",
  controlObservationCapabilities: ["Logged", "Alerted", "NoEvidence"],
  customerVisibleDescription:
    "Runs authorized read-only Elastic Security alert searches for logging, alerting, and control-validation evidence.",
  dataSensitivity: "High",
  healthCheckMethod: "Elastic cluster health read plus alert-index search",
  marketplaceCategory: "SIEM",
  mockSupported: true,
  permissionsSummary:
    "Uses an Elastic API key scoped to cluster monitor and read-only Security alert index search. Periscan does not create rules, update alerts, trigger actions, mutate cases, read secrets, or call write APIs.",
  product: "Elastic Security",
  requiredPermissions: [
    "cluster:monitor/health",
    "read on configured Elastic Security alert index"
  ],
  setupComplexity: "Medium",
  signalCategories: ["ControlObservation"],
  supportedMissionTypes: ["ValidationSnapshot", "ControlValidation"],
  validationCapabilities: [
    "Detection evidence lookup",
    "Alert evidence lookup",
    "Control validation observer"
  ],
  vendor: "Elastic",
  workflowCapabilities: []
});

function elasticSecurityBaseUrl(config: ElasticSecurityApiKeyConfig) {
  return config.baseUrl.replace(/\/+$/u, "");
}

function elasticSecurityUrl(
  config: ElasticSecurityApiKeyConfig,
  pathName: string
) {
  return `${elasticSecurityBaseUrl(config)}${pathName}`;
}

function elasticSecurityHeaders(config: ElasticSecurityApiKeyConfig) {
  return {
    accept: "application/json",
    authorization: `ApiKey ${config.apiKey}`,
    "content-type": "application/json"
  };
}

function elasticSecurityErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Elastic Security API error.";
}

function buildElasticSecurityQuery(
  config: ElasticSecurityApiKeyConfig,
  context: ConnectorExecutionContext
) {
  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? context.config.techniqueId.replace(/["'\\;]/gu, "")
      : null;
  const correlationToken =
    typeof context.config.correlationToken === "string" &&
    context.config.correlationToken.length > 0
      ? context.config.correlationToken.replace(/["'\\;]/gu, "")
      : null;
  const query =
    correlationToken ??
    config.query ??
    ["periscan", techniqueId]
      .filter((item): item is string => Boolean(item))
      .join(" ");

  return {
    query: {
      bool: {
        filter: [
          {
            range: {
              "@timestamp": {
                gte: `now-${config.timeWindowHours}h`,
                lte: "now"
              }
            }
          },
          {
            simple_query_string: {
              default_operator: "and",
              fields: [
                "message",
                "event.action",
                "event.kind",
                "event.category",
                "rule.name",
                "kibana.alert.rule.name",
                "threat.technique.id",
                "threat.technique.name"
              ],
              query: query || "periscan"
            }
          }
        ]
      }
    },
    size: config.size,
    sort: [
      {
        "@timestamp": {
          order: "desc"
        }
      }
    ],
    track_total_hits: true
  };
}

function elasticSecurityHasHits(json: Record<string, unknown>) {
  const hits = json.hits;

  if (!hits || typeof hits !== "object" || Array.isArray(hits)) {
    return false;
  }

  const total = (hits as Record<string, unknown>).total;
  const hitRows = (hits as Record<string, unknown>).hits;

  if (Array.isArray(hitRows) && hitRows.length > 0) {
    return true;
  }

  if (typeof total === "number") {
    return total > 0;
  }

  if (total && typeof total === "object" && !Array.isArray(total)) {
    const value = (total as Record<string, unknown>).value;

    return typeof value === "number" && value > 0;
  }

  return false;
}

async function observeElasticSecurityControl(
  context: ConnectorExecutionContext
) {
  const config = ElasticSecurityApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const response = await connectorFetch(
      elasticSecurityUrl(config, `/${config.alertIndex}/_search`),
      {
        body: JSON.stringify(buildElasticSecurityQuery(config, context)),
        headers: elasticSecurityHeaders(config),
        method: "POST"
      }
    );

    if (!response.ok) {
      return {
        confidence: 0.4,
        detail: `Elastic Security alert search returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        outcome: "NoEvidence",
        sourceType: "elastic_security.alerts.observer"
      };
    }

    const json = (await response.json().catch(() => ({}))) as Record<
      string,
      unknown
    >;
    const hasHits = elasticSecurityHasHits(json);

    const exactCorrelationRequested =
      typeof context.config.correlationToken === "string" &&
      context.config.correlationToken.length > 0;

    return {
      confidence: hasHits ? 0.82 : 0.62,
      correlationMatched: exactCorrelationRequested && hasHits,
      detail: hasHits
        ? "Elastic Security alert search returned alert evidence for the validation context."
        : "Elastic Security alert search completed but returned no matching alert evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasHits ? "Alerted" : "NoEvidence",
      sourceType: "elastic_security.alerts.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Elastic Security alert search failed: ${elasticSecurityErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "elastic_security.alerts.observer"
    };
  }
}

function createElasticSecurityConnector(): Connector {
  return {
    manifest: ELASTIC_SECURITY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return [
        createMockPlaceholderControlObservation(
          contextTechniqueIds(parsedContext)
        )
      ].map((signal) => ConnectorSignalInputSchema.parse(signal));
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(
          ELASTIC_SECURITY_CONNECTOR_MANIFEST,
          parsedContext
        );
      }

      const config = ElasticSecurityApiKeyConfigSchema.parse(
        parsedContext.config
      );
      const startedAt = Date.now();

      try {
        const response = await connectorFetch(
          elasticSecurityUrl(config, "/_cluster/health"),
          {
            headers: elasticSecurityHeaders(config),
            method: "GET"
          }
        );

        return ConnectorHealthSchema.parse({
          authorizationVerified: response.ok,
          checkedAt: new Date().toISOString(),
          detail: response.ok
            ? "Elastic Security API key verified for read-only observer access."
            : `Elastic Security health check returned status ${response.status}.`,
          latencyMs: Date.now() - startedAt,
          status: response.ok ? "Healthy" : "Unhealthy"
        });
      } catch (error) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail: `Elastic Security health check failed: ${elasticSecurityErrorDetail(
            error
          )}`,
          latencyMs: Date.now() - startedAt,
          status: "Unhealthy"
        });
      }
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            ELASTIC_SECURITY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        const outcome = normalizeElasticSecurityOutcome(
          parsedContext.config.fixtureOutcome
        );

        return {
          confidence: outcome === "NoEvidence" ? 0.58 : 0.79,
          correlationMatched:
            typeof parsedContext.config.correlationToken === "string" &&
            parsedContext.config.correlationToken.length > 0 &&
            outcome !== "NoEvidence",
          detail: "Mock Elastic Security observer verdict.",
          outcome,
          sourceType: "elastic_security.alerts.observer"
        };
      }

      return observeElasticSecurityControl(parsedContext);
    }
  };
}

