function datadogSiemBaseUrl(config: DatadogSiemApiKeyConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function datadogSiemUrl(config: DatadogSiemApiKeyConfig, pathName: string) {
  return `${datadogSiemBaseUrl(config)}${pathName}`;
}

function datadogSiemHeaders(config: DatadogSiemApiKeyConfig) {
  return {
    accept: "application/json",
    "content-type": "application/json",
    "DD-API-KEY": config.apiKey,
    "DD-APPLICATION-KEY": config.applicationKey
  };
}

function datadogSiemErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Datadog Cloud SIEM API error.";
}

function buildDatadogSiemQuery(
  config: DatadogSiemApiKeyConfig,
  context: ConnectorExecutionContext
) {
  if (config.query) {
    return config.query;
  }

  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? context.config.techniqueId.replace(/["'\\;]/gu, "")
      : null;

  return ["periscan", techniqueId]
    .filter((item): item is string => Boolean(item))
    .join(" ");
}

function datadogSiemSearchWindow(config: DatadogSiemApiKeyConfig) {
  const now = new Date();

  return {
    from:
      config.from ??
      new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(),
    to: config.to ?? now.toISOString()
  };
}

function datadogSiemSignalsHaveRows(json: Record<string, unknown>) {
  if (Array.isArray(json.data) && json.data.length > 0) {
    return true;
  }

  const meta = json.meta;

  if (!meta || typeof meta !== "object" || Array.isArray(meta)) {
    return false;
  }

  const page = (meta as Record<string, unknown>).page;

  if (!page || typeof page !== "object" || Array.isArray(page)) {
    return false;
  }

  const totalCount = (page as Record<string, unknown>).total_count;

  return typeof totalCount === "number" && totalCount > 0;
}

async function observeDatadogSiemControl(context: ConnectorExecutionContext) {
  const config = DatadogSiemApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();
  const window = datadogSiemSearchWindow(config);

  try {
    const response = await connectorFetch(
      datadogSiemUrl(config, "/api/v2/security_monitoring/signals/search"),
      {
        body: JSON.stringify({
          filter: {
            from: window.from,
            query: buildDatadogSiemQuery(config, context),
            to: window.to
          },
          page: {
            limit: config.limit
          },
          sort: "-timestamp"
        }),
        headers: datadogSiemHeaders(config),
        method: "POST"
      }
    );

    if (!response.ok) {
      return {
        confidence: 0.4,
        detail: `Datadog Cloud SIEM signal search returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        outcome: "NoEvidence",
        sourceType: "datadog_siem.security_signals.observer"
      };
    }

    const json = (await response.json().catch(() => ({}))) as Record<
      string,
      unknown
    >;
    const hasSignals = datadogSiemSignalsHaveRows(json);

    return {
      confidence: hasSignals ? 0.82 : 0.62,
      detail: hasSignals
        ? "Datadog Cloud SIEM signal search returned security-signal evidence for the validation context."
        : "Datadog Cloud SIEM signal search completed but returned no matching security-signal evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasSignals ? "Alerted" : "NoEvidence",
      sourceType: "datadog_siem.security_signals.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Datadog Cloud SIEM signal search failed: ${datadogSiemErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "datadog_siem.security_signals.observer"
    };
  }
}

function createDatadogSiemConnector(): Connector {
  return {
    manifest: DATADOG_SIEM_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return [
        createMockPlaceholderControlObservation(
          contextTechniqueIds(parsedContext)
        )
      ].map((signal) => ConnectorSignalInputSchema.parse(signal));
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(DATADOG_SIEM_CONNECTOR_MANIFEST, parsedContext);
      }

      const config = DatadogSiemApiKeyConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();

      try {
        const response = await connectorFetch(
          datadogSiemUrl(config, "/api/v1/validate"),
          {
            headers: datadogSiemHeaders(config),
            method: "GET"
          }
        );

        return ConnectorHealthSchema.parse({
          authorizationVerified: response.ok,
          checkedAt: new Date().toISOString(),
          detail: response.ok
            ? "Datadog API key accepted; application key is validated during read-only observer searches."
            : `Datadog health check returned status ${response.status}.`,
          latencyMs: Date.now() - startedAt,
          status: response.ok ? "Healthy" : "Unhealthy"
        });
      } catch (error) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail: `Datadog health check failed: ${datadogSiemErrorDetail(
            error
          )}`,
          latencyMs: Date.now() - startedAt,
          status: "Unhealthy"
        });
      }
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            DATADOG_SIEM_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        const outcome = normalizeDatadogSiemOutcome(
          parsedContext.config.fixtureOutcome
        );

        return {
          confidence: outcome === "NoEvidence" ? 0.58 : 0.79,
          detail: "Mock Datadog Cloud SIEM observer verdict.",
          outcome,
          sourceType: "datadog_siem.security_signals.observer"
        };
      }

      return observeDatadogSiemControl(parsedContext);
    }
  };
}

