function googleChronicleBaseUrl(config: GoogleChronicleAccessTokenConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function googleChronicleUrl(
  config: GoogleChronicleAccessTokenConfig,
  pathName: string
) {
  return `${googleChronicleBaseUrl(config)}${pathName}`;
}

function googleChronicleHeaders(config: GoogleChronicleAccessTokenConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.accessToken}`
  };
}

function googleChronicleErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Google SecOps API error.";
}

function googleChronicleSearchWindow(config: GoogleChronicleAccessTokenConfig) {
  const now = new Date();

  return {
    from:
      config.from ??
      new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(),
    to: config.to ?? now.toISOString()
  };
}

function googleChronicleEscapeRegexLiteral(value: string) {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

function buildGoogleChronicleQuery(
  config: GoogleChronicleAccessTokenConfig,
  context: ConnectorExecutionContext
) {
  if (config.query) {
    return config.query;
  }

  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? context.config.techniqueId.replace(/["'\\;]/gu, "")
      : null;

  if (!techniqueId) {
    return 'metadata.event_type != ""';
  }

  const escapedTechniqueId = googleChronicleEscapeRegexLiteral(techniqueId);

  return [
    'metadata.event_type != ""',
    "AND",
    "(",
    `metadata.description = /${escapedTechniqueId}/ nocase`,
    "OR",
    `security_result.rule_name = /${escapedTechniqueId}/ nocase`,
    ")"
  ].join(" ");
}

function googleChronicleSearchUrl(
  config: GoogleChronicleAccessTokenConfig,
  context: ConnectorExecutionContext
) {
  const window = googleChronicleSearchWindow(config);
  const instance = config.instance.replace(/^\/+/u, "");
  const url = new URL(
    googleChronicleUrl(config, `/v1alpha/${instance}:udmSearch`)
  );

  url.searchParams.set("query", buildGoogleChronicleQuery(config, context));
  url.searchParams.set("timeRange.startTime", window.from);
  url.searchParams.set("timeRange.endTime", window.to);
  url.searchParams.set("limit", String(config.limit));
  url.searchParams.set("queryDialect", config.queryDialect);

  return url.toString();
}

function googleChronicleHasEvents(json: Record<string, unknown>) {
  if (Array.isArray(json.events) && json.events.length > 0) {
    return true;
  }

  const stats = json.stats;

  if (!stats || typeof stats !== "object" || Array.isArray(stats)) {
    return false;
  }

  const results = (stats as Record<string, unknown>).results;

  return Array.isArray(results) && results.length > 0;
}

async function observeGoogleChronicleControl(
  context: ConnectorExecutionContext
) {
  const config = GoogleChronicleAccessTokenConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const response = await connectorFetch(
      googleChronicleSearchUrl(config, context),
      {
        headers: googleChronicleHeaders(config),
        method: "GET"
      }
    );

    if (!response.ok) {
      return {
        confidence: 0.4,
        detail: `Google SecOps UDM search returned status ${response.status}.`,
        latencyMs: Date.now() - startedAt,
        outcome: "NoEvidence",
        sourceType: "google_secops.udm_search.observer"
      };
    }

    const json = (await response.json().catch(() => ({}))) as Record<
      string,
      unknown
    >;
    const hasEvents = googleChronicleHasEvents(json);

    return {
      confidence: hasEvents ? 0.82 : 0.62,
      detail: hasEvents
        ? "Google SecOps UDM search returned event evidence for the validation context."
        : "Google SecOps UDM search completed but returned no matching event evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasEvents ? "Logged" : "NoEvidence",
      sourceType: "google_secops.udm_search.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Google SecOps UDM search failed: ${googleChronicleErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "google_secops.udm_search.observer"
    };
  }
}

