function sumoLogicAuthorizationHeader(config: SumoLogicAccessKeyConfig) {
  return `Basic ${Buffer.from(
    `${config.accessId}:${config.accessKey}`
  ).toString("base64")}`;
}

function sumoLogicHeaders(config: SumoLogicAccessKeyConfig) {
  return {
    accept: "application/json",
    authorization: sumoLogicAuthorizationHeader(config),
    "content-type": "application/json"
  };
}

function sumoLogicErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Sumo Logic API error.";
}

function sumoLogicSearchWindow(config: SumoLogicAccessKeyConfig) {
  const now = new Date();

  return {
    from:
      config.from ??
      new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(),
    to: config.to ?? now.toISOString()
  };
}

function sumoLogicEscapeTerm(value: string) {
  return value.replace(/["\\]/gu, "");
}

function buildSumoLogicQuery(
  config: SumoLogicAccessKeyConfig,
  context: ConnectorExecutionContext
) {
  if (config.query) {
    return config.query;
  }

  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? sumoLogicEscapeTerm(context.config.techniqueId)
      : null;
  const terms = ["periscan", techniqueId].filter((item): item is string =>
    Boolean(item)
  );

  return `${terms.map((term) => `"${term}"`).join(" OR ")} | limit 1`;
}

async function readSumoLogicJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function sleep(milliseconds: number) {
  if (milliseconds <= 0) {
    return;
  }

  await new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
}

function sumoLogicHasMessages(json: Record<string, unknown>) {
  if (Array.isArray(json.messages) && json.messages.length > 0) {
    return true;
  }

  if (Array.isArray(json.records) && json.records.length > 0) {
    return true;
  }

  const messageCount = json.messageCount ?? json.message_count;

  return typeof messageCount === "number" && messageCount > 0;
}

function sumoLogicSearchDone(json: Record<string, unknown>) {
  const state = json.state;

  return (
    typeof state === "string" &&
    (state.toUpperCase() === "DONE GATHERING RESULTS" ||
      state.toUpperCase() === "DONE")
  );
}

async function createSumoLogicSearchJob(
  config: SumoLogicAccessKeyConfig,
  context: ConnectorExecutionContext
) {
  const window = sumoLogicSearchWindow(config);
  const response = await connectorFetch(
    sumoLogicUrl(config, "/api/v1/search/jobs"),
    {
      body: JSON.stringify({
        from: window.from,
        query: buildSumoLogicQuery(config, context),
        timeZone: config.timeZone,
        to: window.to
      }),
      headers: sumoLogicHeaders(config),
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Sumo Logic search job returned status ${response.status}.`
    );
  }

  const json = await readSumoLogicJson(response);
  const parsed = z
    .object({
      id: z.string().min(1)
    })
    .or(
      z.object({
        searchJobId: z.string().min(1)
      })
    )
    .parse(json);

  return "id" in parsed ? parsed.id : parsed.searchJobId;
}

async function waitForSumoLogicSearchJob(
  config: SumoLogicAccessKeyConfig,
  searchJobId: string
) {
  for (let attempt = 0; attempt < config.maxStatusPolls; attempt += 1) {
    const response = await connectorFetch(
      sumoLogicUrl(
        config,
        `/api/v1/search/jobs/${encodeURIComponent(searchJobId)}`
      ),
      {
        headers: sumoLogicHeaders(config),
        method: "GET"
      }
    );

    if (!response.ok) {
      throw new Error(
        `Sumo Logic search status returned status ${response.status}.`
      );
    }

    const json = await readSumoLogicJson(response);

    if (sumoLogicSearchDone(json) || sumoLogicHasMessages(json)) {
      return;
    }

    await sleep(config.statusPollMs);
  }
}

async function fetchSumoLogicSearchMessages(
  config: SumoLogicAccessKeyConfig,
  searchJobId: string
) {
  const response = await connectorFetch(
    sumoLogicUrl(
      config,
      `/api/v1/search/jobs/${encodeURIComponent(
        searchJobId
      )}/messages?offset=0&limit=${config.limit}`
    ),
    {
      headers: sumoLogicHeaders(config),
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Sumo Logic search messages returned status ${response.status}.`
    );
  }

  return readSumoLogicJson(response);
}

async function observeSumoLogicControl(context: ConnectorExecutionContext) {
  const config = SumoLogicAccessKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const searchJobId = await createSumoLogicSearchJob(config, context);

    await waitForSumoLogicSearchJob(config, searchJobId);

    const messages = await fetchSumoLogicSearchMessages(config, searchJobId);
    const hasMessages = sumoLogicHasMessages(messages);

    return {
      confidence: hasMessages ? 0.82 : 0.62,
      detail: hasMessages
        ? "Sumo Logic Search Job returned message evidence for the validation context."
        : "Sumo Logic Search Job completed but returned no matching message evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasMessages ? "Logged" : "NoEvidence",
      sourceType: "sumo_logic.search_job.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Sumo Logic Search Job failed: ${sumoLogicErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "sumo_logic.search_job.observer"
    };
  }
}

function createSumoLogicConnector(): Connector {
  return {
    manifest: SUMO_LOGIC_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return [
        createMockPlaceholderControlObservation(
          contextTechniqueIds(parsedContext)
        )
      ].map((signal) => ConnectorSignalInputSchema.parse(signal));
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        return createMockHealth(SUMO_LOGIC_CONNECTOR_MANIFEST, parsedContext);
      }

      const config = SumoLogicAccessKeyConfigSchema.parse(parsedContext.config);
      const startedAt = Date.now();

      try {
        await createSumoLogicSearchJob(
          {
            ...config,
            limit: 1,
            query: config.query ?? "_sourceCategory=* | limit 1"
          },
          parsedContext
        );

        return ConnectorHealthSchema.parse({
          authorizationVerified: true,
          checkedAt: new Date().toISOString(),
          detail:
            "Sumo Logic Search Job access verified for read-only observer use.",
          latencyMs: Date.now() - startedAt,
          status: "Healthy"
        });
      } catch (error) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail: `Sumo Logic health check failed: ${sumoLogicErrorDetail(
            error
          )}`,
          latencyMs: Date.now() - startedAt,
          status: "Unhealthy"
        });
      }
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const health = await this.healthCheck(parsedContext);
      const rawSignals = parsedContext.mockMode
        ? await this.collectSignals(parsedContext)
        : [];

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: rawSignals.map((signal) =>
          createTimestampedSignal(
            SUMO_LOGIC_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      if (parsedContext.mockMode) {
        const outcome = normalizeSumoLogicOutcome(
          parsedContext.config.fixtureOutcome
        );

        return {
          confidence: outcome === "NoEvidence" ? 0.58 : 0.79,
          detail: "Mock Sumo Logic observer verdict.",
          outcome,
          sourceType: "sumo_logic.search_job.observer"
        };
      }

      return observeSumoLogicControl(parsedContext);
    }
  };
}

