function rapid7InsightIdrBaseUrl(config: Rapid7InsightIdrApiKeyConfig) {
  return config.apiBaseUrl.replace(/\/+$/u, "");
}

function rapid7InsightIdrHeaders(config: Rapid7InsightIdrApiKeyConfig) {
  return {
    accept: "application/json",
    "x-api-key": config.apiKey
  };
}

function rapid7InsightIdrErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Rapid7 InsightIDR API error.";
}

function rapid7InsightIdrTime(
  value: Rapid7InsightIdrApiKeyConfig["from"],
  fallback: Date
) {
  if (typeof value === "number") {
    return String(value);
  }

  if (typeof value === "string") {
    const parsed = Date.parse(value);

    if (Number.isFinite(parsed)) {
      return String(parsed);
    }

    return value;
  }

  return String(fallback.getTime());
}

function rapid7InsightIdrSearchWindow(config: Rapid7InsightIdrApiKeyConfig) {
  const now = new Date();

  return {
    from: rapid7InsightIdrTime(
      config.from,
      new Date(now.getTime() - 24 * 60 * 60 * 1000)
    ),
    to: rapid7InsightIdrTime(config.to, now)
  };
}

function rapid7InsightIdrEscapeTerm(value: string) {
  return value.replace(/["/\\]/gu, "");
}

function buildRapid7InsightIdrQuery(
  config: Rapid7InsightIdrApiKeyConfig,
  context: ConnectorExecutionContext
) {
  if (config.query) {
    return config.query;
  }

  const techniqueId =
    typeof context.config.techniqueId === "string" &&
    context.config.techniqueId.length > 0
      ? rapid7InsightIdrEscapeTerm(context.config.techniqueId)
      : null;
  const terms = ["periscan", techniqueId].filter((item): item is string =>
    Boolean(item)
  );

  return `where(${terms.map((term) => `/${term}/`).join(" OR ")})`;
}

function rapid7InsightIdrSearchUrl(
  config: Rapid7InsightIdrApiKeyConfig,
  context: ConnectorExecutionContext
) {
  const window = rapid7InsightIdrSearchWindow(config);
  const url = new URL(`${rapid7InsightIdrBaseUrl(config)}/query/logsets`);

  url.searchParams.set("query", buildRapid7InsightIdrQuery(config, context));
  url.searchParams.set("from", window.from);
  url.searchParams.set("to", window.to);
  url.searchParams.set("per_page", String(config.perPage));

  for (const logsetName of config.logsetNames) {
    url.searchParams.append("logset_name", logsetName);
  }

  for (const label of config.labels) {
    url.searchParams.append("label", label);
  }

  return url.toString();
}

async function readRapid7InsightIdrJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function rapid7InsightIdrArrayHasEvents(value: unknown) {
  return Array.isArray(value) && value.length > 0;
}

function rapid7InsightIdrNumericCount(value: unknown) {
  return typeof value === "number" && value > 0;
}

function rapid7InsightIdrHasEvents(json: Record<string, unknown>) {
  if (
    rapid7InsightIdrArrayHasEvents(json.events) ||
    rapid7InsightIdrArrayHasEvents(json.logs) ||
    rapid7InsightIdrArrayHasEvents(json.results) ||
    rapid7InsightIdrArrayHasEvents(json.messages)
  ) {
    return true;
  }

  const data = json.data;

  if (
    data &&
    typeof data === "object" &&
    (rapid7InsightIdrArrayHasEvents((data as Record<string, unknown>).events) ||
      rapid7InsightIdrArrayHasEvents((data as Record<string, unknown>).results))
  ) {
    return true;
  }

  const metadata = json.metadata;
  const statistics = json.statistics;

  return (
    rapid7InsightIdrNumericCount(json.total) ||
    rapid7InsightIdrNumericCount(json.count) ||
    (metadata !== null &&
      typeof metadata === "object" &&
      (rapid7InsightIdrNumericCount(
        (metadata as Record<string, unknown>).total
      ) ||
        rapid7InsightIdrNumericCount(
          (metadata as Record<string, unknown>).total_count
        ))) ||
    (statistics !== null &&
      typeof statistics === "object" &&
      rapid7InsightIdrNumericCount(
        (statistics as Record<string, unknown>).eventsMatched
      ))
  );
}

async function observeRapid7InsightIdrControl(
  context: ConnectorExecutionContext
) {
  const config = Rapid7InsightIdrApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const response = await connectorFetch(
      rapid7InsightIdrSearchUrl(config, context),
      {
        headers: rapid7InsightIdrHeaders(config),
        method: "GET"
      }
    );

    if (!response.ok) {
      throw new Error(
        `Rapid7 InsightIDR Log Search returned status ${response.status}.`
      );
    }

    const json = await readRapid7InsightIdrJson(response);
    const hasEvents = rapid7InsightIdrHasEvents(json);

    return {
      confidence: hasEvents ? 0.8 : 0.6,
      detail: hasEvents
        ? "Rapid7 InsightIDR Log Search returned event evidence for the validation context."
        : "Rapid7 InsightIDR Log Search completed but returned no matching event evidence.",
      latencyMs: Date.now() - startedAt,
      outcome: hasEvents ? "Logged" : "NoEvidence",
      sourceType: "rapid7_insightidr.log_search.observer"
    };
  } catch (error) {
    return {
      confidence: 0.35,
      detail: `Rapid7 InsightIDR Log Search failed: ${rapid7InsightIdrErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      outcome: "NoEvidence",
      sourceType: "rapid7_insightidr.log_search.observer"
    };
  }
}

