function createPaloAltoXsiamConnector(): Connector {
  const loadIncidents = async (context: ConnectorExecutionContext) =>
    context.mockMode
      ? loadPaloAltoCortexXdrFixtureIncidents(context.config)
      : fetchPaloAltoCortexXdrIncidents(
          PaloAltoCortexXdrApiKeyConfigSchema.parse(context.config),
          "Cortex XSIAM"
        );

  return {
    manifest: PALO_ALTO_XSIAM_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      return createPaloAltoXsiamSignals({
        incidents: await loadIncidents(parsedContext)
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      if (parsedContext.mockMode) {
        return createMockHealth(
          PALO_ALTO_XSIAM_CONNECTOR_MANIFEST,
          parsedContext
        );
      }
      const startedAt = Date.now();
      const incidents = await fetchPaloAltoCortexXdrIncidents(
        {
          ...PaloAltoCortexXdrApiKeyConfigSchema.parse(parsedContext.config),
          limit: 1
        },
        "Cortex XSIAM"
      );
      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail: `Cortex XSIAM incident read access verified; ${incidents.length} sample incident record(s) accessible.`,
        latencyMs: Date.now() - startedAt,
        status: "Healthy"
      });
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const result = await observePaloAltoCortexXdrControl(parsedContext);
      return {
        ...result,
        detail: result.detail.replaceAll("Cortex XDR", "Cortex XSIAM"),
        sourceType: result.sourceType.replaceAll(
          "palo_alto_cortex_xdr",
          "palo_alto_cortex_xsiam"
        )
      };
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const startedAt = Date.now();
      const incidents = await loadIncidents(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(PALO_ALTO_XSIAM_CONNECTOR_MANIFEST, parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Cortex XSIAM incident read-only sync returned ${incidents.length} incident record(s).`,
            latencyMs: Date.now() - startedAt,
            status: "Healthy"
          });
      return ConnectorSyncResultSchema.parse({
        assets: createPaloAltoXsiamAssets(),
        health,
        signals: createPaloAltoXsiamSignals({ incidents }).map((signal) =>
          createTimestampedSignal(
            PALO_ALTO_XSIAM_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

