function azureBaseUrl(value: string) {
  return value.replace(/\/+$/u, "");
}

function azureTokenUrl(config: AzureClientCredentialConfig) {
  return `${azureBaseUrl(config.loginUrl)}/${encodeURIComponent(
    config.tenantId
  )}/oauth2/v2.0/token`;
}

function azureScope(config: AzureClientCredentialConfig) {
  return `${azureBaseUrl(config.managementBaseUrl)}/.default`;
}

function azureManagementUrl(
  config: AzureClientCredentialConfig,
  pathName: string
) {
  return `${azureBaseUrl(config.managementBaseUrl)}${pathName}`;
}

function azureErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Azure API error.";
}

async function readAzureJson(response: Response) {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function getAzureAccessToken(config: AzureClientCredentialConfig) {
  const response = await connectorFetch(azureTokenUrl(config), {
    body: new URLSearchParams({
      client_id: config.clientId,
      client_secret: config.clientSecret,
      grant_type: "client_credentials",
      scope: azureScope(config)
    }),
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(
      `Azure identity token request returned status ${response.status}.`
    );
  }

  const json = await readAzureJson(response);
  const parsed = z
    .object({
      access_token: z.string().min(1)
    })
    .passthrough()
    .parse(json);

  return parsed.access_token;
}

function azureFetchHeaders(accessToken: string) {
  return {
    authorization: `Bearer ${accessToken}`
  };
}

async function azureFetchJson(
  config: AzureClientCredentialConfig,
  accessToken: string,
  pathName: string
) {
  const response = await connectorFetch(azureManagementUrl(config, pathName), {
    headers: azureFetchHeaders(accessToken)
  });

  if (!response.ok) {
    throw new Error(
      `Azure Resource Manager returned status ${response.status}.`
    );
  }

  return readAzureJson(response);
}

function azureString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function azureTags(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).filter(
      (entry): entry is [string, string] => typeof entry[1] === "string"
    )
  );
}

function parseAzureSubscriptions(json: Record<string, unknown>) {
  const values = Array.isArray(json.value) ? json.value : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) =>
      AzureSubscriptionSchema.parse({
        displayName: azureString(item.displayName, "Azure subscription"),
        state: azureString(item.state, "Unknown"),
        subscriptionId: azureString(item.subscriptionId, "unknown-subscription")
      })
    )
    .filter(
      (subscription) => subscription.subscriptionId !== "unknown-subscription"
    );
}

function subscriptionIdFromResourceId(resourceId: string) {
  const match = /\/subscriptions\/([^/]+)/iu.exec(resourceId);

  return match?.[1] ?? "unknown-subscription";
}

function parseAzureResources(
  json: Record<string, unknown>,
  fallbackSubscriptionId: string
) {
  const values = Array.isArray(json.value) ? json.value : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => {
      const id = azureString(item.id, "unknown-resource");
      const type = azureString(item.type, "unknown");

      return AzureResourceSchema.parse({
        id,
        location: typeof item.location === "string" ? item.location : null,
        name: azureString(item.name, id),
        publicExposure:
          /publicipaddresses|frontdoors|applicationgateways/iu.test(type),
        subscriptionId:
          subscriptionIdFromResourceId(id) === "unknown-subscription"
            ? fallbackSubscriptionId
            : subscriptionIdFromResourceId(id),
        tags: azureTags(item.tags),
        type
      });
    })
    .filter((resource) => resource.id !== "unknown-resource");
}

function parseAzurePortValue(value: unknown): number[] {
  if (typeof value !== "string") {
    return [];
  }

  if (value === "*") {
    return [0];
  }

  const first = value.split("-")[0];
  const port = Number.parseInt(first ?? "", 10);

  return Number.isFinite(port) ? [port] : [];
}

function azureRuleAllowsInternet(rule: Record<string, unknown>) {
  const properties =
    rule.properties && typeof rule.properties === "object"
      ? (rule.properties as Record<string, unknown>)
      : {};
  const sourcePrefixes = [
    properties.sourceAddressPrefix,
    ...(Array.isArray(properties.sourceAddressPrefixes)
      ? properties.sourceAddressPrefixes
      : [])
  ];
  const destinationPorts = [
    properties.destinationPortRange,
    ...(Array.isArray(properties.destinationPortRanges)
      ? properties.destinationPortRanges
      : [])
  ];
  const sourceIsInternet = sourcePrefixes.some(
    (prefix) =>
      typeof prefix === "string" &&
      ["*", "internet", "0.0.0.0/0", "::/0"].includes(prefix.toLowerCase())
  );
  const direction = azureString(properties.direction, "Inbound");
  const access = azureString(properties.access, "Deny");

  return {
    allowed:
      sourceIsInternet &&
      direction.toLowerCase() === "inbound" &&
      access.toLowerCase() === "allow",
    ports: destinationPorts.flatMap(parseAzurePortValue)
  };
}

function parseAzureNetworkSecurityGroups(
  json: Record<string, unknown>,
  fallbackSubscriptionId: string
) {
  const values = Array.isArray(json.value) ? json.value : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => {
      const id = azureString(item.id, "unknown-nsg");
      const properties =
        item.properties && typeof item.properties === "object"
          ? (item.properties as Record<string, unknown>)
          : {};
      const rules = [
        ...(Array.isArray(properties.securityRules)
          ? properties.securityRules
          : []),
        ...(Array.isArray(properties.defaultSecurityRules)
          ? properties.defaultSecurityRules
          : [])
      ].filter(
        (rule): rule is Record<string, unknown> =>
          Boolean(rule) && typeof rule === "object"
      );
      const allowedRules = rules.map(azureRuleAllowsInternet);
      const ports = allowedRules
        .flatMap((rule) => (rule.allowed ? rule.ports : []))
        .filter((port, index, values) => values.indexOf(port) === index)
        .sort((left, right) => left - right);

      return AzureNetworkSecurityGroupSchema.parse({
        id,
        location: typeof item.location === "string" ? item.location : null,
        name: azureString(item.name, id),
        openToInternet: allowedRules.some((rule) => rule.allowed),
        ports,
        subscriptionId:
          subscriptionIdFromResourceId(id) === "unknown-subscription"
            ? fallbackSubscriptionId
            : subscriptionIdFromResourceId(id)
      });
    })
    .filter((group) => group.id !== "unknown-nsg");
}

async function azureFetchPagedValues(
  config: AzureClientCredentialConfig,
  accessToken: string,
  pathName: string
) {
  let nextPath: string | null = pathName;
  const values: unknown[] = [];
  const managementBaseUrl = azureBaseUrl(config.managementBaseUrl);

  while (nextPath) {
    const page = await azureFetchJson(config, accessToken, nextPath);

    if (Array.isArray(page.value)) {
      values.push(...page.value);
    }

    const nextLink = typeof page.nextLink === "string" ? page.nextLink : null;

    if (!nextLink) {
      break;
    }

    nextPath = nextLink.startsWith(managementBaseUrl)
      ? nextLink.slice(managementBaseUrl.length)
      : nextLink;
  }

  return { value: values };
}

