async function loadRealGcpInventory(
  context: ConnectorExecutionContext
): Promise<GcpInventory> {
  const config = GcpAccessTokenConfigSchema.parse(context.config);
  const projects = config.projectIds?.length
    ? config.projectIds.map((projectId) =>
        GcpProjectSchema.parse({
          displayName: projectId,
          projectId,
          state: "CONFIGURED"
        })
      )
    : parseGcpProjectsFromValues(
        await gcpFetchPagedArray(
          config,
          config.crmBaseUrl,
          "/v1/projects?pageSize=100",
          "projects"
        )
      );
  const projectIds = projects.map((project) => project.projectId);
  const resources: z.infer<typeof GcpResourceSchema>[] = [];
  const firewallRules: z.infer<typeof GcpFirewallRuleSchema>[] = [];

  for (const projectId of projectIds) {
    const parsed = parseGcpAssets(
      projectId,
      await gcpFetchPagedArray(
        config,
        config.assetBaseUrl,
        gcpAssetListPath(projectId, config),
        "assets"
      )
    );

    resources.push(...parsed.resources);
    firewallRules.push(...parsed.firewallRules);
  }

  return GcpInventorySchema.parse({
    firewallRules,
    projects,
    resources
  });
}

async function getGcpHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GCP_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();

  try {
    const inventory = await loadRealGcpInventory(context);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Google Cloud read-only sync can access ${inventory.projects.length} project(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Google Cloud read-only sync failed: ${gcpErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Degraded"
    });
  }
}

function createGcpAssets(inventory: GcpInventory): ConnectorAssetInput[] {
  const assets: ConnectorAssetInput[] = [];

  for (const project of inventory.projects) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: "High",
        environment: "Cloud",
        identifiers: {
          provider: "gcp",
          projectId: project.projectId,
          state: project.state
        },
        internetExposed: false,
        name: project.displayName,
        owner: "Google Cloud",
        status: "Active",
        tags: ["gcp", "project"]
      })
    );
  }

  for (const resource of inventory.resources) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: resource.publicExposure ? "High" : "Moderate",
        environment: resource.location ?? "Cloud",
        identifiers: {
          assetType: resource.assetType,
          provider: "gcp",
          projectId: resource.projectId
        },
        internetExposed: resource.publicExposure,
        name: resource.name,
        owner: "Google Cloud",
        status: "Active",
        tags: [
          "gcp",
          resource.assetType,
          ...Object.entries(resource.tags).map(
            ([key, value]) => `${key}:${value}`
          )
        ]
      })
    );
  }

  return assets;
}

function createGcpSignals(inventory: GcpInventory): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const project of inventory.projects) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.91,
        freshness: "Fresh",
        rawPayloadPointer: `gcp://projects/${project.projectId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "CloudAccount",
        sourceType: "gcp.cloudresourcemanager.project",
        timestampObserved
      })
    );
  }

  for (const resource of inventory.resources) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `gcp://projects/${resource.projectId}/${resource.assetType}/${resource.name}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: resource.publicExposure ? "High" : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "CloudAsset",
        sourceType: "gcp.cloudasset.resource",
        timestampObserved
      })
    );

    if (resource.publicExposure) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.88,
          freshness: "Fresh",
          rawPayloadPointer: `gcp://projects/${resource.projectId}/${resource.assetType}/${resource.name}/public-exposure`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Cloud",
          signalSubcategory: "PublicExposure",
          sourceType: "gcp.cloudasset.public_exposure",
          timestampObserved
        })
      );
    }
  }

  for (const firewall of inventory.firewallRules) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `gcp://projects/${firewall.projectId}/firewalls/${firewall.name}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: firewall.openToInternet ? "High" : "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "SecurityGroup",
        sourceType: "gcp.compute.firewall",
        timestampObserved
      })
    );

    if (firewall.openToInternet) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.88,
          freshness: "Fresh",
          rawPayloadPointer: `gcp://projects/${firewall.projectId}/firewalls/${firewall.name}/internet-open`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Cloud",
          signalSubcategory: "PublicExposure",
          sourceType: "gcp.compute.firewall_public_exposure",
          timestampObserved
        })
      );
    }
  }

  return signals;
}

async function syncGcpInventory(context: ConnectorExecutionContext) {
  const inventory = context.mockMode
    ? await loadGcpFixtureInventory(context.config)
    : await loadRealGcpInventory(context);
  const health = await getGcpHealth(context);

  return ConnectorSyncResultSchema.parse({
    assets: createGcpAssets(inventory),
    health,
    signals: createGcpSignals(inventory).map((signal) =>
      createTimestampedSignal(GCP_CONNECTOR_MANIFEST, context, signal)
    )
  });
}

function createGcpConnector(): Connector {
  return {
    manifest: GCP_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? await loadGcpFixtureInventory(parsedContext.config)
        : await loadRealGcpInventory(parsedContext);

      return createGcpSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGcpHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return syncGcpInventory(parsedContext);
    }
  };
}

