function azureFrontDoorWafOptionsFromConfig(config: Record<string, unknown>) {
  return AzureFrontDoorWafOptionsSchema.parse(config);
}

function parseAzureFrontDoorWafPolicy(
  item: Record<string, unknown>,
  fallbackSubscriptionId: string
) {
  const properties =
    item.properties && typeof item.properties === "object"
      ? (item.properties as Record<string, unknown>)
      : {};
  const policySettings =
    properties.policySettings && typeof properties.policySettings === "object"
      ? (properties.policySettings as Record<string, unknown>)
      : {};
  const customRules =
    properties.customRules && typeof properties.customRules === "object"
      ? (properties.customRules as Record<string, unknown>)
      : {};
  const managedRules =
    properties.managedRules && typeof properties.managedRules === "object"
      ? (properties.managedRules as Record<string, unknown>)
      : {};
  const id = azureString(item.id, "unknown-front-door-waf");
  const associatedResourceIds = [
    ...(Array.isArray(properties.frontendEndpointLinks)
      ? properties.frontendEndpointLinks
      : []),
    ...(Array.isArray(properties.routingRuleLinks)
      ? properties.routingRuleLinks
      : [])
  ]
    .filter(
      (link): link is Record<string, unknown> =>
        Boolean(link) && typeof link === "object"
    )
    .flatMap((link) => (typeof link.id === "string" ? [link.id] : []));
  const customRuleItems = Array.isArray(customRules.rules)
    ? customRules.rules
    : [];
  const managedRuleSets = Array.isArray(managedRules.managedRuleSets)
    ? managedRules.managedRuleSets
    : [];

  return AzureFrontDoorWafPolicySchema.parse({
    associatedResourceIds,
    customRulesCount: customRuleItems.length,
    enabled:
      azureString(policySettings.enabledState, "Enabled").toLowerCase() !==
      "disabled",
    id,
    location: typeof item.location === "string" ? item.location : null,
    managedRuleSetsCount: managedRuleSets.length,
    mode: azureString(policySettings.mode, "Unknown"),
    name: azureString(item.name, id),
    subscriptionId:
      subscriptionIdFromResourceId(id) === "unknown-subscription"
        ? fallbackSubscriptionId
        : subscriptionIdFromResourceId(id)
  });
}

async function loadAzureFrontDoorWafFixturePolicies(
  config: Record<string, unknown>
) {
  const options = azureFrontDoorWafOptionsFromConfig(config);

  if (options.fixturePolicies?.length) {
    return options.fixturePolicies.map((policy) =>
      parseAzureFrontDoorWafPolicy(policy, "fixture-subscription")
    );
  }

  return [
    AzureFrontDoorWafPolicySchema.parse({
      associatedResourceIds: [
        "/subscriptions/sub-001/resourceGroups/rg-edge/providers/Microsoft.Network/frontDoors/periscan-demo/frontendEndpoints/www"
      ],
      customRulesCount: 1,
      enabled: true,
      id: "/subscriptions/sub-001/resourceGroups/rg-edge/providers/Microsoft.Network/frontDoorWebApplicationFirewallPolicies/periscan-edge",
      location: "global",
      managedRuleSetsCount: 2,
      mode: "Prevention",
      name: "periscan-edge",
      subscriptionId: "sub-001"
    }),
    AzureFrontDoorWafPolicySchema.parse({
      associatedResourceIds: [],
      customRulesCount: 0,
      enabled: false,
      id: "/subscriptions/sub-001/resourceGroups/rg-edge/providers/Microsoft.Network/frontDoorWebApplicationFirewallPolicies/periscan-disabled",
      location: "global",
      managedRuleSetsCount: 0,
      mode: "Detection",
      name: "periscan-disabled",
      subscriptionId: "sub-001"
    })
  ];
}

async function loadRealAzureFrontDoorWafPolicies(
  context: ConnectorExecutionContext
) {
  const config = AzureClientCredentialConfigSchema.parse(context.config);
  const options = azureFrontDoorWafOptionsFromConfig(context.config);
  const accessToken = await getAzureAccessToken(config);
  const subscriptions = parseAzureSubscriptions(
    await azureFetchJson(
      config,
      accessToken,
      `/subscriptions?api-version=${encodeURIComponent(
        config.subscriptionApiVersion
      )}`
    )
  ).filter(
    (subscription) =>
      !config.subscriptionIds ||
      config.subscriptionIds.includes(subscription.subscriptionId)
  );
  const policies: AzureFrontDoorWafPolicy[] = [];

  for (const subscription of subscriptions) {
    const json = await azureFetchPagedValues(
      config,
      accessToken,
      `/subscriptions/${encodeURIComponent(
        subscription.subscriptionId
      )}/providers/Microsoft.Network/frontDoorWebApplicationFirewallPolicies?api-version=${encodeURIComponent(
        options.wafApiVersion
      )}`
    );
    const values = Array.isArray(json.value) ? json.value : [];

    policies.push(
      ...values
        .filter(
          (item): item is Record<string, unknown> =>
            Boolean(item) && typeof item === "object"
        )
        .map((item) =>
          parseAzureFrontDoorWafPolicy(item, subscription.subscriptionId)
        )
    );
  }

  return policies;
}

async function loadAzureFrontDoorWafPolicies(
  context: ConnectorExecutionContext
) {
  return context.mockMode
    ? loadAzureFrontDoorWafFixturePolicies(context.config)
    : loadRealAzureFrontDoorWafPolicies(context);
}

function createAzureFrontDoorWafAssets(
  policies: AzureFrontDoorWafPolicy[]
): ConnectorAssetInput[] {
  return policies.flatMap((policy) => [
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality:
        policy.enabled &&
        policy.associatedResourceIds.length > 0 &&
        policy.managedRuleSetsCount + policy.customRulesCount > 0
          ? "Moderate"
          : "High",
      environment: "edge",
      identifiers: {
        customRulesCount: policy.customRulesCount,
        enabled: policy.enabled,
        managedRuleSetsCount: policy.managedRuleSetsCount,
        mode: policy.mode,
        resourceId: policy.id,
        resourceKind: "AzureFrontDoorWAFPolicy",
        subscriptionId: policy.subscriptionId
      },
      internetExposed: false,
      name: `azure-front-door-waf/${policy.name}`,
      owner: "edge-security",
      status: policy.enabled ? "Active" : "Inactive",
      tags: ["azure", "front-door", "waf"]
    }),
    ...policy.associatedResourceIds.map((resourceId) =>
      createMockAsset({
        assetType: "Service",
        businessCriticality: "High",
        environment: "edge",
        identifiers: {
          protectedByPolicyId: policy.id,
          resourceId,
          resourceKind: "AzureFrontDoorProtectedEndpoint"
        },
        internetExposed: true,
        name: resourceId,
        owner: "edge-security",
        status: "Active",
        tags: ["azure", "front-door", "protected-endpoint"]
      })
    )
  ]);
}

function createAzureFrontDoorWafSignals(
  policies: AzureFrontDoorWafPolicy[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  if (policies.length === 0) {
    return [
      ConnectorSignalInputSchema.parse({
        confidence: 0.7,
        freshness: "Fresh",
        rawPayloadPointer: "azure-front-door-waf://policies/none",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: "WAFPolicyMissing",
        sourceType: "azure.front_door_waf.policy",
        timestampObserved
      })
    ];
  }

  return policies.flatMap((policy) => {
    const rulesConfigured =
      policy.customRulesCount + policy.managedRuleSetsCount > 0;

    return [
      ConnectorSignalInputSchema.parse({
        confidence: policy.enabled && rulesConfigured ? 0.9 : 0.65,
        freshness: "Fresh",
        rawPayloadPointer: `azure-front-door-waf://${policy.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          policy.enabled && rulesConfigured ? "Moderate" : "High",
        signalCategory: "ControlObservation",
        signalSubcategory: policy.enabled
          ? rulesConfigured
            ? "WAFRulesConfigured"
            : "WAFRulesMissing"
          : "WAFPolicyDisabled",
        sourceType: "azure.front_door_waf.policy",
        timestampObserved
      }),
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `azure-front-door-waf://${policy.id}/coverage`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          policy.associatedResourceIds.length > 0 ? "Moderate" : "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          policy.associatedResourceIds.length > 0
            ? "WAFResourceCoverage"
            : "WAFUnassociated",
        sourceType: "azure.front_door_waf.coverage",
        timestampObserved
      })
    ];
  });
}

async function getAzureFrontDoorWafHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AZURE_FRONT_DOOR_WAF_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();

  try {
    const policies = await loadRealAzureFrontDoorWafPolicies(context);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Azure Front Door WAF read-only access verified for ${policies.length} visible polic${policies.length === 1 ? "y" : "ies"}.`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Azure Front Door WAF health check failed: ${azureErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createAzureFrontDoorWafConnector(): Connector {
  return {
    manifest: AZURE_FRONT_DOOR_WAF_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const policies = await loadAzureFrontDoorWafPolicies(parsedContext);

      return createAzureFrontDoorWafSignals(policies);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAzureFrontDoorWafHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const policies = await loadAzureFrontDoorWafPolicies(parsedContext);
      const health = parsedContext.mockMode
        ? await getAzureFrontDoorWafHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Azure Front Door WAF read-only sync returned ${policies.length} polic${policies.length === 1 ? "y" : "ies"}.`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createAzureFrontDoorWafAssets(policies),
        health,
        signals: createAzureFrontDoorWafSignals(policies).map((signal) =>
          createTimestampedSignal(
            AZURE_FRONT_DOOR_WAF_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const AwsStaticCredentialConfigSchema = z.object({
  accessKeyId: z.string().min(1),
  region: z.string().min(1),
  secretAccessKey: z.string().min(1),
  sessionToken: z.string().min(1).optional()
});

const AwsAssumeRoleConfigSchema = z.object({
  durationSeconds: z.number().int().min(900).max(43200).optional(),
  externalId: z.string().min(1).optional(),
  region: z.string().min(1),
  roleArn: z.string().regex(/^arn:aws(?:-[a-z0-9-]+)?:iam::\d{12}:role\/.+$/u),
  sessionName: z.string().min(1).optional(),
  sourceAccessKeyId: z.string().min(1).optional(),
  sourceSecretAccessKey: z.string().min(1).optional(),
  sourceSessionToken: z.string().min(1).optional()
});

const AwsInstanceSchema = z.object({
  instanceId: z.string().min(1),
  name: z.string().min(1),
  publicIpAddress: z.string().min(1).nullable(),
  region: z.string().min(1),
  securityGroupIds: z.array(z.string().min(1)).default([]),
  state: z.string().min(1)
});

const AwsSecurityGroupSchema = z.object({
  groupId: z.string().min(1),
  groupName: z.string().min(1),
  openToWorld: z.boolean(),
  ports: z.array(z.number().int().nonnegative()).default([]),
  region: z.string().min(1)
});

const AwsBucketSchema = z.object({
  isPublic: z.boolean(),
  name: z.string().min(1),
  region: z.string().min(1)
});

const AwsRoleSchema = z.object({
  arn: z.string().min(1),
  attachedPolicies: z.array(z.string().min(1)).default([]),
  isPrivileged: z.boolean(),
  name: z.string().min(1)
});

const AwsInventorySchema = z.object({
  accountAlias: z.string().min(1).nullish(),
  accountId: z.string().min(1),
  buckets: z.array(AwsBucketSchema).default([]),
  instances: z.array(AwsInstanceSchema).default([]),
  roles: z.array(AwsRoleSchema).default([]),
  securityGroups: z.array(AwsSecurityGroupSchema).default([])
});

type AwsAssumeRoleConfig = z.infer<typeof AwsAssumeRoleConfigSchema>;
type AwsClientConfig = {
  credentials?: {
    accessKeyId: string;
    secretAccessKey: string;
    sessionToken?: string;
  };
  region: string;
};
type AwsInventory = z.infer<typeof AwsInventorySchema>;

