function sourceCredentialsFromAssumeRoleConfig(config: AwsAssumeRoleConfig) {
  if (!config.sourceAccessKeyId || !config.sourceSecretAccessKey) {
    return undefined;
  }

  return {
    accessKeyId: config.sourceAccessKeyId,
    secretAccessKey: config.sourceSecretAccessKey,
    sessionToken: config.sourceSessionToken
  };
}

async function resolveAwsClientConfig(
  context: ConnectorExecutionContext
): Promise<AwsClientConfig> {
  if (context.authType === "assumeRole") {
    const config = AwsAssumeRoleConfigSchema.parse(context.config);
    const sts = new STSClient({
      credentials: sourceCredentialsFromAssumeRoleConfig(config),
      region: config.region
    });
    const response = await sts.send(
      new AssumeRoleCommand({
        DurationSeconds: config.durationSeconds,
        ExternalId: config.externalId,
        RoleArn: config.roleArn,
        RoleSessionName:
          config.sessionName ?? `periscan-${context.integrationId.slice(0, 8)}`
      })
    );
    const credentials = response.Credentials;

    if (
      !credentials?.AccessKeyId ||
      !credentials.SecretAccessKey ||
      !credentials.SessionToken
    ) {
      throw new Error("AWS AssumeRole response did not include credentials.");
    }

    return {
      credentials: {
        accessKeyId: credentials.AccessKeyId,
        secretAccessKey: credentials.SecretAccessKey,
        sessionToken: credentials.SessionToken
      },
      region: config.region
    };
  }

  const config = AwsStaticCredentialConfigSchema.parse(context.config);

  return {
    credentials: {
      accessKeyId: config.accessKeyId,
      secretAccessKey: config.secretAccessKey,
      sessionToken: config.sessionToken
    },
    region: config.region
  };
}

function createAwsClients(config: AwsClientConfig) {
  return {
    ec2: new EC2Client({
      credentials: config.credentials,
      region: config.region
    }),
    iam: new IAMClient({
      credentials: config.credentials,
      region: config.region
    }),
    s3: new S3Client({
      credentials: config.credentials,
      region: config.region
    }),
    sts: new STSClient({
      credentials: config.credentials,
      region: config.region
    })
  };
}

async function loadAwsFixtureInventory(config: Record<string, unknown>) {
  const fixturePath =
    typeof config.fixturePath === "string" && config.fixturePath.length > 0
      ? config.fixturePath
      : DEFAULT_AWS_FIXTURE_PATH;
  const raw = await readFile(fixturePath, "utf8");

  return AwsInventorySchema.parse(JSON.parse(raw));
}

async function loadRealAwsInventory(context: ConnectorExecutionContext) {
  const clientConfig = await resolveAwsClientConfig(context);
  const clients = createAwsClients(clientConfig);
  const identity = await clients.sts.send(new GetCallerIdentityCommand({}));
  const accountId = identity.Account;

  if (!accountId) {
    throw new Error("AWS STS identity response did not include an account ID.");
  }

  const instances: AwsInventory["instances"] = [];
  let nextToken: string | undefined;

  do {
    const response = await clients.ec2.send(
      new DescribeInstancesCommand({
        NextToken: nextToken
      })
    );

    for (const reservation of response.Reservations ?? []) {
      for (const instance of reservation.Instances ?? []) {
        if (!instance.InstanceId) {
          continue;
        }

        instances.push(
          AwsInstanceSchema.parse({
            instanceId: instance.InstanceId,
            name:
              instance.Tags?.find((tag) => tag.Key === "Name")?.Value ??
              instance.InstanceId,
            publicIpAddress: instance.PublicIpAddress ?? null,
            region: clientConfig.region,
            securityGroupIds:
              instance.SecurityGroups?.flatMap((group) =>
                group.GroupId ? [group.GroupId] : []
              ) ?? [],
            state: instance.State?.Name ?? "unknown"
          })
        );
      }
    }

    nextToken = response.NextToken;
  } while (nextToken);

  const securityGroups: AwsInventory["securityGroups"] = [];
  let nextGroupToken: string | undefined;

  do {
    const response = await clients.ec2.send(
      new DescribeSecurityGroupsCommand({
        NextToken: nextGroupToken
      })
    );

    for (const group of response.SecurityGroups ?? []) {
      if (!group.GroupId || !group.GroupName) {
        continue;
      }

      const ports = [
        ...(group.IpPermissions ?? []),
        ...(group.IpPermissionsEgress ?? [])
      ]
        .flatMap((permission) =>
          typeof permission.FromPort === "number" ? [permission.FromPort] : []
        )
        .filter((port, index, values) => values.indexOf(port) === index)
        .sort((left, right) => left - right);
      const openToWorld = [
        ...(group.IpPermissions ?? []),
        ...(group.IpPermissionsEgress ?? [])
      ]
        .flatMap((permission) => permission.IpRanges ?? [])
        .some((range) => range.CidrIp === "0.0.0.0/0");

      securityGroups.push(
        AwsSecurityGroupSchema.parse({
          groupId: group.GroupId,
          groupName: group.GroupName,
          openToWorld,
          ports,
          region: clientConfig.region
        })
      );
    }

    nextGroupToken = response.NextToken;
  } while (nextGroupToken);

  const bucketResponse = await clients.s3.send(new ListBucketsCommand({}));
  const buckets: AwsInventory["buckets"] = (bucketResponse.Buckets ?? [])
    .filter((bucket) => Boolean(bucket.Name))
    .map((bucket) =>
      AwsBucketSchema.parse({
        isPublic: false,
        name: bucket.Name!,
        region: clientConfig.region
      })
    );

  const roles: AwsInventory["roles"] = [];
  let marker: string | undefined;

  do {
    const roleResponse = await clients.iam.send(
      new ListRolesCommand({
        Marker: marker
      })
    );

    for (const role of roleResponse.Roles ?? []) {
      if (!role.RoleName || !role.Arn) {
        continue;
      }

      const attachedPolicies = [];
      let attachmentMarker: string | undefined;

      do {
        const attachmentResponse = await clients.iam.send(
          new ListAttachedRolePoliciesCommand({
            Marker: attachmentMarker,
            RoleName: role.RoleName
          })
        );

        attachedPolicies.push(
          ...(attachmentResponse.AttachedPolicies ?? []).flatMap((policy) =>
            policy.PolicyName ? [policy.PolicyName] : []
          )
        );
        attachmentMarker = attachmentResponse.IsTruncated
          ? attachmentResponse.Marker
          : undefined;
      } while (attachmentMarker);

      roles.push(
        AwsRoleSchema.parse({
          arn: role.Arn,
          attachedPolicies: attachedPolicies.sort(),
          isPrivileged: attachedPolicies.includes("AdministratorAccess"),
          name: role.RoleName
        })
      );
    }

    marker = roleResponse.IsTruncated ? roleResponse.Marker : undefined;
  } while (marker);

  return AwsInventorySchema.parse({
    accountAlias: null,
    accountId,
    buckets,
    instances,
    roles,
    securityGroups
  });
}

function createAwsConnectorHealth(
  authorizationVerified: boolean,
  detail: string,
  status: ConnectorHealth["status"],
  latencyMs: number
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified,
    checkedAt: new Date().toISOString(),
    detail,
    latencyMs,
    status
  });
}

async function getAwsHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AWS_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const clientConfig = await resolveAwsClientConfig(context);
  const { sts } = createAwsClients(clientConfig);
  const identity = await sts.send(new GetCallerIdentityCommand({}));

  return createAwsConnectorHealth(
    true,
    `${
      context.authType === "assumeRole" ? "AssumeRole" : "Read-only"
    } AWS identity verified for account ${identity.Account ?? "unknown"}.`,
    "Healthy",
    Date.now() - startedAt
  );
}

function createAwsAssets(inventory: AwsInventory): ConnectorAssetInput[] {
  const assets: ConnectorAssetInput[] = [
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality: "Critical",
      environment: "production",
      identifiers: {
        accountAlias: inventory.accountAlias ?? null,
        accountId: inventory.accountId,
        resourceKind: "CloudAccount"
      },
      internetExposed: inventory.instances.some(
        (instance) => instance.publicIpAddress !== null
      ),
      name: `aws-account/${inventory.accountId}`,
      owner: "cloud-security",
      status: "Active",
      tags: ["aws", "account"]
    })
  ];

  for (const instance of inventory.instances) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: instance.publicIpAddress ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          instanceId: instance.instanceId,
          publicIpAddress: instance.publicIpAddress,
          region: instance.region,
          resourceKind: "EC2Instance",
          securityGroupIds: instance.securityGroupIds,
          state: instance.state
        },
        internetExposed: instance.publicIpAddress !== null,
        name: `ec2/${instance.instanceId}`,
        owner: instance.name,
        status: "Active",
        tags: ["aws", "ec2", `region:${instance.region}`]
      })
    );
  }

  for (const securityGroup of inventory.securityGroups) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: securityGroup.openToWorld ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          groupId: securityGroup.groupId,
          groupName: securityGroup.groupName,
          openToWorld: securityGroup.openToWorld,
          ports: securityGroup.ports,
          region: securityGroup.region,
          resourceKind: "SecurityGroup"
        },
        internetExposed: securityGroup.openToWorld,
        name: `security-group/${securityGroup.groupId}`,
        owner: "cloud-security",
        status: "Active",
        tags: ["aws", "security-group", `region:${securityGroup.region}`]
      })
    );
  }

  for (const bucket of inventory.buckets) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: bucket.isPublic ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          bucketName: bucket.name,
          isPublic: bucket.isPublic,
          region: bucket.region,
          resourceKind: "S3Bucket"
        },
        internetExposed: bucket.isPublic,
        name: `s3/${bucket.name}`,
        owner: "platform-storage",
        status: "Active",
        tags: ["aws", "s3", `region:${bucket.region}`]
      })
    );
  }

  for (const role of inventory.roles) {
    assets.push(
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: role.isPrivileged ? "High" : "Moderate",
        environment: "production",
        identifiers: {
          arn: role.arn,
          attachedPolicies: role.attachedPolicies,
          isPrivileged: role.isPrivileged,
          resourceKind: "IAMRole",
          roleName: role.name
        },
        internetExposed: false,
        name: `iam-role/${role.name}`,
        owner: "identity-security",
        status: "Active",
        tags: [
          "aws",
          "iam",
          role.isPrivileged ? "privileged" : "least-privilege"
        ]
      })
    );
  }

  return assets;
}

function createAwsSignals(inventory: AwsInventory): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [
    ConnectorSignalInputSchema.parse({
      confidence: 0.99,
      freshness: "Fresh",
      rawPayloadPointer: `aws://account/${inventory.accountId}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Moderate",
      signalCategory: "Cloud",
      signalSubcategory: "CloudAccount",
      sourceType: "aws.sts.identity",
      timestampObserved
    })
  ];

  for (const instance of inventory.instances) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `aws://ec2/${instance.instanceId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "CloudAsset",
        sourceType: "aws.ec2.instance",
        timestampObserved
      })
    );

    if (instance.publicIpAddress) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.93,
          freshness: "Fresh",
          rawPayloadPointer: `aws://ec2/${instance.instanceId}/public-ip`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Cloud",
          signalSubcategory: "PublicExposure",
          sourceType: "aws.ec2.public_exposure",
          timestampObserved
        })
      );
    }
  }

  for (const securityGroup of inventory.securityGroups) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.91,
        freshness: "Fresh",
        rawPayloadPointer: `aws://security-group/${securityGroup.groupId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: securityGroup.openToWorld ? "High" : "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "SecurityGroup",
        sourceType: "aws.ec2.security_group",
        timestampObserved
      })
    );

    if (securityGroup.openToWorld) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.92,
          freshness: "Fresh",
          rawPayloadPointer: `aws://security-group/${securityGroup.groupId}/world-open`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Cloud",
          signalSubcategory: "PublicExposure",
          sourceType: "aws.ec2.security_group_public_exposure",
          timestampObserved
        })
      );
    }
  }

  for (const bucket of inventory.buckets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `aws://s3/${bucket.name}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: bucket.isPublic ? "High" : "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "StorageBucket",
        sourceType: "aws.s3.bucket",
        timestampObserved
      })
    );

    if (bucket.isPublic) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.91,
          freshness: "Fresh",
          rawPayloadPointer: `aws://s3/${bucket.name}/public`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Cloud",
          signalSubcategory: "PublicExposure",
          sourceType: "aws.s3.public_exposure",
          timestampObserved
        })
      );
    }
  }

  for (const role of inventory.roles) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.89,
        freshness: "Fresh",
        rawPayloadPointer: `aws://iam-role/${role.name}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: role.isPrivileged ? "High" : "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "IAMRole",
        sourceType: "aws.iam.role",
        timestampObserved
      })
    );

    for (const policyName of role.attachedPolicies) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.87,
          freshness: "Fresh",
          rawPayloadPointer: `aws://iam-role/${role.name}/policy/${policyName}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel:
            policyName === "AdministratorAccess" ? "High" : "Moderate",
          signalCategory: "Cloud",
          signalSubcategory: "IAMPolicy",
          sourceType: "aws.iam.policy_attachment",
          timestampObserved
        })
      );
    }
  }

  return signals;
}

async function syncAwsInventory(context: ConnectorExecutionContext) {
  const inventory = context.mockMode
    ? await loadAwsFixtureInventory(context.config)
    : await loadRealAwsInventory(context);
  const health = await getAwsHealth(context);

  return ConnectorSyncResultSchema.parse({
    assets: createAwsAssets(inventory),
    health,
    signals: createAwsSignals(inventory).map((signal) =>
      createTimestampedSignal(AWS_CONNECTOR_MANIFEST, context, signal)
    )
  });
}

function createAwsConnector(): Connector {
  return {
    manifest: AWS_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? await loadAwsFixtureInventory(parsedContext.config)
        : await loadRealAwsInventory(parsedContext);

      return createAwsSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAwsHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return syncAwsInventory(parsedContext);
    }
  };
}

