function awsEcrOptionsFromConfig(config: Record<string, unknown>) {
  return AwsEcrOptionsSchema.parse(config);
}

function createAwsEcrClient(config: AwsClientConfig) {
  return new ECRClient({
    credentials: config.credentials,
    region: config.region
  });
}

async function listAwsEcrRepositories(
  client: ECRClient,
  options: z.infer<typeof AwsEcrOptionsSchema>
) {
  const repositories: AwsEcrRepository[] = [];
  let nextToken: string | undefined;

  do {
    const response = await client.send(
      new DescribeRepositoriesCommand({
        nextToken,
        registryId: options.registryId,
        repositoryNames:
          options.repositories.length > 0 ? options.repositories : undefined
      })
    );

    repositories.push(
      ...(response.repositories ?? []).map((repository) =>
        AwsEcrRepositorySchema.parse(repository)
      )
    );
    nextToken = response.nextToken;
  } while (nextToken);

  return repositories;
}

async function listAwsEcrImages(
  client: ECRClient,
  options: z.infer<typeof AwsEcrOptionsSchema>,
  repository: AwsEcrRepository
) {
  const images: AwsEcrImage[] = [];
  let nextToken: string | undefined;

  do {
    const response = await client.send(
      new DescribeImagesCommand({
        maxResults: 25,
        nextToken,
        registryId: options.registryId,
        repositoryName: repository.repositoryName
      })
    );

    images.push(
      ...(response.imageDetails ?? []).map((image) =>
        AwsEcrImageSchema.parse(image)
      )
    );
    nextToken = response.nextToken;
  } while (nextToken);

  return images;
}

function loadAwsEcrFixtureInventory() {
  return {
    imagesByRepository: AWS_ECR_FIXTURE_IMAGES,
    repositories: AWS_ECR_FIXTURE_REPOSITORIES
  };
}

async function loadRealAwsEcrInventory(context: ConnectorExecutionContext) {
  const clientConfig = await resolveAwsClientConfig(context);
  const options = awsEcrOptionsFromConfig(context.config);
  const client = createAwsEcrClient(clientConfig);
  const repositories = await listAwsEcrRepositories(client, options);
  const imagesByRepository: Record<string, AwsEcrImage[]> = {};

  for (const repository of repositories) {
    imagesByRepository[repository.repositoryName] = await listAwsEcrImages(
      client,
      options,
      repository
    );
  }

  return {
    imagesByRepository,
    repositories
  };
}

function awsEcrRepositoryDisplayName(repository: AwsEcrRepository) {
  return (
    repository.repositoryUri ??
    `${repository.registryId}/${repository.repositoryName}`
  );
}

function awsEcrTimestamp(value: Date | string | null | undefined) {
  if (value instanceof Date) {
    return value.toISOString();
  }

  return typeof value === "string" ? value : new Date().toISOString();
}

function createAwsEcrAssets(repositories: AwsEcrRepository[]) {
  return repositories.map((repository) =>
    createMockAsset({
      assetType: "Container",
      businessCriticality:
        repository.imageScanningConfiguration?.scanOnPush === false ||
        repository.imageTagMutability === "MUTABLE"
          ? "High"
          : "Moderate",
      environment: "container-registry",
      identifiers: {
        encryptionType:
          repository.encryptionConfiguration?.encryptionType ?? null,
        imageScanningOnPush:
          repository.imageScanningConfiguration?.scanOnPush ?? null,
        imageTagMutability: repository.imageTagMutability ?? null,
        registryId: repository.registryId,
        repositoryArn: repository.repositoryArn ?? null,
        repositoryName: repository.repositoryName,
        repositoryUri: repository.repositoryUri ?? null,
        resourceKind: "ECRRepository"
      },
      internetExposed: false,
      name: `aws-ecr/${awsEcrRepositoryDisplayName(repository)}`,
      owner: "cloud-platform",
      status: "Active",
      tags: [
        "container-registry",
        "aws-ecr",
        repository.imageTagMutability === "IMMUTABLE" ? "immutable" : "mutable"
      ]
    })
  );
}

function createAwsEcrSignals(input: {
  imagesByRepository: Record<string, AwsEcrImage[]>;
  repositories: AwsEcrRepository[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const repository of input.repositories) {
    const repositoryBase = `aws-ecr://repository/${repository.registryId}/${repository.repositoryName}`;
    const scanOnPush = repository.imageScanningConfiguration?.scanOnPush;
    const tagMutability = repository.imageTagMutability ?? "UNKNOWN";

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: repositoryBase,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "ContainerImageRepository",
        sourceType: "aws_ecr.repository.metadata",
        timestampObserved: awsEcrTimestamp(repository.createdAt)
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `${repositoryBase}/visibility`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Low",
        signalCategory: "Exposure",
        signalSubcategory: "PrivateContainerRepository",
        sourceType: "aws_ecr.repository.visibility",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `${repositoryBase}/scan-on-push`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: scanOnPush === false ? "High" : "Moderate",
        signalCategory: scanOnPush === false ? "Exposure" : "Asset",
        signalSubcategory:
          scanOnPush === false
            ? "ContainerImageScanOnPushDisabled"
            : "ContainerImageScanOnPushEnabled",
        sourceType: "aws_ecr.repository.scan_configuration",
        timestampObserved
      })
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.83,
        freshness: "Fresh",
        rawPayloadPointer: `${repositoryBase}/tag-mutability`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: tagMutability === "MUTABLE" ? "Moderate" : "Low",
        signalCategory: tagMutability === "MUTABLE" ? "Exposure" : "Asset",
        signalSubcategory:
          tagMutability === "MUTABLE"
            ? "ContainerImageMutableTags"
            : "ContainerImageImmutableTags",
        sourceType: "aws_ecr.repository.tag_mutability",
        timestampObserved
      })
    );

    for (const image of input.imagesByRepository[repository.repositoryName] ??
      []) {
      if (image.imageDigest) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.8,
            freshness: "Fresh",
            rawPayloadPointer: `${repositoryBase}/images/${image.imageDigest}`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "Asset",
            signalSubcategory: "ContainerImageDigest",
            sourceType: "aws_ecr.image.metadata",
            timestampObserved: awsEcrTimestamp(image.imagePushedAt)
          })
        );
      }

      for (const tag of image.imageTags ?? []) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.8,
            freshness: "Fresh",
            rawPayloadPointer: `${repositoryBase}/tags/${tag}`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "Asset",
            signalSubcategory: "ContainerImageTag",
            sourceType: "aws_ecr.image.tag",
            timestampObserved: awsEcrTimestamp(image.imagePushedAt)
          })
        );
      }
    }
  }

  return signals;
}

async function getAwsEcrHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AWS_ECR_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const clientConfig = await resolveAwsClientConfig(context);
  const options = awsEcrOptionsFromConfig(context.config);
  const repositories = await listAwsEcrRepositories(
    createAwsEcrClient(clientConfig),
    options
  );

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `AWS ECR read-only metadata access verified for ${repositories.length} repositor${repositories.length === 1 ? "y" : "ies"}.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createAwsEcrConnector(): Connector {
  return {
    manifest: AWS_ECR_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadAwsEcrFixtureInventory()
        : await loadRealAwsEcrInventory(parsedContext);

      return createAwsEcrSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAwsEcrHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadAwsEcrFixtureInventory()
        : await loadRealAwsEcrInventory(parsedContext);
      const health = parsedContext.mockMode
        ? await getAwsEcrHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `AWS ECR read-only sync returned ${inventory.repositories.length} repositor${inventory.repositories.length === 1 ? "y" : "ies"}.`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createAwsEcrAssets(inventory.repositories),
        health,
        signals: createAwsEcrSignals(inventory).map((signal) =>
          createTimestampedSignal(
            AWS_ECR_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

