function parseAwsWafDefaultAction(value: unknown) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    if ("Allow" in value) {
      return "ALLOW";
    }

    if ("Block" in value) {
      return "BLOCK";
    }
  }

  return "UNKNOWN";
}

function parseAwsWafFixtureWebAcl(item: Record<string, unknown>): AwsWafWebAcl {
  return AwsWafWebAclSchema.parse({
    arn: connectorString(item.arn, "arn:aws:wafv2:fixture:webacl/unknown"),
    associatedResourceArns: Array.isArray(item.associatedResourceArns)
      ? item.associatedResourceArns.filter(
          (value): value is string => typeof value === "string"
        )
      : [],
    capacity: typeof item.capacity === "number" ? item.capacity : null,
    defaultAction: connectorString(item.defaultAction, "UNKNOWN"),
    description:
      typeof item.description === "string" && item.description.length > 0
        ? item.description
        : null,
    id: connectorString(item.id, "unknown-web-acl"),
    managedByFirewallManager: item.managedByFirewallManager === true,
    name: connectorString(item.name, "unknown-web-acl"),
    rulesCount: typeof item.rulesCount === "number" ? item.rulesCount : 0,
    scope: AwsWafScopeSchema.parse(item.scope ?? "REGIONAL")
  });
}

async function loadAwsWafFixtureInventory(config: Record<string, unknown>) {
  const options = awsWafOptionsFromConfig(config);

  if (options.fixtureWebAcls?.length) {
    return options.fixtureWebAcls.map(parseAwsWafFixtureWebAcl);
  }

  return [
    AwsWafWebAclSchema.parse({
      arn: "arn:aws:wafv2:us-east-1:123456789012:regional/webacl/periscan-edge/fixture-waf-1",
      associatedResourceArns: [
        "arn:aws:elasticloadbalancing:us-east-1:123456789012:loadbalancer/app/public-app/abc123"
      ],
      capacity: 82,
      defaultAction: "BLOCK",
      description: "Fixture AWS WAF web ACL protecting the public app.",
      id: "fixture-waf-1",
      managedByFirewallManager: false,
      name: "periscan-edge",
      rulesCount: 5,
      scope: "REGIONAL"
    }),
    AwsWafWebAclSchema.parse({
      arn: "arn:aws:wafv2:us-east-1:123456789012:regional/webacl/periscan-empty/fixture-waf-2",
      associatedResourceArns: [],
      capacity: 0,
      defaultAction: "ALLOW",
      description: "Fixture AWS WAF web ACL with no associated resources.",
      id: "fixture-waf-2",
      managedByFirewallManager: false,
      name: "periscan-empty",
      rulesCount: 0,
      scope: "REGIONAL"
    })
  ];
}

function createAwsWafClient(config: AwsClientConfig) {
  return new WAFV2Client({
    credentials: config.credentials,
    region: config.region
  });
}

function awsWafSummaryValue(value: unknown, fallback: string) {
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

async function listAwsWafResourcesForWebAcl(
  client: WAFV2Client,
  webAclArn: string,
  scope: AwsWafScope
) {
  if (scope === "CLOUDFRONT") {
    return [];
  }

  const response = await client.send(
    new ListResourcesForWebACLCommand({
      WebACLArn: webAclArn
    })
  );

  return response.ResourceArns ?? [];
}

async function getAwsWafWebAclDetails(
  client: WAFV2Client,
  summary: Record<string, unknown>,
  scope: AwsWafScope
) {
  const name = awsWafSummaryValue(summary.Name, "unknown-web-acl");
  const id = awsWafSummaryValue(summary.Id, "unknown-web-acl");
  const arn = awsWafSummaryValue(summary.ARN, `aws-waf://${scope}/${id}`);
  const response = await client.send(
    new GetWebACLCommand({
      Id: id,
      Name: name,
      Scope: scope
    })
  );
  const webAcl = response.WebACL;
  const associatedResourceArns = await listAwsWafResourcesForWebAcl(
    client,
    arn,
    scope
  );

  return AwsWafWebAclSchema.parse({
    arn,
    associatedResourceArns,
    capacity: webAcl?.Capacity ?? null,
    defaultAction: parseAwsWafDefaultAction(webAcl?.DefaultAction),
    description: webAcl?.Description ?? null,
    id,
    managedByFirewallManager: webAcl?.ManagedByFirewallManager === true,
    name,
    rulesCount: webAcl?.Rules?.length ?? 0,
    scope
  });
}

async function loadRealAwsWafInventory(context: ConnectorExecutionContext) {
  const clientConfig = await resolveAwsClientConfig(context);
  const client = createAwsWafClient(clientConfig);
  const options = awsWafOptionsFromConfig(context.config);
  const webAcls: AwsWafWebAcl[] = [];

  for (const scope of options.scopes) {
    let nextMarker: string | undefined;

    do {
      const response = await client.send(
        new ListWebACLsCommand({
          Limit: 100,
          NextMarker: nextMarker,
          Scope: scope
        })
      );

      for (const summary of response.WebACLs ?? []) {
        webAcls.push(
          await getAwsWafWebAclDetails(
            client,
            summary as Record<string, unknown>,
            scope
          )
        );
      }

      nextMarker = response.NextMarker;
    } while (nextMarker);
  }

  return webAcls;
}

function createAwsWafAssets(webAcls: AwsWafWebAcl[]): ConnectorAssetInput[] {
  return webAcls.flatMap((webAcl) => [
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality:
        webAcl.rulesCount > 0 && webAcl.associatedResourceArns.length > 0
          ? "Moderate"
          : "High",
      environment: "edge",
      identifiers: {
        arn: webAcl.arn,
        capacity: webAcl.capacity,
        defaultAction: webAcl.defaultAction,
        managedByFirewallManager: webAcl.managedByFirewallManager,
        resourceKind: "AWSWAFWebACL",
        rulesCount: webAcl.rulesCount,
        scope: webAcl.scope,
        webAclId: webAcl.id
      },
      internetExposed: false,
      name: `aws-waf/${webAcl.name}`,
      owner: "edge-security",
      status: "Active",
      tags: ["aws", "waf", webAcl.scope.toLowerCase()]
    }),
    ...webAcl.associatedResourceArns.map((resourceArn) =>
      createMockAsset({
        assetType: "Service",
        businessCriticality: "High",
        environment: "edge",
        identifiers: {
          protectedByWebAclArn: webAcl.arn,
          resourceArn,
          resourceKind: "AWSWAFProtectedResource"
        },
        internetExposed: true,
        name: resourceArn,
        owner: "edge-security",
        status: "Active",
        tags: ["aws", "waf", "protected-resource"]
      })
    )
  ]);
}

function createAwsWafSignals(webAcls: AwsWafWebAcl[]): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  if (webAcls.length === 0) {
    return [
      ConnectorSignalInputSchema.parse({
        confidence: 0.7,
        freshness: "Fresh",
        rawPayloadPointer: "aws-waf://web-acls/none",
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "ControlObservation",
        signalSubcategory: "WAFWebACLMissing",
        sourceType: "aws.waf.web_acl",
        timestampObserved
      })
    ];
  }

  return webAcls.flatMap((webAcl) => [
    ConnectorSignalInputSchema.parse({
      confidence: webAcl.rulesCount > 0 ? 0.9 : 0.65,
      freshness: "Fresh",
      rawPayloadPointer: `aws-waf://${webAcl.scope}/${webAcl.id}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel:
        webAcl.rulesCount > 0 && webAcl.defaultAction === "BLOCK"
          ? "Moderate"
          : "High",
      signalCategory: "ControlObservation",
      signalSubcategory:
        webAcl.rulesCount > 0 ? "WAFRulesConfigured" : "WAFRulesMissing",
      sourceType: "aws.waf.web_acl",
      timestampObserved
    }),
    ...(webAcl.associatedResourceArns.length === 0
      ? [
          ConnectorSignalInputSchema.parse({
            confidence: 0.85,
            freshness: "Fresh",
            rawPayloadPointer: `aws-waf://${webAcl.scope}/${webAcl.id}/coverage`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "High",
            signalCategory: "ControlObservation",
            signalSubcategory: "WAFUnassociated",
            sourceType: "aws.waf.coverage",
            timestampObserved
          })
        ]
      : [
          ConnectorSignalInputSchema.parse({
            confidence: 0.9,
            freshness: "Fresh",
            rawPayloadPointer: `aws-waf://${webAcl.scope}/${webAcl.id}/coverage`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "ControlObservation",
            signalSubcategory: "WAFResourceCoverage",
            sourceType: "aws.waf.coverage",
            timestampObserved
          })
        ])
  ]);
}

async function loadAwsWafInventory(context: ConnectorExecutionContext) {
  return context.mockMode
    ? loadAwsWafFixtureInventory(context.config)
    : loadRealAwsWafInventory(context);
}

async function getAwsWafHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AWS_WAF_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const clientConfig = await resolveAwsClientConfig(context);
  const client = createAwsWafClient(clientConfig);
  const firstScope =
    awsWafOptionsFromConfig(context.config).scopes[0] ?? "REGIONAL";
  const response = await client.send(
    new ListWebACLsCommand({
      Limit: 1,
      Scope: firstScope
    })
  );

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `AWS WAFv2 read-only access verified for ${firstScope} scope with ${response.WebACLs?.length ?? 0} visible web ACLs.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createAwsWafConnector(): Connector {
  return {
    manifest: AWS_WAF_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const webAcls = await loadAwsWafInventory(parsedContext);

      return createAwsWafSignals(webAcls);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAwsWafHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const webAcls = await loadAwsWafInventory(parsedContext);
      const health = await getAwsWafHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createAwsWafAssets(webAcls),
        health,
        signals: createAwsWafSignals(webAcls).map((signal) =>
          createTimestampedSignal(
            AWS_WAF_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const CloudflareApiTokenConfigSchema = z.object({
  accountId: z.string().min(1).optional(),
  apiToken: z.string().min(1),
  baseUrl: z.url().default("https://api.cloudflare.com"),
  zoneIds: z.array(z.string().min(1)).optional()
});

type CloudflareApiTokenConfig = z.infer<typeof CloudflareApiTokenConfigSchema>;

type CloudflareZone = {
  id: string;
  name: string;
  status: string;
};

type CloudflareDnsRecord = {
  content: string;
  id: string;
  name: string;
  proxied: boolean;
  type: string;
  zoneId: string;
};

type CloudflareRuleset = {
  id: string;
  kind: string;
  name: string;
  phase: string;
  rulesCount: number;
  zoneId: string;
};

type CloudflareInventory = {
  accountId: string | null;
  dnsRecords: CloudflareDnsRecord[];
  rulesets: CloudflareRuleset[];
  zones: CloudflareZone[];
};

const CLOUDFLARE_CONNECTOR_MANIFEST = ConnectorManifestSchema.parse({
  authMethods: [
    {
      description: "Use fixture-backed mock Cloudflare zone and WAF data.",
      fields: [],
      kind: "mock",
      label: "Mock",
      mockSupported: true
    },
    {
      description:
        "Use a Cloudflare API token with read-only zone, DNS, and WAF/ruleset permissions.",
      fields: [
        {
          key: "apiToken",
          label: "Cloudflare API Token",
          required: true,
          secret: true
        },
        {
          key: "baseUrl",
          label: "Cloudflare API Base URL",
          required: false,
          secret: false
        },
        {
          key: "accountId",
          label: "Account ID",
          required: false,
          secret: false
        },
        {
          key: "zoneIds",
          label: "Allowed Zone IDs",
          required: false,
          secret: false
        }
      ],
      kind: "apiToken",
      label: "Cloudflare API Token",
      mockSupported: false
    }
  ],
  availability: "Beta",
  category: "Cloud",
  connectorKey: "cloudflare",
  controlObservationCapabilities: ["Blocked", "Logged", "NoEvidence"],
  customerVisibleDescription:
    "Reads authorized Cloudflare zones, DNS records, and WAF/ruleset posture for exposure and control validation.",
  dataSensitivity: "High",
  healthCheckMethod: "Cloudflare API token verification",
  marketplaceCategory: "WAF/Firewall",
  mockSupported: true,
  permissionsSummary:
    "Reads zone, DNS, and WAF/ruleset metadata only; no write permissions are required.",
  product: "Cloudflare",
  requiredPermissions: ["Zone.Zone:Read", "Zone.DNS:Read", "Zone.WAF:Read"],
  setupComplexity: "Low",
  signalCategories: ["Cloud", "Asset", "ControlObservation"],
  supportedMissionTypes: [
    "ValidationSnapshot",
    "ExposureValidation",
    "ControlValidation"
  ],
  validationCapabilities: [
    "Edge asset inventory",
    "DNS exposure signals",
    "WAF/ruleset posture signals"
  ],
  vendor: "Cloudflare",
  workflowCapabilities: []
});

function cloudflareApiUrl(config: CloudflareApiTokenConfig, pathName: string) {
  return new URL(pathName, config.baseUrl).toString();
}

function cloudflareErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Cloudflare API error.";
}

async function cloudflareFetchJson(
  config: CloudflareApiTokenConfig,
  pathName: string
) {
  const response = await connectorFetch(cloudflareApiUrl(config, pathName), {
    headers: {
      authorization: `Bearer ${config.apiToken}`
    }
  });

  if (!response.ok) {
    throw new Error(`Cloudflare API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function connectorString(value: unknown, fallback: string) {
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

function cloudflareResultArray(json: Record<string, unknown>) {
  return Array.isArray(json.result)
    ? (json.result.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      ) as Record<string, unknown>[])
    : [];
}

function parseCloudflareZone(item: Record<string, unknown>): CloudflareZone {
  return {
    id: connectorString(item.id, "unknown-zone"),
    name: connectorString(item.name, "unknown-zone"),
    status: connectorString(item.status, "unknown")
  };
}

function parseCloudflareDnsRecord(
  zoneId: string,
  item: Record<string, unknown>
): CloudflareDnsRecord {
  return {
    content: connectorString(item.content, ""),
    id: connectorString(item.id, "unknown-record"),
    name: connectorString(item.name, "unknown-record"),
    proxied: item.proxied === true,
    type: connectorString(item.type, "UNKNOWN"),
    zoneId
  };
}

function parseCloudflareRuleset(
  zoneId: string,
  item: Record<string, unknown>
): CloudflareRuleset {
  return {
    id: connectorString(item.id, "unknown-ruleset"),
    kind: connectorString(item.kind, "zone"),
    name: connectorString(item.name, "unnamed-ruleset"),
    phase: connectorString(item.phase, "unknown"),
    rulesCount: Array.isArray(item.rules) ? item.rules.length : 0,
    zoneId
  };
}

async function loadCloudflareFixtureInventory(
  config: Record<string, unknown>
): Promise<CloudflareInventory> {
  const accountId =
    typeof config.accountId === "string" && config.accountId.length > 0
      ? config.accountId
      : null;

  if (Array.isArray(config.fixtureZones)) {
    const zones = config.fixtureZones
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map(parseCloudflareZone);

    return {
      accountId,
      dnsRecords: [],
      rulesets: [],
      zones
    };
  }

  return {
    accountId: "cloudflare-demo-account",
    dnsRecords: [
      {
        content: "203.0.113.10",
        id: "dns-demo-root",
        name: "periscan-demo.example",
        proxied: true,
        type: "A",
        zoneId: "zone-demo"
      },
      {
        content: "origin.periscan-demo.example",
        id: "dns-demo-origin",
        name: "origin.periscan-demo.example",
        proxied: false,
        type: "CNAME",
        zoneId: "zone-demo"
      }
    ],
    rulesets: [
      {
        id: "ruleset-demo-waf",
        kind: "zone",
        name: "Managed WAF",
        phase: "http_request_firewall_managed",
        rulesCount: 4,
        zoneId: "zone-demo"
      }
    ],
    zones: [
      {
        id: "zone-demo",
        name: "periscan-demo.example",
        status: "active"
      }
    ]
  };
}

async function cloudflareFetchOptionalList(
  config: CloudflareApiTokenConfig,
  pathName: string
) {
  try {
    return cloudflareResultArray(await cloudflareFetchJson(config, pathName));
  } catch {
    return [];
  }
}

async function loadRealCloudflareInventory(
  context: ConnectorExecutionContext
): Promise<CloudflareInventory> {
  const config = CloudflareApiTokenConfigSchema.parse(context.config);
  const zoneIds = config.zoneIds ?? [];
  const zones =
    zoneIds.length > 0
      ? (
          await Promise.all(
            zoneIds.map(async (zoneId) => {
              const json = await cloudflareFetchJson(
                config,
                `/client/v4/zones/${zoneId}`
              );
              const result = json.result;

              return parseCloudflareZone(
                result && typeof result === "object" && !Array.isArray(result)
                  ? (result as Record<string, unknown>)
                  : {}
              );
            })
          )
        ).filter((zone) => zone.id !== "unknown-zone")
      : cloudflareResultArray(
          await cloudflareFetchJson(config, "/client/v4/zones?per_page=50")
        ).map(parseCloudflareZone);
  const dnsRecords: CloudflareDnsRecord[] = [];
  const rulesets: CloudflareRuleset[] = [];

  for (const zone of zones) {
    const dnsItems = await cloudflareFetchOptionalList(
      config,
      `/client/v4/zones/${zone.id}/dns_records?per_page=100`
    );
    dnsRecords.push(
      ...dnsItems.map((item) => parseCloudflareDnsRecord(zone.id, item))
    );

    const rulesetItems = await cloudflareFetchOptionalList(
      config,
      `/client/v4/zones/${zone.id}/rulesets?per_page=50`
    );
    rulesets.push(
      ...rulesetItems.map((item) => parseCloudflareRuleset(zone.id, item))
    );

    const firewallItems = await cloudflareFetchOptionalList(
      config,
      `/client/v4/zones/${zone.id}/firewall/rules?per_page=50`
    );
    rulesets.push(
      ...firewallItems.map((item) => parseCloudflareRuleset(zone.id, item))
    );
  }

  return {
    accountId: config.accountId ?? null,
    dnsRecords,
    rulesets,
    zones
  };
}

async function getCloudflareHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CLOUDFLARE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = CloudflareApiTokenConfigSchema.parse(context.config);

  try {
    await cloudflareFetchJson(config, "/client/v4/user/tokens/verify");

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Cloudflare API token verified for read-only zone and WAF metadata.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Cloudflare health check failed: ${cloudflareErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createCloudflareAssets(
  inventory: CloudflareInventory
): ConnectorAssetInput[] {
  const assets: ConnectorAssetInput[] = inventory.zones.map((zone) =>
    createMockAsset({
      assetType: "Domain",
      businessCriticality: "High",
      environment: "edge",
      identifiers: {
        accountId: inventory.accountId,
        resourceKind: "CloudflareZone",
        status: zone.status,
        zoneId: zone.id
      },
      internetExposed: true,
      name: zone.name,
      owner: "edge-security",
      status: zone.status === "active" ? "Active" : "Inactive",
      tags: ["cloudflare", "zone"]
    })
  );

  for (const record of inventory.dnsRecords) {
    assets.push(
      createMockAsset({
        assetType: "Service",
        businessCriticality: record.proxied ? "Moderate" : "High",
        environment: "edge",
        identifiers: {
          content: record.content,
          proxied: record.proxied,
          recordId: record.id,
          recordType: record.type,
          resourceKind: "CloudflareDNSRecord",
          zoneId: record.zoneId
        },
        internetExposed: true,
        name: record.name,
        owner: "edge-security",
        status: "Active",
        tags: [
          "cloudflare",
          "dns",
          record.proxied ? "proxied" : "direct-origin"
        ]
      })
    );
  }

  return assets;
}

function createCloudflareSignals(
  inventory: CloudflareInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const zone of inventory.zones) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.93,
        freshness: "Fresh",
        rawPayloadPointer: `cloudflare://zone/${zone.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "CloudflareZone",
        sourceType: "cloudflare.zone",
        timestampObserved
      })
    );
  }

  for (const record of inventory.dnsRecords) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `cloudflare://zone/${record.zoneId}/dns/${record.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: record.proxied ? "Moderate" : "High",
        signalCategory: record.proxied ? "Asset" : "Exposure",
        signalSubcategory: record.proxied
          ? "DNSRecord"
          : "DirectOriginExposure",
        sourceType: "cloudflare.dns.record",
        timestampObserved
      })
    );
  }

  for (const ruleset of inventory.rulesets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: ruleset.rulesCount > 0 ? 0.88 : 0.65,
        freshness: "Fresh",
        rawPayloadPointer: `cloudflare://zone/${ruleset.zoneId}/ruleset/${ruleset.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: ruleset.rulesCount > 0 ? "Moderate" : "High",
        signalCategory: "ControlObservation",
        signalSubcategory:
          ruleset.rulesCount > 0 ? "WAFRulesConfigured" : "WAFRulesMissing",
        sourceType: "cloudflare.waf.ruleset",
        timestampObserved
      })
    );
  }

  return signals;
}

async function loadCloudflareInventory(context: ConnectorExecutionContext) {
  return context.mockMode
    ? loadCloudflareFixtureInventory(context.config)
    : loadRealCloudflareInventory(context);
}

function createCloudflareConnector(): Connector {
  return {
    manifest: CLOUDFLARE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadCloudflareInventory(parsedContext);

      return createCloudflareSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getCloudflareHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadCloudflareInventory(parsedContext);
      const health = await getCloudflareHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createCloudflareAssets(inventory),
        health,
        signals: createCloudflareSignals(inventory).map((signal) =>
          createTimestampedSignal(
            CLOUDFLARE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const KubernetesApiTokenConfigSchema = z.object({
  apiServerUrl: z.url(),
  bearerToken: z.string().min(1),
  clusterName: z.string().min(1).default("customer-kubernetes"),
  includeNodes: z.boolean().default(false),
  namespaceNames: z.array(z.string().min(1)).default([])
});

type KubernetesApiTokenConfig = z.infer<typeof KubernetesApiTokenConfigSchema>;

type KubernetesNamespace = {
  labelCount: number;
  name: string;
};

type KubernetesWorkload = {
  automountServiceAccountToken: boolean | null;
  containerCount: number;
  hostIpc: boolean;
  hostNetwork: boolean;
  hostPid: boolean;
  imageCount: number;
  kind: "Pod" | "Deployment";
  name: string;
  namespace: string;
  privilegedContainerCount: number;
  readyReplicas: number | null;
  replicas: number | null;
};

type KubernetesService = {
  externalHostnameCount: number;
  externalIpCount: number;
  kind: string;
  loadBalancerIngressCount: number;
  name: string;
  namespace: string;
  portCount: number;
  serviceType: string;
};

type KubernetesNetworkPolicy = {
  name: string;
  namespace: string;
  podSelectorEmpty: boolean;
  policyTypes: string[];
};

type KubernetesNodeSummary = {
  kubeletVersion: string | null;
  name: string;
  osImage: string | null;
};

type KubernetesInventory = {
  clusterName: string;
  namespaces: KubernetesNamespace[];
  networkPolicies: KubernetesNetworkPolicy[];
  nodes: KubernetesNodeSummary[];
  services: KubernetesService[];
  workloads: KubernetesWorkload[];
};

