function normalizeSalesforceUrl(value: string) {
  return value.replace(/\/+$/u, "");
}

async function getSalesforceAccessToken(config: SalesforceOAuthConfig) {
  const response = await connectorFetch(
    `${normalizeSalesforceUrl(config.loginUrl)}/services/oauth2/token`,
    {
      body: new URLSearchParams({
        client_id: config.clientId,
        client_secret: config.clientSecret,
        grant_type: "client_credentials"
      }),
      headers: { "content-type": "application/x-www-form-urlencoded" },
      method: "POST"
    }
  );

  if (!response.ok) {
    throw new Error(
      `Salesforce OAuth token request failed with status ${response.status}.`
    );
  }

  return SalesforceTokenSchema.parse(await response.json());
}

async function fetchSalesforceQuery<T>(input: {
  accessToken: string;
  instanceUrl: string;
  maxRecords: number;
  pathName: string;
  schema: z.ZodType<T>;
}) {
  const rows: T[] = [];
  let nextPath: string | null = input.pathName;
  let pageCount = 0;

  while (nextPath && rows.length < input.maxRecords && pageCount < 10) {
    const response = await connectorFetch(
      nextPath.startsWith("https://")
        ? nextPath
        : `${normalizeSalesforceUrl(input.instanceUrl)}${nextPath}`,
      {
        headers: {
          accept: "application/json",
          authorization: `Bearer ${input.accessToken}`
        },
        method: "GET"
      }
    );
    if (!response.ok) {
      throw new Error(
        `Salesforce REST query failed with status ${response.status}.`
      );
    }
    const page = SalesforceQueryResponseSchema.parse(await response.json());
    rows.push(...page.records.map((row) => input.schema.parse(row)));
    nextPath = page.done ? null : (page.nextRecordsUrl ?? null);
    pageCount += 1;
  }

  return rows.slice(0, input.maxRecords);
}

function salesforceQueryPath(apiVersion: string, query: string) {
  return `/services/data/v${apiVersion}/query?q=${encodeURIComponent(query)}`;
}

async function loadSalesforceLiveInventory(
  config: SalesforceOAuthConfig
): Promise<SalesforceInventory> {
  const token = await getSalesforceAccessToken(config);
  const common = {
    accessToken: token.access_token,
    instanceUrl: token.instance_url,
    maxRecords: config.maxRecords
  };
  const [organizations, users, loginHistory] = await Promise.all([
    fetchSalesforceQuery({
      ...common,
      pathName: salesforceQueryPath(
        config.apiVersion,
        "SELECT Id, Name, OrganizationType, IsSandbox FROM Organization LIMIT 1"
      ),
      schema: SalesforceOrganizationSchema
    }),
    fetchSalesforceQuery({
      ...common,
      pathName: salesforceQueryPath(
        config.apiVersion,
        "SELECT Id, Username, Name, IsActive, UserType, Profile.Name, LastLoginDate FROM User ORDER BY Id"
      ),
      schema: SalesforceUserSchema
    }),
    config.includeLoginHistory
      ? fetchSalesforceQuery({
          ...common,
          pathName: salesforceQueryPath(
            config.apiVersion,
            "SELECT Id, UserId, LoginTime, Status FROM LoginHistory ORDER BY LoginTime DESC LIMIT 200"
          ),
          schema: SalesforceLoginHistorySchema
        })
      : Promise.resolve([])
  ]);

  return { loginHistory, organizations, users };
}

function salesforceUserIsStale(user: SalesforceUser, now = Date.now()) {
  if (!user.IsActive || !user.LastLoginDate) return false;
  const lastLogin = Date.parse(user.LastLoginDate);
  return (
    Number.isFinite(lastLogin) && now - lastLogin > 90 * 24 * 60 * 60 * 1000
  );
}

function salesforceUserIsPrivileged(user: SalesforceUser) {
  return /\b(?:system administrator|admin(?:istrator)?|security)\b/iu.test(
    user.Profile?.Name ?? ""
  );
}

function createSalesforceAssets(
  inventory: SalesforceInventory
): ConnectorAssetInput[] {
  return inventory.organizations.map((organization) =>
    createMockAsset({
      assetType: "IdentityStore",
      businessCriticality: "High",
      environment: organization.IsSandbox ? "test" : "production",
      identifiers: {
        organizationId: organization.Id,
        organizationType: organization.OrganizationType ?? null,
        provider: "salesforce",
        sandbox: organization.IsSandbox ?? null,
        userCount: inventory.users.length
      },
      internetExposed: true,
      name: organization.Name ?? `Salesforce org ${organization.Id}`,
      owner: "identity-security",
      status: "Active",
      tags: ["salesforce", "saas", "identity"]
    })
  );
}

function createSalesforceSignals(
  inventory: SalesforceInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const base = {
    confidence: 0.9,
    freshness: "Fresh" as const,
    redactionStatus: "Redacted" as const,
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: []
  };

  return [
    ...inventory.organizations.map((organization) =>
      ConnectorSignalInputSchema.parse({
        ...base,
        rawPayloadPointer: `salesforce://organization/${organization.Id}`,
        sensitivityLevel: "High",
        signalCategory: "Identity",
        signalSubcategory: "IdentityStore",
        sourceType: "salesforce.organization.metadata",
        timestampObserved
      })
    ),
    ...inventory.users.flatMap((user) => {
      const signals = [
        ConnectorSignalInputSchema.parse({
          ...base,
          confidence: 0.88,
          rawPayloadPointer: `salesforce://user/${user.Id}`,
          sensitivityLevel: "High",
          signalCategory: "Identity",
          signalSubcategory: salesforceUserIsPrivileged(user)
            ? "PrivilegedIdentity"
            : user.IsActive
              ? "UserAccount"
              : "InactiveUserAccount",
          sourceType: "salesforce.user.posture",
          timestampObserved
        })
      ];
      if (salesforceUserIsStale(user)) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            ...base,
            confidence: 0.86,
            rawPayloadPointer: `salesforce://user/${user.Id}/last-login`,
            sensitivityLevel: "High",
            signalCategory: "ControlObservation",
            signalSubcategory: "StaleUserAccount",
            sourceType: "salesforce.user.last_login_posture",
            timestampObserved
          })
        );
      }
      return signals;
    }),
    ...inventory.loginHistory
      .filter((event) => !/^success$/iu.test(event.Status ?? ""))
      .map((event) =>
        ConnectorSignalInputSchema.parse({
          ...base,
          confidence: 0.84,
          rawPayloadPointer: `salesforce://login-history/${event.Id}`,
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "FailedAuthenticationObserved",
          sourceType: "salesforce.login_history.status",
          timestampObserved: event.LoginTime ?? timestampObserved
        })
      )
  ];
}

async function getSalesforceHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SALESFORCE_CONNECTOR_MANIFEST, context);
  }
  const startedAt = Date.now();
  const config = SalesforceOAuthConfigSchema.parse(context.config);
  const token = await getSalesforceAccessToken(config);
  await fetchSalesforceQuery({
    accessToken: token.access_token,
    instanceUrl: token.instance_url,
    maxRecords: 1,
    pathName: salesforceQueryPath(
      config.apiVersion,
      "SELECT Id FROM Organization LIMIT 1"
    ),
    schema: SalesforceOrganizationSchema.pick({ Id: true })
  });

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail:
      "Salesforce OAuth and read-only Organization query verified. No business objects or mutation resources were called.",
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

function createSalesforceConnector(): Connector {
  return {
    manifest: SALESFORCE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? SALESFORCE_FIXTURE_INVENTORY
        : await loadSalesforceLiveInventory(
            SalesforceOAuthConfigSchema.parse(parsedContext.config)
          );
      return createSalesforceSignals(inventory);
    },
    async healthCheck(context) {
      return getSalesforceHealth(
        ConnectorExecutionContextSchema.parse(context)
      );
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? SALESFORCE_FIXTURE_INVENTORY
        : await loadSalesforceLiveInventory(
            SalesforceOAuthConfigSchema.parse(parsedContext.config)
          );
      return ConnectorSyncResultSchema.parse({
        assets: createSalesforceAssets(inventory),
        health: parsedContext.mockMode
          ? createMockHealth(SALESFORCE_CONNECTOR_MANIFEST, parsedContext)
          : ConnectorHealthSchema.parse({
              authorizationVerified: true,
              checkedAt: new Date().toISOString(),
              detail:
                "Salesforce OAuth and read-only organization, user, and optional login-history queries completed. No business objects or mutation resources were called.",
              latencyMs: null,
              status: "Healthy"
            }),
        signals: createSalesforceSignals(inventory).map((signal) =>
          createTimestampedSignal(
            SALESFORCE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

