function herokuRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function herokuRecordArray(value: unknown) {
  return Array.isArray(value)
    ? value.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
    : [];
}

function herokuStringOrNull(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : null;
}

function herokuBoolean(value: unknown) {
  return typeof value === "boolean" ? value : false;
}

function herokuNumber(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function parseHerokuAccount(value: unknown): HerokuAccount {
  const account = herokuRecord(value);

  return {
    id: connectorString(account.id, "unknown-account"),
    verified: herokuBoolean(account.verified)
  };
}

function parseHerokuFormation(item: Record<string, unknown>) {
  return {
    quantity: herokuNumber(item.quantity),
    size: herokuStringOrNull(herokuRecord(item.size).name),
    type: connectorString(item.type, "unknown")
  } satisfies HerokuFormation;
}

function parseHerokuDomain(item: Record<string, unknown>) {
  return {
    id: connectorString(item.id, "unknown-domain"),
    kind: connectorString(item.kind, "custom"),
    status: connectorString(item.status, "unknown")
  } satisfies HerokuDomain;
}

function parseHerokuApp(
  item: Record<string, unknown>,
  formation: HerokuFormation[],
  domains: HerokuDomain[]
) {
  const owner = herokuRecord(item.owner);

  return {
    domainCount: domains.length,
    dynoQuantity: formation.reduce((total, processType) => {
      return total + processType.quantity;
    }, 0),
    formation,
    id: connectorString(item.id, "unknown-app"),
    internalRouting: herokuBoolean(item.internal_routing),
    maintenance: herokuBoolean(item.maintenance),
    name: connectorString(item.name, "unknown-app"),
    ownerKind: herokuStringOrNull(owner.type),
    region: connectorString(herokuRecord(item.region).name, "unknown-region"),
    stack: herokuStringOrNull(herokuRecord(item.stack).name),
    status: herokuStringOrNull(item.archived_at) ? "archived" : "active"
  } satisfies HerokuApp;
}

