function herokuApiUrl(config: HerokuApiTokenConfig, pathName: string) {
  const baseUrl = `${config.apiBaseUrl.replace(/\/+$/u, "")}/`;
  const safePath = pathName.replace(/^\/+/u, "");

  return new URL(safePath, baseUrl).toString();
}

function assertHerokuReadOnlyPath(pathName: string) {
  const pathname = new URL(pathName, "https://api.heroku.com").pathname;
  const allowed =
    pathname === "/account" ||
    pathname === "/apps" ||
    /^\/apps\/[^/]+\/(?:formation|domains)$/u.test(pathname);

  if (
    !allowed ||
    /\/(?:config-vars|logs?|builds?|releases?|dynos?|addons?|actions?|transfers?|oauth|authorizations?)(?:\/|$)/iu.test(
      pathname
    )
  ) {
    throw new Error(
      "Heroku connector only allows read-only account, app, formation, and domain inventory endpoints."
    );
  }
}

function herokuHeaders(config: HerokuApiTokenConfig) {
  return {
    accept: "application/vnd.heroku+json; version=3",
    authorization: `Bearer ${config.apiToken}`
  };
}

function herokuErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Heroku API error.";
}

async function herokuFetchJson(
  config: HerokuApiTokenConfig,
  pathName: string,
  options: {
    optional?: boolean;
  } = {}
) {
  assertHerokuReadOnlyPath(pathName);

  const response = await connectorFetch(herokuApiUrl(config, pathName), {
    headers: herokuHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    if (options.optional && [403, 404].includes(response.status)) {
      return [];
    }

    throw new Error(`Heroku API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as unknown;
  } catch {
    return options.optional ? [] : {};
  }
}

async function loadHerokuLiveInventory(
  config: HerokuApiTokenConfig
): Promise<HerokuInventory> {
  const account = parseHerokuAccount(await herokuFetchJson(config, "/account"));
  const apps = herokuRecordArray(await herokuFetchJson(config, "/apps"));
  const parsedApps: HerokuApp[] = [];

  for (const app of apps) {
    const appId = connectorString(app.id, connectorString(app.name, ""));
    const formation = config.includeFormation
      ? herokuRecordArray(
          await herokuFetchJson(
            config,
            `/apps/${encodeURIComponent(appId)}/formation`,
            {
              optional: true
            }
          )
        ).map(parseHerokuFormation)
      : [];
    const domains = config.includeDomains
      ? herokuRecordArray(
          await herokuFetchJson(
            config,
            `/apps/${encodeURIComponent(appId)}/domains`,
            {
              optional: true
            }
          )
        ).map(parseHerokuDomain)
      : [];

    parsedApps.push(parseHerokuApp(app, formation, domains));
  }

  return {
    account,
    apps: parsedApps
  };
}

async function loadHerokuInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadHerokuFixtureInventory();
  }

  const config = HerokuApiTokenConfigSchema.parse(context.config);

  return loadHerokuLiveInventory(config);
}

function createHerokuAssets(inventory: HerokuInventory): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality: "High",
      environment: "heroku",
      identifiers: {
        provider: "heroku",
        resourceKind: "HerokuAccount",
        verified: inventory.account.verified
      },
      internetExposed: inventory.apps.some((app) => app.domainCount > 0),
      name: `heroku-account/${inventory.account.id}`,
      owner: "cloud",
      status: inventory.account.verified ? "Active" : "Inactive",
      tags: ["heroku", "account"]
    }),
    ...inventory.apps.map((app) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: app.domainCount > 0 ? "High" : "Moderate",
        environment: "heroku",
        identifiers: {
          domainCount: app.domainCount,
          dynoQuantity: app.dynoQuantity,
          formationTypeCount: app.formation.length,
          internalRouting: app.internalRouting,
          maintenance: app.maintenance,
          ownerKind: app.ownerKind,
          provider: "heroku",
          region: app.region,
          resourceKind: "HerokuApp",
          stack: app.stack
        },
        internetExposed: app.domainCount > 0 && !app.internalRouting,
        name: `heroku-app/${app.name}`,
        owner: "cloud",
        status: app.status === "archived" ? "Archived" : "Active",
        tags: ["heroku", "app"]
      })
    )
  ];
}

function createHerokuSignals(
  inventory: HerokuInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: `heroku://account/${encodeURIComponent(inventory.account.id)}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Restricted",
      signalCategory: "Cloud",
      signalSubcategory: "HerokuAccountInventory",
      sourceType: "heroku.account.inventory",
      timestampObserved
    }),
    ...inventory.apps.flatMap((app) => {
      const signals = [
        ConnectorSignalInputSchema.parse({
          confidence: 0.88,
          freshness: "Fresh",
          rawPayloadPointer: `heroku://apps/${encodeURIComponent(app.id)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: app.domainCount > 0 ? "High" : "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "HerokuAppObserved",
          sourceType: "heroku.app",
          timestampObserved
        })
      ];

      if (app.domainCount > 0 && !app.internalRouting) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.82,
            freshness: "Fresh",
            rawPayloadPointer: `heroku://apps/${encodeURIComponent(app.id)}/domains`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "High",
            signalCategory: "Exposure",
            signalSubcategory: "HerokuPublicAppExposure",
            sourceType: "heroku.app.public_domain",
            timestampObserved
          })
        );
      }

      if (app.formation.length > 0) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.84,
            freshness: "Fresh",
            rawPayloadPointer: `heroku://apps/${encodeURIComponent(app.id)}/formation`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "Cloud",
            signalSubcategory: "HerokuFormationObserved",
            sourceType: "heroku.app.formation",
            timestampObserved
          })
        );
      }

      if (app.maintenance) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.8,
            freshness: "Fresh",
            rawPayloadPointer: `heroku://apps/${encodeURIComponent(app.id)}/maintenance`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "ControlObservation",
            signalSubcategory: "HerokuMaintenanceModeEnabled",
            sourceType: "heroku.app.maintenance",
            timestampObserved
          })
        );
      }

      return signals;
    })
  ];
}

async function getHerokuHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(HEROKU_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = HerokuApiTokenConfigSchema.parse(context.config);

  try {
    await herokuFetchJson(config, "/account");

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Heroku API token verified for read-only inventory. No config-var, log, build, release, dyno, add-on, or mutation endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Heroku health check failed: ${herokuErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createHerokuConnector(): Connector {
  return {
    manifest: HEROKU_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadHerokuInventory(parsedContext);

      return createHerokuSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getHerokuHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadHerokuInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(HEROKU_CONNECTOR_MANIFEST, parsedContext)
        : await getHerokuHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createHerokuAssets(inventory),
        health,
        signals: createHerokuSignals(inventory).map((signal) =>
          createTimestampedSignal(
            HEROKU_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

