function databricksApiUrl(config: DatabricksPatConfig, pathName: string) {
  const baseUrl = `${config.workspaceUrl.replace(/\/+$/u, "")}/`;
  const safePath = pathName.replace(/^\/+/u, "");

  return new URL(safePath, baseUrl).toString();
}

function assertDatabricksReadOnlyPath(pathName: string) {
  const pathname = new URL(pathName, "https://databricks.invalid").pathname;
  const allowed = [
    "/api/2.0/clusters/list",
    "/api/2.1/jobs/list",
    "/api/2.0/sql/warehouses",
    "/api/2.0/workspace/list"
  ].includes(pathname);

  if (
    !allowed ||
    /\/(?:commands?|command-execution|runs?|run-now|submit|cancel|create|delete|edit|reset|start|restart|resize|terminate|permanent-delete|export|import|dbfs|secrets?|libraries\/install|permissions)(?:\/|$)/iu.test(
      pathname
    )
  ) {
    throw new Error(
      "Databricks connector only allows read-only workspace metadata list endpoints."
    );
  }
}

function databricksHeaders(config: DatabricksPatConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.patToken}`
  };
}

function databricksErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Databricks API error.";
}

async function databricksFetchJson(
  config: DatabricksPatConfig,
  pathName: string,
  options: {
    optional?: boolean;
  } = {}
) {
  assertDatabricksReadOnlyPath(pathName);

  const response = await connectorFetch(databricksApiUrl(config, pathName), {
    headers: databricksHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    if (options.optional && [403, 404].includes(response.status)) {
      return {};
    }

    throw new Error(`Databricks API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function loadDatabricksLiveInventory(
  config: DatabricksPatConfig
): Promise<DatabricksInventory> {
  const [clustersJson, jobsJson, warehousesJson, workspaceJson] =
    await Promise.all([
      config.includeClusters
        ? databricksFetchJson(config, "/api/2.0/clusters/list", {
            optional: true
          })
        : {},
      config.includeJobs
        ? databricksFetchJson(
            config,
            `/api/2.1/jobs/list?limit=${config.maxItems}`,
            {
              optional: true
            }
          )
        : {},
      config.includeSQLWarehouses
        ? databricksFetchJson(config, "/api/2.0/sql/warehouses", {
            optional: true
          })
        : {},
      config.includeWorkspaceObjects
        ? databricksFetchJson(
            config,
            `/api/2.0/workspace/list?path=${encodeURIComponent(config.workspacePath)}`,
            {
              optional: true
            }
          )
        : {}
    ]);
  const clustersRecord = databricksRecord(clustersJson);
  const jobsRecord = databricksRecord(jobsJson);
  const warehousesRecord = databricksRecord(warehousesJson);
  const workspaceRecord = databricksRecord(workspaceJson);

  return {
    clusters: databricksRecordArray(clustersRecord.clusters)
      .map(parseDatabricksCluster)
      .filter((cluster) => cluster.id !== "unknown-cluster")
      .slice(0, config.maxItems),
    jobs: databricksRecordArray(jobsRecord.jobs)
      .map(parseDatabricksJob)
      .filter((job) => job.id !== "unknown-job")
      .slice(0, config.maxItems),
    sqlWarehouses: databricksRecordArray(warehousesRecord.warehouses)
      .map(parseDatabricksSQLWarehouse)
      .filter((warehouse) => warehouse.id !== "unknown-warehouse")
      .slice(0, config.maxItems),
    workspaceHost: databricksWorkspaceHost(config.workspaceUrl),
    workspaceObjects: databricksRecordArray(workspaceRecord.objects)
      .map(parseDatabricksWorkspaceObject)
      .filter((object) => object.id !== "unknown-object")
      .slice(0, config.maxItems)
  };
}

async function loadDatabricksInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadDatabricksFixtureInventory(context.config);
  }

  const config = DatabricksPatConfigSchema.parse(context.config);

  return loadDatabricksLiveInventory(config);
}

function createDatabricksAssets(
  inventory: DatabricksInventory
): ConnectorAssetInput[] {
  const workspaceAsset = createMockAsset({
    assetType: "CloudResource",
    businessCriticality: "High",
    environment: "databricks",
    identifiers: {
      clusterCount: inventory.clusters.length,
      jobCount: inventory.jobs.length,
      provider: "databricks",
      resourceKind: "DatabricksWorkspace",
      sqlWarehouseCount: inventory.sqlWarehouses.length,
      workspaceObjectCount: inventory.workspaceObjects.length
    },
    internetExposed: false,
    name: `databricks-workspace/${inventory.workspaceHost}`,
    owner: "data-platform",
    status: "Active",
    tags: ["databricks", "workspace"]
  });
  const clusterAssets = inventory.clusters.map((cluster) =>
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality:
        cluster.state === "RUNNING" || cluster.dataSecurityMode === null
          ? "High"
          : "Moderate",
      environment: "databricks",
      identifiers: {
        dataSecurityMode: cluster.dataSecurityMode,
        nodeTypeId: cluster.nodeTypeId,
        provider: "databricks",
        resourceKind: "DatabricksCluster",
        source: cluster.source,
        sparkVersion: cluster.sparkVersion
      },
      internetExposed: false,
      name: `databricks-cluster/${cluster.name}`,
      owner: "data-platform",
      status: cluster.state === "TERMINATED" ? "Inactive" : "Active",
      tags: ["databricks", "cluster"]
    })
  );
  const jobAssets = inventory.jobs.map((job) =>
    createMockAsset({
      assetType: "Application",
      businessCriticality:
        job.hasSchedule || job.taskCount > 1 ? "High" : "Moderate",
      environment: "databricks",
      identifiers: {
        format: job.format,
        hasGitSource: job.hasGitSource,
        hasSchedule: job.hasSchedule,
        provider: "databricks",
        resourceKind: "DatabricksJob",
        taskCount: job.taskCount
      },
      internetExposed: false,
      name: `databricks-job/${job.name}`,
      owner: "data-platform",
      status: "Active",
      tags: ["databricks", "job"]
    })
  );
  const warehouseAssets = inventory.sqlWarehouses.map((warehouse) =>
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality:
        warehouse.state === "RUNNING" || warehouse.warehouseType === "PRO"
          ? "High"
          : "Moderate",
      environment: "databricks",
      identifiers: {
        autoStopMinutes: warehouse.autoStopMinutes,
        channelName: warehouse.channelName,
        clusterSize: warehouse.clusterSize,
        provider: "databricks",
        resourceKind: "DatabricksSQLWarehouse",
        warehouseType: warehouse.warehouseType
      },
      internetExposed: false,
      name: `databricks-sql-warehouse/${warehouse.name}`,
      owner: "data-platform",
      status: warehouse.state === "STOPPED" ? "Inactive" : "Active",
      tags: ["databricks", "sql-warehouse"]
    })
  );
  const workspaceObjectAssets = inventory.workspaceObjects.map((object) =>
    createMockAsset({
      assetType:
        object.objectType === "NOTEBOOK" ||
        object.objectType === "REPO" ||
        object.objectType === "DASHBOARD"
          ? "Application"
          : "Other",
      businessCriticality:
        object.objectType === "REPO" || object.objectType === "DASHBOARD"
          ? "High"
          : "Moderate",
      environment: "databricks",
      identifiers: {
        language: object.language,
        pathDepth: object.pathDepth,
        provider: "databricks",
        resourceKind: "DatabricksWorkspaceObject",
        workspaceObjectType: object.objectType
      },
      internetExposed: false,
      name: `databricks-workspace-object/${object.objectType.toLowerCase()}/${object.id}`,
      owner: "data-platform",
      status: "Active",
      tags: ["databricks", "workspace-object"]
    })
  );

  return [
    workspaceAsset,
    ...clusterAssets,
    ...jobAssets,
    ...warehouseAssets,
    ...workspaceObjectAssets
  ];
}

function createDatabricksSignals(
  inventory: DatabricksInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const workspaceSignal = ConnectorSignalInputSchema.parse({
    confidence: 0.9,
    freshness: "Fresh",
    rawPayloadPointer: `databricks://workspaces/${encodeURIComponent(inventory.workspaceHost)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "Cloud",
    signalSubcategory: "DatabricksWorkspaceInventory",
    sourceType: "databricks.workspace.inventory",
    timestampObserved
  });
  const clusterSignals = inventory.clusters.flatMap((cluster) => {
    const signals = [
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `databricks://clusters/${encodeURIComponent(cluster.id)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          cluster.state === "RUNNING" || cluster.dataSecurityMode === null
            ? "High"
            : "Moderate",
        signalCategory: "Cloud",
        signalSubcategory: "DatabricksClusterObserved",
        sourceType: "databricks.cluster",
        timestampObserved
      })
    ];

    if (cluster.dataSecurityMode === null) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.76,
          freshness: "Fresh",
          rawPayloadPointer: `databricks://clusters/${encodeURIComponent(cluster.id)}/access-mode`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "ControlObservation",
          signalSubcategory: "DatabricksClusterAccessModeMissing",
          sourceType: "databricks.cluster.access_mode",
          timestampObserved
        })
      );
    }

    return signals;
  });
  const jobSignals = inventory.jobs.flatMap((job) => {
    const signals = [
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `databricks://jobs/${encodeURIComponent(job.id)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: job.hasSchedule ? "High" : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "DatabricksJobObserved",
        sourceType: "databricks.job",
        timestampObserved
      })
    ];

    if (job.hasGitSource) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `databricks://jobs/${encodeURIComponent(job.id)}/git-source`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Repository",
          signalSubcategory: "DatabricksJobGitSourceObserved",
          sourceType: "databricks.job.git_source",
          timestampObserved
        })
      );
    }

    return signals;
  });
  const warehouseSignals = inventory.sqlWarehouses.map((warehouse) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.84,
      freshness: "Fresh",
      rawPayloadPointer: `databricks://sql-warehouses/${encodeURIComponent(warehouse.id)}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: warehouse.state === "RUNNING" ? "High" : "Moderate",
      signalCategory: "Cloud",
      signalSubcategory: "DatabricksSQLWarehouseObserved",
      sourceType: "databricks.sql_warehouse",
      timestampObserved
    })
  );
  const workspaceObjectSignals = inventory.workspaceObjects.map((object) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.78,
      freshness: "Fresh",
      rawPayloadPointer: `databricks://workspace-objects/${encodeURIComponent(object.id)}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel:
        object.objectType === "REPO" || object.objectType === "DASHBOARD"
          ? "High"
          : "Moderate",
      signalCategory: "Asset",
      signalSubcategory: "DatabricksWorkspaceObjectObserved",
      sourceType: "databricks.workspace.object",
      timestampObserved
    })
  );

  return [
    workspaceSignal,
    ...clusterSignals,
    ...jobSignals,
    ...warehouseSignals,
    ...workspaceObjectSignals
  ];
}

function databricksHealthPath(config: DatabricksPatConfig) {
  if (config.includeWorkspaceObjects) {
    return `/api/2.0/workspace/list?path=${encodeURIComponent(config.workspacePath)}`;
  }

  if (config.includeClusters) {
    return "/api/2.0/clusters/list";
  }

  if (config.includeJobs) {
    return `/api/2.1/jobs/list?limit=${config.maxItems}`;
  }

  if (config.includeSQLWarehouses) {
    return "/api/2.0/sql/warehouses";
  }

  return null;
}

async function getDatabricksHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(DATABRICKS_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = DatabricksPatConfigSchema.parse(context.config);
  const healthPath = databricksHealthPath(config);

  if (!healthPath) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: "No read-only Databricks inventory toggles are enabled.",
      latencyMs: Date.now() - startedAt,
      status: "Degraded"
    });
  }

  try {
    await databricksFetchJson(config, healthPath);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Databricks personal access token verified for read-only metadata inventory. No notebook export, DBFS, secret, command execution, job run, cluster mutation, or SQL query endpoints were called.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Databricks health check failed: ${databricksErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createDatabricksConnector(): Connector {
  return {
    manifest: DATABRICKS_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadDatabricksInventory(parsedContext);

      return createDatabricksSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getDatabricksHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadDatabricksInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(DATABRICKS_CONNECTOR_MANIFEST, parsedContext)
        : await getDatabricksHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createDatabricksAssets(inventory),
        health,
        signals: createDatabricksSignals(inventory).map((signal) =>
          createTimestampedSignal(
            DATABRICKS_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const SnowflakeAccessTokenConfigSchema = z.object({
  accessToken: z.string().min(1),
  accountUrl: z.url(),
  database: z.string().min(1).optional(),
  includeDatabases: z.boolean().default(true),
  includeGrants: z.boolean().default(true),
  includeSchemas: z.boolean().default(true),
  includeUsers: z.boolean().default(true),
  includeWarehouses: z.boolean().default(true),
  role: z.string().min(1).optional(),
  sqlApiPath: z.string().min(1).default("/api/v2/statements"),
  statementLimit: z.number().int().min(1).max(500).default(100),
  warehouse: z.string().min(1).optional()
});

type SnowflakeAccessTokenConfig = z.infer<
  typeof SnowflakeAccessTokenConfigSchema
>;

type SnowflakeWarehouse = {
  autoSuspend: number;
  name: string;
  size: string;
  state: string;
};

type SnowflakeDatabase = {
  createdOn: string | null;
  name: string;
  owner: string | null;
};

type SnowflakeSchema = {
  databaseName: string;
  name: string;
  owner: string | null;
};

type SnowflakeUser = {
  defaultRole: string | null;
  disabled: boolean;
  hasMfa: boolean | null;
  hasPassword: boolean;
  name: string;
};

type SnowflakeGrant = {
  granteeName: string;
  grantedOn: string;
  name: string;
  privilege: string;
};

type SnowflakeInventory = {
  accountName: string;
  databases: SnowflakeDatabase[];
  grants: SnowflakeGrant[];
  schemas: SnowflakeSchema[];
  users: SnowflakeUser[];
  warehouses: SnowflakeWarehouse[];
};

