const SNOWFLAKE_READ_ONLY_VERB_DENYLIST =
  /\b(?:ALTER|CALL|COPY|CREATE|DELETE|DROP|EXEC(?:UTE)?|GET|GRANT|INSERT|MERGE|PUT|REMOVE|REVOKE|TRUNCATE|UPDATE|USE)\b/iu;

function assertSnowflakeReadOnlyStatement(statement: string) {
  const normalized = statement.trim().replace(/\s+/gu, " ");

  if (!/^SELECT\b/iu.test(normalized)) {
    throw new Error(
      "Snowflake connector only allows generated SELECT queries."
    );
  }

  if (
    normalized.includes(";") ||
    SNOWFLAKE_READ_ONLY_VERB_DENYLIST.test(normalized)
  ) {
    throw new Error("Snowflake connector rejected a non-read-only statement.");
  }
}

function snowflakeStatementUrl(config: SnowflakeAccessTokenConfig) {
  return `${config.accountUrl.replace(/\/+$/u, "")}/${config.sqlApiPath.replace(/^\/+/u, "")}`;
}

function snowflakeStatementBody(
  config: SnowflakeAccessTokenConfig,
  statement: string
) {
  return JSON.stringify({
    database: config.database,
    role: config.role,
    statement,
    timeout: 30,
    warehouse: config.warehouse
  });
}

function snowflakeQueryLimit(config: SnowflakeAccessTokenConfig) {
  return config.statementLimit;
}

function snowflakeQueries(config: SnowflakeAccessTokenConfig) {
  const limit = snowflakeQueryLimit(config);

  return {
    account: "SELECT CURRENT_ACCOUNT() AS ACCOUNT_NAME",
    databases: `SELECT DATABASE_NAME, OWNER, CREATED AS CREATED_ON FROM SNOWFLAKE.ACCOUNT_USAGE.DATABASES WHERE DELETED IS NULL LIMIT ${limit}`,
    grants: `SELECT GRANTEE_NAME, GRANTED_ON, NAME, PRIVILEGE FROM SNOWFLAKE.ACCOUNT_USAGE.GRANTS_TO_ROLES WHERE DELETED_ON IS NULL LIMIT ${limit}`,
    schemas: `SELECT CATALOG_NAME AS DATABASE_NAME, SCHEMA_NAME, OWNER FROM SNOWFLAKE.ACCOUNT_USAGE.SCHEMATA WHERE DELETED IS NULL LIMIT ${limit}`,
    users: `SELECT NAME, DISABLED, HAS_PASSWORD, HAS_MFA, DEFAULT_ROLE FROM SNOWFLAKE.ACCOUNT_USAGE.USERS WHERE DELETED_ON IS NULL LIMIT ${limit}`,
    warehouses: `SELECT WAREHOUSE_NAME, STATE, SIZE, AUTO_SUSPEND FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSES LIMIT ${limit}`
  };
}

function snowflakeRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function snowflakeString(value: unknown, fallback = "unknown") {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
}

function snowflakeNullableString(value: unknown) {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : null;
}

function snowflakeBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return /^(true|yes|y|1)$/iu.test(value);
  }

  return false;
}

function snowflakeNullableBoolean(value: unknown) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string" && value.trim().length > 0) {
    return /^(true|yes|y|1)$/iu.test(value);
  }

  return null;
}

function snowflakeNumber(value: unknown, fallback = 0) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);

    return Number.isFinite(parsed) ? parsed : fallback;
  }

  return fallback;
}

function snowflakeRowsFromPayload(payload: unknown) {
  if (Array.isArray(payload)) {
    return payload.flatMap((item) =>
      Boolean(item) && typeof item === "object"
        ? [item as Record<string, unknown>]
        : []
    );
  }

  const record = snowflakeRecord(payload);

  for (const key of ["rows", "items", "results"]) {
    if (Array.isArray(record[key])) {
      return (record[key] as unknown[]).flatMap((item) =>
        Boolean(item) && typeof item === "object"
          ? [item as Record<string, unknown>]
          : []
      );
    }
  }

  if (Array.isArray(record.data)) {
    const rowType = snowflakeRecord(record.resultSetMetaData).rowType;
    const columns = Array.isArray(rowType)
      ? rowType.map((item) => snowflakeString(snowflakeRecord(item).name, ""))
      : [];

    return record.data.flatMap((row) => {
      if (!Array.isArray(row)) {
        return [];
      }

      return [
        Object.fromEntries(
          row.map((value, index) => [
            columns[index] ?? `COL${index + 1}`,
            value
          ])
        )
      ];
    });
  }

  return [];
}

function snowflakeRowValue(row: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const exact = row[key];

    if (exact !== undefined && exact !== null) {
      return exact;
    }

    const matchedKey = Object.keys(row).find(
      (candidate) => candidate.toLowerCase() === key.toLowerCase()
    );

    if (matchedKey) {
      return row[matchedKey];
    }
  }

  return null;
}

async function snowflakeExecuteReadOnly(
  config: SnowflakeAccessTokenConfig,
  statement: string
) {
  assertSnowflakeReadOnlyStatement(statement);

  const response = await connectorFetch(snowflakeStatementUrl(config), {
    body: snowflakeStatementBody(config, statement),
    headers: {
      accept: "application/json",
      authorization: `Bearer ${config.accessToken}`,
      "content-type": "application/json"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(`Snowflake SQL API returned status ${response.status}.`);
  }

  return snowflakeRowsFromPayload(await response.json());
}

function parseSnowflakeWarehouse(row: Record<string, unknown>) {
  return {
    autoSuspend: snowflakeNumber(
      snowflakeRowValue(row, ["AUTO_SUSPEND", "autoSuspend"]),
      0
    ),
    name: snowflakeString(
      snowflakeRowValue(row, ["WAREHOUSE_NAME", "name", "warehouseName"]),
      "unknown-warehouse"
    ),
    size: snowflakeString(snowflakeRowValue(row, ["SIZE", "size"]), "unknown"),
    state: snowflakeString(
      snowflakeRowValue(row, ["STATE", "state"]),
      "unknown"
    )
  } satisfies SnowflakeWarehouse;
}

function parseSnowflakeDatabase(row: Record<string, unknown>) {
  return {
    createdOn: snowflakeNullableString(
      snowflakeRowValue(row, ["CREATED_ON", "createdOn", "CREATED"])
    ),
    name: snowflakeString(
      snowflakeRowValue(row, ["DATABASE_NAME", "name", "databaseName"]),
      "unknown-database"
    ),
    owner: snowflakeNullableString(snowflakeRowValue(row, ["OWNER", "owner"]))
  } satisfies SnowflakeDatabase;
}

function parseSnowflakeSchema(row: Record<string, unknown>) {
  return {
    databaseName: snowflakeString(
      snowflakeRowValue(row, ["DATABASE_NAME", "CATALOG_NAME", "databaseName"]),
      "unknown-database"
    ),
    name: snowflakeString(
      snowflakeRowValue(row, ["SCHEMA_NAME", "name", "schemaName"]),
      "unknown-schema"
    ),
    owner: snowflakeNullableString(snowflakeRowValue(row, ["OWNER", "owner"]))
  } satisfies SnowflakeSchema;
}

function parseSnowflakeUser(row: Record<string, unknown>) {
  return {
    defaultRole: snowflakeNullableString(
      snowflakeRowValue(row, ["DEFAULT_ROLE", "defaultRole"])
    ),
    disabled: snowflakeBoolean(
      snowflakeRowValue(row, ["DISABLED", "disabled"])
    ),
    hasMfa: snowflakeNullableBoolean(
      snowflakeRowValue(row, ["HAS_MFA", "hasMfa", "EXT_AUTHN_DUO"])
    ),
    hasPassword: snowflakeBoolean(
      snowflakeRowValue(row, ["HAS_PASSWORD", "hasPassword"])
    ),
    name: snowflakeString(
      snowflakeRowValue(row, ["NAME", "name", "userName"]),
      "unknown-user"
    )
  } satisfies SnowflakeUser;
}

function parseSnowflakeGrant(row: Record<string, unknown>) {
  return {
    granteeName: snowflakeString(
      snowflakeRowValue(row, ["GRANTEE_NAME", "granteeName"]),
      "unknown-grantee"
    ),
    grantedOn: snowflakeString(
      snowflakeRowValue(row, ["GRANTED_ON", "grantedOn"]),
      "unknown"
    ),
    name: snowflakeString(
      snowflakeRowValue(row, ["NAME", "name"]),
      "unknown-grant"
    ),
    privilege: snowflakeString(
      snowflakeRowValue(row, ["PRIVILEGE", "privilege"]),
      "unknown"
    )
  } satisfies SnowflakeGrant;
}

