async function loadSnowflakeLiveInventory(
  config: SnowflakeAccessTokenConfig
): Promise<SnowflakeInventory> {
  const queries = snowflakeQueries(config);
  const accountRows = await snowflakeExecuteReadOnly(config, queries.account);
  const accountName = snowflakeString(
    snowflakeRowValue(accountRows[0] ?? {}, ["ACCOUNT_NAME"]),
    "unknown-account"
  );
  const [warehouses, databases, schemas, users, grants] = await Promise.all([
    config.includeWarehouses
      ? snowflakeExecuteReadOnly(config, queries.warehouses)
      : Promise.resolve([]),
    config.includeDatabases
      ? snowflakeExecuteReadOnly(config, queries.databases)
      : Promise.resolve([]),
    config.includeSchemas
      ? snowflakeExecuteReadOnly(config, queries.schemas)
      : Promise.resolve([]),
    config.includeUsers
      ? snowflakeExecuteReadOnly(config, queries.users)
      : Promise.resolve([]),
    config.includeGrants
      ? snowflakeExecuteReadOnly(config, queries.grants)
      : Promise.resolve([])
  ]);

  return {
    accountName,
    databases: databases.map(parseSnowflakeDatabase),
    grants: grants.map(parseSnowflakeGrant),
    schemas: schemas.map(parseSnowflakeSchema),
    users: users.map(parseSnowflakeUser),
    warehouses: warehouses.map(parseSnowflakeWarehouse)
  };
}

async function loadSnowflakeInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadSnowflakeFixtureInventory();
  }

  return loadSnowflakeLiveInventory(
    SnowflakeAccessTokenConfigSchema.parse(context.config)
  );
}

function isLargeSnowflakeWarehouse(warehouse: SnowflakeWarehouse) {
  return /^(?:X-?LARGE|2X-?LARGE|3X-?LARGE|4X-?LARGE|5X-?LARGE|6X-?LARGE)$/iu.test(
    warehouse.size
  );
}

function createSnowflakeAssets(
  inventory: SnowflakeInventory
): ConnectorAssetInput[] {
  return [
    createMockAsset({
      assetType: "Service",
      businessCriticality: "High",
      environment: "snowflake",
      identifiers: {
        databaseCount: inventory.databases.length,
        provider: "snowflake",
        schemaCount: inventory.schemas.length,
        userCount: inventory.users.length,
        warehouseCount: inventory.warehouses.length
      },
      internetExposed: false,
      name: `snowflake-account/${inventory.accountName}`,
      owner: "data-platform",
      status: "Active",
      tags: ["snowflake", "data-platform"]
    }),
    ...inventory.warehouses.map((warehouse) =>
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: isLargeSnowflakeWarehouse(warehouse)
          ? "High"
          : "Moderate",
        environment: "snowflake",
        identifiers: {
          autoSuspend: warehouse.autoSuspend,
          provider: "snowflake",
          size: warehouse.size,
          state: warehouse.state
        },
        internetExposed: false,
        name: `snowflake-warehouse/${warehouse.name}`,
        owner: "data-platform",
        status:
          warehouse.state.toLowerCase() === "suspended" ? "Inactive" : "Active",
        tags: ["snowflake", "warehouse"]
      })
    ),
    ...inventory.databases.map((database) =>
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: "High",
        environment: "snowflake",
        identifiers: {
          createdOn: database.createdOn,
          owner: database.owner,
          provider: "snowflake"
        },
        internetExposed: false,
        name: `snowflake-database/${database.name}`,
        owner: "data-platform",
        status: "Active",
        tags: ["snowflake", "database"]
      })
    )
  ];
}

function isPrivilegedSnowflakeGrant(grant: SnowflakeGrant) {
  return /\b(?:ACCOUNTADMIN|SECURITYADMIN|SYSADMIN|OWNERSHIP|MONITOR|IMPORTED PRIVILEGES)\b/iu.test(
    `${grant.granteeName} ${grant.name} ${grant.privilege}`
  );
}

function createSnowflakeSignals(
  inventory: SnowflakeInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return [
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: `snowflake://account/${encodeURIComponent(inventory.accountName)}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Restricted",
      signalCategory: "Cloud",
      signalSubcategory: "SnowflakeAccountInventory",
      sourceType: "snowflake.account.inventory",
      timestampObserved
    }),
    ...inventory.warehouses.flatMap((warehouse) => {
      const signals = [
        ConnectorSignalInputSchema.parse({
          confidence: 0.88,
          freshness: "Fresh",
          rawPayloadPointer: `snowflake://warehouses/${encodeURIComponent(warehouse.name)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: isLargeSnowflakeWarehouse(warehouse)
            ? "High"
            : "Moderate",
          signalCategory: "Cloud",
          signalSubcategory: "SnowflakeWarehouseObserved",
          sourceType: "snowflake.warehouse",
          timestampObserved
        })
      ];

      if (isLargeSnowflakeWarehouse(warehouse) || warehouse.autoSuspend === 0) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.78,
            freshness: "Fresh",
            rawPayloadPointer: `snowflake://warehouses/${encodeURIComponent(warehouse.name)}/cost-risk`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Moderate",
            signalCategory: "ControlObservation",
            signalSubcategory: "SnowflakeWarehouseCostGuardrailGap",
            sourceType: "snowflake.warehouse.cost_guardrail_gap",
            timestampObserved
          })
        );
      }

      return signals;
    }),
    ...inventory.databases.map((database) =>
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `snowflake://databases/${encodeURIComponent(database.name)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "High",
        signalCategory: "Asset",
        signalSubcategory: "SnowflakeDatabaseObserved",
        sourceType: "snowflake.database",
        timestampObserved
      })
    ),
    ...inventory.schemas.map((schema) =>
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `snowflake://databases/${encodeURIComponent(schema.databaseName)}/schemas/${encodeURIComponent(schema.name)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "SnowflakeSchemaObserved",
        sourceType: "snowflake.schema",
        timestampObserved
      })
    ),
    ...inventory.users.flatMap((user) => {
      const signals = [
        ConnectorSignalInputSchema.parse({
          confidence: 0.84,
          freshness: user.disabled ? "Stale" : "Fresh",
          rawPayloadPointer: `snowflake://users/${encodeURIComponent(user.name)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Identity",
          signalSubcategory: "SnowflakeUserObserved",
          sourceType: "snowflake.user",
          timestampObserved
        })
      ];

      if (user.hasPassword && user.hasMfa === false && !user.disabled) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.78,
            freshness: "Fresh",
            rawPayloadPointer: `snowflake://users/${encodeURIComponent(user.name)}/mfa`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "High",
            signalCategory: "ControlObservation",
            signalSubcategory: "SnowflakeUserMfaGapObserved",
            sourceType: "snowflake.user.mfa_gap",
            timestampObserved
          })
        );
      }

      return signals;
    }),
    ...inventory.grants.map((grant) =>
      ConnectorSignalInputSchema.parse({
        confidence: 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `snowflake://grants/${encodeURIComponent(grant.granteeName)}/${encodeURIComponent(grant.privilege)}/${encodeURIComponent(grant.name)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: isPrivilegedSnowflakeGrant(grant)
          ? "High"
          : "Moderate",
        signalCategory: isPrivilegedSnowflakeGrant(grant)
          ? "Identity"
          : "ControlObservation",
        signalSubcategory: isPrivilegedSnowflakeGrant(grant)
          ? "SnowflakePrivilegedGrantObserved"
          : "SnowflakeGrantObserved",
        sourceType: "snowflake.grant",
        timestampObserved
      })
    )
  ];
}

function snowflakeErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Snowflake API error.";
}

async function getSnowflakeHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SNOWFLAKE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = SnowflakeAccessTokenConfigSchema.parse(context.config);

  try {
    await snowflakeExecuteReadOnly(config, snowflakeQueries(config).account);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Snowflake SQL API token verified for generated read-only metadata SELECT statements. No DDL, DML, role changes, COPY/PUT/GET, or arbitrary customer SQL was executed.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Snowflake health check failed: ${snowflakeErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createSnowflakeConnector(): Connector {
  return {
    manifest: SNOWFLAKE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadSnowflakeInventory(parsedContext);

      return createSnowflakeSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getSnowflakeHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadSnowflakeInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(SNOWFLAKE_CONNECTOR_MANIFEST, parsedContext)
        : await getSnowflakeHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createSnowflakeAssets(inventory),
        health,
        signals: createSnowflakeSignals(inventory).map((signal) =>
          createTimestampedSignal(
            SNOWFLAKE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

