function alibabaRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function alibabaRecordArray(value: unknown) {
  return Array.isArray(value)
    ? value.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
    : [];
}

function alibabaStringArray(value: unknown) {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
}

function alibabaNumber(value: unknown, fallback = 0) {
  const parsed = typeof value === "number" ? value : Number(value);

  return Number.isFinite(parsed) ? parsed : fallback;
}

function alibabaNestedRecordArray(
  value: Record<string, unknown>,
  pathSegments: string[]
) {
  let current: unknown = value;

  for (const segment of pathSegments) {
    current = alibabaRecord(current)[segment];
  }

  return alibabaRecordArray(current);
}

