function alibabaPercentEncode(value: string) {
  return encodeURIComponent(value)
    .replace(
      /[!'()*]/gu,
      (character) => `%${character.charCodeAt(0).toString(16).toUpperCase()}`
    )
    .replace(/%7E/gu, "~");
}

function alibabaCanonicalQuery(params: Record<string, string>) {
  return Object.keys(params)
    .sort()
    .map(
      (key) =>
        `${alibabaPercentEncode(key)}=${alibabaPercentEncode(params[key] ?? "")}`
    )
    .join("&");
}

function assertAlibabaCloudReadOnlyAction(action: string) {
  const allowedActions = new Set([
    "DescribeInstances",
    "DescribeSecurityGroups",
    "ListRoles"
  ]);

  if (
    !allowedActions.has(action) ||
    /(?:Create|Update|Modify|Delete|Attach|Detach|Start|Stop|Reboot|Authorize|Revoke|Put|Set|Run|Exec|Shell|Console|Assume|GetCredential)/iu.test(
      action
    )
  ) {
    throw new Error(
      "Alibaba Cloud connector only allows read-only inventory Describe/List actions."
    );
  }
}

function alibabaSignedRpcUrl(
  config: AlibabaCloudAccessKeyConfig,
  endpoint: string,
  params: Record<string, string>
) {
  assertAlibabaCloudReadOnlyAction(params.Action ?? "");

  const requestParams = {
    AccessKeyId: config.accessKeyId,
    Format: "JSON",
    SignatureMethod: "HMAC-SHA1",
    SignatureNonce: randomUUID(),
    SignatureVersion: "1.0",
    Timestamp: new Date().toISOString(),
    ...params
  };
  const canonicalQuery = alibabaCanonicalQuery(requestParams);
  const stringToSign = `GET&%2F&${alibabaPercentEncode(canonicalQuery)}`;
  const signature = createHmac("sha1", `${config.accessKeySecret}&`)
    .update(stringToSign)
    .digest("base64");
  const signedQuery = `${canonicalQuery}&Signature=${alibabaPercentEncode(
    signature
  )}`;
  const normalizedEndpoint = endpoint.replace(/\/+$/u, "");

  return `${normalizedEndpoint}/?${signedQuery}`;
}

function alibabaCloudErrorDetail(error: unknown) {
  return error instanceof Error
    ? error.message
    : "Unknown Alibaba Cloud API error.";
}

async function alibabaCloudRpcRequest(
  config: AlibabaCloudAccessKeyConfig,
  endpoint: string,
  params: Record<string, string>
) {
  const response = await connectorFetch(
    alibabaSignedRpcUrl(config, endpoint, params),
    {
      headers: {
        accept: "application/json"
      },
      method: "GET"
    }
  );

  if (!response.ok) {
    throw new Error(`Alibaba Cloud API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function parseAlibabaCloudInstance(
  item: Record<string, unknown>,
  fallbackRegionId: string
): AlibabaCloudInstance {
  const publicIpAddress = alibabaStringArray(
    alibabaRecord(item.PublicIpAddress).IpAddress
  );
  const eipAddress = connectorString(
    alibabaRecord(item.EipAddress).IpAddress,
    ""
  );
  const publicAddressCount =
    publicIpAddress.length + (eipAddress.length > 0 ? 1 : 0);
  const privateAddressCount = alibabaStringArray(
    alibabaRecord(alibabaRecord(item.VpcAttributes).PrivateIpAddress).IpAddress
  ).length;
  const securityGroupIds = alibabaStringArray(
    alibabaRecord(item.SecurityGroupIds).SecurityGroupId
  );
  const instanceId = connectorString(item.InstanceId, "unknown-instance");

  return {
    hasPublicAddress: publicAddressCount > 0,
    instanceId,
    internetMaxBandwidthOut: alibabaNumber(item.InternetMaxBandwidthOut),
    name: connectorString(item.InstanceName, instanceId),
    privateAddressCount,
    publicAddressCount,
    regionId: connectorString(item.RegionId, fallbackRegionId),
    securityGroupIds,
    status: connectorString(item.Status, "unknown"),
    vpcId: connectorString(alibabaRecord(item.VpcAttributes).VpcId, ""),
    zoneId: connectorString(item.ZoneId, "")
  };
}

function parseAlibabaCloudSecurityGroup(
  item: Record<string, unknown>,
  fallbackRegionId: string
): AlibabaCloudSecurityGroup {
  const groupId = connectorString(
    item.SecurityGroupId,
    "unknown-security-group"
  );

  return {
    groupId,
    name: connectorString(item.SecurityGroupName, groupId),
    regionId: connectorString(item.RegionId, fallbackRegionId),
    serviceManaged: item.ServiceManaged === true,
    vpcId: connectorString(item.VpcId, "")
  };
}

function parseAlibabaCloudRamRole(
  item: Record<string, unknown>
): AlibabaCloudRamRole {
  const roleName = connectorString(item.RoleName, "unknown-role");

  return {
    arn: connectorString(item.Arn, ""),
    name: roleName
  };
}

async function loadAlibabaCloudLiveInventory(
  config: AlibabaCloudAccessKeyConfig
): Promise<AlibabaCloudInventory> {
  const instancesJson = await alibabaCloudRpcRequest(
    config,
    config.ecsEndpoint,
    {
      Action: "DescribeInstances",
      PageSize: String(config.maxResults),
      RegionId: config.regionId,
      Version: "2014-05-26"
    }
  );
  const securityGroupsJson = config.includeSecurityGroups
    ? await alibabaCloudRpcRequest(config, config.ecsEndpoint, {
        Action: "DescribeSecurityGroups",
        PageSize: String(config.maxResults),
        RegionId: config.regionId,
        Version: "2014-05-26"
      })
    : {};
  const rolesJson = config.includeRamRoles
    ? await alibabaCloudRpcRequest(config, config.ramEndpoint, {
        Action: "ListRoles",
        PageSize: String(config.maxResults),
        Version: "2015-05-01"
      })
    : {};

  return {
    accountId: config.accountId ?? null,
    instances: alibabaNestedRecordArray(instancesJson, [
      "Instances",
      "Instance"
    ]).map((item) => parseAlibabaCloudInstance(item, config.regionId)),
    regionId: config.regionId,
    roles: alibabaNestedRecordArray(rolesJson, ["Roles", "Role"]).map(
      parseAlibabaCloudRamRole
    ),
    securityGroups: alibabaNestedRecordArray(securityGroupsJson, [
      "SecurityGroups",
      "SecurityGroup"
    ]).map((item) => parseAlibabaCloudSecurityGroup(item, config.regionId))
  };
}

async function loadAlibabaCloudInventory(
  context: ConnectorExecutionContext
): Promise<AlibabaCloudInventory> {
  if (context.mockMode) {
    return loadAlibabaCloudFixtureInventory();
  }

  return loadAlibabaCloudLiveInventory(
    AlibabaCloudAccessKeyConfigSchema.parse(context.config)
  );
}

function createAlibabaCloudAssets(
  inventory: AlibabaCloudInventory
): ConnectorAssetInput[] {
  const accountName = inventory.accountId ?? `region-${inventory.regionId}`;

  return [
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality: inventory.instances.some(
        (instance) => instance.hasPublicAddress
      )
        ? "High"
        : "Moderate",
      environment: "alibaba-cloud",
      identifiers: {
        accountId: inventory.accountId,
        provider: "alibaba-cloud",
        regionId: inventory.regionId,
        resourceKind: "CloudAccount"
      },
      internetExposed: inventory.instances.some(
        (instance) => instance.hasPublicAddress
      ),
      name: `alibaba-cloud-account/${accountName}`,
      owner: "cloud-security",
      status: "Active",
      tags: ["alibaba-cloud", "account", `region:${inventory.regionId}`]
    }),
    ...inventory.instances.map((instance) =>
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: instance.hasPublicAddress ? "High" : "Moderate",
        environment: "alibaba-cloud",
        identifiers: {
          hasPublicAddress: instance.hasPublicAddress,
          instanceId: instance.instanceId,
          internetMaxBandwidthOut: instance.internetMaxBandwidthOut,
          privateAddressCount: instance.privateAddressCount,
          provider: "alibaba-cloud",
          publicAddressCount: instance.publicAddressCount,
          regionId: instance.regionId,
          resourceKind: "ECSInstance",
          securityGroupCount: instance.securityGroupIds.length,
          state: instance.status,
          vpcConfigured: Boolean(instance.vpcId),
          zoneConfigured: Boolean(instance.zoneId)
        },
        internetExposed: instance.hasPublicAddress,
        name: `alibaba-ecs/${instance.name}`,
        owner: "cloud",
        status:
          instance.status.toLowerCase() === "running" ? "Active" : "Inactive",
        tags: ["alibaba-cloud", "ecs", `region:${instance.regionId}`]
      })
    ),
    ...inventory.securityGroups.map((group) =>
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: "Moderate",
        environment: "alibaba-cloud",
        identifiers: {
          groupId: group.groupId,
          provider: "alibaba-cloud",
          regionId: group.regionId,
          resourceKind: "SecurityGroup",
          serviceManaged: group.serviceManaged,
          vpcConfigured: Boolean(group.vpcId)
        },
        internetExposed: false,
        name: `alibaba-security-group/${group.name}`,
        owner: "cloud-security",
        status: "Active",
        tags: ["alibaba-cloud", "security-group", `region:${group.regionId}`]
      })
    ),
    ...inventory.roles.map((role) =>
      createMockAsset({
        assetType: "CloudResource",
        businessCriticality: "Moderate",
        environment: "alibaba-cloud",
        identifiers: {
          arnPresent: Boolean(role.arn),
          provider: "alibaba-cloud",
          resourceKind: "RAMRole",
          roleName: role.name
        },
        internetExposed: false,
        name: `alibaba-ram-role/${role.name}`,
        owner: "identity-security",
        status: "Active",
        tags: ["alibaba-cloud", "ram"]
      })
    )
  ];
}

function createAlibabaCloudSignals(
  inventory: AlibabaCloudInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const accountName = inventory.accountId ?? inventory.regionId;

  return [
    ConnectorSignalInputSchema.parse({
      confidence: 0.88,
      freshness: "Fresh",
      rawPayloadPointer: `alibaba-cloud://account/${encodeURIComponent(
        accountName
      )}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Moderate",
      signalCategory: "Cloud",
      signalSubcategory: "AlibabaCloudAccountInventory",
      sourceType: "alibaba_cloud.account.inventory",
      timestampObserved
    }),
    ...inventory.instances.flatMap((instance) => {
      const signals = [
        ConnectorSignalInputSchema.parse({
          confidence: 0.9,
          freshness: "Fresh",
          rawPayloadPointer: `alibaba-cloud://ecs/${encodeURIComponent(
            instance.instanceId
          )}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: instance.hasPublicAddress ? "High" : "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "AlibabaEcsInstanceObserved",
          sourceType: "alibaba_cloud.ecs.instance",
          timestampObserved
        })
      ];

      if (instance.hasPublicAddress) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.88,
            freshness: "Fresh",
            rawPayloadPointer: `alibaba-cloud://ecs/${encodeURIComponent(
              instance.instanceId
            )}/public-exposure`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "High",
            signalCategory: "Exposure",
            signalSubcategory: "AlibabaEcsPublicExposure",
            sourceType: "alibaba_cloud.ecs.public_exposure",
            timestampObserved
          })
        );
      }

      return signals;
    }),
    ...inventory.securityGroups.map((group) =>
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `alibaba-cloud://security-groups/${encodeURIComponent(
          group.groupId
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: group.serviceManaged ? "Low" : "Moderate",
        signalCategory: "ControlObservation",
        signalSubcategory: "AlibabaSecurityGroupObserved",
        sourceType: "alibaba_cloud.ecs.security_group",
        timestampObserved
      })
    ),
    ...inventory.roles.map((role) =>
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `alibaba-cloud://ram/roles/${encodeURIComponent(
          role.name
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Identity",
        signalSubcategory: "AlibabaRamRoleObserved",
        sourceType: "alibaba_cloud.ram.role",
        timestampObserved
      })
    )
  ];
}

async function getAlibabaCloudHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ALIBABA_CLOUD_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = AlibabaCloudAccessKeyConfigSchema.parse(context.config);

  try {
    await alibabaCloudRpcRequest(config, config.ecsEndpoint, {
      Action: "DescribeInstances",
      PageSize: "1",
      RegionId: config.regionId,
      Version: "2014-05-26"
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "Alibaba Cloud access key verified with ECS DescribeInstances. Periscan called read-only inventory APIs only.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Alibaba Cloud health check failed: ${alibabaCloudErrorDetail(
        error
      )}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createAlibabaCloudConnector(): Connector {
  return {
    manifest: ALIBABA_CLOUD_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadAlibabaCloudInventory(parsedContext);

      return createAlibabaCloudSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAlibabaCloudHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadAlibabaCloudInventory(parsedContext);
      const health = parsedContext.mockMode
        ? createMockHealth(ALIBABA_CLOUD_CONNECTOR_MANIFEST, parsedContext)
        : await getAlibabaCloudHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createAlibabaCloudAssets(inventory),
        health,
        signals: createAlibabaCloudSignals(inventory).map((signal) =>
          createTimestampedSignal(
            ALIBABA_CLOUD_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const OracleCloudApiKeyConfigSchema = z.object({
  apiBaseUrl: z.url().optional(),
  compartmentId: z.string().min(1),
  fingerprint: z.string().min(1),
  privateKeyPem: z.string().min(1),
  region: z.string().min(1).default("us-ashburn-1"),
  tenancyOcid: z.string().min(1),
  userOcid: z.string().min(1),
  limit: z.coerce.number().int().min(1).max(100).default(50)
});

type OracleCloudApiKeyConfig = z.infer<typeof OracleCloudApiKeyConfigSchema>;

type OracleCloudInstance = {
  availabilityDomain: string | null;
  compartmentId: string;
  displayName: string;
  id: string;
  lifecycleState: string;
  region: string;
  shape: string | null;
};

type OracleCloudVcn = {
  cidrBlockCount: number;
  compartmentId: string;
  displayName: string;
  id: string;
};

type OracleCloudSecurityList = {
  compartmentId: string;
  displayName: string;
  id: string;
  ingressRuleCount: number;
  publicIngressRuleCount: number;
  vcnId: string;
};

type OracleCloudInventory = {
  compartmentId: string;
  instances: OracleCloudInstance[];
  region: string;
  securityLists: OracleCloudSecurityList[];
  tenancyOcid: string;
  vcns: OracleCloudVcn[];
};

