function pineconeHeaders(config: PineconeApiKeyConfig) {
  return {
    "Api-Key": config.apiKey,
    "X-Pinecone-Api-Version": config.apiVersion
  };
}

function pineconeErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Pinecone API error.";
}

async function pineconeFetchJson(
  config: PineconeApiKeyConfig,
  pathName: string
) {
  const response = await connectorFetch(pineconeApiUrl(config, pathName), {
    headers: pineconeHeaders(config)
  });

  if (!response.ok) {
    throw new Error(`Pinecone API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function pineconeTags(value: unknown): Record<string, string> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .filter(([, tagValue]) => typeof tagValue === "string")
      .map(([tagKey, tagValue]) => [tagKey, tagValue as string])
  );
}

function pineconeSpecLocation(spec: unknown) {
  if (!spec || typeof spec !== "object" || Array.isArray(spec)) {
    return {
      cloud: null,
      region: null
    };
  }

  const record = spec as Record<string, unknown>;
  const serverless =
    record.serverless &&
    typeof record.serverless === "object" &&
    !Array.isArray(record.serverless)
      ? (record.serverless as Record<string, unknown>)
      : null;
  const pod =
    record.pod && typeof record.pod === "object" && !Array.isArray(record.pod)
      ? (record.pod as Record<string, unknown>)
      : null;
  const cloud =
    typeof serverless?.cloud === "string"
      ? serverless.cloud
      : typeof pod?.cloud === "string"
        ? pod.cloud
        : null;
  const region =
    typeof serverless?.region === "string"
      ? serverless.region
      : typeof pod?.region === "string"
        ? pod.region
        : typeof pod?.environment === "string"
          ? pod.environment
          : null;

  return {
    cloud,
    region
  };
}

function parsePineconeIndexes(json: Record<string, unknown>) {
  const items = Array.isArray(json.indexes)
    ? json.indexes
    : Array.isArray(json.data)
      ? json.data
      : [];

  return items
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => {
      const status =
        item.status &&
        typeof item.status === "object" &&
        !Array.isArray(item.status)
          ? (item.status as Record<string, unknown>)
          : {};
      const location = pineconeSpecLocation(item.spec);

      return {
        cloud: location.cloud,
        deletionProtection:
          typeof item.deletion_protection === "string"
            ? item.deletion_protection
            : null,
        dimension: typeof item.dimension === "number" ? item.dimension : null,
        host: typeof item.host === "string" ? item.host : null,
        metric: typeof item.metric === "string" ? item.metric : null,
        name: connectorString(item.name, "unknown-index"),
        ready: typeof status.ready === "boolean" ? status.ready : null,
        region: location.region,
        state: typeof status.state === "string" ? status.state : null,
        tags: pineconeTags(item.tags),
        vectorType:
          typeof item.vector_type === "string" ? item.vector_type : null
      } satisfies PineconeIndex;
    })
    .filter((index) => index.name !== "unknown-index");
}

function loadPineconeFixtureIndexes(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureIndexes)) {
    return parsePineconeIndexes({
      indexes: config.fixtureIndexes
    });
  }

  return [
    {
      cloud: "aws",
      deletionProtection: "enabled",
      dimension: 1536,
      host: "periscan-rag-prod.svc.us-east-1-aws.pinecone.io",
      metric: "cosine",
      name: "periscan-rag-prod",
      ready: true,
      region: "us-east-1",
      state: "Ready",
      tags: {
        environment: "production"
      },
      vectorType: "dense"
    },
    {
      cloud: "gcp",
      deletionProtection: "disabled",
      dimension: 768,
      host: "periscan-support-rag.svc.us-west1-gcp.pinecone.io",
      metric: "dotproduct",
      name: "periscan-support-rag",
      ready: false,
      region: "us-west1",
      state: "Initializing",
      tags: null,
      vectorType: "dense"
    }
  ] satisfies PineconeIndex[];
}

async function loadPineconeIndexes(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadPineconeFixtureIndexes(context.config);
  }

  const config = PineconeApiKeyConfigSchema.parse(context.config);

  return parsePineconeIndexes(await pineconeFetchJson(config, "/indexes"));
}

function createPineconeAssets(indexes: PineconeIndex[]): ConnectorAssetInput[] {
  return indexes.map((index) =>
    createMockAsset({
      assetType: "Application",
      businessCriticality:
        index.tags?.environment === "production" ? "High" : "Moderate",
      environment: "ai-stack",
      identifiers: {
        cloud: index.cloud,
        deletionProtection: index.deletionProtection,
        dimension: index.dimension,
        host: index.host,
        metric: index.metric,
        pineconeIndexName: index.name,
        ready: index.ready,
        region: index.region,
        resourceKind: "PineconeIndex",
        state: index.state,
        vectorType: index.vectorType
      },
      internetExposed: Boolean(index.host),
      name: `pinecone-index/${index.name}`,
      owner: "ai-platform",
      status: index.ready === false ? "Inactive" : "Active",
      tags: ["pinecone", "vector-index"]
    })
  );
}

function createPineconeSignals(
  indexes: PineconeIndex[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return indexes.flatMap((index) => {
    const signals = [
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `pinecone://indexes/${encodeURIComponent(index.name)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Restricted",
        signalCategory: "AIApplication",
        signalSubcategory: "VectorIndexAvailable",
        sourceType: "pinecone.indexes.index",
        timestampObserved
      })
    ];

    if (
      index.ready === false ||
      (index.state !== null && index.state.toLowerCase() !== "ready")
    ) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `pinecone://indexes/${encodeURIComponent(index.name)}/status`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "AIApplication",
          signalSubcategory: "VectorIndexNotReady",
          sourceType: "pinecone.indexes.status",
          timestampObserved
        })
      );
    }

    if (index.deletionProtection === "disabled") {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `pinecone://indexes/${encodeURIComponent(index.name)}/deletion-protection`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "AIApplication",
          signalSubcategory: "VectorIndexDeletionProtectionDisabled",
          sourceType: "pinecone.indexes.deletion_protection",
          timestampObserved
        })
      );
    }

    return signals;
  });
}

async function getPineconeHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(PINECONE_CONNECTOR_MANIFEST, context);
  }

  const config = PineconeApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const indexes = parsePineconeIndexes(
      await pineconeFetchJson(config, "/indexes")
    );

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Pinecone read-only index inventory verified with ${indexes.length} index(es).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Pinecone health check failed: ${pineconeErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createPineconeConnector(): Connector {
  return {
    manifest: PINECONE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const indexes = await loadPineconeIndexes(parsedContext);

      return createPineconeSignals(indexes);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getPineconeHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const indexes = await loadPineconeIndexes(parsedContext);
      const health = parsedContext.mockMode
        ? await getPineconeHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Pinecone read-only sync returned ${indexes.length} index metadata record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createPineconeAssets(indexes),
        health,
        signals: createPineconeSignals(indexes).map((signal) =>
          createTimestampedSignal(
            PINECONE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const WeaviateApiKeyConfigSchema = z.object({
  apiKey: z.string().min(1),
  baseUrl: z.url()
});

type WeaviateApiKeyConfig = z.infer<typeof WeaviateApiKeyConfigSchema>;

type WeaviateCollection = {
  className: string;
  description: string | null;
  multiTenancyEnabled: boolean | null;
  propertyCount: number;
  propertyNames: string[];
  replicationFactor: number | null;
  vectorIndexType: string | null;
  vectorizer: string | null;
};

type WeaviateMeta = {
  hostname: string | null;
  modules: string[];
  version: string | null;
};

type WeaviateInventory = {
  collections: WeaviateCollection[];
  meta: WeaviateMeta;
};

const WEAVIATE_CONNECTOR_MANIFEST = ConnectorManifestSchema.parse({
  authMethods: [
    {
      description: "Use fixture-backed mock Weaviate collection metadata.",
      fields: [],
      kind: "mock",
      label: "Mock",
      mockSupported: true
    },
    {
      description:
        "Use a Weaviate API key for read-only REST schema and metadata inventory.",
      fields: [
        {
          key: "baseUrl",
          label: "Weaviate REST Endpoint",
          required: true,
          secret: false
        },
        {
          key: "apiKey",
          label: "Weaviate API Key",
          required: true,
          secret: true
        }
      ],
      kind: "apiKey",
      label: "Weaviate API Key",
      mockSupported: false
    }
  ],
  availability: "Beta",
  category: "AIStack",
  connectorKey: "weaviate",
  controlObservationCapabilities: [],
  customerVisibleDescription:
    "Reads authorized Weaviate REST schema and cluster metadata for RAG/vector-store context without querying objects, GraphQL, vectors, backups, or mutating collections.",
  dataSensitivity: "Restricted",
  healthCheckMethod: "Weaviate REST /v1/meta and /v1/schema",
  marketplaceCategory: "AI Stack",
  mockSupported: true,
  permissionsSummary:
    "Requires read-only Weaviate API-key access to schema and metadata endpoints. Periscan does not call GraphQL, object, batch, backup, classification, vector search, or mutation endpoints.",
  product: "Weaviate",
  requiredPermissions: ["schema:read", "meta:read"],
  setupComplexity: "Medium",
  signalCategories: ["AIApplication"],
  supportedMissionTypes: ["ValidationSnapshot", "AIAppValidation"],
  validationCapabilities: [
    "Vector collection inventory",
    "RAG schema context signals",
    "AI stack context signals"
  ],
  vendor: "Weaviate",
  workflowCapabilities: []
});

function weaviateApiUrl(config: WeaviateApiKeyConfig, pathName: string) {
  const baseUrl = config.baseUrl.replace(/\/+$/u, "");
  const versionedBaseUrl = baseUrl.endsWith("/v1") ? baseUrl : `${baseUrl}/v1`;

  return `${versionedBaseUrl}${pathName}`;
}

function weaviateHeaders(config: WeaviateApiKeyConfig) {
  return {
    authorization: `Bearer ${config.apiKey}`
  };
}

function weaviateErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Weaviate API error.";
}

async function weaviateFetchJson(
  config: WeaviateApiKeyConfig,
  pathName: string
) {
  const response = await connectorFetch(weaviateApiUrl(config, pathName), {
    headers: weaviateHeaders(config)
  });

  if (!response.ok) {
    throw new Error(`Weaviate API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function weaviateStringArray(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => connectorString(item, ""))
    .filter((item) => item.length > 0);
}

function parseWeaviateCollections(json: Record<string, unknown>) {
  const items = Array.isArray(json.classes)
    ? json.classes
    : Array.isArray(json.collections)
      ? json.collections
      : [];

  return items
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => {
      const properties = Array.isArray(item.properties)
        ? item.properties.filter(
            (property): property is Record<string, unknown> =>
              Boolean(property) && typeof property === "object"
          )
        : [];
      const multiTenancyConfig =
        item.multiTenancyConfig &&
        typeof item.multiTenancyConfig === "object" &&
        !Array.isArray(item.multiTenancyConfig)
          ? (item.multiTenancyConfig as Record<string, unknown>)
          : {};
      const replicationConfig =
        item.replicationConfig &&
        typeof item.replicationConfig === "object" &&
        !Array.isArray(item.replicationConfig)
          ? (item.replicationConfig as Record<string, unknown>)
          : {};
      const replicationFactor =
        typeof replicationConfig.factor === "number"
          ? replicationConfig.factor
          : typeof replicationConfig.replicationFactor === "number"
            ? replicationConfig.replicationFactor
            : null;

      return {
        className: connectorString(item.class ?? item.name, "unknown-class"),
        description:
          typeof item.description === "string" ? item.description : null,
        multiTenancyEnabled:
          typeof multiTenancyConfig.enabled === "boolean"
            ? multiTenancyConfig.enabled
            : null,
        propertyCount: properties.length,
        propertyNames: properties
          .map((property) => connectorString(property.name, ""))
          .filter((propertyName) => propertyName.length > 0),
        replicationFactor,
        vectorIndexType:
          typeof item.vectorIndexType === "string"
            ? item.vectorIndexType
            : null,
        vectorizer: typeof item.vectorizer === "string" ? item.vectorizer : null
      } satisfies WeaviateCollection;
    })
    .filter((collection) => collection.className !== "unknown-class");
}

function parseWeaviateMeta(json: Record<string, unknown>): WeaviateMeta {
  const modules =
    json.modules &&
    typeof json.modules === "object" &&
    !Array.isArray(json.modules)
      ? Object.keys(json.modules as Record<string, unknown>)
      : weaviateStringArray(json.modules);

  return {
    hostname:
      typeof json.hostname === "string"
        ? json.hostname
        : typeof json.host === "string"
          ? json.host
          : null,
    modules,
    version: typeof json.version === "string" ? json.version : null
  };
}

function loadWeaviateFixtureInventory(
  config: Record<string, unknown>
): WeaviateInventory {
  if (config.fixtureInventory && typeof config.fixtureInventory === "object") {
    const fixture = config.fixtureInventory as Record<string, unknown>;

    return {
      collections: parseWeaviateCollections({ classes: fixture.classes }),
      meta: parseWeaviateMeta(
        fixture.meta && typeof fixture.meta === "object"
          ? (fixture.meta as Record<string, unknown>)
          : {}
      )
    };
  }

  return {
    collections: [
      {
        className: "CustomerDocument",
        description: "Production RAG documents.",
        multiTenancyEnabled: true,
        propertyCount: 3,
        propertyNames: ["title", "tenantId", "source"],
        replicationFactor: 3,
        vectorIndexType: "hnsw",
        vectorizer: "text2vec-openai"
      },
      {
        className: "SupportArticle",
        description: "Support RAG article corpus.",
        multiTenancyEnabled: false,
        propertyCount: 2,
        propertyNames: ["title", "body"],
        replicationFactor: 1,
        vectorIndexType: "hnsw",
        vectorizer: "text2vec-transformers"
      }
    ],
    meta: {
      hostname: "weaviate-demo",
      modules: ["text2vec-openai", "generative-openai"],
      version: "1.32.0"
    }
  };
}

async function loadWeaviateInventory(
  context: ConnectorExecutionContext
): Promise<WeaviateInventory> {
  if (context.mockMode) {
    return loadWeaviateFixtureInventory(context.config);
  }

  const config = WeaviateApiKeyConfigSchema.parse(context.config);
  const [schemaJson, metaJson] = await Promise.all([
    weaviateFetchJson(config, "/schema"),
    weaviateFetchJson(config, "/meta")
  ]);

  return {
    collections: parseWeaviateCollections(schemaJson),
    meta: parseWeaviateMeta(metaJson)
  };
}

function createWeaviateAssets(
  inventory: WeaviateInventory
): ConnectorAssetInput[] {
  return inventory.collections.map((collection) =>
    createMockAsset({
      assetType: "Application",
      businessCriticality: collection.multiTenancyEnabled ? "High" : "Moderate",
      environment: "ai-stack",
      identifiers: {
        className: collection.className,
        description: collection.description,
        modules: inventory.meta.modules,
        multiTenancyEnabled: collection.multiTenancyEnabled,
        propertyCount: collection.propertyCount,
        propertyNames: collection.propertyNames,
        replicationFactor: collection.replicationFactor,
        resourceKind: "WeaviateCollection",
        vectorIndexType: collection.vectorIndexType,
        vectorizer: collection.vectorizer,
        version: inventory.meta.version
      },
      internetExposed: false,
      name: `weaviate-collection/${collection.className}`,
      owner: "ai-platform",
      status: "Active",
      tags: ["weaviate", "vector-collection"]
    })
  );
}

function createWeaviateSignals(
  inventory: WeaviateInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return inventory.collections.flatMap((collection) => {
    const signals = [
      ConnectorSignalInputSchema.parse({
        confidence: 0.9,
        freshness: "Fresh",
        rawPayloadPointer: `weaviate://schema/${encodeURIComponent(collection.className)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Restricted",
        signalCategory: "AIApplication",
        signalSubcategory: "VectorCollectionAvailable",
        sourceType: "weaviate.schema.collection",
        timestampObserved
      })
    ];

    if (collection.multiTenancyEnabled === false) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `weaviate://schema/${encodeURIComponent(collection.className)}/multi-tenancy`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "AIApplication",
          signalSubcategory: "VectorCollectionSingleTenant",
          sourceType: "weaviate.schema.multi_tenancy",
          timestampObserved
        })
      );
    }

    if (collection.vectorizer) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.86,
          freshness: "Fresh",
          rawPayloadPointer: `weaviate://schema/${encodeURIComponent(collection.className)}/vectorizer`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "VectorizerConfigured",
          sourceType: "weaviate.schema.vectorizer",
          timestampObserved
        })
      );
    }

    return signals;
  });
}

async function getWeaviateHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(WEAVIATE_CONNECTOR_MANIFEST, context);
  }

  const config = WeaviateApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const meta = parseWeaviateMeta(await weaviateFetchJson(config, "/meta"));

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Weaviate read-only metadata access verified${meta.version ? ` for version ${meta.version}` : ""}.`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Weaviate health check failed: ${weaviateErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createWeaviateConnector(): Connector {
  return {
    manifest: WEAVIATE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadWeaviateInventory(parsedContext);

      return createWeaviateSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getWeaviateHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadWeaviateInventory(parsedContext);
      const health = parsedContext.mockMode
        ? await getWeaviateHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Weaviate read-only sync returned ${inventory.collections.length} collection schema record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createWeaviateAssets(inventory),
        health,
        signals: createWeaviateSignals(inventory).map((signal) =>
          createTimestampedSignal(
            WEAVIATE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

