function parseLangChainInventory(value: unknown): LangChainInventory {
  const config = langChainRecord(value);

  return {
    agents: parseLangChainComponents(config.agents, "agent"),
    applicationName: connectorString(
      config.applicationName ?? config.name,
      "langchain-application"
    ),
    callbacks: parseLangChainComponents(config.callbacks, "callback"),
    chains: parseLangChainComponents(config.chains, "chain"),
    environment: connectorString(config.environment, "ai-stack"),
    retrievers: parseLangChainComponents(config.retrievers, "retriever"),
    runnables: parseLangChainComponents(config.runnables, "runnable"),
    tools: parseLangChainTools(config.tools),
    vectorStores: parseLangChainComponents(config.vectorStores, "vector-store")
  };
}

function loadLangChainInventory(
  context: ConnectorExecutionContext
): LangChainInventory {
  return context.mockMode
    ? loadLangChainFixtureInventory(context.config)
    : parseLangChainInventory(context.config);
}

function createLangChainAssets(
  inventory: LangChainInventory
): ConnectorAssetInput[] {
  const counts = {
    agents: inventory.agents.length,
    callbacks: inventory.callbacks.length,
    chains: inventory.chains.length,
    retrievers: inventory.retrievers.length,
    runnables: inventory.runnables.length,
    tools: inventory.tools.length,
    vectorStores: inventory.vectorStores.length
  };

  return [
    createMockAsset({
      assetType: "Application",
      businessCriticality:
        counts.tools > 0 || counts.retrievers > 0 ? "High" : "Moderate",
      environment: inventory.environment,
      identifiers: {
        ...counts,
        applicationName: inventory.applicationName,
        resourceKind: "LangChainApplication"
      },
      internetExposed: false,
      name: `langchain-app/${inventory.applicationName}`,
      owner: "ai-platform",
      status: "Active",
      tags: ["langchain", "ai-application"]
    }),
    ...inventory.agents.map((agent) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: "High",
        environment: inventory.environment,
        identifiers: {
          componentType: agent.componentType,
          metadataKeys: agent.metadataKeys,
          provider: agent.provider,
          resourceKind: "LangChainAgent"
        },
        internetExposed: false,
        name: `langchain-agent/${agent.name}`,
        owner: "ai-platform",
        status: "Active",
        tags: ["langchain", "agent"]
      })
    )
  ];
}

function createLangChainComponentSignal(
  kind: LangChainComponentKind,
  component: LangChainComponent,
  timestampObserved: string
) {
  const sourceKind = kind.replace(/([a-z])([A-Z])/gu, "$1_$2").toLowerCase();

  return ConnectorSignalInputSchema.parse({
    confidence: 0.82,
    freshness: "Fresh",
    rawPayloadPointer: `langchain://metadata/${sourceKind}/${encodeURIComponent(component.name)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: `LangChain${kind}Declared`,
    sourceType: `langchain.metadata.${sourceKind}`,
    timestampObserved
  });
}

function createLangChainSignals(
  inventory: LangChainInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const applicationSignal = ConnectorSignalInputSchema.parse({
    confidence: 0.9,
    freshness: "Fresh",
    rawPayloadPointer: `langchain://metadata/applications/${encodeURIComponent(inventory.applicationName)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: "LangChainApplicationDeclared",
    sourceType: "langchain.metadata.application",
    timestampObserved
  });
  const componentSignals = [
    ...inventory.chains.map((component) =>
      createLangChainComponentSignal("Chain", component, timestampObserved)
    ),
    ...inventory.agents.map((component) =>
      createLangChainComponentSignal("Agent", component, timestampObserved)
    ),
    ...inventory.tools.map((component) =>
      createLangChainComponentSignal("Tool", component, timestampObserved)
    ),
    ...inventory.retrievers.map((component) =>
      createLangChainComponentSignal("Retriever", component, timestampObserved)
    ),
    ...inventory.vectorStores.map((component) =>
      createLangChainComponentSignal(
        "VectorStore",
        component,
        timestampObserved
      )
    ),
    ...inventory.callbacks.map((component) =>
      createLangChainComponentSignal("Callback", component, timestampObserved)
    ),
    ...inventory.runnables.map((component) =>
      createLangChainComponentSignal("Runnable", component, timestampObserved)
    )
  ];
  const toolRiskSignals = inventory.tools.flatMap((tool) => {
    const signals: ConnectorSignalInput[] = [];

    if (tool.requiresHumanApproval) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `langchain://metadata/tools/${encodeURIComponent(tool.name)}/approval`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "LangChainToolApprovalRequired",
          sourceType: "langchain.metadata.tool_approval",
          timestampObserved
        })
      );
    }

    if (tool.sensitive) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `langchain://metadata/tools/${encodeURIComponent(tool.name)}/sensitive`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "LangChainSensitiveToolDeclared",
          sourceType: "langchain.metadata.sensitive_tool",
          timestampObserved
        })
      );
    }

    return signals;
  });

  return [applicationSignal, ...componentSignals, ...toolRiskSignals];
}

async function getLangChainHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(LANGCHAIN_CONNECTOR_MANIFEST, context);
  }

  const inventory = parseLangChainInventory(context.config);
  const componentCount =
    inventory.agents.length +
    inventory.callbacks.length +
    inventory.chains.length +
    inventory.retrievers.length +
    inventory.runnables.length +
    inventory.tools.length +
    inventory.vectorStores.length;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `LangChain metadata import validated for ${componentCount} component(s); no chains, agents, tools, retrievers, vector stores, or models were executed.`,
    latencyMs: 0,
    status: "Healthy"
  });
}

function createLangChainConnector(): Connector {
  return {
    manifest: LANGCHAIN_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadLangChainInventory(parsedContext);

      return createLangChainSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getLangChainHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadLangChainInventory(parsedContext);
      const health = await getLangChainHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createLangChainAssets(inventory),
        health,
        signals: createLangChainSignals(inventory).map((signal) =>
          createTimestampedSignal(
            LANGCHAIN_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

