function parseLlamaIndexInventory(value: unknown): LlamaIndexInventory {
  const config = llamaIndexRecord(value);

  return {
    agents: parseLlamaIndexComponents(config.agents, "agent"),
    applicationName: connectorString(
      config.applicationName ?? config.name,
      "llamaindex-application"
    ),
    dataSources: parseLlamaIndexComponents(config.dataSources, "data-source"),
    environment: connectorString(config.environment, "ai-stack"),
    indexes: parseLlamaIndexComponents(config.indexes, "index"),
    queryEngines: parseLlamaIndexComponents(
      config.queryEngines,
      "query-engine"
    ),
    retrievers: parseLlamaIndexComponents(config.retrievers, "retriever"),
    tools: parseLlamaIndexTools(config.tools),
    vectorStores: parseLlamaIndexComponents(
      config.vectorStores,
      "vector-store"
    ),
    workflows: parseLlamaIndexComponents(config.workflows, "workflow")
  };
}

function loadLlamaIndexInventory(
  context: ConnectorExecutionContext
): LlamaIndexInventory {
  return context.mockMode
    ? loadLlamaIndexFixtureInventory(context.config)
    : parseLlamaIndexInventory(context.config);
}

