function createLlamaIndexComponentSignal(
  kind: LlamaIndexComponentKind,
  component: LlamaIndexComponent,
  timestampObserved: string
) {
  const sourceKind = kind.replace(/([a-z])([A-Z])/gu, "$1_$2").toLowerCase();

  return ConnectorSignalInputSchema.parse({
    confidence: 0.82,
    freshness: "Fresh",
    rawPayloadPointer: `llamaindex://metadata/${sourceKind}/${encodeURIComponent(component.name)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: `LlamaIndex${kind}Declared`,
    sourceType: `llamaindex.metadata.${sourceKind}`,
    timestampObserved
  });
}

function createLlamaIndexSignals(
  inventory: LlamaIndexInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const applicationSignal = ConnectorSignalInputSchema.parse({
    confidence: 0.9,
    freshness: "Fresh",
    rawPayloadPointer: `llamaindex://metadata/applications/${encodeURIComponent(inventory.applicationName)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: "LlamaIndexApplicationDeclared",
    sourceType: "llamaindex.metadata.application",
    timestampObserved
  });
  const componentSignals = [
    ...inventory.indexes.map((component) =>
      createLlamaIndexComponentSignal("Index", component, timestampObserved)
    ),
    ...inventory.queryEngines.map((component) =>
      createLlamaIndexComponentSignal(
        "QueryEngine",
        component,
        timestampObserved
      )
    ),
    ...inventory.retrievers.map((component) =>
      createLlamaIndexComponentSignal("Retriever", component, timestampObserved)
    ),
    ...inventory.agents.map((component) =>
      createLlamaIndexComponentSignal("Agent", component, timestampObserved)
    ),
    ...inventory.tools.map((component) =>
      createLlamaIndexComponentSignal("Tool", component, timestampObserved)
    ),
    ...inventory.dataSources.map((component) =>
      createLlamaIndexComponentSignal(
        "DataSource",
        component,
        timestampObserved
      )
    ),
    ...inventory.vectorStores.map((component) =>
      createLlamaIndexComponentSignal(
        "VectorStore",
        component,
        timestampObserved
      )
    ),
    ...inventory.workflows.map((component) =>
      createLlamaIndexComponentSignal("Workflow", component, timestampObserved)
    )
  ];
  const toolRiskSignals = inventory.tools.flatMap((tool) => {
    const signals: ConnectorSignalInput[] = [];

    if (tool.requiresHumanApproval) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `llamaindex://metadata/tools/${encodeURIComponent(tool.name)}/approval`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "LlamaIndexToolApprovalRequired",
          sourceType: "llamaindex.metadata.tool_approval",
          timestampObserved
        })
      );
    }

    if (tool.sensitive) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `llamaindex://metadata/tools/${encodeURIComponent(tool.name)}/sensitive`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "LlamaIndexSensitiveToolDeclared",
          sourceType: "llamaindex.metadata.sensitive_tool",
          timestampObserved
        })
      );
    }

    return signals;
  });

  return [applicationSignal, ...componentSignals, ...toolRiskSignals];
}

async function getLlamaIndexHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(LLAMAINDEX_CONNECTOR_MANIFEST, context);
  }

  const inventory = parseLlamaIndexInventory(context.config);
  const componentCount =
    inventory.agents.length +
    inventory.dataSources.length +
    inventory.indexes.length +
    inventory.queryEngines.length +
    inventory.retrievers.length +
    inventory.tools.length +
    inventory.vectorStores.length +
    inventory.workflows.length;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `LlamaIndex metadata import validated for ${componentCount} component(s); no query engines, retrievers, agents, tools, workflows, vector stores, or models were executed.`,
    latencyMs: 0,
    status: "Healthy"
  });
}

function createLlamaIndexConnector(): Connector {
  return {
    manifest: LLAMAINDEX_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadLlamaIndexInventory(parsedContext);

      return createLlamaIndexSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getLlamaIndexHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadLlamaIndexInventory(parsedContext);
      const health = await getLlamaIndexHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createLlamaIndexAssets(inventory),
        health,
        signals: createLlamaIndexSignals(inventory).map((signal) =>
          createTimestampedSignal(
            LLAMAINDEX_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

type GuardrailsAiComponentKind =
  | "Guard"
  | "Policy"
  | "RailSpec"
  | "ServerEndpoint"
  | "TelemetrySink"
  | "Validator";

type GuardrailsAiComponent = {
  appliesTo: string | null;
  componentType: string | null;
  metadataKeys: string[];
  name: string;
  provider: string | null;
  purpose: string | null;
};

type GuardrailsAiValidatorComponent = GuardrailsAiComponent & {
  onFailPolicy: string | null;
  requiresRuntimeMetadata: boolean | null;
  sensitive: boolean | null;
  validationMethod: string | null;
};

type GuardrailsAiInventory = {
  applicationName: string;
  environment: string;
  guards: GuardrailsAiComponent[];
  policies: GuardrailsAiComponent[];
  railSpecs: GuardrailsAiComponent[];
  serverEndpoints: GuardrailsAiComponent[];
  telemetrySinks: GuardrailsAiComponent[];
  validators: GuardrailsAiValidatorComponent[];
};

