function guardrailsAiRecord(value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function guardrailsAiRecordArray(value: unknown) {
  return Array.isArray(value)
    ? value.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      )
    : [];
}

function guardrailsAiStringOrNull(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : null;
}

function guardrailsAiBooleanOrNull(value: unknown) {
  return typeof value === "boolean" ? value : null;
}

function guardrailsAiMetadataKeys(value: unknown) {
  return Object.keys(guardrailsAiRecord(value)).filter((key) => key.length > 0);
}

function parseGuardrailsAiComponent(
  item: Record<string, unknown>,
  fallbackPrefix: string
): GuardrailsAiComponent {
  const name = connectorString(
    item.name ?? item.id ?? item.key,
    `${fallbackPrefix}-unknown`
  );

  return {
    appliesTo:
      guardrailsAiStringOrNull(item.appliesTo) ??
      guardrailsAiStringOrNull(item.on),
    componentType:
      guardrailsAiStringOrNull(item.componentType) ??
      guardrailsAiStringOrNull(item.type) ??
      guardrailsAiStringOrNull(item.className) ??
      guardrailsAiStringOrNull(item.kind),
    metadataKeys: guardrailsAiMetadataKeys(item.metadata),
    name,
    provider:
      guardrailsAiStringOrNull(item.provider) ??
      guardrailsAiStringOrNull(item.hubId),
    purpose:
      guardrailsAiStringOrNull(item.purpose) ??
      guardrailsAiStringOrNull(item.description)
  };
}

function parseGuardrailsAiValidator(
  item: Record<string, unknown>
): GuardrailsAiValidatorComponent {
  const component = parseGuardrailsAiComponent(item, "validator");

  return {
    ...component,
    onFailPolicy:
      guardrailsAiStringOrNull(item.onFailPolicy) ??
      guardrailsAiStringOrNull(item.on_fail),
    requiresRuntimeMetadata: guardrailsAiBooleanOrNull(
      item.requiresRuntimeMetadata
    ),
    sensitive: guardrailsAiBooleanOrNull(item.sensitive),
    validationMethod:
      guardrailsAiStringOrNull(item.validationMethod) ??
      guardrailsAiStringOrNull(item.validation_method)
  };
}

function parseGuardrailsAiComponents(
  value: unknown,
  fallbackPrefix: string
): GuardrailsAiComponent[] {
  return guardrailsAiRecordArray(value)
    .map((item) => parseGuardrailsAiComponent(item, fallbackPrefix))
    .filter((component) => component.name !== `${fallbackPrefix}-unknown`);
}

function parseGuardrailsAiValidators(
  value: unknown
): GuardrailsAiValidatorComponent[] {
  return guardrailsAiRecordArray(value)
    .map(parseGuardrailsAiValidator)
    .filter((component) => component.name !== "validator-unknown");
}

