function createGuardrailsAiComponentSignal(
  kind: GuardrailsAiComponentKind,
  component: GuardrailsAiComponent,
  timestampObserved: string
) {
  const sourceKind = kind.replace(/([a-z])([A-Z])/gu, "$1_$2").toLowerCase();

  return ConnectorSignalInputSchema.parse({
    confidence: 0.82,
    freshness: "Fresh",
    rawPayloadPointer: `guardrails-ai://metadata/${sourceKind}/${encodeURIComponent(component.name)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: `GuardrailsAI${kind}Declared`,
    sourceType: `guardrails_ai.metadata.${sourceKind}`,
    timestampObserved
  });
}

function createGuardrailsAiSignals(
  inventory: GuardrailsAiInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const applicationSignal = ConnectorSignalInputSchema.parse({
    confidence: 0.9,
    freshness: "Fresh",
    rawPayloadPointer: `guardrails-ai://metadata/applications/${encodeURIComponent(inventory.applicationName)}`,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "Restricted",
    signalCategory: "AIApplication",
    signalSubcategory: "GuardrailsAIApplicationDeclared",
    sourceType: "guardrails_ai.metadata.application",
    timestampObserved
  });
  const componentSignals = [
    ...inventory.guards.map((component) =>
      createGuardrailsAiComponentSignal("Guard", component, timestampObserved)
    ),
    ...inventory.validators.map((component) =>
      createGuardrailsAiComponentSignal(
        "Validator",
        component,
        timestampObserved
      )
    ),
    ...inventory.policies.map((component) =>
      createGuardrailsAiComponentSignal("Policy", component, timestampObserved)
    ),
    ...inventory.railSpecs.map((component) =>
      createGuardrailsAiComponentSignal(
        "RailSpec",
        component,
        timestampObserved
      )
    ),
    ...inventory.serverEndpoints.map((component) =>
      createGuardrailsAiComponentSignal(
        "ServerEndpoint",
        component,
        timestampObserved
      )
    ),
    ...inventory.telemetrySinks.map((component) =>
      createGuardrailsAiComponentSignal(
        "TelemetrySink",
        component,
        timestampObserved
      )
    )
  ];
  const guardSignals = inventory.guards.flatMap((guard) => {
    const appliesTo = (guard.appliesTo ?? "").toLowerCase();
    const signalSubcategory =
      appliesTo === "messages" || appliesTo === "input"
        ? "GuardrailsAIInputGuardConfigured"
        : appliesTo === "output"
          ? "GuardrailsAIOutputGuardConfigured"
          : null;

    return signalSubcategory
      ? [
          ConnectorSignalInputSchema.parse({
            confidence: 0.78,
            freshness: "Fresh",
            rawPayloadPointer: `guardrails-ai://metadata/guards/${encodeURIComponent(guard.name)}/${appliesTo}`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Restricted",
            signalCategory: "ControlObservation",
            signalSubcategory,
            sourceType: "guardrails_ai.metadata.guard_scope",
            timestampObserved
          })
        ]
      : [];
  });
  const validatorSignals = inventory.validators.flatMap((validator) => {
    const signals: ConnectorSignalInput[] = [];

    if (validator.onFailPolicy) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `guardrails-ai://metadata/validators/${encodeURIComponent(validator.name)}/on-fail-policy`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "ControlObservation",
          signalSubcategory: "GuardrailsAIOnFailPolicyConfigured",
          sourceType: "guardrails_ai.metadata.on_fail_policy",
          timestampObserved
        })
      );
    }

    if (validator.requiresRuntimeMetadata) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.72,
          freshness: "Fresh",
          rawPayloadPointer: `guardrails-ai://metadata/validators/${encodeURIComponent(validator.name)}/runtime-metadata`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "GuardrailsAIRuntimeMetadataRequired",
          sourceType: "guardrails_ai.metadata.runtime_metadata",
          timestampObserved
        })
      );
    }

    if (validator.sensitive) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.76,
          freshness: "Fresh",
          rawPayloadPointer: `guardrails-ai://metadata/validators/${encodeURIComponent(validator.name)}/sensitive`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "AIApplication",
          signalSubcategory: "GuardrailsAISensitiveValidatorDeclared",
          sourceType: "guardrails_ai.metadata.sensitive_validator",
          timestampObserved
        })
      );
    }

    return signals;
  });

  return [
    applicationSignal,
    ...componentSignals,
    ...guardSignals,
    ...validatorSignals
  ];
}

async function getGuardrailsAiHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GUARDRAILS_AI_CONNECTOR_MANIFEST, context);
  }

  const inventory = parseGuardrailsAiInventory(context.config);
  const componentCount =
    inventory.guards.length +
    inventory.policies.length +
    inventory.railSpecs.length +
    inventory.serverEndpoints.length +
    inventory.telemetrySinks.length +
    inventory.validators.length;

  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `Guardrails AI metadata import validated for ${componentCount} component(s); no guards, validators, RAIL specs, server endpoints, prompts, LLMs, or models were executed.`,
    latencyMs: 0,
    status: "Healthy"
  });
}

function createGuardrailsAiConnector(): Connector {
  return {
    manifest: GUARDRAILS_AI_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadGuardrailsAiInventory(parsedContext);

      return createGuardrailsAiSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGuardrailsAiHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = loadGuardrailsAiInventory(parsedContext);
      const health = await getGuardrailsAiHealth(parsedContext);

      return ConnectorSyncResultSchema.parse({
        assets: createGuardrailsAiAssets(inventory),
        health,
        signals: createGuardrailsAiSignals(inventory).map((signal) =>
          createTimestampedSignal(
            GUARDRAILS_AI_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const LakeraApiKeyConfigSchema = z.object({
  apiKey: z.string().min(1),
  platformBaseUrl: z.url().default("https://api.lakera.ai/v2"),
  policyIds: z.array(z.string().min(1)).default([]),
  projectIds: z.array(z.string().min(1)).default([])
});

type LakeraApiKeyConfig = z.infer<typeof LakeraApiKeyConfigSchema>;

type LakeraDetector = {
  allowedDomainCount: number | null;
  detectorType: string;
  threshold: string | null;
};

type LakeraProject = {
  id: string;
  metadataKeys: string[];
  name: string;
  policyId: string | null;
};

type LakeraPolicy = {
  id: string;
  inputDetectors: LakeraDetector[];
  mode: string | null;
  name: string;
  outputDetectors: LakeraDetector[];
};

type LakeraInventory = {
  policies: LakeraPolicy[];
  projects: LakeraProject[];
};

const LAKERA_CONNECTOR_MANIFEST = ConnectorManifestSchema.parse({
  authMethods: [
    {
      description:
        "Use fixture-backed mock Lakera Guard project and policy metadata.",
      fields: [],
      kind: "mock",
      label: "Mock",
      mockSupported: true
    },
    {
      description:
        "Use a Lakera API key for read-only project and policy metadata inventory. Periscan does not submit prompts, outputs, or runtime screening requests.",
      fields: [
        {
          key: "apiKey",
          label: "Lakera API Key",
          required: true,
          secret: true
        },
        {
          key: "platformBaseUrl",
          label: "Lakera Platform API Base URL",
          required: false,
          secret: false
        },
        {
          key: "projectIds",
          label: "Project IDs",
          required: false,
          secret: false
        },
        {
          key: "policyIds",
          label: "Policy IDs",
          required: false,
          secret: false
        }
      ],
      kind: "apiKey",
      label: "Lakera API Key",
      mockSupported: false
    }
  ],
  availability: "Beta",
  category: "AIStack",
  connectorKey: "lakera",
  controlObservationCapabilities: [
    "AI guardrail project and policy context",
    "Prompt defense detector coverage",
    "Data leakage detector coverage",
    "Content moderation detector coverage",
    "Malicious link detector coverage"
  ],
  customerVisibleDescription:
    "Reads authorized Lakera Guard project and policy metadata for AI guardrail coverage context without screening prompts or fetching runtime results.",
  dataSensitivity: "Restricted",
  healthCheckMethod: "Lakera read-only project and policy metadata",
  marketplaceCategory: "AI Stack",
  mockSupported: true,
  permissionsSummary:
    "Reads configured Lakera Guard projects and policies only; Periscan does not call /guard, /guard/results, submit prompts or outputs, or execute guardrail screening.",
  product: "Lakera Guard",
  requiredPermissions: ["lakera:projects:read", "lakera:policies:read"],
  setupComplexity: "Low",
  signalCategories: ["AIApplication", "ControlObservation"],
  supportedMissionTypes: [
    "ValidationSnapshot",
    "AIAppValidation",
    "ControlValidation"
  ],
  validationCapabilities: [
    "AI guardrail configuration inventory",
    "Project-to-policy mapping context",
    "AI guardrail detector coverage signals"
  ],
  vendor: "Lakera",
  workflowCapabilities: []
});

function lakeraRecord(value: unknown) {
  return Boolean(value) && typeof value === "object"
    ? (value as Record<string, unknown>)
    : {};
}

function lakeraRecordArray(value: unknown) {
  return Array.isArray(value)
    ? value
        .filter(
          (item): item is Record<string, unknown> =>
            Boolean(item) && typeof item === "object"
        )
        .map((item) => item)
    : [];
}

function lakeraStringOrNull(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : null;
}

function lakeraMetadataKeys(value: unknown) {
  return Object.keys(lakeraRecord(value)).filter((key) => key.length > 0);
}

function parseLakeraDetector(value: unknown): LakeraDetector {
  const record = lakeraRecord(value);
  const allowedDomains = Array.isArray(record.allowed_domains)
    ? record.allowed_domains
    : Array.isArray(record.allowedDomains)
      ? record.allowedDomains
      : null;

  return {
    allowedDomainCount: allowedDomains ? allowedDomains.length : null,
    detectorType:
      lakeraStringOrNull(record.type) ??
      lakeraStringOrNull(record.detector_type) ??
      lakeraStringOrNull(record.detectorType) ??
      lakeraStringOrNull(record.name) ??
      "unknown-detector",
    threshold:
      lakeraStringOrNull(record.threshold) ??
      lakeraStringOrNull(record.level) ??
      lakeraStringOrNull(record.sensitivity)
  };
}

function parseLakeraProject(value: unknown): LakeraProject {
  const record = lakeraRecord(value);
  const policy = lakeraRecord(record.policy);
  const id =
    lakeraStringOrNull(record.id) ??
    lakeraStringOrNull(record.project_id) ??
    lakeraStringOrNull(record.projectId) ??
    "unknown-project";

  return {
    id,
    metadataKeys: [
      ...new Set([
        ...lakeraMetadataKeys(record.metadata),
        ...lakeraMetadataKeys(record.project_metadata),
        ...lakeraMetadataKeys(record.projectMetadata)
      ])
    ],
    name:
      lakeraStringOrNull(record.name) ??
      lakeraStringOrNull(record.display_name) ??
      lakeraStringOrNull(record.displayName) ??
      id,
    policyId:
      lakeraStringOrNull(record.policy_id) ??
      lakeraStringOrNull(record.policyId) ??
      lakeraStringOrNull(policy.id) ??
      lakeraStringOrNull(policy.policy_id) ??
      lakeraStringOrNull(policy.policyId)
  };
}

function parseLakeraPolicy(value: unknown): LakeraPolicy {
  const record = lakeraRecord(value);
  const id =
    lakeraStringOrNull(record.id) ??
    lakeraStringOrNull(record.policy_id) ??
    lakeraStringOrNull(record.policyId) ??
    "unknown-policy";

  return {
    id,
    inputDetectors: [
      ...lakeraRecordArray(record.input_detectors),
      ...lakeraRecordArray(record.inputDetectors),
      ...lakeraRecordArray(record.input_guardrails),
      ...lakeraRecordArray(record.inputGuardrails)
    ].map(parseLakeraDetector),
    mode:
      lakeraStringOrNull(record.mode) ??
      lakeraStringOrNull(record.policy_mode) ??
      lakeraStringOrNull(record.policyMode),
    name:
      lakeraStringOrNull(record.name) ??
      lakeraStringOrNull(record.display_name) ??
      lakeraStringOrNull(record.displayName) ??
      id,
    outputDetectors: [
      ...lakeraRecordArray(record.output_detectors),
      ...lakeraRecordArray(record.outputDetectors),
      ...lakeraRecordArray(record.output_guardrails),
      ...lakeraRecordArray(record.outputGuardrails)
    ].map(parseLakeraDetector)
  };
}

function loadLakeraFixtureInventory(config: Record<string, unknown>) {
  if (config.fixtureInventory) {
    return parseLakeraInventory(config.fixtureInventory);
  }

  return parseLakeraInventory({
    policies: [
      {
        id: "policy-guard-strict",
        input_detectors: [
          {
            threshold: "balanced",
            type: "prompt_injection"
          },
          {
            threshold: "strict",
            type: "pii"
          }
        ],
        mode: "blocking",
        name: "customer-support-policy",
        output_detectors: [
          {
            threshold: "strict",
            type: "data_loss"
          },
          {
            allowed_domains: ["customer.example"],
            threshold: "balanced",
            type: "malicious_links"
          }
        ]
      }
    ],
    projects: [
      {
        id: "customer-support-ai",
        metadata: {
          environment: "production",
          owner: "ai-platform"
        },
        name: "customer-support-ai",
        policy_id: "policy-guard-strict"
      }
    ]
  });
}

function parseLakeraInventory(value: unknown): LakeraInventory {
  const record = lakeraRecord(value);
  const projects = lakeraRecordArray(record.projects)
    .map(parseLakeraProject)
    .filter((project) => project.id !== "unknown-project");
  const policies = lakeraRecordArray(record.policies)
    .map(parseLakeraPolicy)
    .filter((policy) => policy.id !== "unknown-policy");

  return {
    policies,
    projects
  };
}

function lakeraApiUrl(config: LakeraApiKeyConfig, pathName: string) {
  const baseUrl = `${config.platformBaseUrl.replace(/\/+$/u, "")}/`;
  const safePath = pathName.replace(/^\/+/u, "");

  return new URL(safePath, baseUrl).toString();
}

function assertLakeraReadOnlyPath(pathName: string) {
  const pathname = new URL(pathName, "https://periscan.invalid").pathname;

  if (/\/guard(?:\/results)?(?:\/|$)/u.test(pathname)) {
    throw new Error(
      "Lakera runtime guard screening endpoints are not allowed."
    );
  }
}

function lakeraHeaders(config: LakeraApiKeyConfig) {
  return {
    authorization: `Bearer ${config.apiKey}`
  };
}

function lakeraErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown Lakera API error.";
}

async function lakeraFetchJson(config: LakeraApiKeyConfig, pathName: string) {
  assertLakeraReadOnlyPath(pathName);

  const response = await connectorFetch(lakeraApiUrl(config, pathName), {
    headers: lakeraHeaders(config),
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`Lakera API returned status ${response.status}.`);
  }

  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function loadLakeraLiveInventory(config: LakeraApiKeyConfig) {
  const projects: LakeraProject[] = [];
  const policiesById = new Map<string, LakeraPolicy>();

  for (const projectId of config.projectIds) {
    const json = await lakeraFetchJson(
      config,
      `/projects/${encodeURIComponent(projectId)}`
    );
    const project = parseLakeraProject(json);

    if (project.id !== "unknown-project") {
      projects.push(project);
    }
  }

  const policyIds = new Set([
    ...config.policyIds,
    ...projects.flatMap((project) =>
      project.policyId ? [project.policyId] : []
    )
  ]);

  for (const policyId of policyIds) {
    const json = await lakeraFetchJson(
      config,
      `/policies/${encodeURIComponent(policyId)}`
    );
    const policy = parseLakeraPolicy(json);

    if (policy.id !== "unknown-policy") {
      policiesById.set(policy.id, policy);
    }
  }

  return {
    policies: [...policiesById.values()],
    projects
  } satisfies LakeraInventory;
}

async function loadLakeraInventory(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadLakeraFixtureInventory(context.config);
  }

  const config = LakeraApiKeyConfigSchema.parse(context.config);

  if (config.projectIds.length === 0 && config.policyIds.length === 0) {
    return {
      policies: [],
      projects: []
    } satisfies LakeraInventory;
  }

  return loadLakeraLiveInventory(config);
}

function createLakeraAssets(inventory: LakeraInventory): ConnectorAssetInput[] {
  return [
    ...inventory.projects.map((project) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: "Moderate",
        environment: "ai-stack",
        identifiers: {
          metadataKeys: project.metadataKeys,
          policyId: project.policyId,
          projectId: project.id,
          resourceKind: "LakeraGuardProject"
        },
        internetExposed: false,
        name: `lakera-project/${project.name}`,
        owner: "ai-platform",
        status: "Active",
        tags: ["lakera", "guard", "project"]
      })
    ),
    ...inventory.policies.map((policy) =>
      createMockAsset({
        assetType: "Application",
        businessCriticality: "Moderate",
        environment: "ai-stack",
        identifiers: {
          inputDetectorTypes: policy.inputDetectors.map(
            (detector) => detector.detectorType
          ),
          mode: policy.mode,
          outputDetectorTypes: policy.outputDetectors.map(
            (detector) => detector.detectorType
          ),
          policyId: policy.id,
          resourceKind: "LakeraGuardPolicy"
        },
        internetExposed: false,
        name: `lakera-policy/${policy.name}`,
        owner: "ai-platform",
        status: "Active",
        tags: ["lakera", "guard", "policy"]
      })
    )
  ];
}

function classifyLakeraDetectorSignal(detector: LakeraDetector): string | null {
  const normalized = detector.detectorType.toLowerCase();

  if (normalized.includes("prompt")) {
    return "LakeraPromptDefenseConfigured";
  }

  if (
    normalized.includes("pii") ||
    normalized.includes("data") ||
    normalized.includes("leak") ||
    normalized.includes("sensitive")
  ) {
    return "LakeraDataLeakageDefenseConfigured";
  }

  if (
    normalized.includes("link") ||
    normalized.includes("url") ||
    normalized.includes("domain")
  ) {
    return "LakeraMaliciousLinkDefenseConfigured";
  }

  if (
    normalized.includes("content") ||
    normalized.includes("moderation") ||
    normalized.includes("toxic")
  ) {
    return "LakeraContentModerationConfigured";
  }

  return null;
}

function createLakeraSignals(
  inventory: LakeraInventory
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const projectSignals = inventory.projects.flatMap((project) => [
    ConnectorSignalInputSchema.parse({
      confidence: 0.88,
      freshness: "Fresh",
      rawPayloadPointer: `lakera://projects/${project.id}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Restricted",
      signalCategory: "AIApplication",
      signalSubcategory: "LakeraProjectDeclared",
      sourceType: "lakera.platform.project",
      timestampObserved
    }),
    ...(project.policyId
      ? [
          ConnectorSignalInputSchema.parse({
            confidence: 0.88,
            freshness: "Fresh",
            rawPayloadPointer: `lakera://projects/${project.id}/policy/${project.policyId}`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "Restricted",
            signalCategory: "ControlObservation",
            signalSubcategory: "LakeraProjectPolicyMapped",
            sourceType: "lakera.platform.project_policy",
            timestampObserved
          })
        ]
      : [])
  ]);
  const policySignals = inventory.policies.flatMap((policy) => {
    const detectorSignals = [
      ...policy.inputDetectors.map((detector) => ({
        detector,
        direction: "input" as const
      })),
      ...policy.outputDetectors.map((detector) => ({
        detector,
        direction: "output" as const
      }))
    ].flatMap(({ detector, direction }) => {
      const classification = classifyLakeraDetectorSignal(detector);

      return [
        ConnectorSignalInputSchema.parse({
          confidence: 0.86,
          freshness: "Fresh",
          rawPayloadPointer: `lakera://policies/${policy.id}/${direction}-detectors/${encodeURIComponent(detector.detectorType)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Restricted",
          signalCategory: "ControlObservation",
          signalSubcategory:
            direction === "input"
              ? "LakeraInputDetectorConfigured"
              : "LakeraOutputDetectorConfigured",
          sourceType: `lakera.platform.${direction}_detector`,
          timestampObserved
        }),
        ...(classification
          ? [
              ConnectorSignalInputSchema.parse({
                confidence: 0.84,
                freshness: "Fresh",
                rawPayloadPointer: `lakera://policies/${policy.id}/detector-coverage/${encodeURIComponent(detector.detectorType)}`,
                redactionStatus: "Redacted",
                relatedAssetIds: [],
                relatedControlIds: [],
                relatedEvidenceIds: [],
                relatedIdentityIds: [],
                relatedPathIds: [],
                sensitivityLevel: "Restricted",
                signalCategory: "ControlObservation",
                signalSubcategory: classification,
                sourceType: "lakera.platform.detector_coverage",
                timestampObserved
              })
            ]
          : [])
      ];
    });

    return [
      ConnectorSignalInputSchema.parse({
        confidence: 0.88,
        freshness: "Fresh",
        rawPayloadPointer: `lakera://policies/${policy.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Restricted",
        signalCategory: "AIApplication",
        signalSubcategory: "LakeraPolicyDeclared",
        sourceType: "lakera.platform.policy",
        timestampObserved
      }),
      ...(policy.mode?.toLowerCase().includes("block") ||
      policy.mode?.toLowerCase().includes("enforce")
        ? [
            ConnectorSignalInputSchema.parse({
              confidence: 0.86,
              freshness: "Fresh",
              rawPayloadPointer: `lakera://policies/${policy.id}/mode`,
              redactionStatus: "Redacted",
              relatedAssetIds: [],
              relatedControlIds: [],
              relatedEvidenceIds: [],
              relatedIdentityIds: [],
              relatedPathIds: [],
              sensitivityLevel: "Restricted",
              signalCategory: "ControlObservation",
              signalSubcategory: "LakeraBlockingPolicyConfigured",
              sourceType: "lakera.platform.policy_mode",
              timestampObserved
            })
          ]
        : []),
      ...detectorSignals
    ];
  });

  return [...projectSignals, ...policySignals];
}

function lakeraHealthFromInventory(
  inventory: LakeraInventory,
  startedAt: number,
  detailPrefix: string
) {
  return ConnectorHealthSchema.parse({
    authorizationVerified: true,
    checkedAt: new Date().toISOString(),
    detail: `${detailPrefix} ${inventory.projects.length} project(s) and ${inventory.policies.length} policy record(s); no /guard or /guard/results screening endpoints were called.`,
    latencyMs: Date.now() - startedAt,
    status: "Healthy"
  });
}

async function getLakeraHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(LAKERA_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = LakeraApiKeyConfigSchema.parse(context.config);

  if (config.projectIds.length === 0 && config.policyIds.length === 0) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        "No Lakera projectIds or policyIds are configured for read-only metadata verification.",
      latencyMs: Date.now() - startedAt,
      status: "Unknown"
    });
  }

  try {
    const inventory = await loadLakeraLiveInventory(config);

    return lakeraHealthFromInventory(
      inventory,
      startedAt,
      "Lakera API key verified for read-only metadata inventory across"
    );
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `Lakera health check failed: ${lakeraErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createLakeraConnector(): Connector {
  return {
    manifest: LAKERA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = await loadLakeraInventory(parsedContext);

      return createLakeraSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getLakeraHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const startedAt = Date.now();
      const inventory = await loadLakeraInventory(parsedContext);
      const liveConfig = parsedContext.mockMode
        ? null
        : LakeraApiKeyConfigSchema.parse(parsedContext.config);
      const health = parsedContext.mockMode
        ? createMockHealth(LAKERA_CONNECTOR_MANIFEST, parsedContext)
        : liveConfig &&
            liveConfig.projectIds.length === 0 &&
            liveConfig.policyIds.length === 0
          ? await getLakeraHealth(parsedContext)
          : lakeraHealthFromInventory(
              inventory,
              startedAt,
              "Lakera API key verified for read-only metadata inventory across"
            );

      return ConnectorSyncResultSchema.parse({
        assets: createLakeraAssets(inventory),
        health,
        signals: createLakeraSignals(inventory).map((signal) =>
          createTimestampedSignal(
            LAKERA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

