function loadBedrockFixtureModels(
  config: Record<string, unknown>
): BedrockFoundationModel[] {
  if (Array.isArray(config.fixtureModels)) {
    return config.fixtureModels
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => ({
        inputModalities: Array.isArray(item.inputModalities)
          ? item.inputModalities.map(String)
          : ["TEXT"],
        modelArn: typeof item.modelArn === "string" ? item.modelArn : null,
        modelId: connectorString(item.modelId ?? item.id, "unknown-model"),
        modelName:
          typeof item.modelName === "string"
            ? item.modelName
            : connectorString(item.name, "Unknown Bedrock model"),
        outputModalities: Array.isArray(item.outputModalities)
          ? item.outputModalities.map(String)
          : ["TEXT"],
        providerName:
          typeof item.providerName === "string" ? item.providerName : "AWS",
        responseStreamingSupported:
          typeof item.responseStreamingSupported === "boolean"
            ? item.responseStreamingSupported
            : null
      }))
      .filter((model) => model.modelId !== "unknown-model");
  }

  return [
    {
      inputModalities: ["TEXT"],
      modelArn: null,
      modelId: "anthropic.claude-3-5-sonnet-20241022-v2:0",
      modelName: "Claude 3.5 Sonnet",
      outputModalities: ["TEXT"],
      providerName: "Anthropic",
      responseStreamingSupported: true
    }
  ];
}

function normalizeBedrockModelSummary(
  summary: Record<string, unknown>
): BedrockFoundationModel {
  const modelId = connectorString(summary.modelId, "unknown-model");

  return {
    inputModalities: Array.isArray(summary.inputModalities)
      ? summary.inputModalities.map(String)
      : [],
    modelArn: typeof summary.modelArn === "string" ? summary.modelArn : null,
    modelId,
    modelName:
      typeof summary.modelName === "string" ? summary.modelName : modelId,
    outputModalities: Array.isArray(summary.outputModalities)
      ? summary.outputModalities.map(String)
      : [],
    providerName:
      typeof summary.providerName === "string"
        ? summary.providerName
        : "Unknown",
    responseStreamingSupported:
      typeof summary.responseStreamingSupported === "boolean"
        ? summary.responseStreamingSupported
        : null
  };
}

async function loadRealBedrockModels(context: ConnectorExecutionContext) {
  const clientConfig = await resolveAwsClientConfig(context);
  const client = new BedrockClient({
    credentials: clientConfig.credentials,
    region: clientConfig.region
  });
  const response = await client.send(new ListFoundationModelsCommand({}));

  return (response.modelSummaries ?? [])
    .map((summary) =>
      normalizeBedrockModelSummary(
        summary as unknown as Record<string, unknown>
      )
    )
    .filter((model) => model.modelId !== "unknown-model");
}

async function loadBedrockModels(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return loadBedrockFixtureModels(context.config);
  }

  return loadRealBedrockModels(context);
}

function createBedrockAssets(
  models: BedrockFoundationModel[]
): ConnectorAssetInput[] {
  return models.map((model) =>
    createMockAsset({
      assetType: "Application",
      businessCriticality: "Moderate",
      environment: "ai-stack",
      identifiers: {
        inputModalities: model.inputModalities,
        modelArn: model.modelArn,
        modelId: model.modelId,
        outputModalities: model.outputModalities,
        providerName: model.providerName,
        resourceKind: "AWSBedrockFoundationModel",
        responseStreamingSupported: model.responseStreamingSupported
      },
      internetExposed: false,
      name: `aws-bedrock-model/${model.modelId}`,
      owner: "ai-platform",
      status: "Active",
      tags: ["aws-bedrock", "foundation-model", model.providerName]
    })
  );
}

function createBedrockSignals(
  models: BedrockFoundationModel[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();

  return models.map((model) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.9,
      freshness: "Fresh",
      rawPayloadPointer: `aws-bedrock://foundation-models/${model.modelId}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: "Restricted",
      signalCategory: "AIApplication",
      signalSubcategory: "AIFoundationModelAvailable",
      sourceType: "aws_bedrock.foundation_models.model",
      timestampObserved
    })
  );
}

function bedrockErrorDetail(error: unknown) {
  return error instanceof Error ? error.message : "Unknown AWS Bedrock error.";
}

async function getBedrockHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(AWS_BEDROCK_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();

  try {
    await loadRealBedrockModels(context);

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail:
        "AWS Bedrock read-only foundation model inventory access verified.",
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail: `AWS Bedrock health check failed: ${bedrockErrorDetail(error)}`,
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createAwsBedrockConnector(): Connector {
  return {
    manifest: AWS_BEDROCK_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const models = await loadBedrockModels(parsedContext);

      return createBedrockSignals(models);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getBedrockHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const models = await loadBedrockModels(parsedContext);
      const health = parsedContext.mockMode
        ? await getBedrockHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail:
              "AWS Bedrock foundation model inventory loaded with read-only permissions.",
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createBedrockAssets(models),
        health,
        signals: createBedrockSignals(models).map((signal) =>
          createTimestampedSignal(
            AWS_BEDROCK_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const TenableApiKeyConfigSchema = z.object({
  accessKey: z.string().min(1),
  apiBaseUrl: z.url().default("https://cloud.tenable.com"),
  assetLimit: z.number().int().min(1).max(500).default(100),
  secretKey: z.string().min(1),
  vulnerabilityLimit: z.number().int().min(1).max(500).default(100)
});

const TenableSeveritySchema = z.enum([
  "info",
  "low",
  "medium",
  "high",
  "critical"
]);

const TenableAssetSchema = z
  .object({
    acr_score: z.number().nullable().optional(),
    asset_uuid: z.string().min(1).nullable().optional(),
    fqdn: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    hostname: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    id: z.union([z.string(), z.number()]).nullable().optional(),
    ipv4: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    last_seen: z.string().nullable().optional(),
    operating_system: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    operating_systems: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    severity_counts: z.record(z.string(), z.number()).nullable().optional()
  })
  .passthrough();

const TenableVulnerabilitySchema = z
  .object({
    count: z.number().int().nonnegative().nullable().optional(),
    cve: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    cves: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    plugin_id: z.union([z.string(), z.number()]),
    plugin_name: z.string().min(1).nullable().optional(),
    score: z.number().nullable().optional(),
    severity: z.union([z.string(), z.number()]).nullable().optional(),
    severity_id: z.number().nullable().optional(),
    vpr_score: z.number().nullable().optional(),
    vulnerability_state: z.string().nullable().optional()
  })
  .passthrough();

type TenableApiKeyConfig = z.infer<typeof TenableApiKeyConfigSchema>;
type TenableAsset = z.infer<typeof TenableAssetSchema>;
type TenableVulnerability = z.infer<typeof TenableVulnerabilitySchema>;

