function tenableApiUrl(config: TenableApiKeyConfig, pathName: string) {
  const baseUrl = config.apiBaseUrl.replace(/\/+$/u, "");

  return `${baseUrl}${pathName}`;
}

function tenableHeaders(config: TenableApiKeyConfig) {
  return {
    accept: "application/json",
    "x-apikeys": `accessKey=${config.accessKey}; secretKey=${config.secretKey}`
  };
}

async function readTenableJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Tenable API returned status ${response.status}.`);
  }

  return (await response.json().catch(() => ({}))) as Record<string, unknown>;
}

function tenableStringArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .filter((item): item is string => typeof item === "string")
      .map((item) => item.trim())
      .filter((item) => item.length > 0);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter((item) => item.length > 0);
  }

  return [];
}

function tenableSeverityName(
  value: unknown
): z.infer<typeof TenableSeveritySchema> {
  if (typeof value === "number") {
    if (value >= 4) {
      return "critical";
    }

    if (value === 3) {
      return "high";
    }

    if (value === 2) {
      return "medium";
    }

    if (value === 1) {
      return "low";
    }

    return "info";
  }

  const normalized =
    typeof value === "string" ? value.trim().toLowerCase() : "info";
  const parsed = TenableSeveritySchema.safeParse(normalized);

  return parsed.success ? parsed.data : "info";
}

function tenableAssetIdentifier(asset: TenableAsset) {
  const id = asset.asset_uuid ?? asset.id;

  return typeof id === "number" ? String(id) : (id ?? "unknown-tenable-asset");
}

function tenableAssetName(asset: TenableAsset) {
  return (
    tenableStringArray(asset.hostname)[0] ??
    tenableStringArray(asset.fqdn)[0] ??
    tenableStringArray(asset.ipv4)[0] ??
    tenableAssetIdentifier(asset)
  );
}

function tenableAssetCriticality(asset: TenableAsset) {
  const counts = asset.severity_counts ?? {};
  const critical = counts.critical ?? counts.Critical ?? 0;
  const high = counts.high ?? counts.High ?? 0;

  if (critical > 0 || (asset.acr_score ?? 0) >= 8) {
    return "Critical";
  }

  if (high > 0 || (asset.acr_score ?? 0) >= 6) {
    return "High";
  }

  return "Moderate";
}

function parseTenableAssets(json: Record<string, unknown>) {
  const values = Array.isArray(json.assets)
    ? json.assets
    : Array.isArray(json.data)
      ? json.data
      : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => TenableAssetSchema.parse(item));
}

function parseTenableVulnerabilities(json: Record<string, unknown>) {
  const values = Array.isArray(json.vulnerabilities)
    ? json.vulnerabilities
    : Array.isArray(json.data)
      ? json.data
      : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => TenableVulnerabilitySchema.parse(item));
}

async function fetchTenableInventory(config: TenableApiKeyConfig) {
  const [assetJson, vulnerabilityJson] = await Promise.all([
    connectorFetch(
      tenableApiUrl(
        config,
        `/workbenches/assets?limit=${encodeURIComponent(String(config.assetLimit))}`
      ),
      {
        headers: tenableHeaders(config)
      }
    ).then(readTenableJson),
    connectorFetch(
      tenableApiUrl(
        config,
        `/workbenches/vulnerabilities?limit=${encodeURIComponent(
          String(config.vulnerabilityLimit)
        )}`
      ),
      {
        headers: tenableHeaders(config)
      }
    ).then(readTenableJson)
  ]);

  return {
    assets: parseTenableAssets(assetJson),
    vulnerabilities: parseTenableVulnerabilities(vulnerabilityJson)
  };
}

function loadTenableFixtureInventory(config: Record<string, unknown>) {
  if (config.fixtureInventory && typeof config.fixtureInventory === "object") {
    const fixture = config.fixtureInventory as Record<string, unknown>;

    return {
      assets: parseTenableAssets({ assets: fixture.assets }),
      vulnerabilities: parseTenableVulnerabilities({
        vulnerabilities: fixture.vulnerabilities
      })
    };
  }

  return {
    assets: TENABLE_FIXTURE_ASSETS,
    vulnerabilities: TENABLE_FIXTURE_VULNERABILITIES
  };
}

function createTenableAssets(assets: TenableAsset[]): ConnectorAssetInput[] {
  return assets.map((asset) =>
    createMockAsset({
      assetType: "Host",
      businessCriticality: tenableAssetCriticality(asset),
      environment: "vulnerability-management",
      identifiers: {
        acrScore: asset.acr_score ?? null,
        fqdn: tenableStringArray(asset.fqdn),
        ipv4: tenableStringArray(asset.ipv4),
        lastSeen: asset.last_seen ?? null,
        operatingSystems: [
          ...tenableStringArray(asset.operating_system),
          ...tenableStringArray(asset.operating_systems)
        ],
        resourceKind: "TenableAsset",
        severityCounts: asset.severity_counts ?? {},
        tenableAssetId: tenableAssetIdentifier(asset)
      },
      internetExposed: tenableStringArray(asset.ipv4).some((ipAddress) =>
        /^(?!10\.|127\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.|192\.168\.)\d{1,3}\./u.test(
          ipAddress
        )
      ),
      name: `tenable/${tenableAssetName(asset)}`,
      owner: "vulnerability-management",
      status: "Active",
      tags: ["tenable", "vulnerability-management"]
    })
  );
}

function createTenableSignals(input: {
  assets: TenableAsset[];
  vulnerabilities: TenableVulnerability[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const asset of input.assets) {
    const assetId = tenableAssetIdentifier(asset);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `tenable://assets/${assetId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "VulnerabilityManagedAsset",
        sourceType: "tenable.asset.summary",
        timestampObserved: asset.last_seen ?? timestampObserved
      })
    );
  }

  for (const vulnerability of input.vulnerabilities) {
    const severity = tenableSeverityName(
      vulnerability.severity ?? vulnerability.severity_id
    );
    const cveIds = tenableStringArray(vulnerability.cve).concat(
      tenableStringArray(vulnerability.cves)
    );
    const vprScore = vulnerability.vpr_score ?? vulnerability.score ?? null;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: vprScore && vprScore >= 8 ? 0.9 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `tenable://vulnerabilities/${String(
          vulnerability.plugin_id
        )}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          severity === "critical" || severity === "high" ? "High" : "Moderate",
        signalCategory: "Exposure",
        signalSubcategory:
          severity === "critical"
            ? "CriticalVulnerability"
            : severity === "high"
              ? "HighVulnerability"
              : "VulnerabilityObservation",
        sourceType: "tenable.vulnerability.summary",
        timestampObserved
      })
    );

    for (const cveId of cveIds) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `tenable://vulnerabilities/${String(
            vulnerability.plugin_id
          )}/cves/${cveId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "CveObserved",
          sourceType: "tenable.vulnerability.cve",
          timestampObserved
        })
      );
    }
  }

  return signals;
}

async function getTenableHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(TENABLE_CONNECTOR_MANIFEST, context);
  }

  const config = TenableApiKeyConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const assetJson = await connectorFetch(
      tenableApiUrl(
        config,
        `/workbenches/assets?limit=${encodeURIComponent(String(Math.min(config.assetLimit, 1)))}`
      ),
      {
        headers: tenableHeaders(config)
      }
    ).then(readTenableJson);
    const assetCount = parseTenableAssets(assetJson).length;

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Tenable read-only workbench access verified with ${assetCount} visible asset summary record(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Tenable health check failed: ${error.message}`
          : "Tenable health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createTenableConnector(): Connector {
  return {
    manifest: TENABLE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadTenableFixtureInventory(parsedContext.config)
        : await fetchTenableInventory(
            TenableApiKeyConfigSchema.parse(parsedContext.config)
          );

      return createTenableSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getTenableHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadTenableFixtureInventory(parsedContext.config)
        : await fetchTenableInventory(
            TenableApiKeyConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getTenableHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Tenable read-only sync returned ${inventory.assets.length} asset(s) and ${inventory.vulnerabilities.length} vulnerability summary record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createTenableAssets(inventory.assets),
        health,
        signals: createTenableSignals(inventory).map((signal) =>
          createTimestampedSignal(
            TENABLE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

