function rapid7InsightVmApiUrl(
  config: Rapid7InsightVmConfig,
  pathName: string
) {
  const baseUrl = config.apiBaseUrl.replace(/\/+$/u, "");

  return `${baseUrl}${pathName}`;
}

function rapid7InsightVmHeaders(config: Rapid7InsightVmConfig) {
  return {
    accept: "application/json",
    authorization: `Basic ${Buffer.from(`${config.username}:${config.password}`).toString("base64")}`
  };
}

async function readRapid7InsightVmJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Rapid7 InsightVM API returned status ${response.status}.`);
  }

  return (await response.json().catch(() => ({}))) as Record<string, unknown>;
}

function parseRapid7InsightVmAssets(json: Record<string, unknown>) {
  const values = Array.isArray(json.resources)
    ? json.resources
    : Array.isArray(json.assets)
      ? json.assets
      : Array.isArray(json.data)
        ? json.data
        : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => Rapid7InsightVmAssetSchema.parse(item));
}

function parseRapid7InsightVmVulnerabilities(json: Record<string, unknown>) {
  const values = Array.isArray(json.resources)
    ? json.resources
    : Array.isArray(json.vulnerabilities)
      ? json.vulnerabilities
      : Array.isArray(json.data)
        ? json.data
        : [];

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => Rapid7InsightVmVulnerabilitySchema.parse(item));
}

async function fetchRapid7InsightVmInventory(config: Rapid7InsightVmConfig) {
  const [assetJson, vulnerabilityJson] = await Promise.all([
    connectorFetch(
      rapid7InsightVmApiUrl(
        config,
        `/assets?size=${encodeURIComponent(String(config.assetLimit))}`
      ),
      {
        headers: rapid7InsightVmHeaders(config)
      }
    ).then(readRapid7InsightVmJson),
    connectorFetch(
      rapid7InsightVmApiUrl(
        config,
        `/vulnerabilities?size=${encodeURIComponent(
          String(config.vulnerabilityLimit)
        )}`
      ),
      {
        headers: rapid7InsightVmHeaders(config)
      }
    ).then(readRapid7InsightVmJson)
  ]);

  return {
    assets: parseRapid7InsightVmAssets(assetJson),
    vulnerabilities: parseRapid7InsightVmVulnerabilities(vulnerabilityJson)
  };
}

function loadRapid7InsightVmFixtureInventory(config: Record<string, unknown>) {
  if (config.fixtureInventory && typeof config.fixtureInventory === "object") {
    const fixture = config.fixtureInventory as Record<string, unknown>;

    return {
      assets: parseRapid7InsightVmAssets({ resources: fixture.assets }),
      vulnerabilities: parseRapid7InsightVmVulnerabilities({
        resources: fixture.vulnerabilities
      })
    };
  }

  return {
    assets: RAPID7_INSIGHTVM_FIXTURE_ASSETS,
    vulnerabilities: RAPID7_INSIGHTVM_FIXTURE_VULNERABILITIES
  };
}

function rapid7InsightVmSeverityName(value: unknown) {
  if (typeof value === "number") {
    if (value >= 9) {
      return "critical";
    }

    if (value >= 7) {
      return "high";
    }

    if (value >= 4) {
      return "medium";
    }

    return "low";
  }

  const normalized =
    typeof value === "string" ? value.trim().toLowerCase() : "low";

  if (["critical", "severe"].includes(normalized)) {
    return "critical";
  }

  if (["high", "important"].includes(normalized)) {
    return "high";
  }

  if (["moderate", "medium"].includes(normalized)) {
    return "medium";
  }

  return "low";
}

function rapid7InsightVmAssetId(asset: Rapid7InsightVmAsset) {
  return String(asset.id);
}

function rapid7InsightVmAssetAddresses(asset: Rapid7InsightVmAsset) {
  return [...asset.addresses, ...(asset.ip ? [asset.ip] : [])].filter(
    (value, index, values) => values.indexOf(value) === index
  );
}

function rapid7InsightVmAssetName(asset: Rapid7InsightVmAsset) {
  return (
    asset.hostName ??
    asset.hostNames[0] ??
    rapid7InsightVmAssetAddresses(asset)[0] ??
    rapid7InsightVmAssetId(asset)
  );
}

function rapid7InsightVmCriticality(asset: Rapid7InsightVmAsset) {
  const critical = asset.vulnerabilities?.critical ?? 0;
  const severe = asset.vulnerabilities?.severe ?? 0;

  if (critical > 0 || (asset.riskScore ?? 0) >= 800) {
    return "Critical";
  }

  if (severe > 0 || (asset.riskScore ?? 0) >= 600) {
    return "High";
  }

  return "Moderate";
}

function createRapid7InsightVmAssets(
  assets: Rapid7InsightVmAsset[]
): ConnectorAssetInput[] {
  return assets.map((asset) =>
    createMockAsset({
      assetType: "Host",
      businessCriticality: rapid7InsightVmCriticality(asset),
      environment: "vulnerability-management",
      identifiers: {
        addresses: rapid7InsightVmAssetAddresses(asset),
        criticality: asset.criticality ?? null,
        hostNames: [
          ...(asset.hostName ? [asset.hostName] : []),
          ...asset.hostNames
        ],
        lastScanTime: asset.lastScanTime ?? null,
        operatingSystem: asset.os ?? null,
        rapid7AssetId: rapid7InsightVmAssetId(asset),
        resourceKind: "Rapid7InsightVmAsset",
        riskScore: asset.riskScore ?? null,
        vulnerabilityCounts: asset.vulnerabilities ?? {}
      },
      internetExposed: rapid7InsightVmAssetAddresses(asset).some((ipAddress) =>
        /^(?!10\.|127\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.|192\.168\.)\d{1,3}\./u.test(
          ipAddress
        )
      ),
      name: `rapid7-insightvm/${rapid7InsightVmAssetName(asset)}`,
      owner: "vulnerability-management",
      status: "Active",
      tags: ["rapid7", "insightvm", "vulnerability-management"]
    })
  );
}

function createRapid7InsightVmSignals(input: {
  assets: Rapid7InsightVmAsset[];
  vulnerabilities: Rapid7InsightVmVulnerability[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const asset of input.assets) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `rapid7-insightvm://assets/${rapid7InsightVmAssetId(asset)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "VulnerabilityManagedAsset",
        sourceType: "rapid7_insightvm.asset.summary",
        timestampObserved: asset.lastScanTime ?? timestampObserved
      })
    );
  }

  for (const vulnerability of input.vulnerabilities) {
    const severity = rapid7InsightVmSeverityName(
      vulnerability.severity ?? vulnerability.cvssScore
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence:
          typeof vulnerability.cvssScore === "number" &&
          vulnerability.cvssScore >= 8
            ? 0.9
            : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `rapid7-insightvm://vulnerabilities/${vulnerability.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          severity === "critical" || severity === "high" ? "High" : "Moderate",
        signalCategory: "Exposure",
        signalSubcategory:
          severity === "critical"
            ? "CriticalVulnerability"
            : severity === "high"
              ? "HighVulnerability"
              : "VulnerabilityObservation",
        sourceType: "rapid7_insightvm.vulnerability.summary",
        timestampObserved: vulnerability.added ?? timestampObserved
      })
    );

    for (const cveId of vulnerability.cves) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `rapid7-insightvm://vulnerabilities/${vulnerability.id}/cves/${cveId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "CveObserved",
          sourceType: "rapid7_insightvm.vulnerability.cve",
          timestampObserved: vulnerability.added ?? timestampObserved
        })
      );
    }
  }

  return signals;
}

async function getRapid7InsightVmHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(RAPID7_INSIGHTVM_CONNECTOR_MANIFEST, context);
  }

  const config = Rapid7InsightVmConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const assetJson = await connectorFetch(
      rapid7InsightVmApiUrl(
        config,
        `/assets?size=${encodeURIComponent(String(Math.min(config.assetLimit, 1)))}`
      ),
      {
        headers: rapid7InsightVmHeaders(config)
      }
    ).then(readRapid7InsightVmJson);
    const assetCount = parseRapid7InsightVmAssets(assetJson).length;

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Rapid7 InsightVM read-only access verified with ${assetCount} visible asset summary record(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Rapid7 InsightVM health check failed: ${error.message}`
          : "Rapid7 InsightVM health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createRapid7InsightVmConnector(): Connector {
  return {
    manifest: RAPID7_INSIGHTVM_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadRapid7InsightVmFixtureInventory(parsedContext.config)
        : await fetchRapid7InsightVmInventory(
            Rapid7InsightVmConfigSchema.parse(parsedContext.config)
          );

      return createRapid7InsightVmSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getRapid7InsightVmHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadRapid7InsightVmFixtureInventory(parsedContext.config)
        : await fetchRapid7InsightVmInventory(
            Rapid7InsightVmConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getRapid7InsightVmHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Rapid7 InsightVM read-only sync returned ${inventory.assets.length} asset(s) and ${inventory.vulnerabilities.length} vulnerability summary record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createRapid7InsightVmAssets(inventory.assets),
        health,
        signals: createRapid7InsightVmSignals(inventory).map((signal) =>
          createTimestampedSignal(
            RAPID7_INSIGHTVM_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

