function wizStringArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .filter((item): item is string => typeof item === "string")
      .map((item) => item.trim())
      .filter((item) => item.length > 0);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter((item) => item.length > 0);
  }

  return [];
}

async function getWizAccessToken(config: WizOAuthConfig) {
  const body = new URLSearchParams({
    audience: config.audience,
    client_id: config.clientId,
    client_secret: config.clientSecret,
    grant_type: "client_credentials"
  });
  const response = await connectorFetch(config.tokenUrl, {
    body,
    headers: {
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(`Wiz token request returned status ${response.status}.`);
  }

  const json = (await response.json().catch(() => ({}))) as {
    access_token?: string;
  };

  if (!json.access_token) {
    throw new Error("Wiz token response did not include an access token.");
  }

  return json.access_token;
}

async function fetchWizGraphql<T>(
  config: WizOAuthConfig,
  accessToken: string,
  body: Record<string, unknown>
) {
  const response = await connectorFetch(config.graphqlUrl, {
    body: JSON.stringify(body),
    headers: {
      authorization: `Bearer ${accessToken}`,
      "content-type": "application/json"
    },
    method: "POST"
  });

  if (!response.ok) {
    throw new Error(`Wiz GraphQL request returned status ${response.status}.`);
  }

  const payload = (await response.json().catch(() => ({}))) as {
    data?: T;
    errors?: unknown[];
  };

  if (payload.errors?.length) {
    throw new Error("Wiz GraphQL request returned errors.");
  }

  return payload.data;
}

function wizNodes(value: unknown): unknown[] {
  if (!value || typeof value !== "object") {
    return [];
  }

  const object = value as Record<string, unknown>;

  if (Array.isArray(object.nodes)) {
    return object.nodes;
  }

  if (Array.isArray(object.edges)) {
    return object.edges
      .map((edge) =>
        edge && typeof edge === "object"
          ? (edge as Record<string, unknown>).node
          : null
      )
      .filter(Boolean);
  }

  if (Array.isArray(object.items)) {
    return object.items;
  }

  return [];
}

function parseWizIssues(value: unknown) {
  return wizNodes(value)
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => WizIssueSchema.parse(item));
}

function parseWizResources(value: unknown) {
  return wizNodes(value)
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => WizResourceSchema.parse(item));
}

async function fetchWizInventory(config: WizOAuthConfig) {
  const accessToken = await getWizAccessToken(config);
  const issueQuery =
    "query PeriscanWizIssues($first: Int!, $projectIds: [String!]) { issues(first: $first, filterBy: { project: $projectIds }) { nodes { id title name severity status type createdAt updatedAt cves entitySnapshot { id name type nativeType providerUniqueId } } } }";
  const resourceQuery =
    "query PeriscanWizCloudResources($first: Int!, $projectIds: [String!]) { cloudResources(first: $first, filterBy: { project: $projectIds }) { nodes { id name type nativeType providerUniqueId cloudPlatform cloudProvider subscriptionExternalId region status internetExposure } } }";
  const [issueData, resourceData] = await Promise.all([
    fetchWizGraphql<{
      issues?: unknown;
    }>(config, accessToken, {
      query: issueQuery,
      variables: {
        first: config.issueLimit,
        projectIds: config.projectIds
      }
    }),
    fetchWizGraphql<{
      cloudResources?: unknown;
    }>(config, accessToken, {
      query: resourceQuery,
      variables: {
        first: config.resourceLimit,
        projectIds: config.projectIds
      }
    })
  ]);

  return {
    issues: parseWizIssues(issueData?.issues),
    resources: parseWizResources(resourceData?.cloudResources)
  };
}

function loadWizFixtureInventory(config: Record<string, unknown>) {
  if (config.fixtureInventory && typeof config.fixtureInventory === "object") {
    const fixture = config.fixtureInventory as Record<string, unknown>;

    return {
      issues: parseWizIssues({ nodes: fixture.issues }),
      resources: parseWizResources({ nodes: fixture.resources })
    };
  }

  return {
    issues: WIZ_FIXTURE_ISSUES,
    resources: WIZ_FIXTURE_RESOURCES
  };
}

function wizResourceName(resource: WizResource) {
  return resource.name ?? resource.providerUniqueId ?? resource.id;
}

function wizIssueSeverity(value: unknown) {
  const normalized =
    typeof value === "string" ? value.trim().toLowerCase() : "low";

  if (normalized === "critical") {
    return "critical";
  }

  if (["high", "severe"].includes(normalized)) {
    return "high";
  }

  if (["medium", "moderate"].includes(normalized)) {
    return "medium";
  }

  return "low";
}

function createWizAssets(resources: WizResource[]): ConnectorAssetInput[] {
  return resources.map((resource) =>
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality: resource.internetExposure ? "High" : "Moderate",
      environment: "cloud",
      identifiers: {
        cloudPlatform: resource.cloudPlatform ?? resource.cloudProvider ?? null,
        internetExposure: resource.internetExposure ?? null,
        nativeType: resource.nativeType ?? null,
        providerUniqueId: resource.providerUniqueId ?? null,
        region: resource.region ?? null,
        resourceKind: "WizCloudResource",
        status: resource.status ?? null,
        subscriptionExternalId: resource.subscriptionExternalId ?? null,
        type: resource.type ?? null,
        wizResourceId: resource.id
      },
      internetExposed: resource.internetExposure === true,
      name: `wiz/${wizResourceName(resource)}`,
      owner: "cloud-security",
      status:
        resource.status?.toLowerCase() === "inactive" ? "Inactive" : "Active",
      tags: ["wiz", "cnapp", resource.type ?? "cloud-resource"]
    })
  );
}

function createWizSignals(input: {
  issues: WizIssue[];
  resources: WizResource[];
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const resource of input.resources) {
    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `wiz://resources/${resource.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: resource.internetExposure ? "High" : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "CnappCloudResource",
        sourceType: "wiz.cloud_resource.summary",
        timestampObserved
      })
    );

    if (resource.internetExposure) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.88,
          freshness: "Fresh",
          rawPayloadPointer: `wiz://resources/${resource.id}/internet-exposure`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Exposure",
          signalSubcategory: "CloudResourceInternetExposed",
          sourceType: "wiz.cloud_resource.internet_exposure",
          timestampObserved
        })
      );
    }
  }

  for (const issue of input.issues) {
    const severity = wizIssueSeverity(issue.severity);
    const cveIds = wizStringArray(issue.cve).concat(wizStringArray(issue.cves));

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: severity === "critical" ? 0.9 : 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `wiz://issues/${issue.id}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          severity === "critical" || severity === "high" ? "High" : "Moderate",
        signalCategory: "Exposure",
        signalSubcategory:
          severity === "critical"
            ? "CriticalCnappIssue"
            : severity === "high"
              ? "HighCnappIssue"
              : "CnappIssue",
        sourceType: "wiz.issue.summary",
        timestampObserved:
          issue.updatedAt ?? issue.createdAt ?? timestampObserved
      })
    );

    for (const cveId of cveIds) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.83,
          freshness: "Fresh",
          rawPayloadPointer: `wiz://issues/${issue.id}/cves/${cveId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "CveObserved",
          sourceType: "wiz.issue.cve",
          timestampObserved:
            issue.updatedAt ?? issue.createdAt ?? timestampObserved
        })
      );
    }
  }

  return signals;
}

async function getWizHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(WIZ_CONNECTOR_MANIFEST, context);
  }

  const config = WizOAuthConfigSchema.parse(context.config);
  const startedAt = Date.now();

  try {
    const accessToken = await getWizAccessToken(config);
    const resourceData = await fetchWizGraphql<{
      cloudResources?: unknown;
    }>(config, accessToken, {
      query:
        "query PeriscanWizHealth($first: Int!) { cloudResources(first: $first) { nodes { id name } } }",
      variables: {
        first: 1
      }
    });
    const resourceCount = parseWizResources(
      resourceData?.cloudResources
    ).length;

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Wiz read-only GraphQL access verified with ${resourceCount} visible cloud resource(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Wiz health check failed: ${error.message}`
          : "Wiz health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createWizConnector(): Connector {
  return {
    manifest: WIZ_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadWizFixtureInventory(parsedContext.config)
        : await fetchWizInventory(
            WizOAuthConfigSchema.parse(parsedContext.config)
          );

      return createWizSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getWizHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadWizFixtureInventory(parsedContext.config)
        : await fetchWizInventory(
            WizOAuthConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getWizHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Wiz read-only sync returned ${inventory.resources.length} cloud resource(s) and ${inventory.issues.length} issue summary record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createWizAssets(inventory.resources),
        health,
        signals: createWizSignals(inventory).map((signal) =>
          createTimestampedSignal(WIZ_CONNECTOR_MANIFEST, parsedContext, signal)
        )
      });
    }
  };
}

