const LaceworkHostVulnerabilitySchema = z.record(z.string(), z.unknown());

type LaceworkConfig = z.infer<typeof LaceworkConfigSchema>;
type LaceworkHostVulnerability = z.infer<
  typeof LaceworkHostVulnerabilitySchema
>;

