function orcaConfigFromContext(context: ConnectorExecutionContext) {
  return OrcaSecurityConfigSchema.parse(
    context.mockMode
      ? {
          ...context.config,
          apiBaseUrl: "https://app.us.orcasecurity.example.test/api",
          apiToken: "mock-orca-api-token"
        }
      : context.config
  );
}

function orcaApiUrl(config: OrcaSecurityConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}/${pathName.replace(/^\/+/u, "")}`;
}

function isOrcaRecord(item: unknown): item is Record<string, unknown> {
  return Boolean(item) && typeof item === "object" && !Array.isArray(item);
}

function parseOrcaAlerts(payload: unknown): OrcaSecurityAlert[] {
  if (Array.isArray(payload)) {
    return payload
      .filter(isOrcaRecord)
      .map((item) => OrcaSecurityAlertSchema.parse(item));
  }

  if (!payload || typeof payload !== "object") {
    return [];
  }

  const container = payload as Record<string, unknown>;
  const listKeys = ["alerts", "data", "items", "results", "records", "value"];
  const alerts = listKeys.flatMap((key) => {
    const value = container[key];

    return Array.isArray(value)
      ? value
          .filter(isOrcaRecord)
          .map((item) => OrcaSecurityAlertSchema.parse(item))
      : [];
  });

  if (alerts.length > 0) {
    return alerts;
  }

  if (
    "alert_id" in container ||
    "alertId" in container ||
    "asset_name" in container ||
    "severity" in container
  ) {
    return [OrcaSecurityAlertSchema.parse(container)];
  }

  return [];
}

async function fetchOrcaAlerts(config: OrcaSecurityConfig) {
  const url = new URL(orcaApiUrl(config, config.alertsPath));

  url.searchParams.set("limit", String(config.alertLimit));

  const response = await connectorFetch(url, {
    headers: {
      accept: "application/json",
      authorization: `${config.authHeaderPrefix} ${config.apiToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(
      `Orca Security alerts API returned status ${response.status}.`
    );
  }

  return parseOrcaAlerts(await response.json()).slice(0, config.alertLimit);
}

function orcaRecordValue(record: OrcaSecurityAlert, keys: string[]) {
  for (const key of keys) {
    const value = record[key];

    if (typeof value === "string" && value.trim().length > 0) {
      return value;
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }

    if (typeof value === "boolean") {
      return String(value);
    }
  }

  return null;
}

function orcaAlertId(record: OrcaSecurityAlert, index: number) {
  return (
    orcaRecordValue(record, ["alert_id", "alertId", "id", "finding_id"]) ??
    `orca-alert-${index + 1}`
  );
}

function orcaAssetId(record: OrcaSecurityAlert, index: number) {
  return (
    orcaRecordValue(record, [
      "asset_id",
      "assetId",
      "asset_unique_id",
      "asset_name",
      "assetName",
      "resource_id"
    ]) ?? `orca-asset-${index + 1}`
  );
}

function orcaAssetName(record: OrcaSecurityAlert, index: number) {
  return (
    orcaRecordValue(record, [
      "asset_name",
      "assetName",
      "resource_name",
      "resourceName",
      "name"
    ]) ?? orcaAssetId(record, index)
  );
}

function orcaSeverity(record: OrcaSecurityAlert) {
  const normalized = (
    orcaRecordValue(record, ["severity", "risk_level", "riskLevel"]) ?? "low"
  )
    .trim()
    .toLowerCase();

  if (normalized === "critical") {
    return "critical";
  }

  if (["high", "severe"].includes(normalized)) {
    return "high";
  }

  if (["medium", "moderate"].includes(normalized)) {
    return "medium";
  }

  return "low";
}

function orcaTimestamp(record: OrcaSecurityAlert, fallback: string) {
  const value = orcaRecordValue(record, [
    "updated_at",
    "updatedAt",
    "last_seen",
    "lastSeen",
    "created_at",
    "createdAt"
  ]);

  if (!value) {
    return fallback;
  }

  const parsed = new Date(value);

  return Number.isNaN(parsed.getTime()) ? fallback : parsed.toISOString();
}

function orcaCveIds(record: OrcaSecurityAlert) {
  const text = JSON.stringify(record);
  const matches = text.match(/\bCVE-\d{4}-\d{4,}\b/giu) ?? [];

  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

function orcaInternetExposed(record: OrcaSecurityAlert) {
  const explicit = orcaRecordValue(record, [
    "is_public",
    "isPublic",
    "publicly_accessible",
    "internet_exposed"
  ]);

  if (explicit) {
    return /^(true|yes|1)$/iu.test(explicit);
  }

  return /(^|[^a-z])(internet|public|external|exposed)([^a-z]|$)/iu.test(
    JSON.stringify(record)
  );
}

function loadOrcaFixtureAlerts(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureAlerts)) {
    return parseOrcaAlerts(config.fixtureAlerts);
  }

  return ORCA_SECURITY_FIXTURE_ALERTS;
}

function createOrcaAssets(alerts: OrcaSecurityAlert[]) {
  const assets = new Map<string, OrcaSecurityAlert>();

  alerts.forEach((alert, index) => {
    assets.set(orcaAssetId(alert, index), alert);
  });

  return [...assets.entries()].map(([assetId, alert], index) =>
    createMockAsset({
      assetType: "CloudResource",
      businessCriticality: orcaInternetExposed(alert) ? "High" : "Moderate",
      environment: "cloud",
      identifiers: {
        assetId,
        assetType:
          orcaRecordValue(alert, [
            "asset_type",
            "assetType",
            "resource_type"
          ]) ?? null,
        cloudAccountId:
          orcaRecordValue(alert, ["cloud_account_id", "cloudAccountId"]) ??
          null,
        cloudProvider:
          orcaRecordValue(alert, ["cloud_provider", "cloudProvider"]) ?? null,
        provider: "orca-security"
      },
      internetExposed: orcaInternetExposed(alert),
      name: `orca/${orcaAssetName(alert, index)}`,
      owner: "cloud-security",
      status: "Active",
      tags: ["orca-security", "cnapp", "cloud-resource"]
    })
  );
}

function createOrcaSignals(alerts: OrcaSecurityAlert[]) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];
  const seenAssets = new Set<string>();

  alerts.forEach((alert, index) => {
    const assetId = orcaAssetId(alert, index);
    const alertId = orcaAlertId(alert, index);
    const severity = orcaSeverity(alert);
    const observedAt = orcaTimestamp(alert, timestampObserved);

    if (!seenAssets.has(assetId)) {
      seenAssets.add(assetId);
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `orca-security://assets/${encodeURIComponent(assetId)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: orcaInternetExposed(alert) ? "High" : "Moderate",
          signalCategory: "Asset",
          signalSubcategory: "CnappCloudResource",
          sourceType: "orca_security.asset.summary",
          timestampObserved: observedAt
        })
      );

      if (orcaInternetExposed(alert)) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: 0.84,
            freshness: "Fresh",
            rawPayloadPointer: `orca-security://assets/${encodeURIComponent(
              assetId
            )}/internet-exposure`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: "High",
            signalCategory: "Exposure",
            signalSubcategory: "CloudResourceInternetExposed",
            sourceType: "orca_security.asset.internet_exposure",
            timestampObserved: observedAt
          })
        );
      }
    }

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: severity === "critical" ? 0.88 : 0.82,
        freshness: "Fresh",
        rawPayloadPointer: `orca-security://alerts/${encodeURIComponent(alertId)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel:
          severity === "critical" || severity === "high" ? "High" : "Moderate",
        signalCategory: "Exposure",
        signalSubcategory:
          severity === "critical"
            ? "CriticalCnappIssue"
            : severity === "high"
              ? "HighCnappIssue"
              : "CnappIssue",
        sourceType: "orca_security.alert.summary",
        timestampObserved: observedAt
      })
    );

    for (const cveId of orcaCveIds(alert)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `orca-security://alerts/${encodeURIComponent(
            alertId
          )}/cves/${cveId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "CveObserved",
          sourceType: "orca_security.alert.cve",
          timestampObserved: observedAt
        })
      );
    }
  });

  return signals;
}

async function getOrcaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ORCA_SECURITY_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = orcaConfigFromContext(context);

  try {
    const alerts = await fetchOrcaAlerts({
      ...config,
      alertLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Orca Security read-only alert access verified with ${alerts.length} visible alert record(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Orca Security health check failed: ${error.message}`
          : "Orca Security health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createOrcaSecurityConnector(): Connector {
  return {
    manifest: ORCA_SECURITY_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const alerts = parsedContext.mockMode
        ? loadOrcaFixtureAlerts(parsedContext.config)
        : await fetchOrcaAlerts(orcaConfigFromContext(parsedContext));

      return createOrcaSignals(alerts);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getOrcaHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const alerts = parsedContext.mockMode
        ? loadOrcaFixtureAlerts(parsedContext.config)
        : await fetchOrcaAlerts(orcaConfigFromContext(parsedContext));
      const health = parsedContext.mockMode
        ? await getOrcaHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Orca Security read-only sync returned ${alerts.length} alert record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createOrcaAssets(alerts),
        health,
        signals: createOrcaSignals(alerts).map((signal) =>
          createTimestampedSignal(
            ORCA_SECURITY_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const QualysVmdrConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://qualysapi.qualys.com"),
  assetLimit: z.number().int().min(1).max(500).default(100),
  detectionLimit: z.number().int().min(1).max(500).default(100),
  password: z.string().min(1),
  username: z.string().min(1)
});

const QualysAssetSchema = z
  .object({
    dnsName: z.string().nullable().optional(),
    hostname: z.string().nullable().optional(),
    id: z.union([z.string(), z.number()]),
    ip: z.string().nullable().optional(),
    ips: z.array(z.string()).default([]),
    lastScanDate: z.string().nullable().optional(),
    netbiosName: z.string().nullable().optional(),
    os: z.string().nullable().optional(),
    severityCounts: z
      .object({
        critical: z.number().int().nonnegative().default(0),
        high: z.number().int().nonnegative().default(0),
        medium: z.number().int().nonnegative().default(0)
      })
      .partial()
      .nullable()
      .optional(),
    trackingMethod: z.string().nullable().optional()
  })
  .passthrough();

const QualysDetectionSchema = z
  .object({
    cves: z
      .union([z.string(), z.array(z.string())])
      .nullable()
      .optional(),
    cvssScore: z.number().nullable().optional(),
    firstFoundDate: z.string().nullable().optional(),
    hostId: z.union([z.string(), z.number()]).nullable().optional(),
    lastFoundDate: z.string().nullable().optional(),
    qid: z.union([z.string(), z.number()]),
    severity: z.union([z.string(), z.number()]).nullable().optional(),
    status: z.string().nullable().optional(),
    title: z.string().nullable().optional()
  })
  .passthrough();

type QualysVmdrConfig = z.infer<typeof QualysVmdrConfigSchema>;
type QualysAsset = z.infer<typeof QualysAssetSchema>;
type QualysDetection = z.infer<typeof QualysDetectionSchema>;

