function runZeroApiUrl(config: RunZeroConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}${pathName}`;
}

function runZeroHeaders(config: RunZeroConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.exportToken}`
  };
}

function runZeroStringArray(value: unknown) {
  if (Array.isArray(value)) {
    return value.flatMap((item) =>
      typeof item === "string" && item.trim() ? [item.trim()] : []
    );
  }

  if (typeof value === "string" && value.trim()) {
    return value
      .split(/[,;\s]+/u)
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
}

function runZeroNumberArray(value: unknown) {
  if (Array.isArray(value)) {
    return value
      .map((item) =>
        typeof item === "number" ? item : Number.parseInt(String(item), 10)
      )
      .filter((item) => Number.isFinite(item));
  }

  if (typeof value === "string") {
    return value
      .split(/[,;\s]+/u)
      .map((item) => Number.parseInt(item, 10))
      .filter((item) => Number.isFinite(item));
  }

  return [];
}

function runZeroAssetId(asset: RunZeroAsset) {
  return String(asset.id);
}

function runZeroAssetName(asset: RunZeroAsset) {
  return (
    asset.hostname ??
    asset.name ??
    asset.address ??
    runZeroStringArray(asset.addresses)[0] ??
    runZeroAssetId(asset)
  );
}

function runZeroAssetAddresses(asset: RunZeroAsset) {
  return [
    ...runZeroStringArray(asset.address),
    ...runZeroStringArray(asset.addresses),
    ...runZeroStringArray(asset.ip),
    ...runZeroStringArray(asset.ipv4),
    ...runZeroStringArray(asset.ipv6)
  ].filter((item, index, values) => values.indexOf(item) === index);
}

function runZeroAssetProtocols(asset: RunZeroAsset) {
  const serviceProtocols = (asset.services ?? []).flatMap((service) => {
    if (!service || typeof service !== "object") {
      return [];
    }

    const protocol = (service as Record<string, unknown>).protocol;

    return typeof protocol === "string" && protocol.trim()
      ? [protocol.trim().toLowerCase()]
      : [];
  });

  return [...runZeroStringArray(asset.protocols), ...serviceProtocols]
    .map((protocol) => protocol.toLowerCase())
    .filter((item, index, values) => values.indexOf(item) === index);
}

function runZeroAssetPorts(asset: RunZeroAsset) {
  const servicePorts = (asset.services ?? []).flatMap((service) => {
    if (!service || typeof service !== "object") {
      return [];
    }

    const port = (service as Record<string, unknown>).port;
    const parsedPort =
      typeof port === "number" ? port : Number.parseInt(String(port), 10);

    return Number.isFinite(parsedPort) ? [parsedPort] : [];
  });

  return [
    ...runZeroNumberArray(asset.tcp_ports),
    ...runZeroNumberArray(asset.udp_ports),
    ...servicePorts
  ]
    .filter((item) => item > 0 && item <= 65_535)
    .filter((item, index, values) => values.indexOf(item) === index)
    .sort((left, right) => left - right);
}

function runZeroAssetIsInternetExposed(asset: RunZeroAsset) {
  return runZeroAssetAddresses(asset).some((ipAddress) =>
    /^(?!10\.|127\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.|192\.168\.)\d{1,3}\./u.test(
      ipAddress
    )
  );
}

function runZeroAssetCriticality(asset: RunZeroAsset) {
  const ports = runZeroAssetPorts(asset);

  if (runZeroAssetIsInternetExposed(asset) && ports.length >= 2) {
    return "High";
  }

  if (runZeroAssetIsInternetExposed(asset)) {
    return "Moderate";
  }

  return "Low";
}

function parseRunZeroAssets(payload: unknown) {
  let values: unknown[] = [];

  if (Array.isArray(payload)) {
    values = payload;
  } else if (payload && typeof payload === "object") {
    const record = payload as Record<string, unknown>;

    if (Array.isArray(record.assets)) {
      values = record.assets;
    } else if (Array.isArray(record.data)) {
      values = record.data;
    }
  }

  return values
    .filter(
      (item): item is Record<string, unknown> =>
        Boolean(item) && typeof item === "object"
    )
    .map((item) => RunZeroAssetSchema.parse(item));
}

async function readRunZeroJson(response: Response) {
  if (!response.ok) {
    throw new Error(`runZero Export API returned status ${response.status}.`);
  }

  return (await response.json()) as unknown;
}

async function fetchRunZeroAssets(config: RunZeroConfig) {
  const url = new URL(
    runZeroApiUrl(config, "/api/v1.0/export/org/assets.json")
  );

  if (config.search) {
    url.searchParams.set("search", config.search);
  }

  const payload = await connectorFetch(url, {
    headers: runZeroHeaders(config)
  }).then(readRunZeroJson);

  return parseRunZeroAssets(payload).slice(0, config.assetLimit);
}

function loadRunZeroFixtureAssets(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureAssets)) {
    return parseRunZeroAssets(config.fixtureAssets);
  }

  return RUNZERO_FIXTURE_ASSETS;
}

function createRunZeroAssets(assets: RunZeroAsset[]): ConnectorAssetInput[] {
  return assets.map((asset) =>
    createMockAsset({
      assetType: "Host",
      businessCriticality: runZeroAssetCriticality(asset),
      environment: "asset-inventory",
      identifiers: {
        addresses: runZeroAssetAddresses(asset),
        alive: asset.alive ?? null,
        lastSeen: asset.last_seen ?? asset.lastSeen ?? null,
        openPorts: runZeroAssetPorts(asset),
        operatingSystem: asset.os ?? null,
        protocols: runZeroAssetProtocols(asset),
        resourceKind: "RunZeroAsset",
        runZeroAssetId: runZeroAssetId(asset),
        siteId: asset.site_id ?? null,
        siteName: asset.site_name ?? null,
        type: asset.type ?? null
      },
      internetExposed: runZeroAssetIsInternetExposed(asset),
      name: `runzero/${runZeroAssetName(asset)}`,
      owner: "asset-inventory",
      status: asset.alive === false ? "Inactive" : "Active",
      tags: ["runzero", "asset-inventory"]
    })
  );
}

function createRunZeroSignals(assets: RunZeroAsset[]): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const asset of assets) {
    const assetId = runZeroAssetId(asset);
    const ports = runZeroAssetPorts(asset);
    const protocols = runZeroAssetProtocols(asset);
    const observedAt = asset.last_seen ?? asset.lastSeen ?? timestampObserved;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.86,
        freshness: "Fresh",
        rawPayloadPointer: `runzero://assets/${assetId}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "AssetInventoryObserved",
        sourceType: "runzero.export.asset",
        timestampObserved: observedAt
      })
    );

    if (ports.length > 0 || protocols.length > 0) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `runzero://assets/${assetId}/services`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: runZeroAssetIsInternetExposed(asset)
            ? "High"
            : "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "ServiceObservation",
          sourceType: "runzero.export.services",
          timestampObserved: observedAt
        })
      );
    }

    if (runZeroAssetIsInternetExposed(asset)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.83,
          freshness: "Fresh",
          rawPayloadPointer: `runzero://assets/${assetId}/public-exposure`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Exposure",
          signalSubcategory: "PublicExposure",
          sourceType: "runzero.export.public_exposure",
          timestampObserved: observedAt
        })
      );
    }
  }

  return signals;
}

async function getRunZeroHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(RUNZERO_CONNECTOR_MANIFEST, context);
  }

  try {
    const config = RunZeroConfigSchema.parse(context.config);
    const assets = await fetchRunZeroAssets({
      ...config,
      assetLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `runZero read-only Export API access verified with ${assets.length} visible asset record(s).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `runZero health check failed: ${error.message}`
          : "runZero health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

function createRunZeroConnector(): Connector {
  return {
    manifest: RUNZERO_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const assets = parsedContext.mockMode
        ? loadRunZeroFixtureAssets(parsedContext.config)
        : await fetchRunZeroAssets(
            RunZeroConfigSchema.parse(parsedContext.config)
          );

      return createRunZeroSignals(assets);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getRunZeroHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const assets = parsedContext.mockMode
        ? loadRunZeroFixtureAssets(parsedContext.config)
        : await fetchRunZeroAssets(
            RunZeroConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getRunZeroHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `runZero read-only sync returned ${assets.length} asset record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createRunZeroAssets(assets),
        health,
        signals: createRunZeroSignals(assets).map((signal) =>
          createTimestampedSignal(
            RUNZERO_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

