function assetnoteConfigFromContext(context: ConnectorExecutionContext) {
  return AssetnoteConfigSchema.parse(
    context.mockMode
      ? {
          ...context.config,
          apiBaseUrl: "https://api.assetnote.example.test",
          apiToken: "mock-assetnote-api-token"
        }
      : context.config
  );
}

function assetnoteApiUrl(config: AssetnoteConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}/${pathName.replace(/^\/+/u, "")}`;
}

function isAssetnoteRecord(item: unknown): item is Record<string, unknown> {
  return Boolean(item) && typeof item === "object" && !Array.isArray(item);
}

function parseAssetnoteAssets(payload: unknown): AssetnoteAsset[] {
  if (Array.isArray(payload)) {
    return payload
      .filter(isAssetnoteRecord)
      .map((item) => AssetnoteAssetSchema.parse(item));
  }

  if (!payload || typeof payload !== "object") {
    return [];
  }

  const record = payload as Record<string, unknown>;
  const listKeys = ["assets", "data", "items", "results", "records", "hosts"];
  const assets = listKeys.flatMap((key) => {
    const value = record[key];

    return Array.isArray(value)
      ? value
          .filter(isAssetnoteRecord)
          .map((item) => AssetnoteAssetSchema.parse(item))
      : [];
  });

  if (assets.length > 0) {
    return assets;
  }

  if ("asset_id" in record || "hostname" in record || "domain" in record) {
    return [AssetnoteAssetSchema.parse(record)];
  }

  return [];
}

async function fetchAssetnoteAssets(config: AssetnoteConfig) {
  const url = new URL(assetnoteApiUrl(config, config.assetsPath));

  url.searchParams.set("limit", String(config.assetLimit));

  const response = await connectorFetch(url, {
    headers: {
      accept: "application/json",
      authorization: `${config.authHeaderPrefix} ${config.apiToken}`
    },
    method: "GET"
  });

  if (!response.ok) {
    throw new Error(`Assetnote asset API returned status ${response.status}.`);
  }

  return parseAssetnoteAssets(await response.json()).slice(
    0,
    config.assetLimit
  );
}

function assetnoteRecordValue(record: AssetnoteAsset, keys: string[]) {
  for (const key of keys) {
    const value = record[key];

    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }

    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }

    if (typeof value === "boolean") {
      return String(value);
    }
  }

  return null;
}

function assetnoteStringArray(value: unknown) {
  if (Array.isArray(value)) {
    return value.flatMap((item) =>
      typeof item === "string" && item.trim() ? [item.trim()] : []
    );
  }

  if (typeof value === "string" && value.trim()) {
    return value
      .split(/[,;\s]+/u)
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
}

function assetnoteNumberArray(value: unknown) {
  if (Array.isArray(value)) {
    return value
      .map((item) =>
        typeof item === "number" ? item : Number.parseInt(String(item), 10)
      )
      .filter((item) => Number.isFinite(item));
  }

  if (typeof value === "string") {
    return value
      .split(/[,;\s]+/u)
      .map((item) => Number.parseInt(item, 10))
      .filter((item) => Number.isFinite(item));
  }

  return [];
}

function assetnoteAssetId(asset: AssetnoteAsset, index: number) {
  return (
    assetnoteRecordValue(asset, ["asset_id", "assetId", "id", "uuid"]) ??
    `assetnote-asset-${index + 1}`
  );
}

function assetnoteAssetName(asset: AssetnoteAsset, index: number) {
  return (
    assetnoteRecordValue(asset, [
      "hostname",
      "host",
      "domain",
      "fqdn",
      "name",
      "ip",
      "address"
    ]) ?? assetnoteAssetId(asset, index)
  );
}

function assetnoteAssetAddresses(asset: AssetnoteAsset) {
  return [
    ...assetnoteStringArray(asset.ip),
    ...assetnoteStringArray(asset.ipv4),
    ...assetnoteStringArray(asset.address),
    ...assetnoteStringArray(asset.addresses)
  ].filter((item, index, values) => values.indexOf(item) === index);
}

function assetnoteAssetPorts(asset: AssetnoteAsset) {
  return [
    ...assetnoteNumberArray(asset.ports),
    ...assetnoteNumberArray(asset.open_ports),
    ...assetnoteNumberArray(asset.tcp_ports)
  ]
    .filter((item) => item > 0 && item <= 65_535)
    .filter((item, index, values) => values.indexOf(item) === index)
    .sort((left, right) => left - right);
}

function assetnoteAssetTechnologies(asset: AssetnoteAsset) {
  return [
    ...assetnoteStringArray(asset.technologies),
    ...assetnoteStringArray(asset.tech),
    ...assetnoteStringArray(asset.services)
  ].filter((item, index, values) => values.indexOf(item) === index);
}

function assetnoteAssetIsInternetExposed(asset: AssetnoteAsset) {
  const explicit = assetnoteRecordValue(asset, [
    "internet_exposed",
    "internetExposed",
    "public",
    "is_public"
  ]);

  if (explicit) {
    return /^(true|yes|1)$/iu.test(explicit);
  }

  const hasPublicAddress = assetnoteAssetAddresses(asset).some((ipAddress) =>
    /^(?!10\.|127\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.|192\.168\.)\d{1,3}\./u.test(
      ipAddress
    )
  );

  return (
    hasPublicAddress ||
    assetnoteRecordValue(asset, ["domain", "hostname", "fqdn"]) !== null
  );
}

function assetnoteSeverity(asset: AssetnoteAsset) {
  const normalized = (
    assetnoteRecordValue(asset, [
      "risk_level",
      "riskLevel",
      "severity",
      "priority"
    ]) ?? "low"
  )
    .trim()
    .toLowerCase();

  if (normalized === "critical") {
    return "critical";
  }

  if (["high", "severe"].includes(normalized)) {
    return "high";
  }

  if (["medium", "moderate"].includes(normalized)) {
    return "medium";
  }

  return "low";
}

function assetnoteTimestamp(asset: AssetnoteAsset, fallback: string) {
  const value = assetnoteRecordValue(asset, [
    "last_seen",
    "lastSeen",
    "updated_at",
    "updatedAt",
    "created_at",
    "createdAt"
  ]);

  if (!value) {
    return fallback;
  }

  const parsed = new Date(value);

  return Number.isNaN(parsed.getTime()) ? fallback : parsed.toISOString();
}

function assetnoteCveIds(asset: AssetnoteAsset) {
  const text = JSON.stringify(asset);
  const matches = text.match(/\bCVE-\d{4}-\d{4,}\b/giu) ?? [];

  return [...new Set(matches.map((value) => value.toUpperCase()))];
}

function loadAssetnoteFixtureAssets(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureAssets)) {
    return parseAssetnoteAssets(config.fixtureAssets);
  }

  return ASSETNOTE_FIXTURE_ASSETS;
}

function createAssetnoteAssets(assets: AssetnoteAsset[]) {
  return assets.map((asset, index) =>
    createMockAsset({
      assetType: assetnoteRecordValue(asset, ["domain", "fqdn"])
        ? "Domain"
        : "Host",
      businessCriticality:
        assetnoteSeverity(asset) === "critical" ||
        assetnoteSeverity(asset) === "high"
          ? "High"
          : assetnoteAssetIsInternetExposed(asset)
            ? "Moderate"
            : "Low",
      environment: "attack-surface",
      identifiers: {
        addresses: assetnoteAssetAddresses(asset),
        assetnoteAssetId: assetnoteAssetId(asset, index),
        domain: assetnoteRecordValue(asset, ["domain", "fqdn"]),
        hostname: assetnoteRecordValue(asset, ["hostname", "host"]),
        lastSeen: assetnoteTimestamp(asset, new Date().toISOString()),
        openPorts: assetnoteAssetPorts(asset),
        provider: "assetnote",
        severity: assetnoteSeverity(asset),
        technologies: assetnoteAssetTechnologies(asset),
        type: assetnoteRecordValue(asset, ["type", "asset_type", "assetType"])
      },
      internetExposed: assetnoteAssetIsInternetExposed(asset),
      name: `assetnote/${assetnoteAssetName(asset, index)}`,
      owner: "attack-surface",
      status:
        assetnoteRecordValue(asset, ["status"])?.toLowerCase() === "inactive"
          ? "Inactive"
          : "Active",
      tags: ["assetnote", "asm", "attack-surface"]
    })
  );
}

function createAssetnoteSignals(assets: AssetnoteAsset[]) {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  assets.forEach((asset, index) => {
    const assetId = assetnoteAssetId(asset, index);
    const observedAt = assetnoteTimestamp(asset, timestampObserved);
    const severity = assetnoteSeverity(asset);

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.84,
        freshness: "Fresh",
        rawPayloadPointer: `assetnote://assets/${encodeURIComponent(assetId)}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: assetnoteAssetIsInternetExposed(asset)
          ? "High"
          : "Moderate",
        signalCategory: "Asset",
        signalSubcategory: "AttackSurfaceAssetObserved",
        sourceType: "assetnote.asset.summary",
        timestampObserved: observedAt
      })
    );

    if (
      assetnoteAssetPorts(asset).length > 0 ||
      assetnoteAssetTechnologies(asset).length > 0
    ) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `assetnote://assets/${encodeURIComponent(
            assetId
          )}/services`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "ExternalServiceObservation",
          sourceType: "assetnote.asset.services",
          timestampObserved: observedAt
        })
      );
    }

    if (assetnoteAssetIsInternetExposed(asset)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.84,
          freshness: "Fresh",
          rawPayloadPointer: `assetnote://assets/${encodeURIComponent(
            assetId
          )}/internet-exposure`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Exposure",
          signalSubcategory: "ExternalExposure",
          sourceType: "assetnote.asset.internet_exposure",
          timestampObserved: observedAt
        })
      );
    }

    if (severity === "critical" || severity === "high") {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: severity === "critical" ? 0.88 : 0.84,
          freshness: "Fresh",
          rawPayloadPointer: `assetnote://assets/${encodeURIComponent(
            assetId
          )}/risk`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "High",
          signalCategory: "Exposure",
          signalSubcategory:
            severity === "critical"
              ? "CriticalAttackSurfaceRisk"
              : "HighAttackSurfaceRisk",
          sourceType: "assetnote.asset.risk",
          timestampObserved: observedAt
        })
      );
    }

    for (const cveId of assetnoteCveIds(asset)) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `assetnote://assets/${encodeURIComponent(
            assetId
          )}/cves/${cveId}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "CveObserved",
          sourceType: "assetnote.asset.cve",
          timestampObserved: observedAt
        })
      );
    }
  });

  return signals;
}

async function getAssetnoteHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ASSETNOTE_CONNECTOR_MANIFEST, context);
  }

  const startedAt = Date.now();
  const config = assetnoteConfigFromContext(context);

  try {
    const assets = await fetchAssetnoteAssets({
      ...config,
      assetLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Assetnote read-only asset access verified with ${assets.length} visible asset record(s).`,
      latencyMs: Date.now() - startedAt,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Assetnote health check failed: ${error.message}`
          : "Assetnote health check failed.",
      latencyMs: Date.now() - startedAt,
      status: "Unhealthy"
    });
  }
}

function createAssetnoteConnector(): Connector {
  return {
    manifest: ASSETNOTE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const assets = parsedContext.mockMode
        ? loadAssetnoteFixtureAssets(parsedContext.config)
        : await fetchAssetnoteAssets(assetnoteConfigFromContext(parsedContext));

      return createAssetnoteSignals(assets);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAssetnoteHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const assets = parsedContext.mockMode
        ? loadAssetnoteFixtureAssets(parsedContext.config)
        : await fetchAssetnoteAssets(assetnoteConfigFromContext(parsedContext));
      const health = parsedContext.mockMode
        ? await getAssetnoteHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Assetnote read-only sync returned ${assets.length} asset record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: createAssetnoteAssets(assets),
        health,
        signals: createAssetnoteSignals(assets).map((signal) =>
          createTimestampedSignal(
            ASSETNOTE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

