function abuseIpDbApiUrl(config: AbuseIpDbConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}${pathName}`;
}

function abuseIpDbHeaders(config: AbuseIpDbConfig) {
  return {
    accept: "application/json",
    key: config.apiKey
  };
}

function abuseIpDbIpList(config: AbuseIpDbConfig) {
  return config.ipAddresses
    .map((ipAddress) => ipAddress.trim())
    .filter(Boolean)
    .filter((ipAddress, index, values) => values.indexOf(ipAddress) === index)
    .slice(0, config.queryLimit);
}

async function readAbuseIpDbJson(response: Response) {
  if (!response.ok) {
    throw new Error(`AbuseIPDB API returned status ${response.status}.`);
  }

  return AbuseIpDbCheckResponseSchema.parse(await response.json()).data;
}

async function fetchAbuseIpDbChecks(config: AbuseIpDbConfig) {
  const ipAddresses = abuseIpDbIpList(config);
  const results: AbuseIpDbCheckData[] = [];

  for (const ipAddress of ipAddresses) {
    const url = new URL(abuseIpDbApiUrl(config, "/check"));

    url.searchParams.set("ipAddress", ipAddress);
    url.searchParams.set("maxAgeInDays", String(config.maxAgeInDays));

    results.push(
      await connectorFetch(url, {
        headers: abuseIpDbHeaders(config),
        method: "GET"
      }).then(readAbuseIpDbJson)
    );
  }

  return results;
}

function loadAbuseIpDbFixtureResults(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => AbuseIpDbCheckDataSchema.parse(item));
  }

  return ABUSEIPDB_FIXTURE_RESULTS;
}

function abuseIpDbSeverity(result: AbuseIpDbCheckData) {
  if (result.abuseConfidenceScore >= 75) {
    return "High";
  }

  if (result.abuseConfidenceScore >= 25) {
    return "Moderate";
  }

  return "Low";
}

function createAbuseIpDbSignals(
  results: AbuseIpDbCheckData[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const result of results) {
    const observedAt = result.lastReportedAt ?? timestampObserved;

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.78,
        freshness: "Fresh",
        rawPayloadPointer: `abuseipdb://check/${result.ipAddress}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: abuseIpDbSeverity(result),
        signalCategory: "Exposure",
        signalSubcategory: "ThreatIntelObservation",
        sourceType: "abuseipdb.check",
        timestampObserved: observedAt
      })
    );

    if (result.abuseConfidenceScore >= 25) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: Math.min(0.95, 0.5 + result.abuseConfidenceScore / 200),
          freshness: "Fresh",
          rawPayloadPointer: `abuseipdb://check/${result.ipAddress}/reputation`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: abuseIpDbSeverity(result),
          signalCategory: "Exposure",
          signalSubcategory:
            result.abuseConfidenceScore >= 75
              ? "HighConfidenceMaliciousIp"
              : "SuspiciousIpReputation",
          sourceType: "abuseipdb.ip_reputation",
          timestampObserved: observedAt
        })
      );
    }
  }

  return signals;
}

async function getAbuseIpDbHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(ABUSEIPDB_CONNECTOR_MANIFEST, context);
  }

  try {
    const config = AbuseIpDbConfigSchema.parse(context.config);
    const firstIp = abuseIpDbIpList(config)[0];

    if (!firstIp) {
      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail:
          "AbuseIPDB API key configuration parsed; no IP indicators configured for health query.",
        latencyMs: null,
        status: "Healthy"
      });
    }

    const results = await fetchAbuseIpDbChecks({
      ...config,
      ipAddresses: [firstIp],
      queryLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `AbuseIPDB read-only check endpoint verified with ${results.length} IP reputation record(s).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `AbuseIPDB health check failed: ${error.message}`
          : "AbuseIPDB health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

function createAbuseIpDbConnector(): Connector {
  return {
    manifest: ABUSEIPDB_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadAbuseIpDbFixtureResults(parsedContext.config)
        : await fetchAbuseIpDbChecks(
            AbuseIpDbConfigSchema.parse(parsedContext.config)
          );

      return createAbuseIpDbSignals(results);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getAbuseIpDbHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadAbuseIpDbFixtureResults(parsedContext.config)
        : await fetchAbuseIpDbChecks(
            AbuseIpDbConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getAbuseIpDbHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `AbuseIPDB read-only sync returned ${results.length} IP reputation record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createAbuseIpDbSignals(results).map((signal) =>
          createTimestampedSignal(
            ABUSEIPDB_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

