function virusTotalApiUrl(config: VirusTotalConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}${pathName}`;
}

function virusTotalHeaders(config: VirusTotalConfig) {
  return {
    accept: "application/json",
    "x-apikey": config.apiKey
  };
}

function virusTotalIndicators(config: VirusTotalConfig) {
  return config.indicators
    .map((indicator) => indicator.trim())
    .filter(Boolean)
    .filter((indicator, index, values) => values.indexOf(indicator) === index)
    .slice(0, config.queryLimit);
}

async function readVirusTotalJson(response: Response) {
  if (!response.ok) {
    throw new Error(`VirusTotal API returned status ${response.status}.`);
  }

  return VirusTotalSearchResponseSchema.parse(await response.json()).data;
}

async function fetchVirusTotalSearches(config: VirusTotalConfig) {
  const results: Array<{ indicator: string; objects: VirusTotalObject[] }> = [];

  for (const indicator of virusTotalIndicators(config)) {
    const url = new URL(virusTotalApiUrl(config, "/search"));

    url.searchParams.set("query", indicator);

    results.push({
      indicator,
      objects: await connectorFetch(url, {
        headers: virusTotalHeaders(config),
        method: "GET"
      }).then(readVirusTotalJson)
    });
  }

  return results;
}

function loadVirusTotalFixtureResults(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults.flatMap((item) => {
      if (!item || typeof item !== "object") {
        return [];
      }

      const record = item as Record<string, unknown>;
      const indicator =
        typeof record.indicator === "string" ? record.indicator : null;

      if (!indicator || !Array.isArray(record.objects)) {
        return [];
      }

      return [
        {
          indicator,
          objects: record.objects
            .filter(
              (object): object is Record<string, unknown> =>
                Boolean(object) && typeof object === "object"
            )
            .map((object) => VirusTotalObjectSchema.parse(object))
        }
      ];
    });
  }

  return VIRUSTOTAL_FIXTURE_RESULTS;
}

function virusTotalStats(object: VirusTotalObject) {
  return object.attributes?.last_analysis_stats ?? {};
}

function virusTotalMaliciousCount(object: VirusTotalObject) {
  return (
    (virusTotalStats(object).malicious ?? 0) +
    (virusTotalStats(object).suspicious ?? 0)
  );
}

function virusTotalSensitivity(object: VirusTotalObject) {
  const malicious = virusTotalMaliciousCount(object);

  if (malicious >= 10) {
    return "High";
  }

  if (malicious > 0) {
    return "Moderate";
  }

  return "Low";
}

function createVirusTotalSignals(
  results: Array<{ indicator: string; objects: VirusTotalObject[] }>
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const result of results) {
    for (const object of result.objects) {
      const malicious = virusTotalMaliciousCount(object);

      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `virustotal://search/${encodeURIComponent(result.indicator)}/${object.type}/${object.id}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: virusTotalSensitivity(object),
          signalCategory: "Exposure",
          signalSubcategory: "ThreatIntelObservation",
          sourceType: `virustotal.${object.type}`,
          timestampObserved
        })
      );

      if (malicious > 0) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: Math.min(0.95, 0.55 + malicious / 50),
            freshness: "Fresh",
            rawPayloadPointer: `virustotal://search/${encodeURIComponent(result.indicator)}/${object.type}/${object.id}/reputation`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel: virusTotalSensitivity(object),
            signalCategory: "Exposure",
            signalSubcategory:
              malicious >= 10
                ? "HighConfidenceMaliciousIndicator"
                : "SuspiciousIndicatorReputation",
            sourceType: "virustotal.reputation",
            timestampObserved
          })
        );
      }
    }
  }

  return signals;
}

async function getVirusTotalHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(VIRUSTOTAL_CONNECTOR_MANIFEST, context);
  }

  try {
    const config = VirusTotalConfigSchema.parse(context.config);
    const firstIndicator = virusTotalIndicators(config)[0];

    if (!firstIndicator) {
      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail:
          "VirusTotal API key configuration parsed; no indicators configured for health query.",
        latencyMs: null,
        status: "Healthy"
      });
    }

    const results = await fetchVirusTotalSearches({
      ...config,
      indicators: [firstIndicator],
      queryLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `VirusTotal read-only search verified with ${results[0]?.objects.length ?? 0} result object(s).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `VirusTotal health check failed: ${error.message}`
          : "VirusTotal health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

function createVirusTotalConnector(): Connector {
  return {
    manifest: VIRUSTOTAL_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadVirusTotalFixtureResults(parsedContext.config)
        : await fetchVirusTotalSearches(
            VirusTotalConfigSchema.parse(parsedContext.config)
          );

      return createVirusTotalSignals(results);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getVirusTotalHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadVirusTotalFixtureResults(parsedContext.config)
        : await fetchVirusTotalSearches(
            VirusTotalConfigSchema.parse(parsedContext.config)
          );
      const objectCount = results.reduce(
        (count, result) => count + result.objects.length,
        0
      );
      const health = parsedContext.mockMode
        ? await getVirusTotalHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `VirusTotal read-only sync returned ${objectCount} IoC reputation object(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createVirusTotalSignals(results).map((signal) =>
          createTimestampedSignal(
            VIRUSTOTAL_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

