const GREYNOISE_FIXTURE_RESULTS: GreyNoiseCommunityResponse[] = [
  {
    classification: "malicious",
    ip: "203.0.113.44",
    last_seen: "2026-06-01",
    link: "https://viz.greynoise.io/ip/203.0.113.44",
    message: "Success",
    name: "Example Scanner",
    noise: true,
    riot: false
  },
  {
    classification: "benign",
    ip: "198.51.100.22",
    last_seen: "2026-06-01",
    link: "https://viz.greynoise.io/riot/198.51.100.22",
    message: "Success",
    name: "Example CDN",
    noise: false,
    riot: true
  }
];

function greyNoiseApiUrl(config: GreyNoiseConfig, ipAddress: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}/${encodeURIComponent(ipAddress)}`;
}

function greyNoiseHeaders(config: GreyNoiseConfig) {
  return {
    accept: "application/json",
    key: config.apiKey
  };
}

function greyNoiseIpList(config: GreyNoiseConfig) {
  return config.ipAddresses
    .map((ipAddress) => ipAddress.trim())
    .filter(Boolean)
    .filter((ipAddress, index, values) => values.indexOf(ipAddress) === index)
    .slice(0, config.queryLimit);
}

async function readGreyNoiseJson(response: Response) {
  if (!response.ok) {
    throw new Error(`GreyNoise API returned status ${response.status}.`);
  }

  return GreyNoiseCommunityResponseSchema.parse(await response.json());
}

async function fetchGreyNoiseCommunity(config: GreyNoiseConfig) {
  const results: GreyNoiseCommunityResponse[] = [];

  for (const ipAddress of greyNoiseIpList(config)) {
    results.push(
      await connectorFetch(greyNoiseApiUrl(config, ipAddress), {
        headers: greyNoiseHeaders(config),
        method: "GET"
      }).then(readGreyNoiseJson)
    );
  }

  return results;
}

function loadGreyNoiseFixtureResults(config: Record<string, unknown>) {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => GreyNoiseCommunityResponseSchema.parse(item));
  }

  return GREYNOISE_FIXTURE_RESULTS;
}

function greyNoiseSensitivity(result: GreyNoiseCommunityResponse) {
  const classification = result.classification?.toLowerCase();

  if (classification === "malicious") {
    return "High";
  }

  if (result.noise) {
    return "Moderate";
  }

  return "Low";
}

function greyNoiseObservedAt(value: string | null | undefined) {
  if (!value) {
    return new Date().toISOString();
  }

  if (/^\d{4}-\d{2}-\d{2}$/u.test(value)) {
    return `${value}T00:00:00Z`;
  }

  return value;
}

function createGreyNoiseSignals(
  results: GreyNoiseCommunityResponse[]
): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const result of results) {
    const observedAt = greyNoiseObservedAt(
      result.last_seen ?? timestampObserved
    );

    signals.push(
      ConnectorSignalInputSchema.parse({
        confidence: 0.78,
        freshness: "Fresh",
        rawPayloadPointer: `greynoise://community/${result.ip}`,
        redactionStatus: "Redacted",
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: greyNoiseSensitivity(result),
        signalCategory: "Exposure",
        signalSubcategory: "ThreatIntelObservation",
        sourceType: "greynoise.community",
        timestampObserved: observedAt
      })
    );

    if (result.noise) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: result.classification === "malicious" ? 0.9 : 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `greynoise://community/${result.ip}/noise`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: greyNoiseSensitivity(result),
          signalCategory: "Exposure",
          signalSubcategory:
            result.classification === "malicious"
              ? "MaliciousInternetScanner"
              : "InternetScannerObserved",
          sourceType: "greynoise.noise",
          timestampObserved: observedAt
        })
      );
    }

    if (result.riot) {
      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.82,
          freshness: "Fresh",
          rawPayloadPointer: `greynoise://community/${result.ip}/riot`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Low",
          signalCategory: "Exposure",
          signalSubcategory: "BenignRiotService",
          sourceType: "greynoise.riot",
          timestampObserved: observedAt
        })
      );
    }
  }

  return signals;
}

async function getGreyNoiseHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(GREYNOISE_CONNECTOR_MANIFEST, context);
  }

  try {
    const config = GreyNoiseConfigSchema.parse(context.config);
    const firstIp = greyNoiseIpList(config)[0];

    if (!firstIp) {
      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail:
          "GreyNoise API key configuration parsed; no IP indicators configured for health query.",
        latencyMs: null,
        status: "Healthy"
      });
    }

    const results = await fetchGreyNoiseCommunity({
      ...config,
      ipAddresses: [firstIp],
      queryLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `GreyNoise Community API read-only lookup verified with ${results.length} IP context record(s).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `GreyNoise health check failed: ${error.message}`
          : "GreyNoise health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

function createGreyNoiseConnector(): Connector {
  return {
    manifest: GREYNOISE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadGreyNoiseFixtureResults(parsedContext.config)
        : await fetchGreyNoiseCommunity(
            GreyNoiseConfigSchema.parse(parsedContext.config)
          );

      return createGreyNoiseSignals(results);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getGreyNoiseHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const results = parsedContext.mockMode
        ? loadGreyNoiseFixtureResults(parsedContext.config)
        : await fetchGreyNoiseCommunity(
            GreyNoiseConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getGreyNoiseHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `GreyNoise read-only sync returned ${results.length} IP context record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createGreyNoiseSignals(results).map((signal) =>
          createTimestampedSignal(
            GREYNOISE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

// --- Snyk (real REST API; SCA/SAST/container issues -> Exposure signals) ---
const SnykConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.snyk.io"),
  apiKey: z.string().min(1),
  apiVersion: z.string().min(1).default("2024-10-15"),
  fixtureResults: z.array(z.unknown()).optional(),
  orgId: z.string().min(1),
  queryLimit: z.number().int().min(1).max(100).default(50)
});
type SnykConfig = z.infer<typeof SnykConfigSchema>;

const SnykIssueSchema = z
  .object({
    attributes: z
      .object({
        effective_severity_level: z
          .enum(["critical", "high", "medium", "low", "info"])
          .nullish(),
        key: z.string().nullish(),
        status: z.string().nullish(),
        title: z.string().nullish(),
        type: z.string().nullish()
      })
      .passthrough(),
    id: z.string()
  })
  .passthrough();
type SnykIssue = z.infer<typeof SnykIssueSchema>;

const SnykIssuesResponseSchema = z
  .object({ data: z.array(SnykIssueSchema).default([]) })
  .passthrough();

const SNYK_FIXTURE_RESULTS: SnykIssue[] = [
  SnykIssueSchema.parse({
    attributes: {
      effective_severity_level: "high",
      key: "SNYK-JS-LODASH-1018905",
      status: "open",
      title: "Prototype Pollution in lodash",
      type: "package_vulnerability"
    },
    id: "issue-fixture-1"
  }),
  SnykIssueSchema.parse({
    attributes: {
      effective_severity_level: "medium",
      key: "SNYK-JS-EXPRESS-2",
      status: "open",
      title: "Open Redirect in express",
      type: "package_vulnerability"
    },
    id: "issue-fixture-2"
  })
];

function snykHeaders(config: SnykConfig) {
  return {
    accept: "application/vnd.api+json",
    authorization: `token ${config.apiKey}`
  };
}

function snykIssuesUrl(config: SnykConfig) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    limit: String(config.queryLimit),
    version: config.apiVersion
  });
  return `${base}/rest/orgs/${encodeURIComponent(config.orgId)}/issues?${params.toString()}`;
}

async function readSnykJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Snyk API responded with HTTP ${response.status}.`);
  }
  return SnykIssuesResponseSchema.parse(await response.json());
}

async function fetchSnykIssues(config: SnykConfig): Promise<SnykIssue[]> {
  const response = await connectorFetch(snykIssuesUrl(config), {
    headers: snykHeaders(config),
    method: "GET"
  }).then(readSnykJson);
  return response.data;
}

function loadSnykFixtureResults(config: Record<string, unknown>): SnykIssue[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => SnykIssueSchema.parse(item));
  }
  return SNYK_FIXTURE_RESULTS;
}

function snykSensitivity(issue: SnykIssue) {
  const level = issue.attributes.effective_severity_level;
  if (level === "critical" || level === "high") {
    return "High";
  }
  if (level === "medium") {
    return "Moderate";
  }
  return "Low";
}

function createSnykSignals(issues: SnykIssue[]): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return issues.map((issue) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: `snyk://issue/${issue.id}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: snykSensitivity(issue),
      signalCategory: "Exposure",
      signalSubcategory:
        issue.attributes.type === "package_vulnerability"
          ? "DependencyVulnerability"
          : "ApplicationVulnerability",
      sourceType: "snyk.issue",
      timestampObserved: observedAt
    })
  );
}

async function getSnykHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SNYK_CONNECTOR_MANIFEST, context);
  }
  try {
    const issues = await fetchSnykIssues({
      ...SnykConfigSchema.parse(context.config),
      queryLimit: 1
    });
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Snyk REST read-only issues lookup verified (${issues.length} issue record(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Snyk health check failed: ${error.message}`
          : "Snyk health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

