// --- SonarQube (real REST API; SAST issues/hotspots -> Exposure signals) ---
const SonarQubeConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://sonarcloud.io"),
  apiToken: z.string().min(1),
  componentKeys: z.string().min(1),
  fixtureResults: z.array(z.unknown()).optional(),
  queryLimit: z.number().int().min(1).max(500).default(100)
});
type SonarQubeConfig = z.infer<typeof SonarQubeConfigSchema>;

const SonarQubeIssueSchema = z
  .object({
    component: z.string().nullish(),
    key: z.string(),
    rule: z.string().nullish(),
    severity: z
      .enum(["BLOCKER", "CRITICAL", "MAJOR", "MINOR", "INFO"])
      .nullish(),
    type: z.string().nullish()
  })
  .passthrough();
type SonarQubeIssue = z.infer<typeof SonarQubeIssueSchema>;

const SonarQubeIssuesResponseSchema = z
  .object({ issues: z.array(SonarQubeIssueSchema).default([]) })
  .passthrough();

const SONARQUBE_FIXTURE_RESULTS: SonarQubeIssue[] = [
  SonarQubeIssueSchema.parse({
    component: "acme:src/auth.ts",
    key: "AY1-issue-1",
    rule: "typescript:S2076",
    severity: "BLOCKER",
    type: "VULNERABILITY"
  }),
  SonarQubeIssueSchema.parse({
    component: "acme:src/util.ts",
    key: "AY1-issue-2",
    rule: "typescript:S1481",
    severity: "MINOR",
    type: "CODE_SMELL"
  })
];

function sonarQubeHeaders(config: SonarQubeConfig) {
  return {
    accept: "application/json",
    authorization: `Bearer ${config.apiToken}`
  };
}

function sonarQubeIssuesUrl(config: SonarQubeConfig) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    componentKeys: config.componentKeys,
    ps: String(config.queryLimit),
    resolved: "false"
  });
  return `${base}/api/issues/search?${params.toString()}`;
}

async function readSonarQubeJson(response: Response) {
  if (!response.ok) {
    throw new Error(`SonarQube API responded with HTTP ${response.status}.`);
  }
  return SonarQubeIssuesResponseSchema.parse(await response.json());
}

async function fetchSonarQubeIssues(
  config: SonarQubeConfig
): Promise<SonarQubeIssue[]> {
  const response = await connectorFetch(sonarQubeIssuesUrl(config), {
    headers: sonarQubeHeaders(config),
    method: "GET"
  }).then(readSonarQubeJson);
  return response.issues;
}

function loadSonarQubeFixtureResults(
  config: Record<string, unknown>
): SonarQubeIssue[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => SonarQubeIssueSchema.parse(item));
  }
  return SONARQUBE_FIXTURE_RESULTS;
}

function sonarQubeSensitivity(issue: SonarQubeIssue) {
  const severity = issue.severity;
  if (severity === "BLOCKER" || severity === "CRITICAL") {
    return "High";
  }
  if (severity === "MAJOR") {
    return "Moderate";
  }
  return "Low";
}

function createSonarQubeSignals(
  issues: SonarQubeIssue[]
): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return issues.map((issue) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.8,
      freshness: "Fresh",
      rawPayloadPointer: `sonarqube://issue/${issue.key}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: sonarQubeSensitivity(issue),
      signalCategory: "Exposure",
      signalSubcategory:
        issue.type === "VULNERABILITY" || issue.type === "SECURITY_HOTSPOT"
          ? "ApplicationVulnerability"
          : "CodeQualityIssue",
      sourceType: "sonarqube.issue",
      timestampObserved: observedAt
    })
  );
}

async function getSonarQubeHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SONARQUBE_CONNECTOR_MANIFEST, context);
  }
  try {
    const issues = await fetchSonarQubeIssues({
      ...SonarQubeConfigSchema.parse(context.config),
      queryLimit: 1
    });
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `SonarQube read-only issues lookup verified (${issues.length} issue record(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `SonarQube health check failed: ${error.message}`
          : "SonarQube health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

