// --- Shodan (real REST API; internet-exposed hosts -> Exposure signals) ---
const ShodanConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.shodan.io"),
  apiKey: z.string().min(1),
  fixtureResults: z.array(z.unknown()).optional(),
  // A tenant-scoped query (e.g. `net:203.0.113.0/24` or `org:"Acme"`) — Shodan
  // requires a search term; Periscan never broad-scans the whole internet.
  query: z.string().min(1),
  queryLimit: z.number().int().min(1).max(100).default(50)
});
type ShodanConfig = z.infer<typeof ShodanConfigSchema>;

const ShodanMatchSchema = z
  .object({
    ip_str: z.string().nullish(),
    org: z.string().nullish(),
    port: z.number().nullish(),
    product: z.string().nullish(),
    transport: z.string().nullish(),
    vulns: z.array(z.string()).nullish()
  })
  .passthrough();
type ShodanMatch = z.infer<typeof ShodanMatchSchema>;

const ShodanHostSearchResponseSchema = z
  .object({
    matches: z.array(ShodanMatchSchema).default([]),
    total: z.number().nonnegative().default(0)
  })
  .passthrough();

const SHODAN_FIXTURE_RESULTS: ShodanMatch[] = [
  ShodanMatchSchema.parse({
    ip_str: "203.0.113.10",
    org: "Acme Corp",
    port: 3389,
    product: "Microsoft Terminal Services",
    transport: "tcp",
    vulns: ["CVE-2019-0708"]
  }),
  ShodanMatchSchema.parse({
    ip_str: "203.0.113.11",
    org: "Acme Corp",
    port: 443,
    product: "nginx",
    transport: "tcp"
  })
];

function shodanHostSearchUrl(config: ShodanConfig) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    key: config.apiKey,
    limit: String(config.queryLimit),
    query: config.query
  });
  return `${base}/shodan/host/search?${params.toString()}`;
}

async function readShodanJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Shodan API responded with HTTP ${response.status}.`);
  }
  return ShodanHostSearchResponseSchema.parse(await response.json());
}

async function fetchShodanMatches(
  config: ShodanConfig
): Promise<ShodanMatch[]> {
  const response = await connectorFetch(shodanHostSearchUrl(config), {
    headers: { accept: "application/json" },
    method: "GET"
  }).then(readShodanJson);
  return response.matches;
}

function loadShodanFixtureResults(
  config: Record<string, unknown>
): ShodanMatch[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => ShodanMatchSchema.parse(item));
  }
  return SHODAN_FIXTURE_RESULTS;
}

function shodanSensitivity(match: ShodanMatch) {
  if ((match.vulns ?? []).length > 0) {
    return "High";
  }
  // Remote-access / management ports exposed to the internet are elevated.
  const port = match.port ?? 0;
  if ([3389, 22, 23, 445, 3306, 5432, 1433, 6379].includes(port)) {
    return "Moderate";
  }
  return "Low";
}

function createShodanSignals(matches: ShodanMatch[]): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return matches.map((match) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.8,
      freshness: "Fresh",
      rawPayloadPointer: `shodan://host/${match.ip_str ?? "unknown"}/${
        match.port ?? 0
      }`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: shodanSensitivity(match),
      signalCategory: "Exposure",
      signalSubcategory:
        (match.vulns ?? []).length > 0
          ? "ExposedVulnerableService"
          : "ExternalAttackSurface",
      sourceType: "shodan.host",
      timestampObserved: observedAt
    })
  );
}

async function getShodanHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SHODAN_CONNECTOR_MANIFEST, context);
  }
  try {
    const matches = await fetchShodanMatches({
      ...ShodanConfigSchema.parse(context.config),
      queryLimit: 1
    });
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Shodan read-only host search verified (${matches.length} match record(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Shodan health check failed: ${error.message}`
          : "Shodan health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

