function censysAuthHeader(config: CensysConfig) {
  return `Basic ${Buffer.from(`${config.apiId}:${config.apiSecret}`).toString(
    "base64"
  )}`;
}

function censysHostSearchUrl(config: CensysConfig, perPage: number) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    per_page: String(perPage),
    q: config.query
  });
  return `${base}/api/v2/hosts/search?${params.toString()}`;
}

async function readCensysJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Censys API responded with HTTP ${response.status}.`);
  }
  return CensysHostSearchResponseSchema.parse(await response.json());
}

async function fetchCensysHosts(
  config: CensysConfig,
  perPage = config.queryLimit
): Promise<CensysHost[]> {
  const response = await connectorFetch(censysHostSearchUrl(config, perPage), {
    headers: {
      accept: "application/json",
      authorization: censysAuthHeader(config)
    },
    method: "GET"
  }).then(readCensysJson);
  return response.result.hits;
}

function loadCensysFixtureResults(
  config: Record<string, unknown>
): CensysHost[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => CensysHostSchema.parse(item));
  }
  return CENSYS_FIXTURE_RESULTS;
}

const CENSYS_SENSITIVE_PORTS = [3389, 22, 23, 445, 3306, 5432, 1433, 6379];

function censysSensitivity(host: CensysHost) {
  const ports = host.services.map((service) => service.port ?? 0);
  if (ports.some((port) => CENSYS_SENSITIVE_PORTS.includes(port))) {
    return "Moderate";
  }
  return "Low";
}

function createCensysSignals(hosts: CensysHost[]): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return hosts.map((host) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.8,
      freshness: "Fresh",
      rawPayloadPointer: `censys://host/${host.ip ?? "unknown"}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: censysSensitivity(host),
      signalCategory: "Exposure",
      signalSubcategory: "ExternalAttackSurface",
      sourceType: "censys.host",
      timestampObserved: observedAt
    })
  );
}

async function getCensysHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CENSYS_CONNECTOR_MANIFEST, context);
  }
  try {
    const hosts = await fetchCensysHosts(
      CensysConfigSchema.parse(context.config),
      1
    );
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Censys read-only host search verified (${hosts.length} host record(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Censys health check failed: ${error.message}`
          : "Censys health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

