// --- Cisco Umbrella (real REST API v2; DNS-layer activity -> ControlObservation) ---
const CiscoUmbrellaConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.umbrella.com"),
  apiKeyId: z.string().min(1),
  apiKeySecret: z.string().min(1),
  fixtureResults: z.array(z.unknown()).optional(),
  queryLimit: z.number().int().min(1).max(100).default(50),
  timeperiod: z.string().min(1).default("-1days")
});
type CiscoUmbrellaConfig = z.infer<typeof CiscoUmbrellaConfigSchema>;

const CiscoUmbrellaTokenResponseSchema = z
  .object({ access_token: z.string().min(1) })
  .passthrough();

const CiscoUmbrellaActivitySchema = z
  .object({
    categories: z.array(z.unknown()).nullish(),
    domain: z.string().nullish(),
    verdict: z.string().nullish()
  })
  .passthrough();
type CiscoUmbrellaActivity = z.infer<typeof CiscoUmbrellaActivitySchema>;

const CiscoUmbrellaActivityResponseSchema = z
  .object({ data: z.array(CiscoUmbrellaActivitySchema).default([]) })
  .passthrough();

const CISCO_UMBRELLA_FIXTURE_RESULTS: CiscoUmbrellaActivity[] = [
  CiscoUmbrellaActivitySchema.parse({
    categories: ["Malware"],
    domain: "malware.example.test",
    verdict: "blocked"
  }),
  CiscoUmbrellaActivitySchema.parse({
    categories: ["Newly Seen Domains"],
    domain: "suspicious.example.test",
    verdict: "allowed"
  })
];

function ciscoUmbrellaTokenUrl(config: CiscoUmbrellaConfig) {
  return `${config.apiBaseUrl.replace(/\/$/u, "")}/auth/v2/token`;
}

function ciscoUmbrellaActivityUrl(config: CiscoUmbrellaConfig, limit: number) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    from: config.timeperiod,
    limit: String(limit),
    to: "now"
  });
  return `${base}/reports/v2/activity?${params.toString()}`;
}

async function fetchCiscoUmbrellaToken(
  config: CiscoUmbrellaConfig
): Promise<string> {
  const basic = Buffer.from(
    `${config.apiKeyId}:${config.apiKeySecret}`
  ).toString("base64");
  const response = await connectorFetch(ciscoUmbrellaTokenUrl(config), {
    body: new URLSearchParams({ grant_type: "client_credentials" }),
    headers: {
      accept: "application/json",
      authorization: `Basic ${basic}`,
      "content-type": "application/x-www-form-urlencoded"
    },
    method: "POST"
  });
  if (!response.ok) {
    throw new Error(
      `Cisco Umbrella token request failed (HTTP ${response.status}).`
    );
  }
  return CiscoUmbrellaTokenResponseSchema.parse(await response.json())
    .access_token;
}

async function fetchCiscoUmbrellaActivity(
  config: CiscoUmbrellaConfig,
  limit = config.queryLimit
): Promise<CiscoUmbrellaActivity[]> {
  const token = await fetchCiscoUmbrellaToken(config);
  const response = await connectorFetch(
    ciscoUmbrellaActivityUrl(config, limit),
    {
      headers: {
        accept: "application/json",
        authorization: `Bearer ${token}`
      },
      method: "GET"
    }
  );
  if (!response.ok) {
    throw new Error(
      `Cisco Umbrella activity request failed (HTTP ${response.status}).`
    );
  }
  return CiscoUmbrellaActivityResponseSchema.parse(await response.json()).data;
}

function loadCiscoUmbrellaFixtureResults(
  config: Record<string, unknown>
): CiscoUmbrellaActivity[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => CiscoUmbrellaActivitySchema.parse(item));
  }
  return CISCO_UMBRELLA_FIXTURE_RESULTS;
}

function ciscoUmbrellaOutcome(activity: CiscoUmbrellaActivity[]) {
  if (activity.length === 0) {
    return "NoEvidence";
  }
  if (activity.some((entry) => entry.verdict === "blocked")) {
    return "Blocked";
  }
  return "Detected";
}

function createCiscoUmbrellaSignals(
  activity: CiscoUmbrellaActivity[]
): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return activity.map((entry, index) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.82,
      freshness: "Fresh",
      rawPayloadPointer: `cisco-umbrella://activity/${entry.domain ?? index}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: entry.verdict === "blocked" ? "High" : "Moderate",
      signalCategory: "ControlObservation",
      signalSubcategory:
        entry.verdict === "blocked"
          ? "DnsLayerBlocked"
          : "DnsLayerActivityObserved",
      sourceType: "cisco-umbrella.activity.observer",
      timestampObserved: observedAt
    })
  );
}

async function getCiscoUmbrellaHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(CISCO_UMBRELLA_CONNECTOR_MANIFEST, context);
  }
  try {
    const activity = await fetchCiscoUmbrellaActivity(
      CiscoUmbrellaConfigSchema.parse(context.config),
      1
    );
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Cisco Umbrella read-only activity lookup verified (${activity.length} record(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Cisco Umbrella health check failed: ${error.message}`
          : "Cisco Umbrella health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

