function createCiscoUmbrellaConnector(): Connector {
  return {
    manifest: CISCO_UMBRELLA_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const activity = parsedContext.mockMode
        ? loadCiscoUmbrellaFixtureResults(parsedContext.config)
        : await fetchCiscoUmbrellaActivity(
            CiscoUmbrellaConfigSchema.parse(parsedContext.config)
          );
      return createCiscoUmbrellaSignals(activity);
    },
    async observeControl(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const startedAt = Date.now();
      try {
        const activity = parsedContext.mockMode
          ? loadCiscoUmbrellaFixtureResults(parsedContext.config)
          : await fetchCiscoUmbrellaActivity(
              CiscoUmbrellaConfigSchema.parse(parsedContext.config)
            );
        const outcome = ciscoUmbrellaOutcome(activity);
        return {
          confidence: activity.length > 0 ? 0.82 : 0.6,
          detail:
            activity.length > 0
              ? `Cisco Umbrella returned ${activity.length} DNS activity record(s) (outcome ${outcome}).`
              : "Cisco Umbrella returned no DNS activity for the validation window.",
          latencyMs: Date.now() - startedAt,
          outcome,
          sourceType: "cisco-umbrella.activity.observer"
        };
      } catch (error) {
        return {
          confidence: 0.35,
          detail: `Cisco Umbrella observation failed: ${
            error instanceof Error ? error.message : "unknown error"
          }`,
          latencyMs: Date.now() - startedAt,
          outcome: "NoEvidence",
          sourceType: "cisco-umbrella.activity.observer"
        };
      }
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      return getCiscoUmbrellaHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const activity = parsedContext.mockMode
        ? loadCiscoUmbrellaFixtureResults(parsedContext.config)
        : await fetchCiscoUmbrellaActivity(
            CiscoUmbrellaConfigSchema.parse(parsedContext.config)
          );
      const health = parsedContext.mockMode
        ? await getCiscoUmbrellaHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Cisco Umbrella read-only sync returned ${activity.length} activity record(s).`,
            latencyMs: null,
            status: "Healthy"
          });
      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createCiscoUmbrellaSignals(activity).map((signal) =>
          createTimestampedSignal(
            CISCO_UMBRELLA_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

