const DomainToolsConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.domaintools.com"),
  apiKey: z.string().min(1),
  apiUser: z.string().min(1),
  domains: z.array(z.string().min(1)).min(1),
  fixtureResults: z.array(z.unknown()).optional()
});
type DomainToolsConfig = z.infer<typeof DomainToolsConfigSchema>;

const DomainToolsResultSchema = z
  .object({
    domain: z.string().nullish(),
    domain_risk: z
      .object({ risk_score: z.number().nullish() })
      .passthrough()
      .nullish()
  })
  .passthrough();
type DomainToolsResult = z.infer<typeof DomainToolsResultSchema>;

const DomainToolsResponseSchema = z
  .object({
    response: z
      .object({ results: z.array(DomainToolsResultSchema).default([]) })
      .passthrough()
      .default({ results: [] })
  })
  .passthrough();

const DOMAINTOOLS_FIXTURE_RESULTS: DomainToolsResult[] = [
  DomainToolsResultSchema.parse({
    domain: "phishy.example.test",
    domain_risk: { risk_score: 92 }
  }),
  DomainToolsResultSchema.parse({
    domain: "acme-partner.example.test",
    domain_risk: { risk_score: 18 }
  })
];

function domainToolsUrl(config: DomainToolsConfig) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({
    api_key: config.apiKey,
    api_username: config.apiUser,
    domain: config.domains.join(",")
  });
  return `${base}/v1/iris-investigate/?${params.toString()}`;
}

async function readDomainToolsJson(response: Response) {
  if (!response.ok) {
    throw new Error(`DomainTools API responded with HTTP ${response.status}.`);
  }
  return DomainToolsResponseSchema.parse(await response.json());
}

async function fetchDomainToolsResults(
  config: DomainToolsConfig
): Promise<DomainToolsResult[]> {
  const parsed = await connectorFetch(domainToolsUrl(config), {
    headers: { accept: "application/json" },
    method: "GET"
  }).then(readDomainToolsJson);
  return parsed.response.results;
}

function loadDomainToolsFixtureResults(
  config: Record<string, unknown>
): DomainToolsResult[] {
  if (Array.isArray(config.fixtureResults)) {
    return config.fixtureResults
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => DomainToolsResultSchema.parse(item));
  }
  return DOMAINTOOLS_FIXTURE_RESULTS;
}

function domainToolsSensitivity(result: DomainToolsResult) {
  const score = result.domain_risk?.risk_score ?? 0;
  if (score >= 70) {
    return "High";
  }
  if (score >= 40) {
    return "Moderate";
  }
  return "Low";
}

function createDomainToolsSignals(
  results: DomainToolsResult[]
): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return results.map((result, index) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.75,
      freshness: "Fresh",
      rawPayloadPointer: `domaintools://iris/${result.domain ?? index}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: domainToolsSensitivity(result),
      signalCategory: "Exposure",
      signalSubcategory: "DomainIntel",
      sourceType: "domaintools.iris",
      timestampObserved: observedAt
    })
  );
}

