// --- Sysdig Secure (real REST API; runtime/posture events -> Cloud signals) ---
// Beta: endpoint + auth match the Sysdig Secure Events API public docs
// (GET /api/v1/secureEvents, Bearer API token). Verify against the tenant's
// regional base URL in the live-smoke runbook before promotion.
const SysdigConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://secure.sysdig.com"),
  apiToken: z.string().min(1),
  fixtureEvents: z.array(z.unknown()).optional(),
  limit: z.number().int().positive().max(1000).default(100)
});
type SysdigConfig = z.infer<typeof SysdigConfigSchema>;

const SysdigEventSchema = z
  .object({
    category: z.string().nullish(),
    id: z.string().nullish(),
    name: z.string().nullish(),
    ruleName: z.string().nullish(),
    severity: z.number().nullish()
  })
  .passthrough();
type SysdigEvent = z.infer<typeof SysdigEventSchema>;

const SysdigResponseSchema = z
  .object({
    data: z.array(SysdigEventSchema).default([])
  })
  .passthrough();

const SYSDIG_FIXTURE_EVENTS: SysdigEvent[] = [
  SysdigEventSchema.parse({
    category: "runtime",
    id: "sysdig-evt-1",
    name: "Terminal shell in container",
    ruleName: "Terminal shell in container",
    severity: 2
  }),
  SysdigEventSchema.parse({
    category: "posture",
    id: "sysdig-evt-2",
    name: "Container running as privileged",
    ruleName: "Privileged container",
    severity: 5
  })
];

function sysdigUrl(config: SysdigConfig) {
  const base = config.apiBaseUrl.replace(/\/$/u, "");
  const params = new URLSearchParams({ limit: String(config.limit) });
  return `${base}/api/v1/secureEvents?${params.toString()}`;
}

async function readSysdigJson(response: Response) {
  if (!response.ok) {
    throw new Error(
      `Sysdig Secure API responded with HTTP ${response.status}.`
    );
  }
  return SysdigResponseSchema.parse(await response.json());
}

async function fetchSysdigEvents(config: SysdigConfig): Promise<SysdigEvent[]> {
  const parsed = await connectorFetch(sysdigUrl(config), {
    headers: {
      accept: "application/json",
      authorization: `Bearer ${config.apiToken}`
    },
    method: "GET"
  }).then(readSysdigJson);
  return parsed.data;
}

function loadSysdigFixtureEvents(
  config: Record<string, unknown>
): SysdigEvent[] {
  if (Array.isArray(config.fixtureEvents)) {
    return config.fixtureEvents
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object"
      )
      .map((item) => SysdigEventSchema.parse(item));
  }
  return SYSDIG_FIXTURE_EVENTS;
}

// Sysdig severity is syslog-style 0 (most severe) .. 7 (least severe).
function sysdigSensitivity(event: SysdigEvent) {
  const severity = event.severity ?? 4;
  if (severity <= 3) {
    return "High";
  }
  if (severity <= 5) {
    return "Moderate";
  }
  return "Low";
}

function createSysdigSignals(events: SysdigEvent[]): ConnectorSignalInput[] {
  const observedAt = new Date().toISOString();
  return events.map((event, index) =>
    ConnectorSignalInputSchema.parse({
      confidence: 0.75,
      freshness: "Fresh",
      rawPayloadPointer: `sysdig://secureEvents/${event.id ?? index}`,
      redactionStatus: "Redacted",
      relatedAssetIds: [],
      relatedControlIds: [],
      relatedEvidenceIds: [],
      relatedIdentityIds: [],
      relatedPathIds: [],
      sensitivityLevel: sysdigSensitivity(event),
      signalCategory: "Cloud",
      signalSubcategory: "CloudWorkloadRisk",
      sourceType: "sysdig.event",
      timestampObserved: observedAt
    })
  );
}

async function getSysdigHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(SYSDIG_CONNECTOR_MANIFEST, context);
  }
  try {
    const config = SysdigConfigSchema.parse(context.config);
    const events = await fetchSysdigEvents({ ...config, limit: 1 });
    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Sysdig Secure events read-only lookup verified (${events.length} event(s)).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Sysdig health check failed: ${error.message}`
          : "Sysdig health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

