function recordedFutureApiUrl(config: RecordedFutureConfig, pathName: string) {
  return `${config.apiBaseUrl.replace(/\/+$/u, "")}${pathName}`;
}

function recordedFutureHeaders(config: RecordedFutureConfig) {
  return {
    accept: "application/json",
    "X-RFToken": config.apiToken
  };
}

function recordedFutureJsonHeaders(config: RecordedFutureConfig) {
  return {
    ...recordedFutureHeaders(config),
    "content-type": "application/json"
  };
}

function recordedFutureCveIds(config: RecordedFutureConfig) {
  return config.cveIds
    .map((cveId) => cveId.trim().toUpperCase())
    .filter((cveId) => /^CVE-\d{4}-\d{4,}$/u.test(cveId))
    .filter((cveId, index, values) => values.indexOf(cveId) === index)
    .slice(0, config.queryLimit);
}

function recordedFutureEntityNames(config: RecordedFutureConfig) {
  return config.entityNames
    .map((entityName) => entityName.trim())
    .filter(Boolean)
    .filter((entityName, index, values) => values.indexOf(entityName) === index)
    .slice(0, config.queryLimit);
}

async function readRecordedFutureVulnerabilityJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Recorded Future API returned status ${response.status}.`);
  }

  return RecordedFutureVulnerabilitySearchResponseSchema.parse(
    await response.json()
  ).data;
}

async function readRecordedFutureEntityMatchJson(response: Response) {
  if (!response.ok) {
    throw new Error(`Recorded Future API returned status ${response.status}.`);
  }

  return RecordedFutureEntityMatchResponseSchema.parse(await response.json())
    .data;
}

async function fetchRecordedFutureVulnerabilitySearches(
  config: RecordedFutureConfig
) {
  const results: Array<{
    cveId: string;
    records: RecordedFutureVulnerabilityRecord[];
  }> = [];

  for (const cveId of recordedFutureCveIds(config)) {
    const url = new URL(
      recordedFutureApiUrl(config, "/v2/vulnerability/search")
    );

    url.searchParams.set("freetext", cveId);
    url.searchParams.set("fields", "risk");
    url.searchParams.set("metadata", "false");
    url.searchParams.set("limit", "1");

    results.push({
      cveId,
      records: await connectorFetch(url, {
        headers: recordedFutureHeaders(config),
        method: "GET"
      }).then(readRecordedFutureVulnerabilityJson)
    });
  }

  return results;
}

async function fetchRecordedFutureEntityMatches(config: RecordedFutureConfig) {
  const results: Array<{
    entityName: string;
    records: RecordedFutureEntityMatchRecord[];
  }> = [];

  for (const entityName of recordedFutureEntityNames(config)) {
    const url = recordedFutureApiUrl(config, "/entity-match/match");

    results.push({
      entityName,
      records: await connectorFetch(url, {
        body: JSON.stringify({
          limit: 5,
          name: entityName
        }),
        headers: recordedFutureJsonHeaders(config),
        method: "POST"
      }).then(readRecordedFutureEntityMatchJson)
    });
  }

  return results;
}

function loadRecordedFutureFixtureVulnerabilityResults(
  config: Record<string, unknown>
) {
  if (Array.isArray(config.fixtureVulnerabilityResults)) {
    return config.fixtureVulnerabilityResults.flatMap((item) => {
      if (!item || typeof item !== "object") {
        return [];
      }

      const record = item as Record<string, unknown>;
      const cveId = typeof record.cveId === "string" ? record.cveId : null;

      if (!cveId || !Array.isArray(record.records)) {
        return [];
      }

      return [
        {
          cveId,
          records: record.records
            .filter(
              (candidate): candidate is Record<string, unknown> =>
                Boolean(candidate) && typeof candidate === "object"
            )
            .map((candidate) =>
              RecordedFutureVulnerabilityRecordSchema.parse(candidate)
            )
        }
      ];
    });
  }

  return RECORDED_FUTURE_FIXTURE_VULNERABILITY_RESULTS;
}

function loadRecordedFutureFixtureEntityMatchResults(
  config: Record<string, unknown>
) {
  if (Array.isArray(config.fixtureEntityMatchResults)) {
    return config.fixtureEntityMatchResults.flatMap((item) => {
      if (!item || typeof item !== "object") {
        return [];
      }

      const record = item as Record<string, unknown>;
      const entityName =
        typeof record.entityName === "string" ? record.entityName : null;

      if (!entityName || !Array.isArray(record.records)) {
        return [];
      }

      return [
        {
          entityName,
          records: record.records
            .filter(
              (candidate): candidate is Record<string, unknown> =>
                Boolean(candidate) && typeof candidate === "object"
            )
            .map((candidate) =>
              RecordedFutureEntityMatchRecordSchema.parse(candidate)
            )
        }
      ];
    });
  }

  return RECORDED_FUTURE_FIXTURE_ENTITY_MATCH_RESULTS;
}

function recordedFutureRiskScore(record: RecordedFutureVulnerabilityRecord) {
  const candidates = [record.risk?.score, record.riskScore, record.risk_score];

  for (const candidate of candidates) {
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      return candidate;
    }

    if (typeof candidate === "string") {
      const parsed = Number.parseFloat(candidate);

      if (Number.isFinite(parsed)) {
        return parsed;
      }
    }
  }

  return 0;
}

function recordedFutureVulnerabilityLabel(
  record: RecordedFutureVulnerabilityRecord,
  fallback: string
) {
  return record.entity?.name ?? record.name ?? record.id ?? fallback;
}

function recordedFutureEntityLabel(
  record: RecordedFutureEntityMatchRecord,
  fallback: string
) {
  return record.entity?.name ?? record.name ?? record.id ?? fallback;
}

function recordedFutureEntityType(record: RecordedFutureEntityMatchRecord) {
  return record.entity?.type ?? record.type ?? "Entity";
}

function recordedFutureSensitivity(score: number) {
  if (score >= 75) {
    return "High";
  }

  if (score >= 40) {
    return "Moderate";
  }

  return "Low";
}

function createRecordedFutureSignals(input: {
  entityMatches: Array<{
    entityName: string;
    records: RecordedFutureEntityMatchRecord[];
  }>;
  vulnerabilitySearches: Array<{
    cveId: string;
    records: RecordedFutureVulnerabilityRecord[];
  }>;
}): ConnectorSignalInput[] {
  const timestampObserved = new Date().toISOString();
  const signals: ConnectorSignalInput[] = [];

  for (const result of input.vulnerabilitySearches) {
    for (const record of result.records) {
      const score = recordedFutureRiskScore(record);
      const sensitivityLevel = recordedFutureSensitivity(score);
      const label = recordedFutureVulnerabilityLabel(record, result.cveId);

      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.8,
          freshness: "Fresh",
          rawPayloadPointer: `recorded-future://vulnerability/search/${encodeURIComponent(result.cveId)}/${encodeURIComponent(label)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel,
          signalCategory: "Exposure",
          signalSubcategory: "ThreatIntelObservation",
          sourceType: "recorded_future.vulnerability_search",
          timestampObserved
        })
      );

      if (score >= 40) {
        signals.push(
          ConnectorSignalInputSchema.parse({
            confidence: Math.min(0.95, 0.55 + score / 200),
            freshness: "Fresh",
            rawPayloadPointer: `recorded-future://vulnerability/search/${encodeURIComponent(result.cveId)}/${encodeURIComponent(label)}/risk`,
            redactionStatus: "Redacted",
            relatedAssetIds: [],
            relatedControlIds: [],
            relatedEvidenceIds: [],
            relatedIdentityIds: [],
            relatedPathIds: [],
            sensitivityLevel,
            signalCategory: "Exposure",
            signalSubcategory:
              score >= 75 ? "HighRiskVulnerability" : "ElevatedCveRisk",
            sourceType: "recorded_future.vulnerability_risk",
            timestampObserved
          })
        );
      }
    }
  }

  for (const result of input.entityMatches) {
    for (const record of result.records) {
      const label = recordedFutureEntityLabel(record, result.entityName);
      const entityType = recordedFutureEntityType(record);

      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.74,
          freshness: "Fresh",
          rawPayloadPointer: `recorded-future://entity-match/${encodeURIComponent(result.entityName)}/${encodeURIComponent(label)}`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "ThreatIntelObservation",
          sourceType: "recorded_future.entity_match",
          timestampObserved
        })
      );

      signals.push(
        ConnectorSignalInputSchema.parse({
          confidence: 0.78,
          freshness: "Fresh",
          rawPayloadPointer: `recorded-future://entity-match/${encodeURIComponent(result.entityName)}/${encodeURIComponent(label)}/context`,
          redactionStatus: "Redacted",
          relatedAssetIds: [],
          relatedControlIds: [],
          relatedEvidenceIds: [],
          relatedIdentityIds: [],
          relatedPathIds: [],
          sensitivityLevel: "Moderate",
          signalCategory: "Exposure",
          signalSubcategory: "RecordedFutureEntityMatch",
          sourceType: `recorded_future.${entityType.toLowerCase().replace(/\s+/gu, "_")}`,
          timestampObserved
        })
      );
    }
  }

  return signals;
}

async function getRecordedFutureHealth(context: ConnectorExecutionContext) {
  if (context.mockMode) {
    return createMockHealth(RECORDED_FUTURE_CONNECTOR_MANIFEST, context);
  }

  try {
    const config = RecordedFutureConfigSchema.parse(context.config);
    const firstCve = recordedFutureCveIds(config)[0];
    const firstEntityName = recordedFutureEntityNames(config)[0];

    if (!firstCve && !firstEntityName) {
      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail:
          "Recorded Future API token configuration parsed; no CVEs or entity names configured for health query.",
        latencyMs: null,
        status: "Healthy"
      });
    }

    if (firstCve) {
      const results = await fetchRecordedFutureVulnerabilitySearches({
        ...config,
        cveIds: [firstCve],
        entityNames: [],
        queryLimit: 1
      });

      return ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail: `Recorded Future vulnerability search verified with ${results[0]?.records.length ?? 0} vulnerability record(s).`,
        latencyMs: null,
        status: "Healthy"
      });
    }

    const results = await fetchRecordedFutureEntityMatches({
      ...config,
      cveIds: [],
      entityNames: firstEntityName ? [firstEntityName] : [],
      queryLimit: 1
    });

    return ConnectorHealthSchema.parse({
      authorizationVerified: true,
      checkedAt: new Date().toISOString(),
      detail: `Recorded Future entity match verified with ${results[0]?.records.length ?? 0} entity record(s).`,
      latencyMs: null,
      status: "Healthy"
    });
  } catch (error) {
    return ConnectorHealthSchema.parse({
      authorizationVerified: false,
      checkedAt: new Date().toISOString(),
      detail:
        error instanceof Error
          ? `Recorded Future health check failed: ${error.message}`
          : "Recorded Future health check failed.",
      latencyMs: null,
      status: "Unhealthy"
    });
  }
}

function createRecordedFutureConnector(): Connector {
  return {
    manifest: RECORDED_FUTURE_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = parsedContext.mockMode
        ? null
        : RecordedFutureConfigSchema.parse(parsedContext.config);
      const vulnerabilitySearches = parsedContext.mockMode
        ? loadRecordedFutureFixtureVulnerabilityResults(parsedContext.config)
        : await fetchRecordedFutureVulnerabilitySearches(config!);
      const entityMatches = parsedContext.mockMode
        ? loadRecordedFutureFixtureEntityMatchResults(parsedContext.config)
        : await fetchRecordedFutureEntityMatches(config!);

      return createRecordedFutureSignals({
        entityMatches,
        vulnerabilitySearches
      });
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);

      return getRecordedFutureHealth(parsedContext);
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const config = parsedContext.mockMode
        ? null
        : RecordedFutureConfigSchema.parse(parsedContext.config);
      const vulnerabilitySearches = parsedContext.mockMode
        ? loadRecordedFutureFixtureVulnerabilityResults(parsedContext.config)
        : await fetchRecordedFutureVulnerabilitySearches(config!);
      const entityMatches = parsedContext.mockMode
        ? loadRecordedFutureFixtureEntityMatchResults(parsedContext.config)
        : await fetchRecordedFutureEntityMatches(config!);
      const health = parsedContext.mockMode
        ? await getRecordedFutureHealth(parsedContext)
        : ConnectorHealthSchema.parse({
            authorizationVerified: true,
            checkedAt: new Date().toISOString(),
            detail: `Recorded Future read-only sync returned ${vulnerabilitySearches.reduce((count, item) => count + item.records.length, 0)} vulnerability record(s) and ${entityMatches.reduce((count, item) => count + item.records.length, 0)} entity match record(s).`,
            latencyMs: null,
            status: "Healthy"
          });

      return ConnectorSyncResultSchema.parse({
        assets: [],
        health,
        signals: createRecordedFutureSignals({
          entityMatches,
          vulnerabilitySearches
        }).map((signal) =>
          createTimestampedSignal(
            RECORDED_FUTURE_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

const MandiantAdvantageConfigSchema = z.object({
  apiBaseUrl: z.url().default("https://api.intelligence.mandiant.com"),
  actorNames: z.array(z.string().min(1)).default([]),
  cveIds: z.array(z.string().min(1)).default([]),
  indicators: z.array(z.string().min(1)).default([]),
  minimumMscore: z.number().int().min(0).max(100).default(0),
  privateKey: z.string().min(1),
  publicKey: z.string().min(1),
  queryLimit: z.number().int().min(1).max(100).default(25)
});

const MandiantIndicatorRecordSchema = z
  .object({
    attributed_associations: z
      .array(
        z
          .object({
            id: z.string().optional(),
            name: z.string().optional(),
            type: z.string().optional()
          })
          .passthrough()
      )
      .optional(),
    first_seen: z.string().optional(),
    id: z.string().optional(),
    last_seen: z.string().optional(),
    mscore: z.union([z.number(), z.string()]).optional(),
    type: z.string().optional(),
    value: z.string().optional(),
    verdict_simple: z.string().optional()
  })
  .passthrough();

const MandiantVulnerabilityRecordSchema = z
  .object({
    cve: z
      .array(
        z
          .object({
            id: z.string().optional(),
            name: z.string().optional()
          })
          .passthrough()
      )
      .optional(),
    exploitation_state: z.string().optional(),
    id: z.string().optional(),
    name: z.string().optional(),
    risk_rating: z.string().optional(),
    risk_score: z.union([z.number(), z.string()]).optional(),
    threat_rating: z
      .object({
        threat_score: z.union([z.number(), z.string()]).optional()
      })
      .passthrough()
      .optional()
  })
  .passthrough();

const MandiantActorRecordSchema = z
  .object({
    aliases: z.array(z.string()).optional(),
    id: z.string().optional(),
    name: z.string().optional(),
    primary_motivation: z.string().optional(),
    type: z.string().optional()
  })
  .passthrough();

const MandiantIndicatorResponseSchema = z
  .object({
    data: z.array(MandiantIndicatorRecordSchema).optional(),
    indicators: z.array(MandiantIndicatorRecordSchema).optional()
  })
  .passthrough();

const MandiantVulnerabilityResponseSchema = z
  .object({
    data: z.array(MandiantVulnerabilityRecordSchema).optional(),
    vulnerability: z.array(MandiantVulnerabilityRecordSchema).optional(),
    vulnerabilities: z.array(MandiantVulnerabilityRecordSchema).optional()
  })
  .passthrough();

const MandiantActorResponseSchema = z
  .object({
    data: z.array(MandiantActorRecordSchema).optional(),
    "threat-actors": z.array(MandiantActorRecordSchema).optional(),
    threat_actors: z.array(MandiantActorRecordSchema).optional()
  })
  .passthrough();

type MandiantAdvantageConfig = z.infer<typeof MandiantAdvantageConfigSchema>;
type MandiantIndicatorRecord = z.infer<typeof MandiantIndicatorRecordSchema>;
type MandiantVulnerabilityRecord = z.infer<
  typeof MandiantVulnerabilityRecordSchema
>;
type MandiantActorRecord = z.infer<typeof MandiantActorRecordSchema>;

