  marketplaceCategory: "Cloud",
  mockSupported: true,
  permissionsSummary:
    "Uses an account with the vCenter Read-only role at the authorized inventory root. Periscan lists inventory only and never powers, creates, reconfigures, migrates, snapshots, or deletes infrastructure. Product depth remains Partial until customer-credential live-smoke qualifies broader claims.",
  product: "vCenter Server",
  requiredPermissions: [
    "System.View on authorized inventory",
    "Read-only role inherited by target datacenters, clusters, hosts, networks, and VMs"
  ],
  setupComplexity: "Medium",
