function vCenterApiUrl(config: VCenterConfig, pathName: string) {
  return new URL(pathName, config.apiBaseUrl).toString();
}

function vCenterRecordList(payload: unknown) {
  const candidate =
    payload && typeof payload === "object" && !Array.isArray(payload)
      ? (payload as Record<string, unknown>).value
      : payload;
  return Array.isArray(candidate)
    ? candidate.filter(
        (item): item is VCenterRecord =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      )
    : [];
}

async function createVCenterSession(config: VCenterConfig) {
  const response = await connectorFetch(vCenterApiUrl(config, "/api/session"), {
    headers: {
      authorization: `Basic ${Buffer.from(`${config.username}:${config.password}`).toString("base64")}`
    },
    method: "POST"
  });
  if (!response.ok) {
    throw new Error(
      `vCenter session creation returned status ${response.status}.`
    );
  }
  const payload = (await response.json()) as unknown;
  const sessionId =
    typeof payload === "string"
      ? payload
      : payload && typeof payload === "object" && !Array.isArray(payload)
        ? (payload as Record<string, unknown>).value
        : null;
  if (typeof sessionId !== "string" || sessionId.length === 0) {
    throw new Error("vCenter session response did not contain a session id.");
  }
  return sessionId;
}

async function fetchVCenterInventory(config: VCenterConfig) {
  const sessionId = await createVCenterSession(config);
  const headers = {
    accept: "application/json",
    "vmware-api-session-id": sessionId
  };
  const readList = async (pathName: string) => {
    const response = await connectorFetch(vCenterApiUrl(config, pathName), {
      headers
    });
    if (!response.ok) {
      throw new Error(
        `vCenter inventory read ${pathName} returned status ${response.status}.`
      );
    }
    return vCenterRecordList(await response.json());
  };
  const [datacenters, clusters, hosts, networks, vms] = await Promise.all([
    readList("/api/vcenter/datacenter"),
    readList("/api/vcenter/cluster"),
    readList("/api/vcenter/host"),
    readList("/api/vcenter/network"),
    readList("/api/vcenter/vm")
  ]);
  return { clusters, datacenters, hosts, networks, vms };
}

function vCenterString(record: VCenterRecord, key: string, fallback: string) {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

function createVCenterAssets(inventory: VCenterInventory) {
  const assets: ConnectorAssetInput[] = [];
  const append = (
    records: VCenterRecord[],
    kind: "cluster" | "datacenter" | "host" | "network" | "vm"
  ) => {
    for (const [index, record] of records.entries()) {
      const idKey = kind === "vm" ? "vm" : kind;
      const identifier = vCenterString(record, idKey, `${kind}-${index + 1}`);
      const name = vCenterString(record, "name", identifier);
      const powerState =
        typeof record.power_state === "string" ? record.power_state : null;
      assets.push(
        ConnectorAssetInputSchema.parse({
          assetType: kind === "host" || kind === "vm" ? "Host" : "Other",
          businessCriticality: "Moderate",
          environment: null,
          identifiers: {
            ...record,
            inventoryKind: kind,
            provider: "vmware-vcenter",
            vcenterObjectId: identifier
          },
          internetExposed: false,
          name,
          owner: null,
          status:
            powerState === "POWERED_OFF" ||
            record.connection_state === "DISCONNECTED"
              ? "Inactive"
              : "Active",
          tags: [
            "vmware",
            "vcenter",
            kind,
            ...(kind === "vm" ? ["virtual-machine"] : [])
          ]
        })
      );
    }
  };
  append(inventory.datacenters, "datacenter");
  append(inventory.clusters, "cluster");
  append(inventory.hosts, "host");
  append(inventory.networks, "network");
  append(inventory.vms, "vm");
  return assets;
}

function createVCenterSignals(inventory: VCenterInventory) {
  const timestampObserved = new Date().toISOString();
  return (
    [
      ["datacenter", inventory.datacenters],
      ["cluster", inventory.clusters],
      ["host", inventory.hosts],
      ["network", inventory.networks],
      ["vm", inventory.vms]
    ] as const
  ).flatMap(([kind, records]) =>
    records.map((record, index) => {
      const idKey = kind === "vm" ? "vm" : kind;
      const identifier = vCenterString(record, idKey, `${kind}-${index + 1}`);
      return ConnectorSignalInputSchema.parse({
        confidence: 0.96,
        freshness: "Fresh",
        rawPayloadPointer: `vmware-vcenter://${kind}/${encodeURIComponent(identifier)}`,
        redactionStatus: "Redacted",
        relatedAssetHints: [vCenterString(record, "name", identifier)],
        relatedAssetIds: [],
        relatedControlIds: [],
        relatedEvidenceIds: [],
        relatedIdentityIds: [],
        relatedPathIds: [],
        sensitivityLevel: "Moderate",
        signalCategory: "Asset",
        signalSubcategory: `VCenter${kind[0]?.toUpperCase()}${kind.slice(1)}Inventory`,
        sourceType: `vmware_vcenter.${kind}`,
        timestampObserved
      });
    })
  );
}

function loadVCenterFixtureInventory(config: Record<string, unknown>) {
  const fixture = config.fixtureInventory;
  if (!fixture || typeof fixture !== "object" || Array.isArray(fixture)) {
    return VCENTER_FIXTURE_INVENTORY;
  }
  const record = fixture as Record<string, unknown>;
  return {
    clusters: vCenterRecordList(record.clusters),
    datacenters: vCenterRecordList(record.datacenters),
    hosts: vCenterRecordList(record.hosts),
    networks: vCenterRecordList(record.networks),
    vms: vCenterRecordList(record.vms)
  };
}

function createVCenterConnector(): Connector {
  return {
    manifest: VCENTER_CONNECTOR_MANIFEST,
    async collectSignals(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const inventory = parsedContext.mockMode
        ? loadVCenterFixtureInventory(parsedContext.config)
        : await fetchVCenterInventory(
            VCenterConfigSchema.parse(parsedContext.config)
          );
      return createVCenterSignals(inventory);
    },
    async healthCheck(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      if (parsedContext.mockMode) {
        return createMockHealth(VCENTER_CONNECTOR_MANIFEST, parsedContext);
      }
      const startedAt = Date.now();
      try {
        const inventory = await fetchVCenterInventory(
          VCenterConfigSchema.parse(parsedContext.config)
        );
        return ConnectorHealthSchema.parse({
          authorizationVerified: true,
          checkedAt: new Date().toISOString(),
          detail: `vCenter read-only inventory verified; ${createVCenterAssets(inventory).length} object(s) accessible.`,
          latencyMs: Date.now() - startedAt,
          status: "Healthy"
        });
      } catch (error) {
        return ConnectorHealthSchema.parse({
          authorizationVerified: false,
          checkedAt: new Date().toISOString(),
          detail:
            error instanceof Error
              ? `vCenter inventory check failed: ${error.message}`
              : "vCenter inventory check failed.",
          latencyMs: Date.now() - startedAt,
          status: "Unhealthy"
        });
      }
    },
    async sync(context) {
      const parsedContext = ConnectorExecutionContextSchema.parse(context);
      const startedAt = Date.now();
      const inventory = parsedContext.mockMode
        ? loadVCenterFixtureInventory(parsedContext.config)
        : await fetchVCenterInventory(
            VCenterConfigSchema.parse(parsedContext.config)
          );
      const assets = createVCenterAssets(inventory);
      const health = ConnectorHealthSchema.parse({
        authorizationVerified: true,
        checkedAt: new Date().toISOString(),
        detail: `vCenter read-only inventory returned ${assets.length} object(s) across datacenters, clusters, hosts, networks, and VMs.`,
        latencyMs: Date.now() - startedAt,
        status: "Healthy"
      });
      return ConnectorSyncResultSchema.parse({
        assets,
        health,
        signals: createVCenterSignals(inventory).map((signal) =>
          createTimestampedSignal(
            VCENTER_CONNECTOR_MANIFEST,
            parsedContext,
            signal
          )
        )
      });
    }
  };
}

type PlannedConnectorSeed = {
  connectorKey: string;
  vendor: string;
  product: string;
  category: z.infer<typeof IntegrationCategorySchema>;
  marketplaceCategory: z.infer<typeof ConnectorMarketplaceCategorySchema>;
  setupComplexity?: z.infer<typeof SetupComplexitySchema>;
  dataSensitivity?: z.infer<typeof SensitivityLevelSchema>;
  description?: string;
  requiredPermissions?: string[];
  signalCategories?: z.infer<typeof SignalCategorySchema>[];
  supportedMissionTypes?: z.infer<typeof MissionTypeSchema>[];
  validationCapabilities?: string[];
  controlObservationCapabilities?: string[];
  workflowCapabilities?: string[];
};

function defaultSignalCategories(
  seed: PlannedConnectorSeed
): z.infer<typeof SignalCategorySchema>[] {
  switch (seed.marketplaceCategory) {
    case "Cloud":
      return ["Cloud", "Asset"];
    case "Identity":
      return ["Identity"];
    case "Code/DevSecOps":
      return ["Repository"];
    case "AI Stack":
      return ["AIApplication"];
    case "SIEM":
    case "EDR/XDR":
    case "WAF/Firewall":
    case "Email Security":
      return ["ControlObservation"];
    case "SOAR/ITSM":
    case "MSSP/PSA/RMM":
    case "Ticketing":
      return ["Remediation"];
    case "Threat Intelligence":
      return ["Exposure"];
    case "VM/EAP/ASM/CNAPP":
      return ["Exposure", "Asset"];
    default:
      return ["Audit"];
  }
}

function defaultMissionTypes(
  seed: PlannedConnectorSeed
): z.infer<typeof MissionTypeSchema>[] {
  switch (seed.marketplaceCategory) {
    case "AI Stack":
      return ["ValidationSnapshot", "AIAppValidation"];
    case "SIEM":
    case "EDR/XDR":
    case "WAF/Firewall":
    case "Email Security":
      return ["ValidationSnapshot", "ControlValidation"];
    case "SOAR/ITSM":
    case "MSSP/PSA/RMM":
    case "Ticketing":
      return ["ValidationSnapshot", "FixVerification"];
    default:
      return [
        "ValidationSnapshot",
        "ExposureValidation",
        "ContinuousValidation"
      ];
  }
}

function defaultValidationCapabilities(seed: PlannedConnectorSeed) {
  switch (seed.marketplaceCategory) {
    case "Cloud":
      return ["Cloud asset inventory", "Posture and exposure signals"];
    case "Identity":
      return ["Identity inventory", "Privilege and MFA posture signals"];
    case "Code/DevSecOps":
      return [
        "Repository and pipeline signals",
        "Secret and dependency path seeds"
      ];
    case "AI Stack":
      return ["AI application context", "RAG and tool configuration signals"];
    case "VM/EAP/ASM/CNAPP":
      return ["Exposure import", "Asset and vulnerability context"];
    case "Threat Intelligence":
      return ["Threat relevance signals", "Known exploitation context"];
    default:
      return [];
  }
}

function createPlannedConnector(seed: PlannedConnectorSeed): Connector {
  const manifest = ConnectorManifestSchema.parse({
    authMethods: [
      {
        description:
          "Planned integration. Connection setup will be enabled after connector implementation and security review.",
        fields: [],
        kind: "planned",
        label: "Planned",
        mockSupported: false
      }
    ],
    availability: "Planned",
    category: seed.category,
    connectable: false,
    connectorKey: seed.connectorKey,
    controlObservationCapabilities:
      seed.controlObservationCapabilities ??
      (["SIEM", "EDR/XDR", "WAF/Firewall", "Email Security"].includes(
        seed.marketplaceCategory
      )
        ? ["Detected", "Blocked", "Logged", "NoEvidence"]
        : []),
    customerVisibleDescription:
      seed.description ??
      `${seed.vendor} ${seed.product} is planned for the Periscan integration marketplace.`,
    dataSensitivity: seed.dataSensitivity ?? "Moderate",
    healthCheckMethod: "Planned connector implementation",
    marketplaceCategory: seed.marketplaceCategory,
    mockSupported: false,
    permissionsSummary:
      "Planned read-only permissions will be finalized before this connector becomes connectable.",
    product: seed.product,
    requiredPermissions: seed.requiredPermissions ?? [
      "Read-only API access (planned)"
    ],
    setupComplexity: seed.setupComplexity ?? "Medium",
    signalCategories: seed.signalCategories ?? defaultSignalCategories(seed),
    supportedMissionTypes:
      seed.supportedMissionTypes ?? defaultMissionTypes(seed),
    validationCapabilities:
      seed.validationCapabilities ?? defaultValidationCapabilities(seed),
    vendor: seed.vendor,
    workflowCapabilities: seed.workflowCapabilities ?? []
  });

  return {
    manifest,
    async collectSignals() {
      throw new Error(
        `${manifest.product} is planned and not connectable yet.`
      );
    },
    async healthCheck() {
      return ConnectorHealthSchema.parse({
        authorizationVerified: false,
        checkedAt: new Date().toISOString(),
        detail: `${manifest.vendor} ${manifest.product} is planned and not connectable yet.`,
        latencyMs: null,
        status: "Unknown"
      });
    },
    async sync() {
      throw new Error(
        `${manifest.product} is planned and not connectable yet.`
      );
    }
  };
}

