const CONNECTOR_REGISTRY = buildConnectorCatalog();

export function certificationLevelForAvailability(
  availability: z.infer<typeof ConnectorAvailabilitySchema>
): ConnectorCertificationLevel {
  if (availability === "Production") {
    return "Certified";
  }

  return availability;
}

function hasCredentialAuth(manifest: ConnectorManifest) {
  return manifest.authMethods.some(
    (authMethod) => authMethod.kind !== "mock" && authMethod.kind !== "planned"
  );
}

function buildConnectorCatalogEntry(
  connector: Connector
): ConnectorCatalogEntry {
  const manifest = connector.manifest;
  const isStandardized = STANDARDIZED_MARKET_LEADER_CONNECTOR_KEYS.has(
    manifest.connectorKey
  );
  const isPlanned =
    manifest.availability === "Planned" || manifest.connectable === false;
  const implementationTier: ConnectorImplementationTier = isStandardized
    ? "StandardizedCatalog"
    : isPlanned
      ? "Planned"
      : "DedicatedClient";
  const dedicatedClient = implementationTier === "DedicatedClient";
  const connectable = !isStandardized && !isPlanned;
  const executionReadiness: ConnectorExecutionReadiness = !connectable
    ? "NotConnectable"
    : hasCredentialAuth(manifest)
      ? "ReadyForCredentials"
      : "FixtureOnly";
  const availability = isStandardized ? "Planned" : manifest.availability;

  return ConnectorCatalogEntrySchema.parse({
    ...manifest,
    availability,
    certificationLevel: certificationLevelForAvailability(availability),
    connectable,
    dedicatedClient,
    executionReadiness,
    executionReadinessReason:
      implementationTier === "StandardizedCatalog"
        ? "Catalog coverage only. Setup is blocked until a vendor-specific live client and credentialed contract tests are implemented and reviewed."
        : isPlanned
          ? "Connector is visible for roadmap transparency but setup is blocked until implementation and security review are complete."
          : "Dedicated connector client is implemented; customer credentials are required before live sync.",
    implementationTier,
    live: dedicatedClient && connectable
  });
}

export function getConnectorCatalog() {
  return [...CONNECTOR_REGISTRY].map((connector) =>
    buildConnectorCatalogEntry(connector)
  );
}

export function getConnectorCatalogEntryByKey(connectorKey: string) {
  const connector = getConnectorByKey(connectorKey);

  return connector ? buildConnectorCatalogEntry(connector) : null;
}

export function getConnectorByKey(connectorKey: string) {
  return CONNECTOR_REGISTRY.find(
    (connector) => connector.manifest.connectorKey === connectorKey
  );
}

export function normalizeSignalEnvelope(
  manifest: ConnectorManifest,
  context: ConnectorExecutionContext,
  signal: ConnectorSignalInput
) {
  return createTimestampedSignal(manifest, context, signal);
}

/**
 * Squad Zeta baseline fabric ingest stub (PRD 3.12).
 * Safe normalization of external siloed finding (vuln/EDR/CSPM/inventory)
 * into SignalEnvelope seeds for evidence graph + pillar validation.
 * "Validate from external finding" entry point. Correlation-friendly.
 * Never mutates upstream; read-only; uses existing SignalEnvelopeSchema.
 */
export function normalizeExternalFindingToFabricSeeds(
  manifest: ConnectorManifest,
  context: ConnectorExecutionContext,
  externalFinding: Record<string, unknown>
): SignalEnvelope[] {
  const now = new Date().toISOString();
  // Minimal safe seed: treat external finding as ControlObservation or Exposure seed.
  // Real impls (CrowdStrike/Wiz/Tenable/XSIAM/QRadar etc) would map vendor fields.
  const baseSignal: ConnectorSignalInput = {
    confidence: 0.75,
    freshness: "recent",
    rawPayloadPointer: null,
    redactionStatus: "Redacted",
    relatedAssetIds: [],
    relatedControlIds: [],
    relatedEvidenceIds: [],
    relatedIdentityIds: [],
    relatedPathIds: [],
    sensitivityLevel: "High",
    signalCategory: "ControlObservation",
    signalSubcategory: "external-finding-seed",
    sourceType: `${manifest.connectorKey}.fabric.ingest`,
    timestampObserved: now,
    techniqueIds: (externalFinding.techniqueIds as string[] | undefined) || [],
    relatedAssetHints:
      (externalFinding.relatedAssetHints as string[] | undefined) || []
  };
  const seed = createTimestampedSignal(manifest, context, baseSignal);
  // In real flow this seeds evidence graph for pillar validation (via worker persist + graph).
  // Noise reduction: caller correlates before persisting.
  return [seed];
}

